\section{Residual minimization of the Physics-Informed Hybrid Scheme}
\label{app:OptPIHS_LM}
Here, we present the formulation of the PI hybrid scheme optimization problem in \cref{eq:min_hybrid} as a non-linear residual minimization problem.~First, we collect all the components of the hybrid approximation into the $N$-dim. column vector:
\begin{equation}
    \tilde{\boldsymbol{\pi}}^{HxS}(\mathbf{y},\boldsymbol{a},\mathbf{p}) = [\tilde{\pi}^{HxS}_1(\mathbf{y},\boldsymbol{\alpha}_1,\mathbf{p}_1), \ldots, \tilde{\pi}^{HxS}(\mathbf{y},\boldsymbol{\alpha}_N,\mathbf{p}_N)]^\top,
\end{equation}
where each element $\tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n)$ is given by \cref{eq:IM_hybrid} for $n=1,\ldots,N$.~In the ensuing text, we drop the dependence on the hyperparameters $\mathcal{H}_1$, $\mathcal{H}_2$ and the radius of the polydisc $\mathbf{r}$ for conciseness of the presentation.~In addition, let us collect all the tunable parameters into the column vector of $N\left( L(M+2) + \left(\prod_{i=1}^M(h +i)\right)/i! +1 \right)$ dimensions, as:
\begin{equation}
    \boldsymbol{\nu} = [\boldsymbol{\nu}_1,\ldots,\boldsymbol{\nu}_n,\ldots,\boldsymbol{\nu}_N]^\top =[\boldsymbol{\alpha}_1,\mathbf{p}_1, \ldots, \boldsymbol{\alpha}_n,\mathbf{p}_n, \ldots, \boldsymbol{\alpha}_N,\mathbf{p}_N ]^\top,  
    \label{eq:pars_PIHxS}
\end{equation}
where each pair $\boldsymbol{\nu}_n=[\boldsymbol{\alpha}_n, \mathbf{p}_n]$ for $n=1,\ldots,N$ includes the coefficients of the $n$-th element of the polynomial series in \cref{eq:IM_polySexp} and the parameters of the $n$-th output of the NN in \cref{eq:IM_NN}, respectively; i.e., all the parameters of the $n$-th output of the hybrid scheme in \cref{eq:IM_hybrid}.

Next, consider the set of collocation points $\mathbf{y}^{(q)}\in\Omega$ with $q=1,\ldots,Q$ and the ones on the boundary, $\mathbf{y}^{(r)}\in\partial\mathcal{D}$ with $r=1,\ldots,R$.~The optimization problem of the loss function in \cref{eq:min_hybrid} over the parameters included in the column vector in \cref{eq:pars_PIHxS} is achieved by the minimization of the following non-linear residuals; (i) the residuals corresponding to the first term of the loss function in \cref{eq:min_hybrid}:
\begin{multline}
    \mathcal{F}^{HxS}_{q,n} = \omega_q \Big(\tilde{\pi}^{HxS}_n(\mathbf{A}\mathbf{y}^{(q)} + \mathbf{g}(\mathbf{y}^{(q)}),\boldsymbol{\nu}_n) - \sum_{i=1}^N B_{n,i} \tilde{\pi}^{HxS}_i(\mathbf{y}^{(q)},\boldsymbol{\nu}_i) - \sum_{j=1}^M C_{n,j} y^{(q)}_j  -  \\
    f_n(\tilde{\boldsymbol{\pi}}^{HxS}(\mathbf{y}^{(q)},\boldsymbol{\nu}),\mathbf{y}^{(q)}) \Big), \label{eq:res_PIHxS1}
\end{multline}
where $B_{n,i}$ and $C_{n,j}$ are the $(n,i)$ and $(n,j)$ elements of $\mathbf{B}\in\mathbb{R}^{N\times N}$ and $\mathbf{C}\in\mathbb{R}^{N\times M}$, respectively, $y^{(q)}_j$ is the $j$-th element of $\mathbf{y}^{(q)}=[y^{(q)}_1,\ldots,y^{(q)}_M]^\top \in \mathbb{R}^M$, and $f_n$ is the $n$-th element of $\mathbf{f}=[f_1,\ldots,f_N]^\top$; (ii) the residuals corresponding to the second term of the loss function in \cref{eq:min_hybrid}:
\begin{equation}
    \mathcal{F}^{HxS}_{0,n} = \omega_1 \tilde{\pi}^{HxS}_n(\mathbf{0}^M,\boldsymbol{\nu}_n)= \omega_1 \tilde{\pi}^{xS}_n(\mathbf{0}^M,\boldsymbol{\alpha}_n),
    \label{eq:res_PIHxS2}
\end{equation}
where the latter equality follows from \cref{eq:IM_hybrid}, since at the equilibrium point only the polynomial series is active; and (iii) the residuals corresponding to the third term of the loss function in \cref{eq:min_hybrid}:
\begin{equation}
    \mathcal{F}^{HxS}_{r,n} = \omega_2 \Big( \tilde{\pi}^{xS}_n(\mathbf{y}^{(r)},\boldsymbol{\alpha}_n) - \tilde{\pi}^{NN}_n(\mathbf{y}^{(r)},\mathbf{p}_n) \Big).
    \label{eq:res_PIHxS3}
\end{equation}
Note that the residuals in \cref{eq:res_PIHxS1} are computed on the basis of all, in general, the coefficients in $\boldsymbol{\nu}$, since all components of $\mathbf{y}$ are contributing to the linear and non-linear terms, $B_{n,i} \cdot \tilde{\pi}^{xS}_i(\mathbf{y}^{(q)},\boldsymbol{\nu}_i)$ and $f_n(\tilde{\boldsymbol{\pi}}^{xS}(\mathbf{y}^{(q)},\boldsymbol{\nu}),\mathbf{y}^{(q)})$, respectively.~Using the expressions of the residuals in \cref{eq:res_PIHxS1,eq:res_PIHxS2,eq:res_PIHxS3}, we then collect all the residuals into the $N(Q+R+1)$-dim. column vector:
\begin{multline}
    \boldsymbol{\mathcal{F}}^{HxS} = [\mathcal{F}^{HxS}_{1,1},\ldots,\mathcal{F}^{HxS}_{Q,1},\ldots,\mathcal{F}^{HxS}_{q,n},\ldots,\mathcal{F}^{HxS}_{1,N},\ldots,\mathcal{F}^{HxS}_{Q,N},\mathcal{F}^{HxS}_{0,1},\ldots,\mathcal{F}^{HxS}_{0,n},\ldots,\mathcal{F}^{HxS}_{0,N},\\
    \mathcal{F}^{HxS}_{1,1},\ldots,\mathcal{F}^{HxS}_{R,1},\ldots,\mathcal{F}^{HxS}_{r,n},\ldots,\mathcal{F}^{HxS}_{1,N},\ldots,\mathcal{F}^{HxS}_{R,N}]^\top.
    \label{eq:res_HS}
\end{multline}

For the minimization of the above residuals, we employ gradient-based optimization via the LM algorithm, for the implementation of which, the Jacobian matrix $\mathbf{J}=\nabla_{\boldsymbol{\nu}} \boldsymbol{\mathcal{F}}^{HxS}$ is computed via symbolic differentiation.~To compute the Jacobian, let $\nu_k$ denote any coefficient belonging to the vector of coefficients $\boldsymbol{\nu}_k=[\boldsymbol{\alpha}_k, \mathbf{p}_k]$ of the $k$-th element of $\boldsymbol{\nu}$ in \cref{eq:pars_PIHxS} for $k=1,\ldots,N$.~Then, the derivatives of the residuals in \cref{eq:res_PIHxS1,eq:res_PIHxS2,eq:res_PIHxS3} w.r.t. $\nu_k$ can be computed by:
\begin{align}
    \dfrac{\partial \mathcal{F}^{HxS}_{q,n}}{\partial \nu_k} & = \omega_q \Bigg(\dfrac{\partial \tilde{\pi}^{HxS}_n(\mathbf{A}\mathbf{y}^{(q)} + \mathbf{g}(\mathbf{y}^{(q)}),\boldsymbol{a}_n,\mathbf{p}_n)}{\partial \nu_k} \delta_{nk} - \sum_{i=1}^N \left(B_{n,i} + \dfrac{\partial f_n}{\partial x_i}\right) \dfrac{\partial \tilde{\pi}^{HxS}_i(\mathbf{y}^{(q)},\boldsymbol{a}_i,\mathbf{p}_i)}{\partial \nu_k} \delta_{ik}\Bigg), \label{eq:resHxS_ders1} \\
    \dfrac{\partial \mathcal{F}^{HxS}_{0,n}}{\partial \nu_k} & = \omega_1 \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{0}^M,\boldsymbol{\alpha}_n)}{\partial \nu_k} \delta_{nk}, \label{eq:resHxS_ders2} \\
    \dfrac{\partial \mathcal{F}^{HxS}_{r,n}}{\partial \nu_k} & = \omega_2 \Bigg( \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{y}^{(r)},\boldsymbol{\alpha}_n)}{\partial \nu_k} - \dfrac{\partial \tilde{\pi}^{NN}_n(\mathbf{y}^{(r)},\mathbf{p}_n)}{\partial \nu_k} \Bigg) \delta_{nk},
    \label{eq:resHxS_ders3}
\end{align}
where the last term in \cref{eq:resHxS_ders1} includes contributions from all $\tilde{\pi}^{HxS}_i(\cdot)$ outputs for $i=1,\ldots,N$, since, in general, the gradient $\partial f_n / \partial x_i$ of the vector field is considered full.

We highlight here that the derivatives in \cref{eq:resHxS_ders1} are computed on the basis of the hybrid scheme $\tilde{\pi}^{HxS}_n(\cdot)$, while the ones in \cref{eq:resHxS_ders2,eq:resHxS_ders3} are computed on the basis of the hybrid scheme's counterparts; i.e., the polynomial series $\tilde{\pi}^{xS}_n(\cdot)$ and the NN $\tilde{\pi}^{NN}_n(\cdot)$, respectively.~For computing the derivatives of the hybrid scheme in \cref{eq:resHxS_ders1}, we exploit the structure of the hybrid scheme in \cref{eq:IM_hybrid} and decompose the related derivatives as:
\begin{subnumcases}{\dfrac{\partial \tilde{\pi}^{HxS}_n(\mathbf{A}\mathbf{y}^{(q)} + \mathbf{g}(\mathbf{y}^{(q)}),\boldsymbol{a}_n,\mathbf{p}_n)}{\partial \nu_k} =} 
    \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{A}\mathbf{y}^{(q)} + \mathbf{g}(\mathbf{y}^{(q)}),\boldsymbol{a}_n)}{\partial \nu_k}, & when $\mathbf{A}\mathbf{y}^{(q)} + \mathbf{g}(\mathbf{y}^{(q)}) \in \mathcal{D}$
    \label{eq:hyb_der1_xS} \\
    \dfrac{\partial \tilde{\pi}^{NN}_n(\mathbf{A}\mathbf{y}^{(q)} + \mathbf{g}(\mathbf{y}^{(q)}),\mathbf{p}_n)}{\partial \nu_k}, & when $\mathbf{A}\mathbf{y}^{(q)} + \mathbf{g}(\mathbf{y}^{(q)}) \notin \mathcal{D}$ \label{eq:hyb_der1_NN}
\end{subnumcases} 
\begin{subnumcases}{\dfrac{\partial \tilde{\pi}^{HxS}_i(\mathbf{y}^{(q)},\boldsymbol{a}_i,\mathbf{p}_i)}{\partial \nu_k} =}
    \dfrac{\partial \tilde{\pi}^{xS}_i(\mathbf{y}^{(q)},\boldsymbol{a}_i)}{\partial \nu_k}, & when  $\mathbf{y}^{(q)} \in \mathcal{D}$ \label{eq:hyb_der2_xS} \\
    \dfrac{\partial \tilde{\pi}^{NN}_i(\mathbf{y}^{(q)},\mathbf{p}_i)}{\partial \nu_k}, & when  $\mathbf{y}^{(q)} \notin \mathcal{D}$ \label{eq:hyb_der2_NN}
\end{subnumcases}
where $\mathcal{D}$ is the polydisc of radius $\mathbf{r}$ within which the polynomial series are active and outside of which the NN acts.~A detailed derivation of the piecewise expressions in Eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_xS}, \ref{eq:hyb_der2_NN}) is provided at the end of this section.

Given the expressions in Eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_xS}, \ref{eq:hyb_der2_NN}), the computation of the derivatives of the hybrid scheme's residuals in \cref{eq:resHxS_ders1,eq:resHxS_ders2,eq:resHxS_ders3} is simplified by the computation of the derivatives of the polynomial series and the NN w.r.t. any parameter $\nu_k$ belonging in $\boldsymbol{\nu}$ of \cref{eq:pars_PIHxS}.~However, $\boldsymbol{\nu}$ includes both the polynomial series coefficients $\boldsymbol{\alpha}_k$ and the NN parameters $\mathbf{p}_k$.~Hence, in the case where:
\begin{enumerate}
    \item $\nu_k \equiv \alpha_k^{i_1,\ldots,i_M}\in \boldsymbol{\alpha}_k$, the derivatives in Eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der2_xS} for the coefficient $\alpha_k^{i_1,\ldots,i_M}$ corresponding to the $i_1$-th,\ldots, $i_M$-th multivariate monomial of \cref{eq:IM_polySexp}, are computed as:
    \begin{equation}
        \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{y}^{(q)},\boldsymbol{a}_n)}{\partial \alpha_k^{i_1,\ldots,i_M}}=P^x_{i_1}(y_1^{(q)}) \cdots P^x_{i_M}(y_M^{(q)}), \label{eq:derPS_coef}
    \end{equation}
    for $k=n$ and zero otherwise.~Since $\nu_k \equiv \alpha_k^{i_1,\ldots,i_M} \notin \mathbf{p}_n$, the derivatives in Eqs.~(\ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_NN} are also zero.~Similarly, the derivatives in \cref{eq:resHxS_ders2} are computed by \cref{eq:derPS_coef}, while the ones in \cref{eq:resHxS_ders3} are zero. 
    \item $\nu_k \in \mathbf{p}_k$, the related derivatives are computed via the symbolic differentiation of the NN output, which is detailed in \cref{app:OptPINN_LM}.~In particular, the derivatives in Eqs.~(\ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_NN} are computed by \cref{eq:derNN_pars}, while the ones in Eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der2_xS} are zero, since now $\nu_k \notin \boldsymbol{\alpha}_k$.~Similarly, the derivatives in \cref{eq:resHxS_ders3} are computed by \cref{eq:derNN_pars}, while the ones in \cref{eq:resHxS_ders2} are zero.
\end{enumerate}
In summary, substitution of \cref{eq:derPS_coef} and \cref{eq:derNN_pars} into Eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_xS}, \ref{eq:hyb_der2_NN}), and then to \cref{eq:resHxS_ders1,eq:resHxS_ders2,eq:resHxS_ders3} provides all the related derivatives for the formation of the $N(Q+R+1) \times N\left( L(M+2) + \left(\prod_{i=1}^M(h +i)\right)/i! +1 \right)$ Jacobian matrix $\mathbf{J}=\nabla_{\boldsymbol{\nu}} \boldsymbol{\mathcal{F}}^{HxS}$.~A detailed presentation of the iterative procedure of the LM algorithm for the minimization of the residuals is provided in \Cref{app:LMalg}, along with a detailed pseudocode.

\subsection{Derivation of the hybrid scheme's piecewise derivatives in eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_xS}, \ref{eq:hyb_der2_NN})}

For the computation of the derivatives in eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_xS}, \ref{eq:hyb_der2_NN}), we begin with the definition of the hybrid scheme in \cref{eq:IM_hybrid}, in which the hyperparamters $\mathcal{H}_1$ and $\mathcal{H}_2$ are omitted for simplicity:
\begin{equation}
    \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r}) = \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{\alpha}_n)^{H(\mathbf{y},\mathbf{r})} \cdot  \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)^{1-H(\mathbf{y},\mathbf{r})}.  \label{eq:xx1} 
\end{equation}
Next, we consider the absolute values of the above equality, which enables us to consider the natural logarithm, implying:
\begin{align}
    \big \lvert \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r}) \big \rvert & = \big \lvert \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{\alpha}_n)^{H(\mathbf{y},\mathbf{r})} \cdot  \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)^{1-H(\mathbf{y},\mathbf{r})} \big \rvert \Rightarrow \nonumber \\
    ln\big \lvert \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r}) \big \rvert & = H(\mathbf{y},\mathbf{r})~ ln\big \lvert \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{\alpha}_n) \big \rvert + (1-H(\mathbf{y},\mathbf{r}))~ ln \big \lvert  \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)^{1-H(\mathbf{y},\mathbf{r})} \big \rvert. \label{eq:xx2}
\end{align}
Differentiation of the expression in \cref{eq:xx2} w.r.t. a parameter $\nu_k$ that belongs in $\boldsymbol{\nu}_k=[\boldsymbol{\alpha}_k,\mathbf{p}_k]$, after some algebraic manipulations, implies:
\begin{multline}
    \dfrac{\partial \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r})}{\partial \nu_k} = H(\mathbf{y},\mathbf{r})~\dfrac{\tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r})}{\tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{a}_n)} \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{a}_n)}{\partial \nu_k} + \\
    (1-H(\mathbf{y},\mathbf{r}))~  \dfrac{\tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r})}{\tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)} \dfrac{\partial \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)}{\partial \nu_k}.  \label{eq:xx3}
\end{multline}
Then, substitution of the expression in \cref{eq:xx1} into \cref{eq:xx3}, further implies:
\begin{multline}
     \dfrac{\partial \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r})}{\partial \nu_k} = H(\mathbf{y},\mathbf{r})~ \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{a}_n)^{H(\mathbf{y},\mathbf{r})-1} \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)^{1-H(\mathbf{y},\mathbf{r})}
    \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{a}_n)}{\partial \nu_k} + \\
    + (1-H(\mathbf{y},\mathbf{r}))~ \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{a}_n)^{H(\mathbf{y},\mathbf{r})} \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)^{H(\mathbf{y},\mathbf{r})}
    \dfrac{\partial \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)}{\partial \nu_k}.
    \label{eq:xx4}
\end{multline}
Given \cref{eq:xx4}, we now consider the two distinct cases where $\mathbf{y}$ lies within or outside the polydisc $\mathcal{D}$ with radius $\mathbf{r}$.
\begin{enumerate}
    \item In the case where $\mathbf{y}\in \mathcal{D}$, we obtain $H(\mathbf{y},\mathbf{r})=1$ according to \cref{eq:Heaviside}.~Then, only the first term in \cref{eq:xx4} survives, which can be further simplified to:
    \begin{equation}
        \dfrac{\partial \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r})}{\partial \nu_k} = \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{a}_n)}{\partial \nu_k},   \qquad \text{when} \quad \mathbf{y} \in \mathcal{D}.
    \end{equation}
    \item In the case where $\mathbf{y}\notin \mathcal{D}$, we obtain $H(\mathbf{y},\mathbf{r})=0$ according to \cref{eq:Heaviside}.~Then, only the second term in \cref{eq:xx4} survives, which can be further simplified to:
    \begin{equation}
        \dfrac{\partial \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r})}{\partial \nu_k} = \dfrac{\partial \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)}{\partial \nu_k},   \qquad \text{when} \quad \mathbf{y} \notin \mathcal{D}.
    \end{equation}
\end{enumerate}
The above result can be summarized to the following piecewise expression for the derivative of the hybrid scheme:
\begin{subnumcases}{\dfrac{\partial \tilde{\pi}^{HxS}_n(\mathbf{y},\boldsymbol{a}_n,\mathbf{p}_n;\mathbf{r})}{\partial \nu_k}=}
    \dfrac{\partial \tilde{\pi}^{xS}_n(\mathbf{y},\boldsymbol{a}_n)}{\partial \nu_k}, &   when  $\mathbf{y} \in \mathcal{D}$, \\
    \dfrac{\partial \tilde{\pi}^{NN}_n(\mathbf{y},\mathbf{p}_n)}{\partial \nu_k}, &  when $\mathbf{y} \notin \mathcal{D}$,
\end{subnumcases}
which was used for deriving the piecewise expressions in eqs.~(\ref{eq:hyb_der1_xS}, \ref{eq:hyb_der1_NN}, \ref{eq:hyb_der2_xS}, \ref{eq:hyb_der2_NN}).


