\begin{lemma}
\label{lemma: W-W* in KNR}
Suppose $n$ tuples $\{ (h_i,a_i,s_i) \}_{i=1}^n$ are observed, and $(h_i, a_i, s_i)$ satisfy the transition $s_i= W^* \phi(h_i,a_i)+ \varepsilon_i$, $\varepsilon_1, ..., \varepsilon_n \stackrel{iid}{\sim} F$. Assume $F$ is $\sigma$-sub-Gaussian. Let $\widehat{W} = (\sum_{i=1}^n s_i \phi_i^T) (\sum_{i=1}^n \phi_i \phi_i^T + \lambda I)^{-1}$ for some $\lambda>0$, where $\phi_i$ denotes $\phi(h_i,a_i)$. Let $\Lambda_n = \sum_{i=1}^n \phi_i \phi_i^T + \lambda I$, then with probability at least $1-\delta$:
\begin{equation*}
\left\| (\widehat{W}-W^*) \Lambda_n^{1/2} \right\|_2 \le \sqrt{\lambda} \|W^*\|_2 + \sqrt{8\sigma^2 d_s \log(5) + 8\sigma^2 \log \left( \frac{\det (\Lambda_n) ^{1/2} / \det (\lambda I) ^{1/2}}{\delta} \right)}.
\end{equation*}
\end{lemma}

