\begin{proof}[Proof of Proposition~\ref{thm: uncertainty quantifier KNR}]

By Assumption~\ref{assumption: noise distribution in KNR} (ii), the following bound holds for any \( s_{k+1} \in \mathcal{S}_{k+1} \):
\[
\left| \widehat{P}_k(s_{k+1} \mid h_k, a_k) - P^*_k(s_{k+1} \mid h_k, a_k) \right|
\le C_L \cdot \| \widehat{W} \phi_k(h_k, a_k) - W^* \phi_k(h_k, a_k) \|_2,
\]
where \( C_L \) is the Lipschitz constant of the conditional density.

Moreover, by Assumption~\ref{assumption: noise distribution in KNR} (i), both distributions have compact support and vanish outside the union of two \( \ell_2 \)-balls: $B(\widehat{W} \phi_k(h_k, a_k), \sigma) \cup B(W^* \phi_k(h_k, a_k), \sigma),$
each of radius \( \sigma \) in \( \mathbb{R}^{d_{k+1}^{(s)}} \). Let \( B_d \) denote the Lebesgue volume of the unit ball in \( \mathbb{R}^d \). Then the \( \ell_1 \) distance between the two distributions can be bounded as:
\[
\| \widehat{P}_k(\cdot \mid h_k, a_k) - P^*_k(\cdot \mid h_k, a_k) \|_1 
\le 2 B_{d_{k+1}^{(s)}} \sigma C_L \cdot \| \widehat{W} \phi_k(h_k, a_k) - W^* \phi_k(h_k, a_k) \|_2.
\]

We now aim to bound the error between the means of the estimated and true conditional distributions, namely, $\| \widehat{W} \phi_k(h_k, a_k) - W^* \phi_k(h_k, a_k) \|_2.$ To do so, we insert the identity matrix \( I_n=\Lambda_n^{1/2} \Lambda_n^{-1/2} \) and apply the sub-multiplicative property of norms:
\begin{equation*}
\begin{split}
\| \widehat{W} \phi_k(h_k, a_k) - W^* \phi_k(h_k, a_k) \|_2 
&= \| (\widehat{W} - W^*) \Lambda_n^{1/2} \Lambda_n^{-1/2} \phi_k(h_k, a_k) \|_2 \\
&\le \| (\widehat{W} - W^*) \Lambda_n^{1/2} \|_2 \cdot \| \Lambda_n^{-1/2} \phi_k(h_k, a_k) \|_2.
\end{split}
\end{equation*}

Therefore, we have:
\begin{equation}
\label{ineq: transition auxiliary}
\widehat{P}_k(\cdot \mid h_k, a_k) - P^*_k(\cdot \mid h_k, a_k) \|_1 
\le 2 B_{d_{k+1}^{(s)}} \sigma C_L \| (\widehat{W} - W^*) \Lambda_n^{1/2} \|_2 \cdot \| \Lambda_n^{-1/2} \phi_k(h_k, a_k) \|_2.
\end{equation}

Next, we turn to bound the term $\| (\widehat{W} - W^*) \Lambda_n^{1/2} \|_2$. We begin by invoking Lemma \ref{lemma: bounded rv is subgaussian}. Under Assumption~\ref{assumption: noise distribution in KNR} (i), the additive noise terms are bounded, and thus each \( \varepsilon_k^{(i)} \) is \( \sigma \)-sub-Gaussian. Consequently, the conditions of Lemma~\ref{lemma: W-W* in KNR} are satisfied, yielding the following high-probability bound:
\begin{equation}
\label{ineq: w sub-gaussian bound}
\left\| (\widehat{W} - W^*) \Lambda_n^{1/2} \right\|_2 
\le \sqrt{\lambda} \|W^*\|_2 + \sqrt{8\sigma^2 d_{k+1}^{(s)} \log(5) + 8\sigma^2 \log \left( \frac{\det (\Lambda_n)^{1/2}}{\det (\lambda I)^{1/2} \delta} \right)} 
= \beta_{k,n}.
\end{equation}
Applying inequality~\eqref{ineq: w sub-gaussian bound} to \eqref{ineq: transition auxiliary}, we obtain with probability at least \( 1 - \delta \) that:
\begin{equation*}
\| \widehat{P}_k(\cdot \mid h_k, a_k) - P^*_k(\cdot \mid h_k, a_k) \|_1 \le 2 B_{d_{k+1}^{(s)}} \sigma C_L \cdot \beta_{k,n} 
\cdot \sqrt{ \phi_k(h_k, a_k)^\top \Lambda_n^{-1} \phi_k(h_k, a_k) },
\end{equation*}
where $\beta_{k,n}=\sqrt{\lambda} \|W^*\|_2 + \sqrt{8\sigma^2 d_{k+1}^{(s)} \log(5) + 8\sigma^2 \log \left( \frac{\det (\Lambda_n)^{1/2}}{\det (\lambda I)^{1/2} \delta} \right)}.$
\end{proof}


