\subsection{Gaussian Process}
\label{subsec: GP}
\subsubsection{Model Specification and Estimation}
Unlike the example in Section \ref{subsec: kernelized}, we no longer assume a parametric form for $P_k$. Instead, we consider a nonparametric setting. We assume the transition dynamic $P_{k}(s_{k+1}\mid h_k,a_k)$ is structured as: $s_{k+1} = g_k(h_k, a_k) + \varepsilon_k$, where $\varepsilon_k \sim N(0, \sigma^2 I)$. 

To estimate this model, we have access to an offline dataset \( \mathcal{D} \) consisting of \( n \) i.i.d. observations at each stage \( k \), given by \( \{(h_k^{(i)}, a_k^{(i)}, s_{k+1}^{(i)}) \}_{i=1}^n \). Our goal is to construct both an estimator \( \widehat{P}_k \) for the transition model and an uncertainty quantifier \( \Gamma_k \). For notational simplicity, we omit the subscript \( k \) when it is clear from the context. Moreover, we simplify notation by letting \( x := (h_k, a_k) \) to represent the input pair when \( k \) is fixed. Under these conventions, we can reformulate the problem using Gaussian process (GP) regression.

Under the GP prior, the posterior distribution over the unknown function \( g \) remains a Gaussian process with posterior mean function \( \widehat{g}(\cdot) \) and covariance function \( \widehat{h}(\cdot, \cdot) \), given by:
\begin{equation}
\label{eq: GP, g hat}
\widehat{g}(x) = (y_1, \dots, y_n)(H_{n,n} + \sigma^2 I)^{-1} H_n(x),
\end{equation}
\begin{equation}
\label{eq: GP, eq 1}
\widehat{h}(x, x') = h(x, x') - H_n(x)^\top (H_{n,n} + \sigma^2 I)^{-1} H_n(x'),
\end{equation}
where \( (y_1, \dots, y_n) \) is a \( d_{k+1}^{(s)} \times n \) matrix of observed outputs, \( H_{n,n} \in \mathbb{R}^{n \times n} \) is the kernel matrix with entries \( h(x_i, x_j) \), and \( H_n: \mathcal{X} \rightarrow \mathbb{R}^n \) is defined as \( H_n(x) = (h(x, x_1), \dots, h(x, x_n))^\top \).

\subsubsection{Theoretical Properties}

To quantify the uncertainty in the GP-based transition model, we define the uncertainty quantifier \( \Gamma \) in the following form: $\Gamma_k(x) = \frac{\beta_{k,n}}{\sigma} \sqrt{\widehat{h}(x,x)},$
where \( \widehat{h} \) is the posterior covariance function defined in equation~(\ref{eq: GP, eq 1}), and \( \beta_{k,n} \) is a constant given by:
\begin{equation}
\label{eq: GP, eq 4}
\beta_{k,n} = \sqrt{d_{k+1}^{(s)} \left(2 + 150 \log^3\left( \frac{d_{k+1}^{(s)} n}{\delta} \right) \log\left( \det\left( I_n + \frac{1}{\sigma^2} H_{n,n} \right) \right) \right)},
\end{equation}
where \( H_{n,n} \) is the kernel matrix defined earlier and \( \delta \in (0,1) \) is the confidence level.

The next proposition guarantees that the quantifier \( \Gamma(x) \) satisfies our Assumption \ref{assumption: uncertainty quantifier}.

\begin{proposition}
\label{thm: uncertainty quantifier GP}
Let \( \widehat{g}(x) \) and \( \Gamma(x) \) be defined as in equations~(\ref{eq: GP, g hat}) and~(\ref{eq: GP, eq 3}), respectively. Then, with probability at least \( 1 - \delta \),
\begin{equation*}
\left\| \widehat{P}(\cdot \mid x) - P^*(\cdot \mid x) \right\|_1 \le \Gamma(x), \quad \forall x \in \mathcal{X}.
\end{equation*}
\end{proposition}

\begin{proof}[Proof of Proposition~\ref{thm: uncertainty quantifier GP}]
See Lemma 14 of \cite{chang2021mitigating} for a detailed proof of this result.
\end{proof}

\section{Practical Algorithm for Section \ref{subsec: method overview}}
\label{subsec: summarized algorithm}

%We present the algorithm that summarizes the procedure in section \ref{subsec: method sieve regression}.     
\begin{algorithm}[ht]
\caption{Practical algorithm}
\label{algo: sieve regression}
%\KwIn{Stepsizes $\{\eta_k^{(t)}\}$; sample sizes $\{m_k^{(t)}\}$ for the regression step; a modified DTR model $\widetilde{M} = (\widehat{P}, \widetilde{r})$}
\KwIn{Offline dataset $\mathcal{D}$; stepsizes $\{\eta_k^{(t)}\}$ and Monte Carlo sample sizes $\{m_k^{(t)}\}$ at $k$-th stage and $t$-th iteration; hyperparameters $\{\widetilde{c}_k\}$}

Construct estimated transition dynamics $\widehat{P}$, estimated reward functions $\{\widehat{r}_k\}$ and uncertainty quantifiers $\{\Gamma\}_k$ from the offline data $\mathcal{D}$ \\
Construct the modified DTR model $\widetilde{M} = (\widehat{P}, \widetilde{r})$, with $\widetilde{r}_k = \widehat{r}_k - \widetilde{c}_k \Gamma_k$ \\
Initialize $\theta^{(0)}=(\theta^{(0)}_1,... \theta^{(0)}_K) = (\bf{0}, \bf{0}, ..., \bf{0})$ (i.e. $\bf{0}$ is a zero matrix $\in \mathbb{R}^{|L_k| \times N_k ^{(A)}} $)\\
$\pi^{(0)}\gets \pi(\theta^{(0)}), t=0 $\\
\For{$t=0,...,T-1$}{
\For{$k=1,...,K$}{
\For{$\overline{a}_k ~ \mathrm{in} ~ \mathcal{A}_1 \times \mathcal{A}_2 \times \cdots \times \mathcal{A}_k$}{
Sample $m_k$ i.i.d. samples $\{\overline{s}_k^{(1)}, ..., \overline{s}_k^{(m_k)} \}$ from $\mathrm{Unif}(\mathcal{S}_1 \times \mathcal{S}_2 \times \cdots \times \mathcal{S}_k)$ \\
Evaluate $Q_{k, \widetilde{M}} ^{\pi^{(t)}}$ on $m_k$ points: $\widehat{Q}_k^{(t)} (\overline{s} _k^{(i)}, \overline{a}_k) \gets Q_{k, \widetilde{M}} ^{\pi^{(t)}} (\overline{s} _k^{(i)}, \overline{a}_k ) $ for all $i$\\
Solve the linear regression problem that projects $\widehat{Q}_k^{(t)}(\cdot)$ onto $\Upsilon_{L_k}(\cdot)$: $\widehat{\theta} _k^{(t)}( \overline{a}_k ) \gets \arg \min_{\theta\in \mathbb{R}^{L_k}} \sum_{i=1}^{m_k} \left( \theta ^T \Upsilon_{L_k}(\overline{s}_k) - \widehat{Q}_k^{(t)} (\overline{s} _k^{(i)}, \overline{a}_k) \right)^2$ \\
}
Concatenate the $N_k^{(A)}$ columns: $\widehat{\theta} _k^{(t)} \gets \left( \widehat{\theta} _k^{(t)}\Bigl( \overline{a} _k^{(1)} \Bigr),~...~,\widehat{\theta} _k^{(t)}\Bigl( \overline{a} _k^{(N_k^{(A)})} \Bigr)  \right)$ \\
Update $\theta_k$: $\theta_k^{(t+1)} \gets \theta_k^{(t)} + \eta_k^{(t)} \widehat{\theta}_k^{(t)}$
}
$\pi^{(t+1)}\gets \pi({\theta^{(t+1)}})$ where $\theta^{(t+1)} = (\theta_1^{(t+1)}, ..., \theta_K^{(t+1)})$
}
\KwOut{$\pi^{(T)}$}
\end{algorithm}

Under the setting of linear sieves \eqref{eq: sieve function class}, $f_k(\theta_k, \cdot, \cdot)$ belongs to the linear space spanned by $L_k$ basis functions.  Our theoretical analysis allows $L_k$ to increase with $m_k$, but we suppose $m_k$ and $L_k$ are both fixed when implementing Algorithm \ref{algo: sieve regression}.

\section{Proofs}
\label{proof:proof}
% \yx they are proofs in Section 4. Again, we need to roadmap. Where do we need this theorem? \xx 
This section provides complete proofs of the theoretical results in Section \ref{sec: theory}. Section~\ref{proof: main thm} covers the regret decomposition under uncertainty quantification. Section~\ref{proof:linear} establishes suboptimality bounds for the linear model using kernel-based estimation. Section~\ref{proof sec: GP} presents the analysis for the Gaussian Process-based model, leveraging posterior contraction for regret control. 

\subsection{Proofs of Section \ref{subsec: theory overview}}
\label{proof: main thm}

The suboptimality of our learned policy can be decomposed into model shift error and policy optimization error. We begin with Theorem \ref{thm: final regret real M}
that upper bounds the model shift error through the uncertainty quantifiers. Next, we bound the policy optimization error in $\widetilde{M}$ in Theorem \ref{thm: M^tilde + general e}, which depends on the function class. Combining Theorem \ref{thm: final regret real M} and Theorem \ref{thm: M^tilde + general e}, we can prove our main Theorem \ref{thm: combined main thm} by carefully setting the stepsize.
In particular, we adopt linear sieves as our function class and establish the corresponding Theorem \ref{thm: M^tilde + sieve reg} to bound the policy optimization error.

\subsubsection{Proofs of Theorem \ref{thm: combined main thm}}


\begin{STheorem}
\label{thm: final regret real M}
Suppose Assumption~\ref{assumption: uncertainty quantifier} holds. Define $\widetilde{c}_k := \sum_{j=k}^K \|\overline{r}_j\|_\infty$, and let $\widetilde{r}_k := \widehat{r}_k - \widetilde{c}_k \Gamma_k$. Consider the modified model $\widetilde{M} = (\widehat{P}, \widetilde{r})$. Then, for any policy $\pi$, the following inequality holds with probability at least $1-K\delta$:
\begin{equation}
\label{eq:regret bound in thm S1}
   \left( V_{M^*}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^\dagger} \right) + \left( V_{\widetilde{M}}^{\pi} - V_{M^*}^{\pi} \right) \le V_{P^*, \underline{r}}^{\pi^\dagger}, 
\end{equation}
where $\underline{r}_k = b_k \Gamma_k$ and $b_k = 2 \widetilde{c}_k + \sum_{j=k+1}^K \widetilde{c}_j \|\Gamma_j\|_\infty.$ Here, $V_{P^*, \underline{r}}^{\pi^\dagger}$ denotes the value function of $\pi^\dagger$ under the DTR model with transition dynamics $\{P^*_k\}_{k=1}^K$ and stage-wise expected rewards $\{\underline{r}_k\}_{k=1}^K$.
\end{STheorem}

The proof of Theorem \ref{thm: final regret real M} relies on the following supporting lemmas. The proofs of these lemmas are deferred to {Section} \ref{pf:lemma them S1}.

\begin{lemma}[Simulation Lemma]
\label{lemma: simulation}
Consider two DTR models $M = (P, r)$ and $\widehat{M} = (\widehat{P}, r)$ that share the same reward function $r$. For any transition dynamics $P$, $\widehat{P}$, any policy $\pi$, any index $k$, and any pair $(h_k, a_k)$, the following identities hold:

\begin{itemize}
    \item[(i)] The difference in action-value functions satisfies:
    \begin{align*}
    &\quad Q_k^\pi(h_k, a_k) - \widehat{Q}_k^\pi(h_k, a_k) \\
    &= \sum_{t=k}^{K-1} \mathbb{E}_{(h_t, a_t) \sim d_{t,P}^\pi(\cdot,\cdot \mid H_k = h_k, A_k = a_k)} \left[
    \mathbb{E}_{h' \sim P_t(\cdot \mid h_t, a_t)} \left[ \widehat{V}_{t+1}^\pi(h') \right]
    - \mathbb{E}_{h' \sim \widehat{P}_t(\cdot \mid h_t, a_t)} \left[ \widehat{V}_{t+1}^\pi(h') \right]
    \right].
    \end{align*}

    \item[(ii)] The difference in state-value functions satisfies:
    \[
    V_k^\pi(h_k) - \widehat{V}_k^\pi(h_k) = \sum_{t=k}^{K-1} \mathbb{E}_{(h_t, a_t) \sim d_{t,P}^\pi(\cdot,\cdot \mid H_k = h_k)} \left[
    \mathbb{E}_{h' \sim P_t(\cdot \mid h_t, a_t)} \left[ \widehat{V}_{t+1}^\pi(h') \right]
    - \mathbb{E}_{h' \sim \widehat{P}_t(\cdot \mid h_t, a_t)} \left[ \widehat{V}_{t+1}^\pi(h') \right]
    \right].
    \]
\end{itemize}
\end{lemma}

\begin{lemma}[Reward Difference Lemma]
\label{lemma: r - rhat}
Under Assumption~\ref{assumption: uncertainty quantifier} and the reward setup in Section~\ref{sec: preliminary}, the following inequality holds with probability at least $1 - \delta$ (under $\mathbb{P}_{\mathcal{D}}$):
\[
\left| r_k(h_k, a_k) - \widehat{r}_k(h_k, a_k) \right| \le \| \overline{r}_k \|_\infty \cdot \Gamma_k(h_k, a_k), \quad \forall k,\ \forall (h_k, a_k) \in \mathcal{H}_k \times \mathcal{A}_k.
\]
\end{lemma}

\begin{proof}[Proof of Theorem \ref{thm: final regret real M}]

We begin by analyzing the difference between the values of policy $\pi$ under the modified model $\widetilde{M}$ and the true model $M^*$. Specifically, we decompose:
\[
\begin{aligned}
V_{\widetilde{M}}^{\pi} - V_{M^*}^{\pi}
&= V_{\widehat{P}, \widetilde{r}}^{\pi} - V_{P^*, r}^{\pi} \\
&= V_{\widehat{P}, r}^{\pi} - V_{P^*, r}^{\pi} - V_{\widehat{P}, \{\widetilde{c}_k \Gamma_k\}}^{\pi} + V_{\widehat{P}, \widehat{r} - r}^{\pi}.
\end{aligned}
\]
This expression follows from the definition $\widetilde{r}_k = \widehat{r}_k - \widetilde{c}_k \Gamma_k$ and the linearity of the value function in the reward.

To bound the term $V_{\widehat{P}, r}^{\pi} - V_{P^*, r}^{\pi}$, we invoke the \textit{simulation lemma} (Lemma~\ref{lemma: simulation}), which quantifies the impact of discrepancies in transition dynamics. Applying the lemma yields:
\begin{equation}
\label{eq: proof thm final regret M^*, eq 3}
    V_{\widehat{P},r}^{\pi} - V_{P^*,r}^{\pi}= \sum_{k=1}^{K-1} \mathbb{E}_{(h_k,a_k)\sim d_{k,\widehat{P}}^{\pi} (\cdot,\cdot)} \left[ \mathbb{E}_{h'\sim \widehat{P}_k(\cdot|h_k,a_k)}\left[ V_{k+1, P^*, r}^{\pi} (h') \right] - \mathbb{E}_{h'\sim P^*_k(\cdot|h_k,a_k)}\left[ V_{k+1, P^*, r}^{\pi} (h') \right] \right].
\end{equation}

This difference can be bounded via total variation and the value function norm:
$$
\begin{aligned}
   &\quad \mathbb{E}_{h' \sim \widehat{P}_k(\cdot \mid h_k, a_k)} \left[V_{k+1, P^*, r}^{\pi}(h')\right] -
\mathbb{E}_{h' \sim P_k^*(\cdot \mid h_k, a_k)} \left[V_{k+1, P^*, r}^{\pi}(h') \right]\\
&\le \|V_{k+1, P^*, r}^{\pi}(\cdot)\|_\infty \|\widehat{P}_k(\cdot \mid h_k, a_k) - P_k^*(\cdot \mid h_k, a_k)\|_1. 
\end{aligned}
$$
To control this, we further bound the supremum norm of the value function as:
\[
\|V_{k, r}(\cdot)\|_\infty \le \sum_{j=k}^{K} \|\overline{r}_j\|_\infty = \widetilde{c}_k.
\]

Substituting back, we obtain:
\begin{equation}
    \label{eq: proof thm final regret M^*, eq 4}
    \mathbb{E}_{h'\sim \widehat{P}_k(\cdot|h_k,a_k)}\left[ V_{k+1, P^*, r}^{\pi} (h') \right] - \mathbb{E}_{h'\sim P^*_k(\cdot|h_k,a_k)}\left[ V_{k+1, P^*, r}^{\pi} (h') \right] \leq \widetilde{c}_{k+1} \Gamma_k(h_k,a_k).
\end{equation}

Combining (\ref{eq: proof thm final regret M^*, eq 3}) and (\ref{eq: proof thm final regret M^*, eq 4}), and noting that $d_{k,\widehat{P}}^{\pi}$ is a non-negative distribution over histories and actions, we conclude:
\begin{equation*}
% \label{eq: proof thm final regret M^*, eq 5}
\begin{split}
V_{\widehat{P},r}^{\pi} - V_{P^*,r}^{\pi} &\le \sum_{k=1}^{K-1} \mathbb{E}_{(h_k,a_k)\sim d_{k,\widehat{P}}^{\pi} (\cdot,\cdot)} \left[ \widetilde{c}_{k+1} \Gamma_k(h_k,a_k) \right]\\
&\stackrel{(i)}{=} \sum_{k=1}^{K} \mathbb{E}_{(h_k,a_k)\sim d_{k,\widehat{P}}^{\pi} (\cdot,\cdot)} \left[ \widetilde{c}_{k+1} \Gamma_k(h_k,a_k) \right]\\
&\stackrel{(ii)}{=} V_{\widehat{P},\{\widetilde{c}_{k+1} \Gamma_k\}}^{\pi},
\end{split}
\end{equation*}
where $(i)$ follows by setting $\widetilde{c}_{K+1} = 0$ for completeness, and $(ii)$ uses the definition of the value function with structured reward $\{\widetilde{c}_{k+1} \Gamma_k\}$.

Substituting this into the earlier decomposition and regrouping the reward terms via linearity, we obtain:
\[
V_{\widetilde{M}}^{\pi} - V_{M^*}^{\pi} \le V_{\widehat{P}, \{\widetilde{c}_{k+1} \Gamma_k - \widetilde{c}_k \Gamma_k + \widehat{r}_k - r_k\}}^{\pi}.
\]

To further simplify this, observe that $\widetilde{c}_k - \widetilde{c}_{k+1} = \|\overline{r}_k\|_\infty$, and Lemma~\ref{lemma: r - rhat} implies that $\widehat{r}_k - r_k \le \|\overline{r}_k\|_\infty \Gamma_k$. Thus, $\widetilde{c}_{k+1} \Gamma_k - \widetilde{c}_k \Gamma_k + \widehat{r}_k - r_k \le 0,$
which leads to the inequality:
\begin{equation}
\label{eq:value negative}
V_{\widetilde{M}}^{\pi} - V_{M^*}^{\pi} \le 0.
\end{equation}
We now proceed to analyze the {first term} in \eqref{eq:regret bound in thm S1}, namely the gap between the optimal policy's performance under the true model $M^*$ and under the modified model $\widetilde{M}$: $V_{M^*}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^\dagger} = V_{P^*, r}^{\pi^\dagger} - V_{\widehat{P}, \widetilde{r}}^{\pi^\dagger}.$To handle this difference, we split it into two components:

\begin{equation}
\label{eq: proof thm final regret M^*, eq 7}
V_{M^*} ^{\pi^\dagger} -V_{\widetilde{M}} ^{\pi^\dagger} = V_{P^*, r} ^{\pi^\dagger} - V_{\widehat{P}, \widetilde{r}} ^{\pi^\dagger} = V_{P^*, r-\widetilde{r}} ^{\pi^\dagger} + \left(V_{P^*, \widetilde{r}} ^{\pi^\dagger} - V_{\widehat{P}, \widetilde{r}} ^{\pi^\dagger}\right).
\end{equation}

To control the latter one, we once again invoke the \emph{simulation lemma} (Lemma~\ref{lemma: simulation}), this time with fixed reward functions $\widetilde{r}$.
\begin{equation}
\label{eq: proof thm final regret M^*, eq 8}
 V_{P^*,\widetilde{r}} ^{\pi^\dagger} - V_{\widehat{P},\widetilde{r}} ^{\pi^\dagger} = \sum_{k=1}^{K-1} \mathbb{E}_{(h_k,a_k)\sim d_{k,P^*}^{\pi^\dagger} (\cdot,\cdot)} \left[ \mathbb{E}_{h'\sim P^*_k(\cdot|h_k,a_k)}\left[ V_{k+1, \widehat{P}, \widetilde{r}}^{\pi^\dagger} (h') \right] - \mathbb{E}_{h'\sim \widehat{P}_k(\cdot|h_k,a_k)}\left[ V_{k+1, \widehat{P}, \widetilde{r}}^{\pi^\dagger} (h') \right] \right].
\end{equation}

A key step is bounding the norm of the value function under $\widetilde{r}$. Recall that for any $k$, $\|V_{k, \widetilde{r}}(\cdot)\|_\infty \le \sum_{j=k}^K \|\widetilde{r}_j\|_\infty,$
then by Assumption \ref{assumption: uncertainty quantifier}, we get
\begin{equation*}
\begin{split}
&\quad \mathbb{E}_{h'\sim P^*_k(\cdot|h_k,a_k)}\left[ V_{k+1, \widehat{P}, \widetilde{r}}^{\pi^\dagger} (h') \right] - \mathbb{E}_{h'\sim \widehat{P}_k(\cdot|h_k,a_k)}\left[ V_{k+1, \widehat{P}, \widetilde{r}}^{\pi^\dagger} (h') \right]\\
&\le \| V_{k+1, \widehat{P}, \widetilde{r}}^{\pi^\dagger} (\cdot) \|_\infty \left\| \widehat{P}_k (\cdot|h_k,a_k) - P^*_k(\cdot |h_k,a_k) \right\|_1 \\
&\le \Bigl( \sum_{j=k+1}^K \|\widetilde{r}_j\|_\infty \Bigr) \Gamma_k(h_k,a_k)\\
&= \widetilde{q}_{k+1} \Gamma_k(h_k,a_k),
\end{split}
\end{equation*}
where $\widetilde{q}_{k} = \sum_{j=k}^K \|\widetilde{r}_j\|_\infty$. Then from (\ref{eq: proof thm final regret M^*, eq 8}), we further get:
\begin{equation*}
\begin{split}
V_{P^*,\widetilde{r}} ^{\pi^\dagger} - V_{\widehat{P},\widetilde{r}} ^{\pi^\dagger} &\le \sum_{k=1}^{K-1} \mathbb{E}_{(h_k,a_k)\sim d_{k,P^*}^{\pi^\dagger} (\cdot,\cdot)} \left[ \widetilde{q}_{k+1} \Gamma_k(h_k,a_k) \right]\\
&= \sum_{k=1}^{K} \mathbb{E}_{(h_k,a_k)\sim d_{k,P^*}^{\pi^\dagger} (\cdot,\cdot)} \left[ \widetilde{q}_{k+1} \Gamma_k(h_k,a_k) \right],
\end{split}
\end{equation*}
where the last step is because we define $\widetilde{q}_{K+1}=0$ for completeness.
Hence, the following important relation holds:
\begin{equation}
\label{eq: proof thm final regret M^*, eq 9}
V_{P^*,\widetilde{r}} ^{\pi^\dagger} - V_{\widehat{P},\widetilde{r}} ^{\pi^\dagger} \leq \sum_{k=1}^{K} \mathbb{E}_{(h_k,a_k)\sim d_{k,P^*}^{\pi^\dagger} (\cdot,\cdot)} \left[ \widetilde{q}_{k+1} \Gamma_k(h_k,a_k) \right]
\end{equation}

Note that the right hand side of (\ref{eq: proof thm final regret M^*, eq 9}) can be rewritten as a value function under $\pi^\dagger$ and $P^*$, with expected value function $\{ \widetilde{q}_{k+1} \Gamma_k\}_{k=1}^K$. Then we can plug (\ref{eq: proof thm final regret M^*, eq 9}) into (\ref{eq: proof thm final regret M^*, eq 7}), and combine them into one value function using the linearity of expected reward function:
\begin{equation}
\label{eq: proof thm final regret M^*, eq 10}
V_{M^*} ^{\pi^\dagger} -V_{\widetilde{M}} ^{\pi^\dagger} \le V^{\pi^\dagger} _{P^*, \{ r_k - \widetilde{r}_k + \widetilde{q}_{k+1} \Gamma_k \} }.
\end{equation}
%where
%\begin{equation}
%\label{eq: proof thm final regret M^*, eq 11}
%\underline{r}_k = r_k - \widetilde{r}_k + \widetilde{q}_{k+1} \Gamma_k.
%\end{equation}
To further simplify the reward difference term, we apply Lemma~\ref{lemma: r - rhat}, which bounds the deviation between the true reward and its estimated version:
\begin{equation*}
r_k - \widetilde{r}_k = r_k - \widehat{r}_k + \widetilde{c}_k \Gamma_k \le (\|\overline{r}_k\|_\infty + \widetilde{c}_k) \Gamma_k.
\end{equation*}
Adding the term $\widetilde{q}_{k+1} \Gamma_k$ to both sides yields:
\begin{equation*}
\begin{split}
r_k - \widetilde{r}_k + \widetilde{q}_{k+1} \Gamma_k &\le \Bigl( \|\overline{r}_k\|_\infty + \widetilde{c}_k + \widetilde{q}_{k+1} \Bigr) \Gamma_k \\
&\stackrel{(i)}{=} \Bigl( \|\overline{r}_k\|_\infty + \widetilde{c}_k + \sum_{j=k}^K \|\widetilde{r}_j\|_\infty \Bigr) \Gamma_k \\
&\stackrel{(ii)}{=} \Bigl( \|\overline{r}_k\|_\infty + \widetilde{c}_k + \sum_{j=k+1}^K \|\widehat{r}_j - \widetilde{c}_j \Gamma_j \|_\infty \Bigr) \Gamma_k \\
&\stackrel{(iii)}{\leq} \Bigl( \|\overline{r}_k\|_\infty + \widetilde{c}_k + \sum_{j=k+1}^K \|\overline{r}_j \|_\infty + \sum_{j=k+1}^K \widetilde{c}_j \| \Gamma_j \|_\infty \Bigr) \Gamma_k. 
\end{split}
\end{equation*}
$(i), (ii)$ come from the definition $\widetilde{q}_{k} = \sum_{j=k}^K \|\widetilde{r}_j\|_\infty 
 \text{ and }\|\widetilde{r}_j\|_\infty= \|\widehat{r}_j - \widetilde{c}_j \Gamma_j \|_\infty$. $(iii)$ is due to triangle inequality. 

Since $\widetilde{c}_k = \sum_{j=k}^K \|\overline{r}_j\|_\infty$, we can simplify the bound as:
\begin{equation}
\label{eq: proof thm final regret M^*, eq 11}
 r_k - \widetilde{r}_k + \widetilde{q}_{k+1} \Gamma_k \leq   \Bigl( 2 \widetilde{c}_k + \sum_{j=k+1}^K \widetilde{c}_j \| \Gamma_j \|_\infty \Bigr) \Gamma_k
\end{equation}


Combining \eqref{eq: proof thm final regret M^*, eq 10} and \eqref{eq: proof thm final regret M^*, eq 11}, we have:
\begin{equation}
\label{eq: value DTR bound}
    V_{M^*} ^{\pi^\dagger} -V_{\widetilde{M}} ^{\pi^\dagger} \le V^{\pi^\dagger} _{P^*, \underline{r}},
\end{equation}
where we define $\underline{r}_k := \left( 2 \widetilde{c}_k + \sum_{j=k+1}^K \widetilde{c}_j \| \Gamma_j \|_\infty \right) \Gamma_k$.

Finally, we complete the proof by combining \eqref{eq:value negative} and \eqref{eq: value DTR bound}.


\end{proof}

\begin{STheorem}
\label{thm: M^tilde + general e}
Suppose Assumption~\ref{assumption: sup norm of e} holds, and let $\widetilde{M} = (\widehat{P}, \widetilde{r})$ be the modified DTR model constructed in Algorithm~\ref{algo: general}. Assume that the step sizes are constant over iterations, i.e., $\eta_k^{(t)} = \eta_k$ for all $t$. Then, Algorithm~\ref{algo: general} returns a policy $\pi^{(T)}$ that satisfies the following performance guarantee:
\begin{equation*}
V_{\widetilde{M}}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^{(T)}} \le \sum_{k=1}^K \left( \frac{\log |\mathcal{A}_k|}{\eta_k T} + \frac{\eta_k}{2} \widetilde{q}_k^2 + \frac{2}{\eta_k} \mathcal{O}_P(G_k) + \frac{T}{8\eta_k} \mathcal{O}_P(G_k^2) \right),
\end{equation*}
where $\widetilde{q}_k := \sum_{j=k}^K \|\widetilde{r}_j\|_\infty$ denotes the cumulative reward supremum norm from stage $k$ onward.
\end{STheorem}

The proof of Theorem \ref{thm: M^tilde + general e} relies on the following supporting lemmas. The proofs of these lemmas can be found in Section \ref{pf:lemma them S2}.

\begin{lemma}[Performance Difference Lemma]
\label{lemma: perf diff}
Let $P$ be the transition dynamics of a fixed DTR model. For any two policies $\pi$ and $\widehat{\pi}$, the following holds for any stage $k$ and any history $h_k$:
\begin{equation*}
\begin{aligned}
V_k^\pi(h_k) - V_k^{\widehat{\pi}}(h_k)
&= \sum_{t=k}^K \mathbb{E}_{(h_t, a_t) \sim d_t^\pi(\cdot,\cdot \mid H_k = h_k)} \left[ A_t^{\widehat{\pi}}(h_t, a_t) \right] \\
&= \sum_{t=k}^K \mathbb{E}_{h_t \sim d_t^\pi(\cdot \mid H_k = h_k)} \left\langle Q_t^{\widehat{\pi}}(h_t, \cdot),\ \pi_t(\cdot \mid h_t) - \widehat{\pi}_t(\cdot \mid h_t) \right\rangle,
\end{aligned}
\end{equation*}
where $A_t^{\widehat{\pi}}(h_t, a_t) := Q_t^{\widehat{\pi}}(h_t, a_t) - V_t^{\widehat{\pi}}(h_t)$ is the advantage function of policy $\widehat{\pi}$ at step $t$.
\end{lemma}

\begin{lemma}
\label{lemma: 3 KL terms}
For any $1\le k\le K$, suppose $\theta_k, \theta'_k \in \Theta_k$, $\pi_k(\theta_k)$ and $\pi_k(\theta'_k)$ are two policies in the policy class $\Pi_k$ defined in (\ref{eq: policy class}). Let $p(\cdot)$ be any probability distribution on $\mathcal{A}_k$. Then for any $h_k\in \mathcal{H}_k$, we have
\begin{equation*}
\begin{split}
& \quad\operatorname{KL}(p,\pi_k(h_k, \theta_k)) - \operatorname{KL}(p,\pi_k(h_k, \theta'_k)) - \operatorname{KL}(\pi_k(h_k, \theta'_k), \pi_k(h_k, \theta_k)) \\
&= \Bigl\langle f_k(\theta'_k, h_k,\cdot)-f_k(\theta_k, h_k,\cdot),\ p(\cdot)-\pi_k(\cdot|h_k, \theta'_k) \Bigr\rangle.
\end{split}
\end{equation*}
\end{lemma}

\begin{lemma}
\label{lemma: <Q,pi_t+1 - pi_t>}
For any $0\le t\le T-1$, $1\le k\le K$, and any $h_k\in \mathcal{H}_k$, we have
\begin{equation*}
\Bigl\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot), \pi_k(\cdot|h_k, \theta_k^{(t+1)}) - \pi_k(\cdot|h_k, \theta_k^{(t)}) \Bigr\rangle + \frac{1}{4 \eta_k^{(t)}} \|e^{(t)}_k(h_k,\cdot)\|_\infty^2 \ge 0.
\end{equation*}
\end{lemma}

\begin{lemma}
\label{lemma: <Q,pi* - pi_t>}
For any $0 \le t \le T-1$, $1 \le k \le K$, and any $h_k \in \mathcal{H}_k$, we have:
\begin{equation*}
\begin{split}
\left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t)}(\cdot|h_k) \right\rangle 
\le\ & \frac{1}{\eta_k^{(t)}} \left[ \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t)}(h_k)) - \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t+1)}(h_k)) \right] \\
& + \frac{\eta_k^{(t)}}{2} \left\| Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot) \right\|_\infty^2 + \frac{2}{\eta_k^{(t)}} \left\| e_k^{(t)}(h_k,\cdot) \right\|_\infty.
\end{split}
\end{equation*}
\end{lemma}



\begin{proof}[Proof of Theorem \ref{thm: M^tilde + general e}]
By the performance difference lemma (Lemma~\ref{lemma: perf diff}), we have
\begin{equation*}
V_{1, \widetilde{M}}^{\pi^\dagger}(h_1) - V_{1, \widetilde{M}}^{\pi^{(t)}}(h_1) = \sum_{k=1}^K \mathbb{E}_{h_k \sim d_k^{\pi^\dagger}(\cdot | H_1 = h_1)} \left\langle Q_{k, \widetilde{M}}^{\pi^{(t)}}(h_k,\cdot),\ \pi_k^\dagger(\cdot | h_k) - \pi_k^{(t)}(\cdot | h_k) \right\rangle.
\end{equation*}
Taking expectation over \( h_1 \sim \mu_1 \), we obtain:
\begin{equation*}
V_{1, \widetilde{M}}^{\pi^\dagger}(\mu_1) - V_{1, \widetilde{M}}^{\pi^{(t+1)}}(\mu_1) = \sum_{k=1}^K \mathbb{E}_{h_k \sim d_k^{\pi^\dagger}} \left\langle Q_{k, \widetilde{M}}^{\pi^{(t+1)}}(h_k,\cdot),\ \pi_k^\dagger(\cdot | h_k) - \pi_k^{(t+1)}(\cdot | h_k) \right\rangle.
\end{equation*}
Summing over \( t = 0, 1, \dots, T-1 \), we have:
\begin{equation}
\label{eq:sum over}
\sum_{t=0}^{T-1} \left(V_{\widetilde{M}}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^{(t+1)}}\right) = \sum_{k=1}^K \mathbb{E}_{h_k \sim d_k^{\pi^\dagger}} \sum_{t=0}^{T-1} \left\langle Q_{k, \widetilde{M}}^{\pi^{(t+1)}}(h_k,\cdot),\ \pi_k^\dagger(\cdot | h_k) - \pi_k^{(t+1)}(\cdot | h_k) \right\rangle.
\end{equation}

Using Lemma~\ref{lemma: <Q,pi* - pi_t>}, we upper bound each inner product by:
\begin{equation}
\label{lemma 6 <,>}
\begin{split}
\left\langle Q_{k, \widetilde{M}}^{\pi^{(t+1)}}(h_k,\cdot), \pi_k^\dagger(\cdot | h_k) - \pi_k^{(t+1)}(\cdot | h_k) \right\rangle
\le & \frac{1}{\eta_k} \left[\mathrm{KL}(\pi_k^\dagger(h_k), \pi_k^{(t+1)}) - \mathrm{KL}(\pi_k^\dagger(h_k), \pi_k^{(t+2)}) \right] \\
&+ \frac{\eta_k}{2} \|Q_{k, \widetilde{M}}^{\pi^{(t+1)}}(h_k, \cdot)\|_\infty^2 + \frac{2}{\eta_k} \|e_k^{(t+1)}(h_k, \cdot)\|_\infty.
\end{split}
\end{equation}

Substituting \eqref{lemma 6 <,>} into \eqref{eq:sum over}, we obtain three additive terms that we now upper bound individually. First, the KL divergence term forms a telescoping sum over iterations, which simplifies to
\[
\sum_{t=0}^{T-1} \frac{1}{\eta_k} \left[ \mathrm{KL}(\pi_k^\dagger(h_k), \pi_k^{(t+1)}) - \mathrm{KL}(\pi_k^\dagger(h_k), \pi_k^{(t+2)}) \right] \le \frac{\log |\mathcal{A}_k|}{\eta_k},
\]
since the KL-divergence is non-negative.


Second, the sum of squared Q-values across iterations is bounded as
\[
\sum_{t=0}^{T-1} \frac{\eta_k}{2} \left\| Q_{k,\widetilde{M}}^{\pi^{(t+1)}}(h_k, \cdot) \right\|_\infty^2 \le \frac{\eta_k}{2} T \widetilde{q}_k^2,
\quad \text{where} \quad \widetilde{q}_k := \sum_{j=k}^K \| \widetilde{r}_j \|_\infty.
\]
Finally, the model error accumulates linearly over time and is controlled via the bound
\[
\sum_{t=0}^{T-1} \frac{2}{\eta_k} \left\| e_k^{(t+1)}(h_k, \cdot) \right\|_\infty \le \frac{2T}{\eta_k} \mathcal{O}_P(G_k).
\]
Combining these three bounds yields a total regret bound:
\begin{equation}
\label{eq: proof thm M^tilde + general e, eq 4}
\sum_{t=0}^{T-1} \left(V_{\widetilde{M}}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^{(t+1)}}\right) \le \sum_{k=1}^K \left( \frac{\log |\mathcal{A}_k|}{\eta_k} + \frac{\eta_k}{2} T \widetilde{q}_k^2 + \frac{2T}{\eta_k} \mathcal{O}_P(G_k) \right).
\end{equation}

We now use Lemma~\ref{lemma: <Q,pi_t+1 - pi_t>}, which implies:
\begin{equation}
\label{eq: proof thm M^tilde + general e, eq 5}
V_{\widetilde{M}}^{\pi^{(t)}} - V_{\widetilde{M}}^{\pi^{(t+1)}} \le \sum_{k=1}^K \frac{1}{4\eta_k} \mathcal{O}_P(G_k^2).
\end{equation}
For any \( t \in \{0, \dots, T-1\} \), it follows that:
\begin{equation}
\label{eq: proof thm M^tilde + general e, eq 6}
V_{\widetilde{M}}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^{(T)}} \le V_{\widetilde{M}}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^{(t+1)}} + (T-1-t) \sum_{k=1}^K \frac{1}{4\eta_k} \mathcal{O}_P(G_k^2).
\end{equation}

Summing \eqref{eq: proof thm M^tilde + general e, eq 6} over all \( t = 0, \dots, T-1 \), and using \eqref{eq: proof thm M^tilde + general e, eq 4}, we get:
\begin{equation*}
T \left(V_{\widetilde{M}}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^{(T)}}\right) \le \sum_{k=1}^K \left( \frac{\log |\mathcal{A}_k|}{\eta_k} + \frac{\eta_k}{2} T \widetilde{q}_k^2 + \frac{2T}{\eta_k} \mathcal{O}_P(G_k) + \frac{T^2}{8\eta_k} \mathcal{O}_P(G_k^2) \right).
\end{equation*}

Dividing both sides by \( T \) completes the proof.
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm: combined main thm}]
From Theorem \ref{thm: M^tilde + general e}, we have
\begin{equation*}
V_{\widetilde{M}}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^{(T)}} \le \sum_{k=1}^K \left( \frac{\log |\mathcal{A}_k|}{\eta_k T} + \frac{\eta_k}{2} (\widetilde{q}_k)^2 + \frac{2}{\eta_k} \mathcal{O}_P(G_k) + \frac{T}{4\eta_k} \mathcal{O}_P(G_k^2) \right).
\end{equation*}

We next invoke Theorem \ref{thm: final regret real M}, which ensures that, with probability at least $1 - K\delta$,
\begin{equation*}
\left( V_{M^*}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^\dagger} \right) + \left( V_{\widetilde{M}}^{\pi^{(T)}} - V_{M^*}^{\pi^{(T)}} \right) \le V^{\pi^\dagger}_{P^*, \underline{r}}.
\end{equation*}

Combining the two inequalities yields:
\begin{equation*}
V_{M^*}^{\pi^\dagger} - V_{M^*}^{\pi^{(T)}} 
\le V^{\pi^\dagger}_{P^*, \underline{r}} + \sum_{k=1}^K \left( \frac{\log |\mathcal{A}_k|}{\eta_k T} + \frac{\eta_k}{2} (\widetilde{q}_k)^2 + \frac{2}{\eta_k} \mathcal{O}_P(G_k) + \frac{T}{4\eta_k} \mathcal{O}_P(G_k^2) \right),
\end{equation*}
which holds with probability at least $1 - K\delta$.

Finally, by setting $\eta_k = \frac{c_{\eta}}{\sqrt{T}}$ in Theorem \ref{thm: M^tilde + general e}, the desired bound follows directly.
\end{proof}

\subsubsection{Proof of Proposition \ref{prop: G_k}}
\label{subsub:pf prop}
To ensure effective approximation of the Q-function,
we adopt the B-splines as the function basis $\Upsilon_{L_k}(\cdot) = \{\upsilon_{L_k,1}(\cdot), \upsilon_{L_k,2}(\cdot), ..., \upsilon_{L_k,L_k}(\cdot)\} ^T.$ The well-definedness of the B-spline functions requires the following assumption on state spaces.

\begin{SAssumption}
\label{assumption: state space is rectangular}
For any $1\le k\le K$, the $k$-th state space $\mathcal{S}_k$ is the Cartesian product of $d_k^{(s)}$ compact and non-degenerate intervals, i.e. $\mathcal{S}_k$ is a rectangle in $\mathbb{R}^{d_k^{(s)}}$ with a nonempty interior.
\end{SAssumption}

We also need to impose assumptions on the target function $Q_{k, \widetilde{M}} ^{\pi^{(t)}}$ so that our selected function class has sufficient representation power. In this case, we present a series of technical assumptions regarding the modified DTR model $\widetilde{M}$.
\begin{SAssumption}[$p$-smoothness of the modified reward]
\label{assumption: reward is p-smooth} 
For any $1\le k\le K$, any fixed $(a_1,...,a_k) \in \mathcal{A}_1 \times \cdots \times \mathcal{A}_k$, the modified reward $\widetilde{r}_k (h_k, a_k) = \widetilde{r}_k (s_1, a_1,..., s_k, a_k)$ as a function of $(s_1,s_2,...,s_k)$ is $p$-smooth in $(s_1,s_2,...,s_k)$.
\end{SAssumption}

The smoothness assumption can also be found in \cite{Huang1998, chen2007large} . See Supplement \ref{subsec:p-smooth} for a detailed description of $p-$smoothness. 
We assume the modified expected reward function, the transition dynamics in the model class, and the policies in the policy class are all $p$-smooth in some certain sense.

\begin{SAssumption}[$p$-smoothness of transition density]
\label{assumption: transition is p-smooth} 
For any $1\le k\le K$, any $P_k\in \mathcal{P}_k$, any $h_k\in \mathcal{H}_k$, there exists transition density $p_k(\cdot|h_k,a_k)$ such that $P_k(\mathrm{d} s |h_k,a_k) = p_k(s|h_k,a_k) \mathrm{d} s$.
  Furthermore, for any fixed $(a_1,...,a_k) \in \mathcal{A}_1 \times \cdots \times \mathcal{A}_k$, the transition density $p_k(s_{k+1}| h_k,a_k) = p_k(s_{k+1}| s_1,a_1,..., s_k,a_k)$ as a function of $(s_1,s_2,..., s_k, s_{k+1})$ is $p$-smooth in $(s_1,s_2,..., s_{k+1})$.
\end{SAssumption}
This assumption can be satisfied if the policy class $\mathcal{P}_k$ belongs to the class of absolutely continuous distributions.

\begin{SAssumption} [$p$-smoothness of policy]
\label{assumption: policy is p-smooth}
For any $\pi \in \Pi$, any $1\le k\le K$, any fixed $(a_1,...,a_k) \in \mathcal{A}_1 \times \cdots \times \mathcal{A}_k$, the probability $\pi_k (a_k| h_k) = \pi_k (a_k| s_1, a_1,..., s_k)$ as a function of $(s_1,s_2,...,s_k)$ is $p$-smooth in $(s_1,s_2,...,s_k)$.
\end{SAssumption}

% Note that line 9 of Algorithm \ref{algo: sieve regression} may suffer from Monte Carlo error, making the $\widehat{Q}_k^{(t)}$ in Line 10 of Algorithm \ref{algo: sieve regression} is not exactly same as the function $Q_{k, \widetilde{M}} ^{\pi^{(t)}}$ that we want to approximate. 

The Monte Carlo approximation error from line 9-10 of Algorithm \ref{algo: sieve regression} is defined as $\epsilon_k^{(i)}(t, \overline{a}_k) = \widehat{Q}_k^{(t)} (\overline{s}_k^{(i)}, \overline{a}_k) - Q_{k, \widetilde{M}} ^{\pi^{(t)}} (\overline{s}_k^{(i)}, \overline{a}_k)$. We need to restrict these errors by the following assumption. For notational simplicity, we fix $t$ and $\overline{a}_k$, and denote $\epsilon_k^{(i)}$ as the shorthand for $\epsilon_k^{(i)}(t, \overline{a}_k)$.
\begin{SAssumption}
\label{assumption: MC error}
For any fixed $t$ and fixed $\overline{a}_k$, the $m_k$ error terms $\epsilon_k^{(1)}, ..., \epsilon_k^{(m_k)}$ defined above satisfy 
\begin{enumerate}
    \item $\mathbb{E}[\epsilon_k^{(i)} \mid \overline{s}_k^{(i)}] = 0$, and $(\overline{s}_k^{(1)}, \epsilon_k^{(1)}), ..., (\overline{s}_k^{(m_k)}, \epsilon_k^{(m_k)})$ are i.i.d.
    \item $\mathbb{E}[ (\epsilon_k^{(i)} )^2 \mid \overline{s}_k^{(i)}]$ are uniformly bounded for all $i$ almost surely.
    \item $\mathbb{E}[ (\epsilon_k^{(i)} )^{2+\delta_k} ] < \infty$ for some $\delta_k>0.$
\end{enumerate}
\end{SAssumption}


\begin{STheorem}
\label{thm: M^tilde + sieve reg} \textbf{[Proposition \ref{prop: G_k} Restated] }Suppose \(\widetilde{M}=(\widehat{P},\widetilde{r})\) is the modified DTR model constructed in Algorithm~\ref{algo: sieve regression}, and that Assumptions~\ref{assumption: state space is rectangular},~\ref{assumption: reward is p-smooth},~\ref{assumption: transition is p-smooth},~\ref{assumption: policy is p-smooth}, and~\ref{assumption: MC error} hold. Let \(\eta_k^{(t)} = \frac{\sqrt{ \log |\mathcal{A}_k|}}{ \widetilde{q}_k \sqrt{T} }\), constant in \(t\). If \(L_k \asymp \left(\frac{m_k}{\log m_k}\right)^{\overline{d}_k /(2p+\overline{d}_k)}\) and \(p \delta_k \ge \overline{d}_k\), then Algorithm~\ref{algo: sieve regression} returns a policy \(\pi^{(T)}\) satisfying:
\begin{equation*}
V_{ \widetilde{M}}^{\pi^\dagger} - V_{ \widetilde{M}}^{\pi^{(T)}} =  \mathcal{O} \left( \frac{K}{\sqrt{T}} \right) + K \sqrt{T} \cdot \mathcal{O}_p\left( \left( \frac{\log m_k}{m_k} \right)^ {2p/ (2p+\overline{d}_k)} \right)
\end{equation*}
as \(m_k, L_k \to \infty\), where \(\widetilde{q}_k := \sum_{j=k}^K \|\widetilde{r}_j\|_\infty\), and \(\overline{d}_k = \dim(\mathcal{S}_1 \times \cdots \times \mathcal{S}_k)\).
\end{STheorem}

The proof of Theorem \ref{thm: M^tilde + sieve reg} relies on the following auxiliary lemma.
\begin{lemma}
\label{lemma: upperbound e}
Suppose Assumptions \ref{assumption: state space is rectangular}, \ref{assumption: reward is p-smooth}, \ref{assumption: transition is p-smooth}, \ref{assumption: policy is p-smooth}, and \ref{assumption: MC error} hold. If $L_k \asymp \left(\frac{m_k}{\log m_k}\right)^{\overline{d}_k /(2p+\overline{d}_k)}$ and $p \delta_k \ge \overline{d}_k$, then
\[
\frac{1}{ \eta_k^{(t)} \| Q_{k,\widetilde{M}}^{\pi^{(t)}} \|_\infty } \sup_{(h_k,a_k)} \left| e^{(t)}_k(h_k,a_k) \right| = \mathcal{O}_P\left( \left( \frac{\log m_k}{m_k} \right)^ {p/ (2p+\overline{d}_k)} \right),
\]
as $m_k, L_k \to \infty$, where $\overline{d}_k = \dim(\mathcal{S}_1 \times \mathcal{S}_2 \times \cdots \times \mathcal{S}_k)$.
\end{lemma}
The proof of Lemma \ref{lemma: upperbound e} can be found in Section \ref{subsec:p-smooth}.
\begin{proof}[Proof of Theorem~\ref{thm: M^tilde + sieve reg}]
We follow the proof of Theorem~\ref{thm: M^tilde + general e}, as Algorithm~\ref{algo: sieve regression} is a special version of Algorithm~\ref{algo: general}. All previous results that do not rely on Assumption~\ref{assumption: sup norm of e} still hold. Similarly to \eqref{eq: proof thm M^tilde + general e, eq 4}, we obtain that:
\begin{equation}
\label{eq: proof thm M^tilde + sieve reg, eq 1}
\sum_{t=0}^{T-1} \left( V_{1, \widetilde{M}}^{\pi^\dagger}(\mu_1) - V_{1, \widetilde{M}}^{\pi^{(t+1)}}(\mu_1) \right) \le \sum_{k=1}^K \frac{\log |\mathcal{A}_k|}{\eta_k} + \sum_{k=1}^K \frac{\eta_k}{2} T (\widetilde{q}_k)^2 + \sum_{k=1}^K \sum_{t=0}^{T-1} \frac{2}{\eta_k} \sup_{(h_k,a_k)} |e^{(t)}_k(h_k,a_k)|.
\end{equation}
We also adapt the analysis in equations~\eqref{eq: proof thm M^tilde + general e, eq 5} and~\eqref{eq: proof thm M^tilde + general e, eq 6}, retaining all terms involving \(e_k^{(t)}\):
\begin{equation}
\label{eq: proof thm M^tilde + sieve reg, eq 2}
\begin{split}
V_{1, \widetilde{M}}^{\pi^\dagger}(\mu_1) - V_{1, \widetilde{M}}^{\pi^{(T)}}(\mu_1) 
&\le V_{1, \widetilde{M}}^{\pi^\dagger}(\mu_1) - V_{1, \widetilde{M}}^{\pi^{(t+1)}}(\mu_1) + \sum_{j=t+1}^{T-1} \sum_{k=1}^K \frac{1}{4 \eta_k} \left( \sup_{(h_k,a_k)} |e^{(j)}_k(h_k,a_k)| \right)^2.
\end{split}
\end{equation}
Summing \eqref{eq: proof thm M^tilde + sieve reg, eq 2} over \(t = 0, \ldots, T-1\) and combining with \eqref{eq: proof thm M^tilde + sieve reg, eq 1}, we obtain:
\begin{equation}
\label{eq: proof thm M^tilde + sieve reg, eq 3}
\begin{split}
T(V_{1, \widetilde{M}}^{\pi^\dagger}(\mu_1) - V_{1, \widetilde{M}}^{\pi^{(T)}}(\mu_1)) 
&\le \sum_{k=1}^K \left( \frac{\log |\mathcal{A}_k|}{\eta_k} + \frac{\eta_k}{2} T (\widetilde{q}_k)^2 \right) + \sum_{k=1}^K \sum_{t=0}^{T-1} \frac{2}{\eta_k} \sup_{(h_k,a_k)} |e^{(t)}_k(h_k,a_k)| \\
&\quad + \sum_{j=1}^{T-1} \sum_{t=0}^{j} \sum_{k=1}^K \frac{1}{4 \eta_k} \left( \sup_{(h_k,a_k)} |e^{(j)}_k(h_k,a_k)| \right)^2.
\end{split}
\end{equation}
By Lemma~\ref{lemma: upperbound e}, and the fact that \(\| Q_{k,\widetilde{M}}^{\pi^{(t)}} \|_\infty \le \widetilde{q}_k\), we have:
\begin{equation}
\label{eq: proof thm M^tilde + sieve reg, eq 5}
\sup_{(h_k,a_k)} |e^{(t)}_k(h_k,a_k)| \le \eta_k \widetilde{q}_k \mathcal{O}_p\left( \left( \frac{\log m_k}{m_k} \right)^ {p/ (2p+\overline{d}_k)} \right).
\end{equation}
Substituting~\eqref{eq: proof thm M^tilde + sieve reg, eq 5} into~\eqref{eq: proof thm M^tilde + sieve reg, eq 3}, and simplifying yields the desired bound:
\begin{equation*}
V_{1, \widetilde{M}}^{\pi^\dagger}(\mu_1) - V_{1, \widetilde{M}}^{\pi^{(T)}}(\mu_1) = \mathcal{O}\left(\frac{K}{\sqrt{T}}\right) + K\sqrt{T}\cdot \mathcal{O}_p\left(\left(\frac{\log m_k}{m_k}\right)^{2p/(2p+\overline{d}_k)}\right).
\end{equation*}
\end{proof}

\subsection{Proof of Theorem \ref{thm: suboptimality for linear} in Section \ref{sec:linear model}}
\label{proof:linear}
To establish Theorem~\ref{thm: suboptimality for linear}, we impose two assumptions to govern the growth rate of the feature dimensions and bound the magnitude of the feature mappings.
\begin{SAssumption}
\label{assumption: sample complexity linear}
There exist constants $c_1$, $c_2$ such that the following two conditions hold for all $1\le k\le K$:
(i) $dim(\mathcal{S}_k) \le c_1$; (ii) $d_k^{(s)} \le c_2 k$.
\end{SAssumption}
Assumption \ref{assumption: sample complexity linear} (i) trivially holds because $K$ is finite. Therefore, $dim(\mathcal{S}_k) = \mathcal{O}(1)$, which further implies $dim(\mathcal{H}_k \times \mathcal{A}_k) = k+\sum_{j=1}^k dim(\mathcal{S}_j) = \mathcal{O}(k)$. Recall that $\phi_k: \mathcal{H}_k \times \mathcal{A}_k \to \mathbb{R}^{d_k^{(s)}}$, so Assumption \ref{assumption: sample complexity linear} (ii) is a mild condition that naturally requires the feature mapping $\phi_k$ to reserve the dimensional structure of $\mathcal{H}_k \times \mathcal{A}_k$.

\begin{SAssumption}[Uniformly Bounded Features]\label{assump:bounded-features}
The feature map 
\(
  \phi_k:\mathcal H_k\times\mathcal A_k\to \mathbb{R}^{d_k^{(s)}}
\)
is uniformly bounded. There exists a constant \(R > 0\) such that
\[
  \|\phi_k(h,a)\|_2^2 \;\le\; R^2 d_k^{(s)},
  \quad \text{for all }(h,a)\in\mathcal H_k\times\mathcal A_k.
\]
\end{SAssumption}

This assumption is standard in high-dimensional regression \citep{Wainwright2019,jin2019provablyefficientreinforcementlearning,Abbasi-Yadkori2011}, which ensures that our uncertainty quantifiers of the linear transition model are well-controlled.

Before proceeding to the main proof, we state a key corollary that upper bounds the model shift error of our linear transition model under the above assumptions.

\begin{Scorollary}
\label{cor: partial coverage linear}
Suppose Assumption \ref{assumption: partial coverage linear} holds under the setting of Theorem \ref{thm: final regret real M}. If $\widehat{W}_k$ and $\Gamma_k$ follow the form in (\ref{eq: KNR, W hat}) and (\ref{eq: KNR, Gamma}) respectively, 
%Let $\widetilde{M} = (\widehat{P}, \widetilde{r})$, 
then for any policy $\pi$, the following inequality holds with probability at least $1-K\delta$:
$$\left( V_{M^*} ^{\pi^\dagger} -V_{\widetilde{M}} ^{\pi^\dagger} \right) + \left( V_{\widetilde{M}}^{\pi} -V_{M^*}^{\pi} \right) \lesssim   {\mathcal{O}}\left( \frac{K^3\sqrt{\log n}}{\sqrt{n}} + \frac{K^5}{n} \right).$$
\end{Scorollary}

\begin{proof}[Proof of Corollary~\ref{cor: partial coverage linear}]
By Theorem~\ref{thm: uncertainty quantifier KNR}, the estimators $\widehat{W}_k$ and the associated uncertainty quantifiers $\Gamma_k$ constructed via (\ref{eq: KNR, W hat}) and (\ref{eq: KNR, Gamma}) satisfy Assumption~\ref{assumption: uncertainty quantifier}. Consequently, applying Theorem~\ref{thm: final regret real M}, we obtain that with probability at least $1 - K\delta$,
\begin{equation}
\label{eq:cor_partial_coverage_regret}
\left( V_{M^*}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^\dagger} \right) + \left( V_{\widetilde{M}}^{\pi} - V_{M^*}^{\pi} \right)
\le \sum_{k=1}^K b_k \, \mathbb{E}_{(h_k,a_k) \sim d_{P^*,k}^{\pi^\dagger}} \Gamma_k(h_k,a_k),
\end{equation}
where $b_k = 2\widetilde{c}_k + \sum_{j=k+1}^K \widetilde{c}_j \|\Gamma_j\|_\infty$ and $\widetilde{c}_k = \sum_{j=k}^K \|\overline{r}_j\|_\infty$.

To bound the right-hand side of \eqref{eq:cor_partial_coverage_regret}, we begin by analyzing the behavior of the uncertainty quantifier $\Gamma_k(h_k, a_k)$ defined in~(\ref{eq: KNR, Gamma}). Recall that
\begin{equation*}
\Gamma_k(h_k,a_k) \le 2 B_{d_{k+1}^{(s)}} \sigma C_L \, \beta_{k,n} \sqrt{ \phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k)},
\end{equation*}
where $\sigma$ and $C_L$ are fixed constants, and $B_{d_{k+1}^{(s)}} = \pi^{d_{k+1}^{(s)}/2} / \Gamma(d_{k+1}^{(s)}/2 + 1)$ denotes the Lebesgue measure of the unit ball in $\mathbb{R}^{d_{k+1}^{(s)}}$. Noting that $B_{d_{k+1}^{(s)}} \le 1$, we simplify the expression as $\Gamma_k(h_k,a_k) \lesssim \beta_{k,n} \sqrt{ \phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k)}$. The scaling factor $\beta_{k,n}$ is defined in~(\ref{eq: KNR, eq 2}) as
\[
\beta_{k,n} = \sqrt{\lambda} \|W^*_k\|_2 + \sqrt{8\sigma^2 d_{k+1}^{(s)} \log(5) + 8\sigma^2 \log \left( \frac{\det (\Lambda_{k,n})^{1/2}}{\det (\lambda I)^{1/2} \, \delta} \right)}.
\]

Since $\Lambda_{k,n}$ is the regularized empirical covariance matrix based on $n$ i.i.d.\ samples, we have $\det(\Lambda_{k,n}) = \mathcal{O}(n^{d_k^{(s)}})$. Therefore, under Assumption~\ref{assumption: sample complexity linear} (ii), it follows that $\beta_{k,n} \lesssim \sqrt{d_k^{(s)} \log n} \lesssim \sqrt{k \log n}$. Therefore,
\begin{equation}
\label{eq:Gamma_bound}
\Gamma_k(h_k,a_k) \lesssim \sqrt{k \log n} \cdot \sqrt{ \phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k)}.
\end{equation}

Taking expectation under $d_{P^*,k}^{\pi^\dagger}$ in \eqref{eq:Gamma_bound}, and applying Jensen's inequality to the concave square root function, yields
\begin{equation}
\label{eq:Gamma_expectation_bound}
\mathbb{E}_{(h_k,a_k) \sim d_{P^*,k}^{\pi^\dagger}} \Gamma_k(h_k,a_k)
\lesssim \sqrt{ k\log n \cdot \mathbb{E}_{(h_k,a_k) \sim d_{P^*,k}^{\pi^\dagger}} \phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k) }.
\end{equation}

To bound the quadratic form inside the square root, observe that $\Lambda_{k,n}^{-1}$ is symmetric positive definite, and thus admits the eigendecomposition $\Lambda_{k,n}^{-1} = \sum_{i=1}^{d_k^{(s)}} \lambda_i u_i u_i^\top$. By Assumption~\ref{assumption: partial coverage linear}, for any eigenvector $u_i$,
\[
\mathbb{E}_{(h_k,a_k) \sim d_{P^*,k}^{\pi^\dagger}} (u_i^\top \phi_k(h_k,a_k))^2 \le C_k \cdot \mathbb{E}_{(h_k,a_k) \sim \rho_k} (u_i^\top \phi_k(h_k,a_k))^2,
\]
This yields 
\begin{align*}
\mathbb{E}_{(h_k,a_k)\sim d_{P^*,k}^{\pi^\dagger}} \phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k)
&= \sum_{i=1}^{d_k^{(s)}} \lambda_i \, \mathbb{E}_{(h_k,a_k)\sim d_{P^*,k}^{\pi^\dagger}} \left[ (u_i^\top \phi_k(h_k,a_k))^2 \right] \nonumber \\
&\le C_k \sum_{i=1}^{d_k^{(s)}} \lambda_i \, \mathbb{E}_{(h_k,a_k)\sim \rho_k} \left[ (u_i^\top \phi_k(h_k,a_k))^2 \right] \nonumber \\
&= C_k \cdot \mathrm{Tr}\left( \Psi_k \Lambda_{k,n}^{-1} \right),
\label{eq:trace_bound}
\end{align*}
where $\Psi_k = \mathbb{E}_{\rho_k} [ \phi_k(h_k,a_k)\phi_k(h_k,a_k)^\top ]$.

Since $\Psi_k$ is full rank and $\Lambda_{k,n}/n \to \Psi_k$ elementwise by the law of large numbers, the trace term satisfies that $\mathrm{Tr}(\Psi_k \Lambda_{k,n}^{-1}) = \mathcal{O}(d_k^{(s)} / n)$. Substituting this into \eqref{eq:Gamma_expectation_bound}, we conclude
\begin{equation}
\label{eq:Gamma_expectation_final}
\mathbb{E}_{(h_k,a_k)\sim d_{P^*,k}^{\pi^\dagger}} \Gamma_k(h_k,a_k) \lesssim k \sqrt{ \frac{C_k \log n}{n} }.
\end{equation}

We now turn to bounding $\|\Gamma_k\|_\infty$ for use in $b_k$. By the expression for $\Gamma_k$ in \eqref{eq: KNR, Gamma} and using similar simplification as above, we have:
\[
\|\Gamma_k\|_\infty \lesssim \beta_{k,n} \cdot \sup_{(h_k,a_k)} \sqrt{ \phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k)}.
\]

To bound the supremum, we recall from Assumption~\ref{assump:bounded-features} that the feature map $\phi_k$ is uniformly bounded. In particular, $\|\phi_k(h_k,a_k)\|_2^2 \le R^2k$ for all $(h_k, a_k)$.  Therefore, we have

\[\phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k) \le \frac{\|\phi_k(h_k,a_k)\|_2^2}{\lambda_{\min}(\Lambda_{k,n})}\lesssim \frac{R^2k}{\lambda_{\min}(\Lambda_{k,n})}\]

Now we apply the Matrix Chernoff II bound (Corollary 5.2 in \citep{Tropp_2011}), it follows that $\lambda_{\min}(\Lambda_{k,n}) = \Omega(n)$ with high probability $1-\delta$. Hence,
\[
\phi_k(h_k,a_k)^\top \Lambda_{k,n}^{-1} \phi_k(h_k,a_k) \lesssim \frac{k}{n},
\]
uniformly over $(h_k,a_k)$, and thus
\begin{equation}
\label{eq:Gammainf_bound}
\|\Gamma_k\|_\infty \lesssim k \sqrt{ \frac{\log n}{n} }.
\end{equation}

Since $\widetilde{c}_k = \sum_{j=k}^K \|\overline{r}_j\|_\infty = \mathcal{O}(K)$, we obtain the bound by plugging \eqref{eq:Gammainf_bound}:
\[
b_k = 2\widetilde{c}_k + \sum_{j=k+1}^K \widetilde{c}_j \|\Gamma_j\|_\infty = \mathcal{O}\left( K + \frac{K^3 \sqrt{\log n}}{\sqrt{n}} \right).
\]
Substituting the bounds on $\mathbb{E}_{(h_k,a_k) \sim d_{P^*,k}^{\pi^\dagger}} \Gamma_k(h_k,a_k)$ \eqref{eq:Gamma_bound} and $b_k$ into \eqref{eq:cor_partial_coverage_regret} yields the desired guarantee:
\[
\left( V_{M^*}^{\pi^\dagger} - V_{\widetilde{M}}^{\pi^\dagger} \right) + \left( V_{\widetilde{M}}^{\pi} - V_{M^*}^{\pi} \right)
\le {\mathcal{O}}\left( \frac{K^3\sqrt{\log n}}{\sqrt{n}} + \frac{K^5}{n} \right),
\]
which completes the proof.
\end{proof}





\begin{proof}[Proof of Theorem \ref{thm: suboptimality for linear}]

By Theorem \ref{thm: combined main thm} , with high probability $1-K\delta$, we have
\begin{equation*}
% \label{eq: proof sample complexity linear eq 7}
\begin{aligned}
\text{Subopt}(\pi^{(T)}; M^*) &\le \sum_{k=1}^K b_k \mathbb{E}_{ (h_k, a_k)\sim d^{\pi^\dagger} _{P^*}} \Gamma_k( h_k, a_k ) + \mathcal{O}\left( \frac{K}{\sqrt{T}} \right) + K \cdot \mathcal{O}_P \left( T^{1/2} G_k + T^{3/2} G_k^2 \right),\\
&\stackrel{(i)}{\le} \widetilde{\mathcal{O}}\left( \frac{ K^3}{ \sqrt{n}}+ \frac{K^{5}}{n} \right) + \mathcal{O} \left( \frac{K}{\sqrt{T}} \right)  + K \sqrt{T} \cdot \mathcal{O}_p\left( \left( \frac{\log m_k}{m_k} \right)^ {\alpha_1} \right),
\end{aligned}
\end{equation*}
where $\widetilde{O}$ hides all logarithmic terms and $(i)$ comes from Corollary \ref{cor: partial coverage linear}.

\end{proof}

\begin{proof}[Proof of Corollary \ref{Cor:Sample Complexity of Linear Model}]
By Theorem~\ref{thm: suboptimality for linear}, with probability at least \(1 - K\delta\), the suboptimality of the learned policy satisfies
\[
\text{Subopt}(\pi^{(T)}; M^*) 
\le \widetilde{\mathcal{O}}\left( \frac{K^3}{\sqrt{n}} + \frac{K^{5}}{n} \right)
+ \mathcal{O}\left( \frac{K}{\sqrt{T}} \right) 
+ K \sqrt{T} \cdot \mathcal{O}_p\left( \left( \frac{\log m_k}{m_k} \right)^{\alpha_1} \right),
\]
where the latter two terms are independent of the offline sample size \(n\), and vanish under appropriate choices of hyperparameters \(T\) and \(m_k \). Therefore, to achieve \(\text{Subopt}(\pi^{(T)}; M^*) \le \epsilon\), it suffices to set $n = \widetilde{\Theta}\left( \frac{K^6}{\epsilon^2} \right),$ where the $\widetilde{\Theta}$ hides a logarithmic dependence on $n$. Then the regret becomes
\[
\text{Subopt}(\pi^{(T)}; M^*) 
\le \widetilde{\mathcal{O}}\left( \frac{K^3}{\sqrt{n}} + \frac{K^{5}}{n} \right)
= \mathcal{O}\left( \epsilon + \frac{\epsilon^2}{K} \right)
= \mathcal{O}(\epsilon).
\]
\end{proof}

\subsection{Proof of Theorem \ref{thm:suboptimality-GP} in Section \ref{sec:GP-model}}
\label{proof sec: GP}

In this section, we build upon the discussion in Section \ref{subsec: GP}. We begin with two kernel assumptions and four auxiliary lemmas that deliver the variance bounds needed for the proof.

\begin{SAssumption}
\label{assumption: GP kernel}
The kernel function \( h(\cdot,\cdot) \) is continuous and bounded on \( \mathcal{X} \times \mathcal{X} \).
\end{SAssumption}

This assumption imposes standard regularity conditions on the kernel function \( h \), namely continuity and boundedness over the domain \( \mathcal{X} \times \mathcal{X} \). These conditions are commonly assumed in the Gaussian process and kernel methods literature to ensure the well-posedness of the associated integral operator and to facilitate theoretical analysis \citep{kanagawa2018gaussian, steinwart2009optimal, chang2021mitigating}.

\begin{SAssumption}
\label{assumption:eigenvalue decay}
The eigenvalues \( \{ \mu_j \}_{j=1}^{\infty} \) of the integral operator defined in \eqref{eq: lemma Mercer eq 1} satisfy the decay condition \( \mu_j = \mathcal{O}(j^{-\omega}) \) for some \( \omega > 5 \).
\end{SAssumption}

Assumption~\ref{assumption:eigenvalue decay} guarantees that the eigenvalue sequence of the integral operator defined in \eqref{eq: lemma Mercer eq 1} is summable, i.e., \( \sum_{j=1}^{\infty} \mu_j < \infty \). This summability condition implies a sufficiently fast decay rate, which ensures the regularization properties and numerical stability of kernel-based estimators. A wide range of commonly used kernels satisfy this condition under mild parameter choices. For instance, the Matérn kernel exhibits eigenvalue decay of the form \( \mu_j \sim j^{-(2\nu + 1)} \), which meets the assumption when the smoothness parameter \( \nu > 2 \). The Rational Quadratic kernel satisfies the condition if its shape parameter \( \beta_1 > 5/2 \), since its eigenvalues decay as \( \mu_j \sim j^{-2\beta_1} \). Similarly, the Sobolev kernel, characterized by \( \mu_j \sim j^{-2s} \), meets the requirement when the smoothness parameter \( s > 5/2 \). The Periodic kernel, with eigenvalue decay \( \mu_j \sim j^{-p} \), satisfies the assumption when the periodicity parameter \( p > 5 \). These examples illustrate that Assumption~\ref{assumption:eigenvalue decay} holds for a broad class of kernels widely used in Gaussian Process modeling.


\begin{lemma}
\label{lemma: Mercer}
Suppose Assumption~\ref{assumption: GP kernel} holds, where \( h: \mathcal{X} \times \mathcal{X} \to \mathbb{R} \) is a continuous, symmetric, and positive semi-definite kernel, and \( \rho \) is a Borel probability measure on \( \mathcal{X} \). Then, there exists a non-increasing sequence of non-negative eigenvalues \( \{ \mu_j \}_{j=1}^\infty \) and a corresponding sequence of orthonormal eigenfunctions \( \{ \psi_j \}_{j=1}^\infty \) forming a complete orthonormal basis for the Hilbert space \( L^2(\mathcal{X}, \rho) \), such that:
\begin{equation}
\label{eq: lemma Mercer eq 1}
\int_\mathcal{X} h(x, x') \psi_j(x') \, \rho(x') \, dx' = \mu_j \psi_j(x), \quad \text{for all } j \ge 1.
\end{equation}
Moreover, the kernel \( h \) admits the following spectral expansion:
\begin{equation}
\label{eq: lemma Mercer eq 2}
h(x, x') = \sum_{j=1}^\infty \mu_j \psi_j(x) \psi_j(x'),
\end{equation}
with convergence in \( L^2(\mathcal{X} \times \mathcal{X}, \rho \otimes \rho) \).
\end{lemma}

\begin{lemma}[Expected Posterior GP Variance]
\label{lemma: GP posterior expected variance}
Suppose Assumptions~\ref{assumption: GP kernel} and~\ref{assumption:eigenvalue decay} hold. Let \( \{\mu_j\}_{j=1}^{\infty} \) and \( \{\psi_j\}_{j=1}^{\infty} \) denote the eigenvalues and corresponding eigenfunctions of the kernel \( h \), as given in Lemma~\ref{lemma: Mercer}. Let \( \widehat{h}(x,x) \) denote the posterior variance of a Gaussian process at point \( x \in \mathcal{X} \), after observing \( n \) samples drawn according to the distribution \( \rho \). Then the expected posterior variance satisfies
\[
\mathbb{E}_{x \sim \rho}\left[\widehat{h}(x, x)\right] = \mathcal{O}\left(n^{\frac{1}{\omega} - 1}\right).
\]
\end{lemma}
\begin{lemma}
\label{lemma: GP posterior variance}
Suppose Assumptions  \ref{assumption: GP kernel} and \ref{assumption:eigenvalue decay} hold. Let $\{\mu_j\}_{j=1} ^{\infty}$, $\{\psi_j\}_{j=1} ^{\infty}$ be the eigenvalues and corresponding eigenfunctions from Lemma \ref{lemma: Mercer}. 
For any fixed $x\in \mathcal{X}$, with high probability $1-\delta$, it satisfies that
\begin{equation*}
\widehat{h}(x,x) \le M,
\end{equation*}
where $M=\sup_{x \in \mathcal{X}} h(x,x)$.
% provided that 
% \begin{equation}
% \label{eq: lemma GP posterior variance eq 1}
% \sum_{j=1}^{\infty} \mathbbm{1}\{\mu_j>0\} (\psi_j(x))^2 < \infty.
% \end{equation}

\end{lemma}

\begin{lemma}
\label{Lemma:beta_n bound GP}
Recall that \( \beta_{k,n} \) is defined as
\[
\beta_{k,n} = \sqrt{d_{k+1}^{(s)} \left(2 + 150 \log^3\left( \frac{d_{k+1}^{(s)} n}{\delta} \right) \log\left( \det\left( I_n + \frac{1}{\sigma^2} H_{n,n} \right) \right) \right)},
\]
where \( H_{n,n} \in \mathbb{R}^{n \times n} \) is the kernel matrix with entries \( h(x_i, x_j) \), and \( d_{k+1}^{(s)}\) is the dimension of the state space $\mathcal{S}_{k+1}$. Then with probability at least \( 1 - \delta \), the following upper bound holds:
\[\beta_n  = \mathcal{O}\left( (\log n)^2 \cdot n^{1/\omega} \right),\]
where \( \omega \) is the kernel eigenvalue decay exponent defined in Assumption~\ref{assumption:eigenvalue decay}.
\end{lemma}

The proofs of Lemma \ref{lemma: Mercer} - Lemma \ref{Lemma:beta_n bound GP} are provided in Section \ref{pf:lemma thm3}.

\begin{proof}[Proof of Theorem~\ref{thm:suboptimality-GP}]
By Theorem~\ref{thm: combined main thm}, with probability at least \( 1 - K\delta \), the suboptimality of the learned policy \( \pi^{(T)} \) is bounded by
\begin{equation*}
\text{Subopt}(\pi^{(T)}; M^*) \le \sum_{k=1}^K b_k \, \mathbb{E}_{(h_k, a_k) \sim d^{\pi^\dagger}_{P^*}} \Gamma_k(h_k, a_k) + \mathcal{O}\left( \frac{K}{\sqrt{T}} \right) + K \cdot \mathcal{O}_P\left( T^{1/2} G_k + T^{3/2} G_k^2 \right).
\end{equation*}

From Lemma~\ref{lemma: GP posterior variance}, it holds that \( \widehat{h}(x,x) \le M \) for any \( x \in \mathcal{X} \). Recall from equation~\eqref{eq: GP, eq 3} that $\Gamma_k(x) = \frac{\beta_{n,k}}{\sigma} \sqrt{\widehat{h}(x,x)}.$

By combining Lemmas ~\ref{lemma: GP posterior variance} and ~\ref{Lemma:beta_n bound GP}, it follows that with probability at least \( 1 - \delta \),
\begin{equation*}
\Gamma_k(x) \lesssim (\log n)^2 n^{\frac{1}{\omega}} \cdot \sqrt{\widehat{h}(x,x)} \lesssim \widetilde{\mathcal{O}}\left(n^{\frac{1}{\omega}}\right),
\end{equation*}
where \( \widetilde{\mathcal{O}} \) hides logarithmic factors in \( n \).

Since $\widetilde{c}_k = \sum_{j=k}^K \|\overline{r}_j\|_\infty = \mathcal{O}(K)$, substituting into the definition of \( b_k \), we obtain
\[
b_k = 2\widetilde{c}_k + \sum_{j = k+1}^K \widetilde{c}_j \|\Gamma_j\|_\infty \lesssim \widetilde{\mathcal{O}}\left(K + K^2 n^{\frac{1}{\omega}}\right).
\]

Next, by Lemma~\ref{lemma: GP posterior expected variance}, we have $\mathbb{E}_{x \sim \rho} \widehat{h}(x,x) \lesssim n^{\frac{1}{\omega} - 1},$
which implies
\[
\mathbb{E}_{(h_k, a_k) \sim d^{\pi^\dagger}_{P^*}} \Gamma_k(h_k, a_k) \lesssim \widetilde{\mathcal{O}}\left(n^{\frac{3}{2\omega} - \frac{1}{2}}\right).
\]

Combining the bounds above, the overall suboptimality is bounded as
\begin{align*}
\text{Subopt}(\pi^{(T)}; M^*) 
&\le \sum_{k=1}^K b_k \, \mathbb{E}_{(h_k, a_k) \sim d^{\pi^\dagger}_{P^*}} \Gamma_k(h_k, a_k) + \mathcal{O}\left( \frac{K}{\sqrt{T}} \right) + K \cdot \mathcal{O}_P\left( T^{1/2} G_k + T^{3/2} G_k^2 \right) \\
&\le \mathcal{O}\left(K^2 (\log n)^2 n^{\frac{3}{2\omega} - \frac{1}{2}} + K^3 (\log n)^4 n^{\frac{5}{2\omega} - \frac{1}{2}}\right) + \mathcal{O}\left( \frac{K}{\sqrt{T}} \right) \\
&\quad + K \sqrt{T} \cdot \mathcal{O}_P\left( \left( \frac{\log m_k}{m_k} \right)^{\alpha_1} \right),
\end{align*}
which concludes the proof.
\end{proof}

\begin{proof}[Proof of Corollary~\ref{cor:sample-complexity-GP}]
By Theorem~\ref{thm:suboptimality-GP}, with probability at least \(1 - K\delta\), the suboptimality of the learned policy satisfies
\[
\text{Subopt}(\pi^{(T)}; M^*) 
\le 
\widetilde{\mathcal{O}}\left( K^2  n^{\frac{3}{2\omega}-\frac{1}{2}}+K^3 n^{\frac{5}{2\omega}-\frac{1}{2}} \right) 
+ \mathcal{O} \left( \frac{K}{\sqrt{T}} \right)
+ K \sqrt{T} \cdot \mathcal{O}_p \left( \left( \frac{\log m_k}{m_k} \right)^{\alpha_1} \right),
\]
where the last two terms are independent of the offline sample size \(n\) and vanish under appropriate choices of hyperparameters \(T\) and \(m_k \). Therefore, to achieve \(\text{Subopt}(\pi^{(T)}; M^*) \le \epsilon\), it suffices to set $n =  \widetilde{\Theta} \left(\frac{K^3}{\epsilon}\right)^{\frac{2\omega}{\omega-5}},$
where the notation \(\widetilde{\Theta}\) hides logarithmic dependencies on \(n\). Then this regret becomes
\[
\text{Subopt}(\pi^{(T)}; M^*) 
= \mathcal{O}(\epsilon).
\]
\end{proof}

