\begin{definition}[$\sigma$-Sub-Gaussian Condition]
\label{definition: sigma-sub-gaussian}
\begin{itemize}
    \item[(i)] A real-valued random variable \( X \) is said to be \(\sigma\)-sub-Gaussian for some \(\sigma > 0\) if it satisfies the inequality
    \[
    \mathbb{E}\left[\exp(\lambda X)\right] \le \exp\left(\frac{\lambda^2 \sigma^2}{2}\right), \quad \text{for all } \lambda \in \mathbb{R}.
    \]
    \item[(ii)] A random vector \( X \in \mathbb{R}^d \) is \(\sigma\)-sub-Gaussian if for every unit vector \( w \in \mathbb{R}^d \) (i.e., \( \|w\|_2 = 1 \)), the one-dimensional projection \( w^\top X \) is \(\sigma\)-sub-Gaussian in the sense of (i).
\end{itemize}
\end{definition}

The scalar case in Definition~\ref{definition: sigma-sub-gaussian} (i) follows the standard formulation as in \citet{Abbasi-Yadkori2011}, while the extension to random vectors in Definition~\ref{definition: sigma-sub-gaussian} (ii) adopts the projective sub-Gaussian criterion used in \citet{kakade2020information}. 


\begin{lemma}
\label{lemma: self normalized}
Let $\{\mathcal{F}_i \}_{i=0}^{\infty}$ be a filtration and $\{\varepsilon_i \}_{i=0}^{\infty}$ be an $\mathbb{R}^d$-valued stochastic process such that $\varepsilon_i$ is $\mathcal{F}_i$-measurable, $\mathbb{E}[\varepsilon_i| \mathcal{F}_i] =0$, and $\varepsilon_i| \mathcal{F}_i$ is $\sigma$-sub-Gaussian.
Meanwhile, let $\{\phi_i \}_{i=0}^{\infty}$ be an $\mathbb{R}^m$-valued, $\mathcal{F}_i$-measurable stochastic process. Let \(\Lambda_0 \in \mathbb{R}^{m \times m}\) be a deterministic positive-definite real matrix, and define $\Lambda_t := \Lambda_0 + \sum_{i=1}^t \phi_i \phi_i^T$. Then, with probability at least $1-\delta$, the following bound holds for all $t\ge 1$:
\[
\left\| \left( \sum_{i=1}^t \varepsilon_i \phi_i^\top \right) \Lambda_t^{-1/2} \right\|_2^2 
\le 8\sigma^2 d \log(5) + 8\sigma^2 \log \left( \frac{\det(\Lambda_t)^{1/2}}{\det(\Lambda_0)^{1/2} \, \delta} \right),
\]
where $\|\cdot\|_2$ denotes the spectral norm of a $d\times m$ matrix.
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lemma: self normalized}]
See Lemma C.4 of \cite{kakade2020information} for a detailed proof.
\end{proof}

