%     \item[(ii)] \( \|Y\|_2 \le \sigma \) almost surely, for some \( \sigma > 0 \).
% \end{itemize}
% Then \( Y \) is \(\sigma\)-sub-Gaussian.
% \end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma: bounded rv is subgaussian}]
Let \( w \in \mathbb{R}^d \) be any unit vector (i.e., \( \|w\|_2 = 1 \)), and define the scalar random variable \( X = w^\top Y \). Then \( \mathbb{E}[X] = w^\top \mathbb{E}[Y] = 0 \), and by the Cauchy–Schwarz inequality,
\[
|X| = |w^\top Y| \le \|w\|_2 \|Y\|_2 \le \sigma.
\]
Thus, \( X \) is a zero-mean, bounded random variable supported on \( [-\sigma, \sigma] \). We now verify that \( X \) is \(\sigma\)-sub-Gaussian. By Definition~\ref{definition: sigma-sub-gaussian}(i), we must show that for all \( \lambda \in \mathbb{R} \), $\mathbb{E}[e^{\lambda X}] \le \exp\left(\frac{\lambda^2 \sigma^2}{2}\right).$ Since \( \lambda X \in [-|\lambda| \sigma, |\lambda| \sigma] \), we apply the convexity of the exponential function:
\[
e^{\lambda X} \le \frac{e^{|\lambda| \sigma} - e^{-|\lambda| \sigma}}{2 |\lambda| \sigma}(X + |\lambda| \sigma) + e^{-|\lambda| \sigma}.
\]
Taking expectations on both sides and using \( \mathbb{E}[X] = 0 \), we obtain:
\[
\mathbb{E}[e^{\lambda X}] \le \frac{1}{2} e^{|\lambda| \sigma} + \frac{1}{2} e^{-|\lambda| \sigma}.
\]
Letting \( t = |\lambda| \sigma \), we finish the proof by using the inequality:
\[
\frac{1}{2}(e^t + e^{-t}) \le \exp\left( \frac{t^2}{2} \right), \quad \forall t \ge 0.
\]
\end{proof}

% \begin{lemma}
% \label{lemma: W-W* in KNR}
% Suppose $n$ tuples $\{ (h_i,a_i,s_i) \}_{i=1}^n$ are observed, and $(h_i, a_i, s_i)$ satisfy the transition $s_i= W^* \phi(h_i,a_i)+ \varepsilon_i$, $\varepsilon_1, ..., \varepsilon_n \stackrel{iid}{\sim} F$. Assume $F$ is $\sigma$-sub-Gaussian. Let $\widehat{W} = (\sum_{i=1}^n s_i \phi_i^T) (\sum_{i=1}^n \phi_i \phi_i^T + \lambda I)^{-1}$ for some $\lambda>0$, where $\phi_i$ denotes $\phi(h_i,a_i)$. Let $\Lambda_n = \sum_{i=1}^n \phi_i \phi_i^T + \lambda I$, then with probability at least $1-\delta$:
% \begin{equation*}
% \left\| (\widehat{W}-W^*) \Lambda_n^{1/2} \right\|_2 \le \sqrt{\lambda} \|W^*\|_2 + \sqrt{8\sigma^2 d_s \log(5) + 8\sigma^2 \log \left( \frac{\det (\Lambda_n) ^{1/2} / \det (\lambda I) ^{1/2}}{\delta} \right)}.
% \end{equation*}
% \end{lemma}

\begin{proof}[Proof of Lemma \ref{lemma: W-W* in KNR}]
Since $s_i= W^* \phi(h_i,a_i)+ \varepsilon_i$, we then can plug it into the construction of $\widehat{W}$:
\begin{equation*}
\begin{split}
\widehat{W} &= \left( \sum_{i=1}^n s_i \phi_i^T \right) \left( \sum_{i=1}^n \phi_i \phi_i^T + \lambda I \right)^{-1}\\
&= \left( \sum_{i=1}^n W^* \phi(h_i,a_i) \phi_i^T + \sum_{i=1}^n \varepsilon_i \phi_i^T \right) \left( \sum_{i=1}^n \phi_i \phi_i^T + \lambda I \right)^{-1}\\
&= \left( W^* \left(\sum_{i=1}^n \phi(h_i,a_i) \phi_i^T +\lambda I \right) - \lambda W^*+ \sum_{i=1}^n \varepsilon_i \phi_i^T \right) \left( \sum_{i=1}^n \phi_i \phi_i^T + \lambda I \right)^{-1} \\
&= W^* - \lambda W^* \left( \sum_{i=1}^n \phi_i \phi_i^T + \lambda I \right)^{-1} + \sum_{i=1}^n \varepsilon_i \phi_i^T \left( \sum_{i=1}^n \phi_i \phi_i^T + \lambda I \right)^{-1}.
\end{split}
\end{equation*}
For simplicity, denote $\Lambda_n = \sum_{i=1}^n \phi_i \phi_i^T + \lambda I$, then
\begin{equation*}
\widehat{W}-W^* = - \lambda W^* \Lambda_n^{-1} + \sum_{i=1}^n \varepsilon_i \phi_i^T \Lambda_n^{-1}.
\end{equation*}
Multiply $\Lambda_n^{1/2}$ on the right, and take the spectral norm on both sides:
\begin{equation}
\label{eq: spec norm both sides}
\left\| (\widehat{W}-W^*) \Lambda_n^{1/2} \right\|_2 \le \left\| \lambda W^* \Lambda_n^{-1/2} \right\|_2 + \left\| \sum_{i=1}^n \varepsilon_i \phi_i^T \Lambda_n^{-1/2} \right\|_2.
\end{equation}
For the first term, note that $\Lambda_n = \sum_{i=1}^n \phi_i \phi_i^T + \lambda I \succeq \lambda I$, so the smallest eigenvalue of $\Lambda_n$ satisfies $\lambda_{min} (\Lambda_n) \ge \lambda >0$. We have $\lambda_{min} (\Lambda_n^{1/2}) \ge \sqrt{\lambda}$, $\lambda_{max} (\Lambda_n^{-1/2}) \le \frac{1}{ \sqrt{\lambda}}$. It suggests that $\|\Lambda_n^{-1/2}\|_2 \le \frac{1}{ \sqrt{\lambda}}$. By the sub-multiplicative property of matrix spectral norm,
\begin{equation}
\label{eq: matrix norm proof}
\left\| \lambda W^* \Lambda_n^{-1/2} \right\|_2 \le \lambda \|W^*\|_2 \|\Lambda_n^{-1/2}\|_2 \le \sqrt{\lambda} \|W^*\|_2.
\end{equation}
For the second term, apply Lemma \ref{lemma: self normalized}: with probability at least $1-\delta$,
\begin{equation}
\label{eq: sec term lemma 7}
\left\| \sum_{i=1}^n \varepsilon_i \phi_i^T \Lambda_n^{-1/2} \right\|_2^2 \le 8\sigma^2 d_s \log(5) + 8\sigma^2 \log \left( \frac{\det (\Lambda_n) ^{1/2} / \det (\lambda I) ^{1/2}}{\delta} \right).
\end{equation}
Merge the inequalities \eqref{eq: spec norm both sides}, \eqref{eq: matrix norm proof} and \eqref{eq: sec term lemma 7} above:
\begin{equation*}
\left\| (\widehat{W}-W^*) \Lambda_n^{1/2} \right\|_2 \le \sqrt{\lambda} \|W^*\|_2 + \sqrt{8\sigma^2 d_s \log(5) + 8\sigma^2 \log \left( \frac{\det (\Lambda_n) ^{1/2} / \det (\lambda I) ^{1/2}}{\delta} \right)}.
\end{equation*}
\end{proof}



