\begin{split}
Q_k^\pi(h_k, a_k) =\ & \widehat{Q}_k^\pi(h_k, a_k) + \sum_{t=k+1}^K \mathbb{E}_{(h_t, a_t) \sim d_{t,P}^\pi(\cdot,\cdot \mid H_k = h_k, A_k = a_k)} \left[ \widehat{Q}_t^\pi(h_t, a_t) \right] \\
& - \sum_{t=k}^{K-1} \mathbb{E}_{(h_t,a_t) \sim d_{t,P}^\pi(\cdot,\cdot \mid H_k = h_k, A_k = a_k)} \left[ \mathbb{E}_{h' \sim \widehat{P}_t(\cdot \mid h_t, a_t)} \left[ \widehat{V}_{t+1}^\pi(h') \right] \right].
\end{split}
\end{equation}

Next, we express the sum in the first line as:
\begin{equation}
\label{eq:proof-simulation-4}
\sum_{t=k+1}^K \mathbb{E}_{(h_t,a_t)\sim d_{t,P}^\pi(\cdot,\cdot \mid H_k = h_k, A_k = a_k)} \left[ \widehat{Q}_t^\pi(h_t, a_t) \right]
= \sum_{t=k}^{K-1} \mathbb{E}_{(h_t, a_t),\ h'\sim P_t,\ a'\sim \pi_{t+1}(h')} \left[ \widehat{Q}_{t+1}^\pi(h', a') \right].
\end{equation}

Since \( a' \sim \pi_{t+1}(h') \), the inner expectation 
\( \mathbb{E}_{a'} \left[ \widehat{Q}_{t+1}^\pi(h', a') \right] \) 
evaluates to \( \widehat{V}_{t+1}^\pi(h') \) by definition of the value function.
Combining \eqref{eq:proof-simulation-3} and \eqref{eq:proof-simulation-4}, and regrouping, yields:
\[
\begin{aligned}
Q_k^\pi(h_k, a_k) - \widehat{Q}_k^\pi(h_k, a_k)
&= \sum_{t=k}^{K-1} \mathbb{E}_{(h_t, a_t) \sim d_{t, P}^\pi(\cdot,\cdot \mid h_k, a_k)} \Big[
\mathbb{E}_{h' \sim P_t(\cdot \mid h_t, a_t)} \widehat{V}_{t+1}^\pi(h') \\
&\quad - \mathbb{E}_{h' \sim \widehat{P}_t(\cdot \mid h_t, a_t)} \widehat{V}_{t+1}^\pi(h')
\Big],
\end{aligned}
\]

which completes the proof.
\end{proof}

