\begin{proof}[Proof of Lemma~\ref{lemma: r - rhat}]
By the definition of $r_k$ and $\widehat{r}_k$:
\begin{align*}
\left| r_k(h_k, a_k) - \widehat{r}_k(h_k, a_k) \right| 
&= \left| \mathbb{E}_{s'\sim P^*_k(\cdot \mid h_k, a_k)} \left[ \overline{r}_k(h_k, a_k, s') \right] - \mathbb{E}_{s'\sim \widehat{P}_k(\cdot \mid h_k, a_k)} \left[ \overline{r}_k(h_k, a_k, s') \right] \right| \\
&\le \| \overline{r}_k \|_\infty \cdot \left\| P^*_k(\cdot \mid h_k, a_k) - \widehat{P}_k(\cdot \mid h_k, a_k) \right\|_1.
\end{align*}

By Assumption~\ref{assumption: uncertainty quantifier}, the $L_1$ distance between the true and estimated transition distributions is bounded by $\Gamma_k(h_k, a_k)$ with probability at least $1 - \delta$. We show our desired result.
\end{proof}


