% \begin{lemma}[Performance Difference Lemma]
% \label{lemma: perf diff}
% Let $P$ be the transition dynamics of a fixed DTR model. For any two policies $\pi$ and $\widehat{\pi}$, the following holds for any stage $k$ and any history $h_k$:
% \begin{equation*}
% \begin{aligned}
% V_k^\pi(h_k) - V_k^{\widehat{\pi}}(h_k)
% &= \sum_{t=k}^K \mathbb{E}_{(h_t, a_t) \sim d_t^\pi(\cdot,\cdot \mid H_k = h_k)} \left[ A_t^{\widehat{\pi}}(h_t, a_t) \right] \\
% &= \sum_{t=k}^K \mathbb{E}_{h_t \sim d_t^\pi(\cdot \mid H_k = h_k)} \left\langle Q_t^{\widehat{\pi}}(h_t, \cdot),\ \pi_t(\cdot \mid h_t) - \widehat{\pi}_t(\cdot \mid h_t) \right\rangle,
% \end{aligned}
% \end{equation*}
% where $A_t^{\widehat{\pi}}(h_t, a_t) := Q_t^{\widehat{\pi}}(h_t, a_t) - V_t^{\widehat{\pi}}(h_t)$ is the advantage function of policy $\widehat{\pi}$ at step $t$.
% \end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma: perf diff}]
We first prove the second equality. By the definition of the advantage function:
\begin{align*}
\mathbb{E}_{a_t \sim \pi_t(\cdot \mid h_t)} A_t^{\widehat{\pi}}(h_t, a_t)
&= \mathbb{E}_{a_t \sim \pi_t(\cdot \mid h_t)} \left[ Q_t^{\widehat{\pi}}(h_t, a_t) \right] - V_t^{\widehat{\pi}}(h_t) \\
&= \mathbb{E}_{a_t \sim \pi_t(\cdot \mid h_t)} \left[ Q_t^{\widehat{\pi}}(h_t, a_t) \right] - \mathbb{E}_{a_t \sim \widehat{\pi}_t(\cdot \mid h_t)} \left[ Q_t^{\widehat{\pi}}(h_t, a_t) \right] \\
&\stackrel{(i)}{=} \left\langle Q_t^{\widehat{\pi}}(h_t, \cdot),\ \pi_t(\cdot \mid h_t) - \widehat{\pi}_t(\cdot \mid h_t) \right\rangle,
\end{align*}
where $(i)$ is because the action space is discrete.
We now prove the first equality. Let $\tau$ denote the trajectory $(H_k, A_k, \dots, H_K, A_K)$ generated under policy $\pi$ and dynamics $P$. Then:
\[
V_k^\pi(h_k) = \mathbb{E}_\pi \left[ \sum_{t=k}^K R_t \mid H_k = h_k \right]
= \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \left[ \sum_{t=k}^K r_t(H_t, A_t) \right].
\]

Adding and subtracting $V_t^{\widehat{\pi}}(H_t)$ inside the summation gives:
\begin{equation}
\label{eq:proof-pdiff-1}
\begin{aligned}
V_k^\pi(h_k)
&= \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \sum_{t=k}^K \left[ r_t(H_t, A_t) - V_t^{\widehat{\pi}}(H_t) + V_t^{\widehat{\pi}}(H_t) \right] \\
&= \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \sum_{t=k}^K \left[ r_t(H_t, A_t) - V_t^{\widehat{\pi}}(H_t) \right]
+ \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \sum_{t=k}^K V_t^{\widehat{\pi}}(H_t).
\end{aligned}
\end{equation}

Since $V_k^{\widehat{\pi}}(H_k) = V_k^{\widehat{\pi}}(h_k)$ deterministically, we rewrite the second sum as:
\begin{equation}
\label{eq:proof-pdiff-2}
\begin{aligned}
\mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \sum_{t=k}^K V_t^{\widehat{\pi}}(H_t)
&= V_k^{\widehat{\pi}}(h_k) + \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \sum_{t=k+1}^K V_t^{\widehat{\pi}}(H_t) \\
&= V_k^{\widehat{\pi}}(h_k) + \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \sum_{t=k}^K V_{t+1}^{\widehat{\pi}}(H_{t+1}),
\end{aligned}
\end{equation}
where we define $V_{K+1}^{\widehat{\pi}} \equiv 0$.

Substituting \eqref{eq:proof-pdiff-2} into \eqref{eq:proof-pdiff-1}, we obtain:
\[
V_k^\pi(h_k) - V_k^{\widehat{\pi}}(h_k)
= \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \sum_{t=k}^K \left[ r_t(H_t, A_t) + V_{t+1}^{\widehat{\pi}}(H_{t+1}) - V_t^{\widehat{\pi}}(H_t) \right].
\]

Since $H_{t+1} \sim P_t(\cdot \mid H_t, A_t)$ under model $P$, we can write:
\begin{equation}
\label{eq:proof-pdiff-3}
\begin{aligned}
&\quad \mathbb{E}_{\tau \sim d_P^\pi(\cdot \mid H_k = h_k)} \left[ r_t(H_t, A_t) + V_{t+1}^{\widehat{\pi}}(H_{t+1}) \right]\\
&= \mathbb{E}_{(H_t, A_t) \sim d_t^\pi(\cdot,\cdot \mid H_k = h_k)} \left[
r_t(H_t, A_t) + \mathbb{E}_{H_{t+1} \sim P_t(\cdot \mid H_t, A_t)} V_{t+1}^{\widehat{\pi}}(H_{t+1})
\right] \\
&= \mathbb{E}_{(H_t, A_t) \sim d_t^\pi(\cdot,\cdot \mid H_k = h_k)} \left[ Q_t^{\widehat{\pi}}(H_t, A_t) \right].
\end{aligned}
\end{equation}

Putting it all together:
\[
\begin{aligned}
V_k^\pi(h_k) - V_k^{\widehat{\pi}}(h_k)
&= \sum_{t=k}^K \mathbb{E}_{(H_t, A_t) \sim d_t^\pi(\cdot,\cdot \mid H_k = h_k)} \left[ Q_t^{\widehat{\pi}}(H_t, A_t) - V_t^{\widehat{\pi}}(H_t) \right] \\
&= \sum_{t=k}^K \mathbb{E}_{(H_t, A_t) \sim d_t^\pi(\cdot,\cdot \mid H_k = h_k)} \left[ A_t^{\widehat{\pi}}(H_t, A_t) \right],
\end{aligned}
\]
which completes the proof.
\end{proof}


% \begin{lemma}
% \label{lemma: 3 KL terms}
% For any $1\le k\le K$, suppose $\theta_k, \theta'_k \in \Theta_k$, $\pi_k(\theta_k)$ and $\pi_k(\theta'_k)$ are two policies in the policy class $\Pi_k$ defined in (\ref{eq: policy class}). Let $p(\cdot)$ be any probability distribution on $\mathcal{A}_k$. Then for any $h_k\in \mathcal{H}_k$, we have
% \begin{equation*}
% \begin{split}
% & \quad\operatorname{KL}(p,\pi_k(h_k, \theta_k)) - \operatorname{KL}(p,\pi_k(h_k, \theta'_k)) - \operatorname{KL}(\pi_k(h_k, \theta'_k), \pi_k(h_k, \theta_k)) \\
% &= \Bigl\langle f_k(\theta'_k, h_k,\cdot)-f_k(\theta_k, h_k,\cdot),\ p(\cdot)-\pi_k(\cdot|h_k, \theta'_k) \Bigr\rangle.
% \end{split}
% \end{equation*}
% \end{lemma}
\begin{proof}[Proof of Lemma~\ref{lemma: 3 KL terms}]
By definition of KL divergence and the formulation of softmax policies, we expand:
\begin{align*}
&\quad \operatorname{KL}(p,\pi_k(h_k, \theta_k)) - \operatorname{KL}(p,\pi_k(h_k, \theta_k')) - \operatorname{KL}(\pi_k(h_k, \theta_k'), \pi_k(h_k, \theta_k)) \\
&= \mathbb{E}_{a \sim p} \left[ \log \frac{p(a)}{\pi_k(a \mid h_k, \theta_k)} \right]
- \mathbb{E}_{a \sim p} \left[ \log \frac{p(a)}{\pi_k(a \mid h_k, \theta_k')} \right]
- \mathbb{E}_{a \sim \pi_k(\cdot \mid h_k, \theta_k')} \left[ \log \frac{\pi_k(a \mid h_k, \theta_k')}{\pi_k(a \mid h_k, \theta_k)} \right] \\
&= \left\langle \log \frac{\pi_k(\cdot \mid h_k, \theta_k')}{\pi_k(\cdot \mid h_k, \theta_k)},\ p(\cdot) - \pi_k(\cdot \mid h_k, \theta_k') \right\rangle.
\end{align*}

Recall the parameterization of the softmax policy: $\log \pi_k(a \mid h_k, \theta) = f_k(\theta, h_k, a) - \log Z_k(h_k, \theta),$
where the normalization constant is $Z_k(h_k, \theta) := \sum_{a' \in \mathcal{A}_k} \exp(f_k(\theta, h_k, a')).$

Substituting into the inner product:
\begin{align*}
&\quad \left\langle \log \frac{\pi_k(\cdot \mid h_k, \theta_k')}{\pi_k(\cdot \mid h_k, \theta_k)},\ p(\cdot) - \pi_k(\cdot \mid h_k, \theta_k') \right\rangle \\
&= \left\langle f_k(\theta_k', h_k, \cdot) - \log Z_k(h_k, \theta_k') - f_k(\theta_k, h_k, \cdot) + \log Z_k(h_k, \theta_k),\ p(\cdot) - \pi_k(\cdot \mid h_k, \theta_k') \right\rangle.
\end{align*}

Since $\log Z_k(h_k, \theta)$ is constant in $a$, and both $p(\cdot)$ and $\pi_k(\cdot \mid h_k, \theta_k')$ are
probability distributions over $\mathcal{A}_k$, we have:
\[
\left\langle \log Z_k(h_k, \theta),\ p(\cdot) - \pi_k(\cdot \mid h_k, \theta_k') \right\rangle
= \log Z_k(h_k, \theta) \cdot \sum_{a \in \mathcal{A}_k} \left( p(a) - \pi_k(a \mid h_k, \theta_k') \right) = 0.
\]


Thus, we simplify the expression to: $\left\langle f_k(\theta_k', h_k, \cdot) - f_k(\theta_k, h_k, \cdot),\ p(\cdot) - \pi_k(\cdot \mid h_k, \theta_k') \right\rangle.$
\end{proof}

% \begin{lemma}
% \label{lemma: <Q,pi_t+1 - pi_t>}
% For any $0\le t\le T-1$, $1\le k\le K$, and any $h_k\in \mathcal{H}_k$, we have
% \begin{equation*}
% \Bigl\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot), \pi_k(\cdot|h_k, \theta_k^{(t+1)}) - \pi_k(\cdot|h_k, \theta_k^{(t)}) \Bigr\rangle + \frac{1}{4 \eta_k^{(t)}} \|e^{(t)}_k(h_k,\cdot)\|_\infty^2 \ge 0.
% \end{equation*}
% \end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma: <Q,pi_t+1 - pi_t>}]
We analyze the policy update from $\theta_k^{(t)}$ to $\theta_k^{(t+1)}$. Applying Lemma~\ref{lemma: 3 KL terms} with $\theta = \theta_k^{(t)}$, $\theta' = \theta_k^{(t+1)}$, for any $p \in \Delta(\mathcal{A}_k)$, we obtain:
\begin{equation}
\label{eq:lemma-kl}
\begin{aligned}
&\quad \operatorname{KL}(p,\pi_k(h_k, \theta_k^{(t)})) - \operatorname{KL}(p,\pi_k(h_k, \theta_k^{(t+1)})) - \operatorname{KL}(\pi_k(h_k, \theta_k^{(t+1)}), \pi_k(h_k, \theta_k^{(t)})) \\
&= \left\langle f_k(\theta_k^{(t+1)}, h_k,\cdot) - f_k(\theta_k^{(t)}, h_k,\cdot),\ p(\cdot) - \pi_k(\cdot|h_k, \theta_k^{(t+1)}) \right\rangle.
\end{aligned}
\end{equation}

Now take $p = \pi_k(\cdot|h_k, \theta_k^{(t)})$ in~\eqref{eq:lemma-kl}, which yields:
\begin{equation}
\label{eq:kl-diff}
- \operatorname{KL}(\pi_k^{(t)}, \pi_k^{(t+1)}) - \operatorname{KL}(\pi_k^{(t+1)}, \pi_k^{(t)})= \left\langle f_k(\theta_k^{(t+1)}, h_k,\cdot) - f_k(\theta_k^{(t)}, h_k,\cdot),\ \pi_k^{(t)} - \pi_k^{(t+1)} \right\rangle,
\end{equation}
where we abbreviate $\pi_k^{(t)} := \pi_k(\cdot|h_k, \theta_k^{(t)})$ and $\pi_k^{(t+1)} := \pi_k(\cdot|h_k, \theta_k^{(t+1)})$.

From the policy update rule~\eqref{eq: e_t}, we know that for each $a \in \mathcal{A}_k$,
\begin{equation}
\label{eq:f-diff}
f_k(\theta_k^{(t+1)}, h_k, a) - f_k(\theta_k^{(t)}, h_k, a) = e_k^{(t)}(h_k, a) + \eta_k^{(t)} Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k, a).
\end{equation}

Substituting~\eqref{eq:f-diff} into~\eqref{eq:kl-diff}, we get:
\begin{equation}
\label{eq: inner-split}
    \operatorname{KL}(\pi_k^{(t)}, \pi_k^{(t+1)}) + \operatorname{KL}(\pi_k^{(t+1)}, \pi_k^{(t)})= \left\langle e_k^{(t)}(h_k, \cdot),\ \pi_k^{(t+1)} - \pi_k^{(t)} \right\rangle + \eta_k^{(t)} \left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^{(t+1)} - \pi_k^{(t)} \right\rangle.
\end{equation}

We now apply Pinsker’s inequality, which states:
\begin{equation}
\label{eq:pinsker}
\operatorname{KL}(p,q) \ge \frac{1}{2} \|p - q\|_1^2,
\end{equation}
for any two distributions $p, q$. Using~\eqref{eq: inner-split} and~\eqref{eq:pinsker}, we obtain:
\begin{align*}
\eta_k^{(t)} \left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^{(t+1)} - \pi_k^{(t)} \right\rangle
&= \operatorname{KL}(\pi_k^{(t)}, \pi_k^{(t+1)}) + \operatorname{KL}(\pi_k^{(t+1)}, \pi_k^{(t)}) \\
&\quad - \left\langle e_k^{(t)}(h_k,\cdot),\ \pi_k^{(t+1)} - \pi_k^{(t)} \right\rangle \\
&\ge \| \pi_k^{(t+1)} - \pi_k^{(t)} \|_1^2 - \| e_k^{(t)}(h_k,\cdot) \|_\infty \cdot \| \pi_k^{(t+1)} - \pi_k^{(t)} \|_1.
\end{align*}

To bound the cross term, we apply the inequality \( ab \le \frac{1}{2}a^2 + \frac{1}{2}b^2 \) and get:
\[
\| \pi_k^{(t+1)} - \pi_k^{(t)} \|_1^2 - \| e_k^{(t)} \|_\infty \cdot \| \pi_k^{(t+1)} - \pi_k^{(t)} \|_1
\ge -\frac{1}{4} \| e_k^{(t)}(h_k,\cdot) \|_\infty^2.
\]

Therefore, for any $h_k \in \mathcal{H}_k$, we conclude:
\[
\left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^{(t+1)} - \pi_k^{(t)} \right\rangle
+ \frac{1}{4 \eta_k^{(t)}} \| e_k^{(t)}(h_k,\cdot) \|_\infty^2 \ge 0.
\]
\end{proof}


% \begin{lemma}
% \label{lemma: <Q,pi* - pi_t>}
% For any $0 \le t \le T-1$, $1 \le k \le K$, and any $h_k \in \mathcal{H}_k$, we have:
% \begin{equation*}
% \begin{split}
% \left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t)}(\cdot|h_k) \right\rangle 
% \le\ & \frac{1}{\eta_k^{(t)}} \left[ \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t)}(h_k)) - \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t+1)}(h_k)) \right] \\
% & + \frac{\eta_k^{(t)}}{2} \left\| Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot) \right\|_\infty^2 + \frac{2}{\eta_k^{(t)}} \left\| e_k^{(t)}(h_k,\cdot) \right\|_\infty.
% \end{split}
% \end{equation*}
% \end{lemma}

\begin{proof}[Proof of Lemma \ref{lemma: <Q,pi* - pi_t>}]
We begin by applying Lemma~\ref{lemma: 3 KL terms}, which states that for any $p \in \Delta(\mathcal{A}_k)$,
\begin{equation*}
\begin{split}
&\quad\operatorname{KL}(p,\ \pi_k(h_k,\theta_k^{(t)})) - \operatorname{KL}(p,\ \pi_k(h_k,\theta_k^{(t+1)})) - \operatorname{KL}(\pi_k(h_k,\theta_k^{(t+1)}),\ \pi_k(h_k,\theta_k^{(t)})) \\
&= \left\langle f_k(\theta_k^{(t+1)}, h_k,\cdot) - f_k(\theta_k^{(t)}, h_k,\cdot),\ p(\cdot) - \pi_k(\cdot|h_k,\theta_k^{(t+1)}) \right\rangle.
\end{split}
\end{equation*}

Letting $p = \pi_k^\dagger(\cdot|h_k)$ and using the definition of $e_k^{(t)}$ in \eqref{eq: e_t}, we have:
\[
f_k(\theta_k^{(t+1)}, h_k, a) - f_k(\theta_k^{(t)}, h_k, a) = e_k^{(t)}(h_k,a) + \eta_k^{(t)} Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,a).
\]

Substituting into the identity above:
\begin{equation}
\label{eq:KL-Q-split}
\begin{split}
&\eta_k^{(t)} \left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t+1)}(\cdot|h_k) \right\rangle \\
= &\operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t)}(h_k)) - \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t+1)}(h_k)) - \operatorname{KL}(\pi_k^{(t+1)}(h_k),\ \pi_k^{(t)}(h_k)) \\
&- \left\langle e_k^{(t)}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t+1)}(\cdot|h_k) \right\rangle.
\end{split}
\end{equation}

We now express the desired inner product as:
\begin{equation*}
\begin{split}
&\left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t)}(\cdot|h_k) \right\rangle \\
= &\left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t+1)}(\cdot|h_k) \right\rangle + \left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^{(t+1)}(\cdot|h_k) - \pi_k^{(t)}(\cdot|h_k) \right\rangle.
\end{split}
\end{equation*}

Substituting from \eqref{eq:KL-Q-split} and using Pinsker's inequality \eqref{eq:pinsker}:
\begin{equation*}
\begin{split}
&\quad\left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t)}(\cdot|h_k) \right\rangle \\
&\le \frac{1}{\eta_k^{(t)}} \left[ \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t)}(h_k)) - \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t+1)}(h_k)) \right] \\
&\quad - \frac{1}{2 \eta_k^{(t)}} \left\| \pi_k^{(t+1)}(h_k) - \pi_k^{(t)}(h_k) \right\|_1^2 + \left\| Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot) \right\|_\infty \left\| \pi_k^{(t+1)}(h_k) - \pi_k^{(t)}(h_k) \right\|_1 \\
&\quad + \frac{1}{\eta_k^{(t)}} \left| \left\langle e_k^{(t)}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t+1)}(\cdot|h_k) \right\rangle \right|.
\end{split}
\end{equation*}

Applying Cauchy–Schwarz inequality and \( \| \pi \|_1 = 1 \), we upper bound the last term by \( \|e_k^{(t)}(h_k,\cdot)\|_\infty \cdot \| \pi_k^\dagger - \pi_k^{(t+1)} \|_1 \le 2 \|e_k^{(t)}(h_k,\cdot)\|_\infty \). Then completing the square on the second line leads to the final result:
$$
\begin{aligned}
   \left\langle Q^{\pi^{(t)}}_{k,\widetilde{M}}(h_k,\cdot),\ \pi_k^\dagger(\cdot|h_k) - \pi_k^{(t)}(\cdot|h_k) \right\rangle 
&\le \frac{1}{\eta_k^{(t)}} \left[ \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t)}(h_k)) - \operatorname{KL}(\pi_k^\dagger(h_k),\ \pi_k^{(t+1)}(h_k)) \right] 
\\
&\quad+ \frac{\eta_k^{(t)}}{2} \| Q^{\pi^{(t)}}_{k,\widetilde{M}} \|_\infty^2 + \frac{2}{\eta_k^{(t)}} \| e_k^{(t)} \|_\infty. 
\end{aligned}
$$
\end{proof}




\subsection{Supporting Lemmas and Their Proofs  for Theorem \ref{thm: M^tilde + sieve reg}}
% \subsection{Basic properties of H\"{o}lder condition and p-smoothness}

\label{subsec:p-smooth}

\begin{definition}[$p$-smoothness]
\label{definition: p-smooth}
Let \( \mathcal{X} \subset \mathbb{R}^d \) be a compact axis-aligned box, i.e., the Cartesian product of \( d \) closed intervals.

\begin{enumerate}[(i)]
    \item Let \( 0 < \beta \le 1 \). A function \( h: \mathcal{X} \to \mathbb{R} \) is said to satisfy a H\"older condition with exponent \( \beta \) if there exists a constant \( c > 0 \) such that
    \[
    |h(x) - h(y)| \le c \|x - y\|_2^{\beta}, \quad \text{for all } x, y \in \mathcal{X}.
    \]

    \item Let \( p > 0 \), and write \( m = \lfloor p \rfloor \) and \( \beta = p - m \). For any multi-index \( \kappa = (\kappa_1, \dots, \kappa_d) \in \mathbb{N}_0^d \), define the differential operator $ D^\kappa := \frac{\partial^{\|\kappa\|_1}}{\partial x_1^{\kappa_1} \cdots \partial x_d^{\kappa_d}}, \text{where } \|\kappa\|_1 = \sum_{j=1}^d \kappa_j.$ A function \( h: \mathcal{X} \to \mathbb{R} \) is said to be \( p \)-smooth if the following two conditions are satisfied:
    \begin{enumerate}[(a)]
        \item \( h \in C^m(\mathcal{X}) \), i.e., all partial derivatives up to order \( m \) exist and are continuous on \( \mathcal{X} \),
        \item for every multi-index \( \kappa \in \mathbb{N}_0^d \) with \( \|\kappa\|_1 = m \), the partial derivative \( D^\kappa h \) satisfies a H\"older condition with exponent \( \beta \) on \( \mathcal{X} \).
    \end{enumerate}
\end{enumerate}
\end{definition}

\begin{lemma}
\label{lemma: holder condition}
Let \( \mathcal{X}_1, \dots, \mathcal{X}_n \subset \mathbb{R} \) be closed intervals, and define \( \mathcal{X} = \mathcal{X}_1 \times \cdots \times \mathcal{X}_n \subset \mathbb{R}^n \). Let \( 0 < \beta \le 1 \). Then:

\begin{enumerate}[(i)]
    \item If functions \( f, g: \mathcal{X} \to \mathbb{R} \) both satisfy a H\"older condition with exponent \( \beta \), then the product \( fg \) also satisfies a H\"older condition with exponent \( \beta \).

    \item Suppose \( f \in C^1(\mathcal{X}) \), and for each \( i = 1, \dots, n \), the partial derivative \( \frac{\partial f}{\partial x_i} \) satisfies a H\"older condition with exponent \( \beta \). Then \( f \) itself satisfies a H\"older condition with exponent \( \beta \).

    \item Let \( m \in \mathbb{N} \), and suppose \( f \in C^m(\mathcal{X}) \). If for every multi-index \( \kappa \in \mathbb{N}_0^n \) with \( \|\kappa\|_1 = m \), the partial derivative \( D^\kappa f \) satisfies a H\"older condition with exponent \( \beta \), then the same holds for all multi-indices \( \kappa \) with \( \|\kappa\|_1 \le m \).
\end{enumerate}
\end{lemma}


