\begin{lemma}
\label{lemma: p-smooth properties}
Let \( \mathcal{X}_1, \dots, \mathcal{X}_n \subset \mathbb{R} \) be closed intervals, and define \( \mathcal{X} = \mathcal{X}_1 \times \cdots \times \mathcal{X}_n \subset \mathbb{R}^n \). The following properties hold for \( p \)-smooth functions on \( \mathcal{X} \):

\begin{enumerate}[(i)]
    \item If \( f \) and \( g \) are \( p \)-smooth on \( \mathcal{X} \), and \( k \in \mathbb{R} \), then \( kf \) and \( f + g \) are also \( p \)-smooth on \( \mathcal{X} \).

    \item If \( f \) and \( g \) are \( p \)-smooth on \( \mathcal{X} \), then their product \( fg \) is \( p \)-smooth on \( \mathcal{X} \).

    \item Let \( f \) be \( p \)-smooth on \( \mathcal{X} \). Then for any fixed \( t \in \mathcal{X}_n \), the function \( g: \mathcal{X}_1 \times \cdots \times \mathcal{X}_{n-1} \to \mathbb{R} \) defined by
    \(
    g(x_1, \dots, x_{n-1}) := f(x_1, \dots, x_{n-1}, t)
    \)
    is \( p \)-smooth on \( \mathcal{X}_1 \times \cdots \times \mathcal{X}_{n-1} \).

    \item Suppose \( f \) is \( p \)-smooth on \( \mathcal{X} \). Define the function \( h: \mathcal{X}_1 \times \cdots \times \mathcal{X}_{n-1} \to \mathbb{R} \) by
    \[
    h(x_1, \dots, x_{n-1}) := \int_{\mathcal{X}_n} f(x_1, \dots, x_n) \, dx_n.
    \]
    Then \( h \) is \( p \)-smooth on \( \mathcal{X}_1 \times \cdots \times \mathcal{X}_{n-1} \).
\end{enumerate}
\end{lemma}
