\begin{proof}[Proof of Lemma~\ref{lemma: p-smooth properties}]
Let \( m = \lfloor p \rfloor \) and \( \beta = p - m \).

(i) Since \( f, g \in C^m(\mathcal{X}) \), it follows immediately that \( kf \in C^m(\mathcal{X}) \) and \( f + g \in C^m(\mathcal{X}) \) for any \( k \in \mathbb{R} \). Moreover, for any multi-index \( \kappa \in \mathbb{N}_0^n \) with \( \|\kappa\|_1 = m \), we have:
\[
D^\kappa(kf) = k D^\kappa f, \quad D^\kappa(f + g) = D^\kappa f + D^\kappa g.
\]
Thus, if \( D^\kappa f \) and \( D^\kappa g \) satisfy a H\"older condition with exponent \( \beta \), then so do \( D^\kappa(kf) \) and \( D^\kappa(f + g) \).

(ii) Since \( f, g \in C^m(\mathcal{X}) \), their product \( fg \in C^m(\mathcal{X}) \) by standard calculus. Fix a multi-index \( \kappa \in \mathbb{N}_0^n \) with \( \|\kappa\|_1 = m \). The product rule for higher-order derivatives gives:
\begin{equation}
\label{eq:product_rule_multiindex}
D^\kappa(fg) = \sum_{\mu \le \kappa} \binom{\kappa}{\mu} \left(D^\mu f\right)\left(D^{\kappa - \mu} g\right),
\end{equation}
where the sum is over all multi-indices \( \mu \in \mathbb{N}_0^n \) such that \( \mu_i \le \kappa_i \) for all \( i \), and \( \binom{\kappa}{\mu} := \prod_{i=1}^n \binom{\kappa_i}{\mu_i} \) is the multi-index binomial coefficient.

By Lemma~\ref{lemma: holder condition}(iii), the \( p \)-smoothness of \( f \) and \( g \) implies that for every \( \mu \le \kappa \), both \( D^\mu f \) and \( D^{\kappa - \mu} g \) satisfy a H\"older condition with exponent \( \beta \). By Lemma~\ref{lemma: holder condition}(i), their product is also H\"older continuous with exponent \( \beta \). Since the sum in \eqref{eq:product_rule_multiindex} is finite, and all terms are H\"older with the same exponent, it follows that \( D^\kappa(fg) \) also satisfies a H\"older condition with exponent \( \beta \). Hence, \( fg \) is \( p \)-smooth.

(iii) Fix \( t \in \mathcal{X}_n \), and define
\(
g(x_1, \dots, x_{n-1}) := f(x_1, \dots, x_{n-1}, t).
\)
Since \( f \in C^m(\mathcal{X}) \), all partial derivatives of \( f \) up to order \( m \) exist and are continuous. The same holds for the restriction \( g \), viewed as a function on \( \mathcal{X}_1 \times \cdots \times \mathcal{X}_{n-1} \).

Now fix a multi-index \( \kappa \in \mathbb{N}_0^{n-1} \) with \( \|\kappa\|_1 = m \). Then
\[
D^\kappa g(x_1, \dots, x_{n-1}) = D^\kappa f(x_1, \dots, x_{n-1}, t).
\]
Since \( f \) is \( p \)-smooth, \( D^\kappa f \) satisfies a H\"older condition with exponent \( \beta \), and restricting the final coordinate to \( t \) preserves the inequality:
\[
\begin{aligned}
|D^\kappa g(x) - D^\kappa g(y)| 
&= |D^\kappa f(x_1, \dots, x_{n-1}, t) - D^\kappa f(y_1, \dots, y_{n-1}, t)| \\
&\le c \|x - y\|_2^\beta.
\end{aligned}
\]
Thus, \( g \) is \( p \)-smooth.

(iv) Define
\[
h(x_1, \dots, x_{n-1}) := \int_{\mathcal{X}_n} f(x_1, \dots, x_n) \, dx_n.
\]
Since \( f \in C^m(\mathcal{X}) \), standard results imply that integration preserves differentiability: \( h \in C^m(\mathcal{X}_1 \times \cdots \times \mathcal{X}_{n-1}) \), and for any multi-index \( \kappa \in \mathbb{N}_0^{n-1} \) with \( \|\kappa\|_1 = m \), we have
\[
D^\kappa h(x_1, \dots, x_{n-1}) = \int_{\mathcal{X}_n} D^\kappa f(x_1, \dots, x_n) \, dx_n.
\]
Let \( x = (x_1, \dots, x_{n-1}) \), \( y = (y_1, \dots, y_{n-1}) \). Then:
\[
\begin{aligned}
|D^\kappa h(x) - D^\kappa h(y)| 
&= \left| \int_{\mathcal{X}_n} \left[ D^\kappa f(x, x_n) - D^\kappa f(y, x_n) \right] dx_n \right| \\
&\le \int_{\mathcal{X}_n} \left| D^\kappa f(x, x_n) - D^\kappa f(y, x_n) \right| dx_n \\
&\le \int_{\mathcal{X}_n} c \|x - y\|_2^\beta dx_n \\
&= c |\mathcal{X}_n|\|x - y\|_2^\beta,
\end{aligned}
\]
where \( |\mathcal{X}_n|\) is the Lebesgue measure of \( \mathcal{X}_n \). It follows that \( D^\kappa h \) satisfies a H\"older condition with exponent \( \beta \), and thus \( h \) is \( p \)-smooth.
\end{proof}


\begin{lemma}
\label{lemma: Q function is p-smooth}
Suppose Assumptions \ref{assumption: reward is p-smooth}, \ref{assumption: transition is p-smooth}, \ref{assumption: policy is p-smooth} hold, then $Q_{k,\widetilde{M}}^{\pi^{(t)}} (h_k, a_k)$ is $p$-smooth in $(s_1,s_2,...,s_k)$ for any $0\le t\le T-1$, $1\le k\le K$, and any fixed $(a_1,...,a_k) \in \mathcal{A}_1 \times \cdots \times \mathcal{A}_k$.
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lemma: Q function is p-smooth}]
Recall that the Algorithm \ref{algo: sieve regression} only update the policy within the policy class $\Pi$, so $\pi^{(t)} \in \Pi$ for any $0\le t\le T-1$. We only need to prove $Q_{k,\widetilde{M}}^{\pi} (h_k, a_k)$ is $p$-smooth in $(s_1,s_2,...,s_k)$ for any $\pi \in \Pi$, any $k$, any $(a_1,...,a_k) \in \mathcal{A}_1 \times \cdots \times \mathcal{A}_k$.

We prove by induction on $k$, from $k=K$ to $k=1$. For $k=K$, we trivially have
\begin{equation*}
Q_{K,\widetilde{M}} ^{\pi} (h_{K},a_{K}) = \widetilde{r}_K (h_K,a_K),
\end{equation*}
so $Q_{K,\widetilde{M}} ^{\pi} (h_{K},a_{K})$ is $p$-smooth in $(s_1,..., s_{K})$ under Assumption \ref{assumption: reward is p-smooth}.

Now we focus on the induction step from $k+1$ to $k$. Suppose $Q_{k+1,\widetilde{M}} ^{\pi} (h_{k+1},a_{k+1})$ is $p$-smooth in $(s_1,..., s_{k+1})$ for some $1\le k\le K-1$. By Bellman equation,
\begin{equation}
\label{eq: proof lemma Q function is p-smooth, eq 1}
\begin{split}
Q_{k,\widetilde{M}} ^{\pi} (h_k,a_k) =& \ \widetilde{r}_k (h_k,a_k) \\
&+ \int_{\mathcal{S}_k} \left( \sum_{a_{k+1} \in \mathcal{A}_{k+1}} \pi_{k+1}(a_{k+1}|h_{k+1}) Q_{k+1, \widetilde{M}} ^{\pi} (h_{k+1},a_{k+1}) \right) \widehat{p}_k (s_{k+1}| h_k, a_k) ds_{k+1}.
\end{split}
\end{equation}
By induction hypothesis, $Q_{k+1,\widetilde{M}} ^{\pi} (h_{k+1},a_{k+1})$ is $p$-smooth in $(s_1,..., s_{k+1})$. By Assumption \ref{assumption: policy is p-smooth}, $\pi_{k+1}(a_{k+1}|h_{k+1})$ is $p$-smooth in $(s_1,..., s_{k+1})$ for any $a_{k+1}\in \mathcal{A}_{k+1}$. Note that $|\mathcal{A}_{k+1}|$ is finite, then by Lemma \ref{lemma: p-smooth properties}(i)(ii), $\sum_{a_{k+1} \in \mathcal{A}_{k+1}} \pi_{k+1} Q_{k+1, \widetilde{M}} ^{\pi}$ is $p$-smooth in $(s_1,..., s_{k+1})$. Similarly, Assumption \ref{assumption: transition is p-smooth} and Lemma \ref{lemma: p-smooth properties}(ii) implies $\sum_{a_{k+1}} \pi_{k+1} Q_{k+1, \widetilde{M}} ^{\pi} \widehat{p}_k (s_{k+1}| h_k, a_k)$ is $p$-smooth in $(s_1,..., s_{k+1})$. By Lemma \ref{lemma: p-smooth properties}(iv), the integral $\int_{\mathcal{S}_k} \sum_{a_{k+1}} \pi_{k+1} Q_{k+1, \widetilde{M}} ^{\pi} \widehat{p}_k ds_{k+1}$ is $p$-smooth in $(s_1,..., s_{k})$. By Assumption \ref{assumption: reward is p-smooth}, $\widetilde{r}_k (h_k,a_k)$ is $p$-smooth in $(s_1,..., s_{k})$. Using Lemma \ref{lemma: p-smooth properties}(i) again, it follows from (\ref{eq: proof lemma Q function is p-smooth, eq 1}) that $Q_{k,\widetilde{M}} ^{\pi} (h_{k},a_{k})$ is $p$-smooth in $(s_1,..., s_{k})$, which finishes the induction step.

\end{proof}

