% \begin{lemma}[Expected Posterior GP Variance]
% \label{lemma: GP posterior expected variance}
% Suppose Assumptions~\ref{assumption: GP kernel} and~\ref{assumption:eigenvalue decay} hold. Let \( \{\mu_j\}_{j=1}^{\infty} \) and \( \{\psi_j\}_{j=1}^{\infty} \) denote the eigenvalues and corresponding eigenfunctions of the kernel \( h \), as given in Lemma~\ref{lemma: Mercer}. Let \( \widehat{h}(x,x) \) denote the posterior variance of a Gaussian process at point \( x \in \mathcal{X} \), after observing \( n \) samples drawn according to the distribution \( \rho \). Then the expected posterior variance satisfies
% \[
% \mathbb{E}_{x \sim \rho}\left[\widehat{h}(x, x)\right] = \mathcal{O}\left(n^{\frac{1}{\omega} - 1}\right).
% \]
% \end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma: GP posterior expected variance}]
Let \( \mathcal{H} := L^2(\mathcal{X}, \rho) \) be the Hilbert space associated with the kernel \( h \), and let \( \{\mu_j\}_{j=1}^\infty \) and \( \{\psi_j\}_{j=1}^\infty \) denote the eigenvalues and eigenfunctions of the integral operator associated with \( h \), as in Lemma~\ref{lemma: Mercer}. By Mercer decomposition from Lemma ~\ref{lemma: Mercer}, the kernel admits the representation
\[
h(x, x') = \sum_{j=1}^{\infty} \mu_j \psi_j(x) \psi_j(x') = \langle \phi(x), \phi(x') \rangle_{\mathcal{H}},
\]
where the feature map is defined by \( \phi(x) := \sum_{j=1}^\infty \sqrt{\mu_j} \, \psi_j(x) \, \psi_j \in \mathcal{H} \).

Given \( n \) observations \( \{x_i\}_{i=1}^n \subset \mathcal{X} \), define the linear operator \( \Phi_n : \mathbb{R}^n \to \mathcal{H} \) by
\[
\Phi_n v := \sum_{i=1}^n v_i \phi(x_i),
\]
with adjoint \( \Phi_n^* : \mathcal{H} \to \mathbb{R}^n \) given by
\[
\Phi_n^* f = \left( \langle f, \phi(x_1) \rangle, \ldots, \langle f, \phi(x_n) \rangle \right)^\top.
\]
Then the Gram operator is given by \( H_{n,n} = \Phi_n^* \Phi_n \), and the kernel evaluation vector at any \( x \in \mathcal{X} \) is \( H_n(x) = \Phi_n^* \phi(x) \in \mathbb{R}^n \).

Using the standard formula for the posterior variance of a Gaussian process,
\[
\widehat{h}(x,x) = h(x,x) - H_n(x)^\top (H_{n,n} + \sigma^2 I)^{-1} H_n(x),
\]
and substituting $H_n(x)$ and $H_{n,n}$ into \eqref{eq: GP, eq 1}, we obtain
\begin{align}
\widehat{h}(x,x) &= \langle \phi(x), \phi(x) \rangle_{\mathcal{H}} - \langle \phi(x), \Phi_n ( \Phi_n^* \Phi_n + \sigma^2 I )^{-1} \Phi_n^* \phi(x) \rangle \nonumber \\
&= \langle \phi(x), A \phi(x) \rangle,
\end{align}
where the linear operator \( A \) is defined by $A := I - \Phi_n(\Phi_n^* \Phi_n + \sigma^2 I)^{-1} \Phi_n^*.$

We simplify \( A \) by observing that
\[
A \Phi_n = \sigma^2 \Phi_n (\Phi_n^* \Phi_n + \sigma^2 I)^{-1},
\quad \text{so} \quad
A \Phi_n \Phi_n^* = \sigma^2(I - A),
\]
which yields the identity
\begin{equation}
\label{eq: A definition}
A = (\sigma^2 I + \Phi_n \Phi_n^*)^{-1} \sigma^2 I
= \left(I + \tfrac{1}{\sigma^2} \sum_{i=1}^n \phi(x_i) \phi(x_i)^* \right)^{-1}.
\end{equation}

Taking expectation over \( x \sim \rho \), we may exchange the expectation with the quadratic form to obtain
\[
\mathbb{E}_{x \sim \rho}[\widehat{h}(x,x)] = \mathbb{E}[\langle \phi(x), A \phi(x) \rangle] = \operatorname{Tr}(A \, \mathbb{E}[\phi(x)\phi(x)^*]).
\]

To control this trace, we apply the matrix Bernstein inequality (Theorem 1.4 in \citep{Tropp_2011}): there exist positive constants \(c_{1},c_{2}>0\), such that
\[
\Pr\left\{ \left\| \tfrac{1}{n} \sum_{i=1}^n \phi(x_i)\phi(x_i)^* - \mathbb{E}[\phi(x)\phi(x)^*] \right\| \ge \tfrac{1}{2} \| \mathbb{E}[\phi(x)\phi(x)^*] \| \right\} \le c_1 e^{-c_2 n}.
\]

Define the event $\mathcal{G}
\;=\;
\Bigl\{\|\frac{1}{n}\sum_{i=1}^n \phi(x_i) \phi(x_i)^* - \mathbb{E}[\phi(x)\phi(x)^{*}]\|\;\le\;\tfrac{1}{2}\,\|\mathbb{E}[\phi(x)\phi(x)^{*}]\|\Bigr\}.$
On \(\mathcal{G}\), we have
\[
\tfrac{1}{n} \sum_{i=1}^n \phi(x_i)\phi(x_i)^* \succeq \tfrac{1}{2} \mathbb{E}[\phi(x)\phi(x)^*],
\]
which implies
\[
A = \left(I + \tfrac{n}{\sigma^2} \cdot \tfrac{1}{n} \sum_{i=1}^n \phi(x_i) \phi(x_i)^* \right)^{-1}
\preceq \left( I + \tfrac{n}{2\sigma^2} \mathbb{E}[\phi(x)\phi(x)^*] \right)^{-1} =: A_{\mathrm{pop}}.
\]
Hence,
\[
\operatorname{Tr}(A \, \mathbb{E}[\phi(x)\phi(x)^*]) \le \operatorname{Tr}(A_{\mathrm{pop}} \, \mathbb{E}[\phi(x)\phi(x)^*]).
\]

Let us now compute the right-hand side trace. Using the Mercer basis \( \{\psi_j\} \), we have
\[
\mathbb{E}[\phi(x)\phi(x)^*] = \sum_{j=1}^{\infty} \mu_j \psi_j \otimes \psi_j,
\quad
A_{\mathrm{pop}} = \sum_{j=1}^{\infty} \frac{2 \sigma^2}{2 \sigma^2 + n \mu_j} \psi_j \otimes \psi_j,
\]
which yields
\[
\operatorname{Tr}(A_{\mathrm{pop}} \, \mathbb{E}[\phi(x)\phi(x)^*]) = \sum_{j=1}^{\infty} \frac{2 \sigma^2 \mu_j}{2 \sigma^2 + n \mu_j}.
\]

To bound the sum, we partition the eigenvalues at the index \( j_0 \), where \( \mu_{j_0} \sim \sigma^2 / n \), i.e., \( j_0 \sim (n/\sigma^2)^{1/\omega} \) under the decay \( \mu_j = \mathcal{O}(j^{-\omega}) \) by Assumption \ref{assumption:eigenvalue decay}. Then
\[
\sum_{j=1}^{\infty} \frac{2 \sigma^2 \mu_j}{2 \sigma^2 + n \mu_j}
\lesssim \frac{\sigma^2}{n} j_0 + \sum_{j=j_0+1}^{\infty} \mu_j
\lesssim n^{-1} \cdot \left(\frac{n}{\sigma^2} \right)^{1/\omega} + \int_{j_0}^\infty j^{-\omega} \, dj
= \mathcal{O}(n^{1/\omega - 1}).
\]

On the complement event \( \mathcal{G}^c \), we trivially have \( A \preceq I \), so
\[
\mathbb{E}[\langle \phi(x), A \phi(x) \rangle \cdot \mathbf{1}_{\mathcal{G}^c}] \le \operatorname{Tr}(\mathbb{E}[\phi(x)\phi(x)^*]) \cdot \Pr(\mathcal{G}^c) = o(n^{1/\omega - 1}).
\]

Combining both cases concludes the proof:
\[
\mathbb{E}_{x \sim \rho}[\widehat{h}(x,x)] = \mathcal{O}(n^{1/\omega - 1}).
\]
\end{proof}


