% \label{lemma: GP posterior variance}
% Suppose Assumptions  \ref{assumption: GP kernel} and \ref{assumption:eigenvalue decay} hold. Let $\{\mu_j\}_{j=1} ^{\infty}$, $\{\psi_j\}_{j=1} ^{\infty}$ be the eigenvalues and corresponding eigenfunctions from Lemma \ref{lemma: Mercer}. 
% For any fixed $x\in \mathcal{X}$, with high probability $1-\delta$, it satisfies that
% \begin{equation*}
% \widehat{h}(x,x) \le M,
% \end{equation*}
% where $M=\sup_{x \in \mathcal{X}} h(x,x)$.
% % provided that 
% % \begin{equation}
% % \label{eq: lemma GP posterior variance eq 1}
% % \sum_{j=1}^{\infty} \mathbbm{1}\{\mu_j>0\} (\psi_j(x))^2 < \infty.
% % \end{equation}

% \end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma: GP posterior variance}]
We adopt the same notation as in the proof of Lemma~\ref{lemma: GP posterior expected variance}. Recall that the posterior variance at a point \( x \in \mathcal{X} \) can be written as $\widehat{h}(x,x) = \langle \phi(x), A \phi(x) \rangle_{\mathcal{H}},$
where \( A  \) is the positive semidefinite, self-adjoint operator.
By spectral decomposition, \( A = \sum_{i=1}^\infty \lambda_i u_i \otimes u_i \), where \( \{u_i\} \) is an orthonormal basis of \( \mathcal{H} \) and \( \lambda_i \ge 0\). Substituting this into the expression for \( \widehat{h}(x,x) \) yields
\[
\widehat{h}(x,x) = \sum_{i=1}^{\infty} \lambda_i \, |\langle u_i, \phi(x) \rangle|^2.
\]

Since \( \{u_i\} \) forms an orthonormal basis, we can expand \( \phi(x) = \sum_{i=1}^\infty \langle u_i, \phi(x) \rangle u_i \), which gives
\[\sum_{i=1}^\infty |\langle u_i, \phi(x) \rangle|^2=\| \phi(x) \|^2 .
\]
By Assumption~\ref{assumption: GP kernel}, the kernel is bounded on \( \mathcal{X} \times \mathcal{X} \), so we define \( M := \sup_{x \in \mathcal{X}} h(x,x)=\sup_{x \in \mathcal{X}} \| \phi(x) \|^2 \). This implies
\[
\sum_{i=1}^\infty |\langle u_i, \phi(x) \rangle|^2 \le M.
\]
and hence,
\begin{equation}
\label{eq: sup posterior bound}
\widehat{h}(x,x) \le  \sup_i \lambda_i \cdot M.
\end{equation}

It remains to bound the spectral norm of \( A \), i.e., \( \max_i \lambda_i \). Recall from the GP posterior derivation that
\[
A = \left(I + \tfrac{1}{\sigma^2} \sum_{i=1}^n \phi(x_i) \phi(x_i)^* \right)^{-1}.
\]
Let \( S := \frac{1}{n} \sum_{i=1}^n \phi(x_i) \phi(x_i)^* \) and note that
\[
\max_i \lambda_i = \left( 1 + \tfrac{n}{\sigma^2} \lambda_{\min}(S) \right)^{-1} \le 1.
\]

Combining with \eqref{eq: sup posterior bound}, we obtain the uniform upper bound:
\[
\widehat{h}(x,x) \le M,
\]
which holds uniformly for all \( x \in \mathcal{X} \).. 
\end{proof}

