\begin{equation}
\label{eq: proof thm uncertainty quantifier GP part2 eq 1}
\log\left( \det \left( I_n + \tfrac{1}{\sigma^2} H_{n,n} \right) \right) \lesssim \left(d^*(n)\right)^2 \log n,
\end{equation}
where the effective dimension \( d^*(n) \) is defined as (see Definition 9 of \cite{chang2021mitigating}):
\[
d^*(n) := \min \left\{ J \in \mathbb{N} : \frac{J}{\sum_{i=J+1}^{\infty} \mu_i} \ge \frac{n}{\sigma^2} \right\}.
\]

Under Assumption~\ref{assumption:eigenvalue decay}, the eigenvalues satisfy \( \sum_{i=J+1}^{\infty} \mu_i \le \int_{J}^{\infty} i^{-\omega} \, di \lesssim J^{-(\omega - 1)} \). This implies that
\[
\frac{J}{\sum_{i=J+1}^{\infty} \mu_i} \gtrsim J^\omega,
\]
and thus the definition of \( d^*(n) \) yields $d^*(n) \lesssim n^{\frac{1}{\omega}}.$

Substituting into the expression for \( \beta_{k,n} \) in equation~\eqref{eq: GP, eq 4}, we obtain
\[
\beta_n \lesssim (\log n)^2 \cdot d^*(n) \lesssim (\log n)^2 \cdot n^{\frac{1}{\omega}}.
\]
This completes the proof.
\end{proof}


