\begin{theorem}[Yu~{\cite[Thm.~4.3]{Yu97}}]\label{Yu}
 Let \(g, d \ge 1\) be integers. 
 Let \(\surf\) be a surface with Euler genus \(g\), and let  \(G\) be a graph embedded in \(\surf\) with face-width at least \(w_{\ref{Yu}}(g, d) := 8(2d+1)(2^{g}-1)\). 
 Then there exists a planarization \((\CC, G', \surf', \CC')\) of \(G\) and a depth-\(d\) nest \(\DD(C')\) in \(G'\) (which is embedded in \(\surf'\)) around each \(C' \in \CC'\) such that for any distinct \(C', C'' \in \CC'\), the nests \(\DD(C')\) and \(\DD(C'')\) are disjoint and \(C'\) is outside \(\DD(C'')\) or \(C''\) is outside \(\DD(C')\).
\end{theorem}

See \Cref{fig:nests_Klein_bottle} for an illustration of Yu's planarization theorem.\medskip

Below, we construct from the planarization and the nests produced by \Cref{Yu} a collection of at most $2g$ surfaces with boundary covering $\surf$. We make sure that each surface with boundary in the cover is either a sphere with boundary or a projective plane with boundary. Hence, we can apply \Cref{thm:planar} or \Cref{proj-planar-case} to each one.

Let \(g \ge 2\) be an integer.
Let \(r := 16\), let \(d := 3r+1\), and let \(w(g) := \max\{w_{\ref{Yu}}(g, d), r+1\}\).
Let \(\surf\) be a surface with Euler genus \(g\), and let \(G\) be a graph embedded in \(\surf\) with face-width at least \(w(g)\).
We apply~\Cref{Yu}. Denote by \(\CC' = \{C'_1,\ldots,C'_g\}\) the set of cuffs of \(\surf'\), regarded as cycles of \(G'\). For each \(i \in [g]\), let \(\DD(C'_i) = (D_{i,0},\ldots,D_{i,d})\) denote the nest around \(C'_i\), and by \(\Delta_{i,0} \subsetneq \cdots \subsetneq \Delta_{i,d}\) the corresponding (closed) disks. Recall that $\widehat{\surf'} = \surf' \cup \Delta_{1,0} \cup \cdots \cup \Delta_{g,0}$ is the sphere obtained from \(\surf'\) by capping all its cuffs.

\paragraph{Construction of an auxiliary tree $T$.}
Consider the subgraph $H$ of $G'$ 
obtained by taking the union of all the cycles $D_{i,j}$ where $i \in [g]$ and $j \in \{0\} \cup [d]$. 
Recall that these cycles are pairwise disjoint. 
We obtain a graph embedded on the sphere $\widehat{\surf'}$, whose dual graph $H^*$ is a tree with parallel edges. 
Let $T$ denote the tree obtained from $H^*$ by keeping one representative edge in each class of parallel edges. 
We make $T$ into a rooted tree by marking as the root the face which is the complement of $\Delta_{1,d} \cup \cdots \cup \Delta_{g,d}$ in $\widehat{\surf'}$. 
We denote the root of $T$ by $r$ and the collection of non-root leaves of $T$ by $L$. 

Note that the tree $T$ has exactly $g(d+1)+1$ vertices and $g$ non-root leaves.
By construction of $T$ through the dual, each vertex $v\in V(T)$ bijectively corresponds to a face $f(v)$ of $H$ embedded in $\widehat{\surf'}$. For each $i\in[g]$, we denote by $\ell_i \in L$, the unique leaf with $f(\ell_i)=\intt(\Delta_{i,0})$.
Note that these faces are contained in $\widehat{\surf'} - \surf'$. Actually, $\widehat{\surf'} \setdiff \surf' = \bigcup_{i \in [g]} f(\ell_i)$.
Further, each edge $e\in E(T)$ corresponds to a cycle of $G'$ in the following way.
Let $e\in E(T)$ be the representative edge for the edges which are dual to the edges of the cycle $D_{i,j}$ for some $i\in [g]$ and $j\in\{0\}\cup[d]$.
Then we label the edge $e$ with the cycle $D(e)=D_{i,j}$. 

Every subset of vertices $U \subseteq V(T)$ has a natural mapping to a subspace of $\surf'$. We define $\Pi'(U)$ to be the union of all the faces $f(u)$ for $u \in U \setdiff L$ and all the cycles $D(e)$ for an edge $e \in E(T)$ incident to some vertex in $U$.
For $v \in V(T - L)$, subspace $\Pi'(\{v\})$ is the closure of a face of $H$, hence a sphere with boundary. Our next result generalizes this to connected subsets of $V(T - L)$. Moreover, the number of cuffs of $\Pi'(\{v\})$ is simply the degree of $v$ in $T$.

\begin{lemma} \label{lem:Pi'}
If $U \subseteq V(T - L)$ is non-empty and connected, then $\Pi'(U)$ is a sphere with boundary contained in $\surf'$. Moreover, $\Pi'(U)$ is contoured by $H = \bigcup_{i,j} D_{i,j}$ and the cuffs of $\Pi'(U)$ are the cycles $D(e)$ for $e \in \delta_T(U \setdiff L)$.
\end{lemma}

\begin{proof}
Let $u_1$, \ldots, $u_p$ be an enumeration of the vertices of $U$ such that, for all $i \in [p]$, $\{u_1,\ldots,u_i\}$ is connected and $u_i$ has (at most) one neighbor in $\{u_1,\ldots,u_{i-1}\}$. We use \Cref{prop:gluing_surfaces_with_bd} to show that $\Pi(\{u_1,\ldots,u_i\})$ is a sphere with boundary for all $i \in [p]$, by induction on $i$. The last part of the statement follows readily from the definition of $\Pi'(U)$.
\end{proof}

We denote $\Pi(U):=\pi(\Pi'(U))$ the corresponding subspace of $\surf$, where $\pi$ is the canonical projection map $\pi$ from \Cref{sec:background_surfaces}. In \Cref{set-props} below, we show that, for our very particular choice of $U$, this subspace is either a sphere with boundary or a projective plane with boundary. 

\paragraph{Using $T$ to find a surface cover.}
We partition the vertices of $T$ into connected subsets.
Let $i\in [g]$. 
We define $A_i$ as the subset of $V(T)$ containing all vertices whose distance to $\ell_i$ is at most $d/3$. (In particular, $A_i$ contains $\ell_i$.)
For distinct disks $\Delta_{i,0}$ and $\Delta_{j,0}$, \Cref{Yu} gives us that either $\Delta_{i,0}$ is disjoint from $\Delta_{j,d}$, or $\Delta_{j,0}$ is disjoint from $\Delta_{i,d}$.
This implies that every two distinct vertices of $L \cup \{r\}$ have distance at least $d$. Hence, $A_{i}$ and $A_{j}$ have distance at least $d/3$, whenever $i, j \in [g]$ are distinct. Let $B_1,B_2,\ldots, B_k$ be the vertex sets of the connected components of $T - A_1 - \cdots - A_g$. 

We proceed to argue that $k\le g$.
We define a surjective map $\psi:[g]\to[k]$ in the following way.
For each $i \in [g]$, we walk up in $T$ towards the root starting from $\ell_i$ until we leave $A_i$. By what precedes, we enter $B_j$ for some $j \in [k]$. We let $\psi(i) := j$. Observe $\psi(i)$ is well defined since the root of $T$ is not contained in $A_i$ for any $i \in [g]$. To see that $\psi$ is surjective, pick any $j \in [k]$ and any vertex $u \in B_j$ and walk down from there until we leave $B_j$. Let $v$ be the first vertex we encounter outside of $B_j$. We know that $v$ is contained in $A_i$ for some $i \in [g]$. We continue by following the path from $v$ down to $\ell_i$, which completely lies within $A_i$. We obtain a path going down from $u$ to $\ell_i$, whose first part is contained in $B_j$ and second part in $A_i$. This gives an index $i \in [g]$ such that $\psi(i) = j$. We conclude that $k\le g$.


Let $L_1\subseteq L$ be the collection of non-root leaves of $T$ such that the corresponding cuff is a one-sided cycle in $\surf$.
We let $\mathcal{A}_1 := \{A_i \mid i\in [g],\ \ell_i\in L_1\}$.
The rest of the $A_i$'s can be partitioned into pairs where the corresponding leaves correspond to cuffs resulting from cutting along the same two-sided cycle in $\surf$. Let $M \subseteq {L \setdiff L_1 \choose 2}$ denote the corresponding matching. 
Let $\mathcal{A}_2 := \{A_{i} \cup A_{j} \mid \ell_i\ell_j \in M\}$. 
Let $\mathcal{A} := \mathcal{A}_1\cup \mathcal{A}_2$. 
Let $\mathcal{B} := \{B_j \mid j \in [k]\}$ and $\mathcal{S}:=\mathcal{A}\cup\mathcal{B}$.

For each set $S \in \mathcal{S}$, we define a set $S^+$ where $S^+$ contains $S$ as well as all adjacent vertices. Notice that $S^+ = N_T[S]$.


\paragraph{Properties of the surface cover.}
Since the members of $\mathcal{S}$ partition $V(T)$, the collection $\left\{(\Pi(S),\Pi(S^+))\right\}_{S\in\mathcal{S}}$ is a surface cover of $\surf$.
In the following, we present further properties of $S$ and $S^+$ for $S\in\mathcal{S}$ that allow us to complete the proof of \Cref{thm:bounded_genus}.

\begin{lemma}\label{set-props}
    Fix $S\in\mathcal{S}$.
    Then $(\Pi(S),\Pi(S^+))$ is a pair of nested surfaces with boundary.
    Furthermore, $\Pi(S)$ and $\Pi(S^+)$ are projective planes with boundary if $S\in\mathcal{A}_1$ and spheres with boundary otherwise.
\end{lemma}


\begin{proof}
    Let $S$ be any member of $\mathcal{S}$. We invoke \Cref{lem:Pi'} and conclude that $\Pi'(S)$ is a sphere with boundary whenever $S \in \mathcal{A}_1 \cup \mathcal{B}$, and the disjoint union of two spheres with boundary whenever $S = A_i \cup A_j \in \mathcal{A}_2$. (Recall that $A_i$ and $A_j$ are at distance at least $d/3 \ge 4$ whenever $i, j \in [g]$ are distinct.)

    Recall that $\pi$ is injective outside of the $g$ cuffs of $\Sigma'$, namely, the cycles $D_{i,0}$ for $i \in [g]$. In order to understand $\Pi(S) = \pi(\Pi'(S))$ topologically, we have to see which cuffs of $\Sigma'$ belong to $\Pi'(S)$.

    Observe that $\Pi'(S)$ contains at most two cuffs of $\Sigma'$. More precisely, $S$ contains exactly one cuff if $S \in \mathcal{A}_1$, two cuffs if $S \in \mathcal{A}_2$ and no cuff if $S \in \mathcal{B}$. Furthermore, we made sure that if $S$ contains one cuff, this cuff is mapped to a one-sided cycle in $\surf$ by $\pi$, and if $S$ contains two cuffs, these cuffs originate from the same two-sided cycle in $\surf$, and are both mapped to this cycle by $\pi$.

    We derive the following consequences. First, if $S \in \mathcal{B}$, then $\Pi(S)$ is a sphere with boundary. Second, if $S = A_i \cup A_j \in \mathcal{A}_2$, then $\Pi(S)$ is obtained by gluing the spheres with boundary $\Pi'(A_i)$ and $\Pi'(A_j)$ along one common cuff, and is hence again a sphere with boundary. Third, if $S = A_i \in \mathcal{A}_1$, then $\Pi(S)$ is obtained from the sphere with boundary $\Pi'(A_i)$ by identifying pairs of points within one cuff, and is thus a projective plane with boundary.

    Notice that $\Pi(S^+)$ is obtained from $\Pi(S)$ by gluing a sphere with boundary along each cuff of $\Pi(S)$. The spheres with boundary that are glued are pairwise disjoint, since the distance of $A_i$ and $A_j$ is at least $4$ for $S=A_i\cup A_j\in\mathcal{A}_2$. Hence $\Pi(S)$ and $\Pi(S^+)$ are nested. In particular, $\Pi(S^+)$ is a sphere with boundary exactly when $\Pi(S)$ is and a projective plane with boundary exactly when $\Pi(S)$ is. Their respective number of cuffs can of course differ.
\end{proof}


\begin{lemma}\label{proj-planar-fw}
	For $S\in \mathcal{A}_1$ we have $\fw(G\cap\Pi(S))\ge r$.
    \end{lemma}
\begin{proof}
	Let $\Pi:=\Pi(S)$. 
    Let $\ell_i\in L_1$ be the leaf of $T$ which is contained in $S$. 
	By \Cref{set-props}, $\Pi$ is a projective plane with boundary. 
    Assume for a contradiction that $\fw(G\cap\Pi)<r$. 
    Let $o$ be a noose in $\widehat{\Pi}$ which intersects $G\cap\Pi$ in less than $r$ vertices. 
    The noose $o$ has to intersect $D_{i,0}$ since both $o$ and $D_{i,0}$ correspond to non-contractible curves in $\Pi$. 
    Since the noose intersects $G\cap\Pi$ in less than $r$ vertices, it is contained in $\Pi$ (recall that $d=3r+1$). 
    Since $o$ is one-sided, it is also a noose in $\surf$ intersecting $G$ in less than $r$ vertices. 
    This is a contradiction to the assumption that the face-width of $G$ is at least $\max\{w_{\ref{Yu}}(g, d), r+1\}$. 
\end{proof}

\begin{proof}[Proof of \Cref{thm:bounded_genus}]
    By the above construction and \Cref{set-props}, we obtain a collection of at most $2g$ pairs of nested spheres with boundary and projective planes with boundary $\left\{(\Pi(S),\Pi(S^+))\right\}_{S\in\mathcal{S}}$ forming a surface cover of $\surf$.
    By \Cref{3c-minor}, we obtain a minor $H_S$ for each $S\in\mathcal{S}$, such that $H_S$ is $3$-connected and agrees with $G$ in the neighborhood of $\Pi(S)$.
    Further, if $H_S$ is embedded in a projective plane, we know by \Cref{proj-planar-fw} that it has face-width at least $16$.
    Since the embeddings of $G$ and $H_S$ coincide within $\Pi(S)$, and $H_S$ is a supergraph of $G\cap\Pi(S)$, we conclude that $\fw(H_S) \ge \fw(G\cap\Pi(S)) \ge 16$ in this case.
    We denote by $R_S:=R\cap V(G\cap\Pi(S))$. 
    Then, by \Cref{thm:planar} and \Cref{proj-planar-case}, we obtain a face cover of size $O(t^4)$ for each $(H_S,R_S)$.
    We conclude by \Cref{lifting-covers} that $(G,R)$ admits a face cover of size $O(g \cdot t^4)$.
\end{proof}

We define the \emph{strong product} of two graphs $G$ and $H$ as $G\boxtimes H$, such that the vertex set corresponds to the cartesian product, that is, $V(G\boxtimes H):=V(G)\times V(H)$.
Further, we have an edge $(u,v)(u',v')\in E(G\boxtimes H)$ if either $u=u'$ and $vv'\in E(H)$, or $uu'\in E(G)$ and $v=v'$, or $uu'\in E(G)$ and $vv'\in E(H)$.

For $p \ge 3$ and $n = 2p$, we define the {\em bagel} as $B_n := K_2 \boxtimes C_p$, that is, the strong product of an edge and the cycle $C_p$. We denote the vertices of the first copy of $C_p$ by $v_1,\dots,v_p$, and the vertices of the second copy by $w_1,\dots,w_p$. Note that there is an edge between $v_i$ and $w_j$ if and only if $i-j\in\{0,\pm1\}$ (recall that indices are computed cyclically). To turn $B_n$ in a rooted graph, we mark each vertex as a root.

\begin{proposition} \label{prop:bagel}
For all even $n \ge 6$, $B_n$ has no (rooted) $K_{2,5}$ minor.
\end{proposition}

\begin{proof}
    Toward a contradiction, assume that $B_n$ has a $K_{2,5}$-model $M$ for some even $n = 2p \ge 6$, and assume that $n$ is minimum among such counterexamples. 

    As before, we denote by $M(x_1)$ and $M(x_2)$ the two branch sets that are adjacent to each \emph{central} branch set $M(y_1),\dots,M(y_5)$.
    Since every vertex of $B_n$ is a root, we can assume without loss of generality that each central branch set $M(y_i)$ contains a single vertex. Summing up, we have seven pairwise disjoint connected sets, namely $M(x_1)$, $M(x_2)$ plus five singleton sets $M(y_1)$, \ldots, $M(y_5)$, such that $M(y_i)\subseteq N(M(x_1))\cap N(M(x_2))$ holds for all $i \in [5]$. 

    In case there is some $i \in [2]$ and $j \in [p]$ such that $M(x_i)$ contains both $v_j$ and $w_j$, we can safely delete one from $M(x_i)$ without destroying our $K_{2,5}$-model.
    Observe further that for any $j \in [p]$, exchanging $v_j$ and $w_j$ 
    yields a graph isomorphism of $B_n$.
    Hence, we may assume without loss of generality that $M(x_1) \subseteq \{v_1,\ldots,v_p\}$ and $M(x_2) \subseteq \{w_1,\ldots,w_p\}$.
    Further, $M(x_1)$ and $M(x_2)$ induce connected subgraphs in their respective cycles, that is, each induces a path or a cycle.

    Since there is a total of $5$ vertices corresponding to the branch sets $M(y_i)$, we can assume without loss of generality that at least $3$ of them are contained in $\{v_1,\dots,v_p\}$.
    Thus in particular $M(x_1)$ cannot contain all vertices in $\{v_1,\dots,v_p\}$ and it induces a path $P=M(x_1)$ within $\{v_1,\dots,v_p\}$.
    Observe that for any such path $|N(P)\cap\{v_1,\dots,v_p\}|\le 2$, which contradicts the assumption that at least $3$ of the central branch sets are contained in $\{v_1,\dots,v_p\}$.
   \end{proof}

