	\title{On Hierarchical Coded Caching with Offline Users\\}

	\author{\IEEEauthorblockN{ Rashid Ummer N.T\IEEEauthorrefmark{1}, Charul Rajput\IEEEauthorrefmark{2}, B. Sundar Rajan\IEEEauthorrefmark{1}}
