\section{Hierarchical Hotplug Placement Delivery Array}\label{hhpda_def}
In this section, we first introduce a combinatorial structure called Hierarchical Hotplug Placement Delivery Array (HHPDA). Then, we show that corresponding to any HHPDA, there exist a hotplug hierarchical coded caching scheme. 
\begin{defn}[Hierarchical Hotplug Placement Delivery Array]\label{def:hhpda}
Consider any positive integers $K_1, K_2, K', F, F', Z_1, Z_2, Z'$ with $Z_1+Z_2 < F' \le F$, $K' \le K_1K_2$,  and any integer sets $\mathcal{S}$ and $\mathcal{S}_{k_1}, k_1 \in [K_1]$, and $\mathcal{S} \cap \mathcal{S}_{k_1} = \emptyset$. Consider two arrays given as follows. \\
\noindent $\bullet$ An  $ F \times (K_1+K_1K_2)$ array $\mathbf{Q}= \left( \mathbf{Q^{(0)}},\mathbf{Q^{(1)}}, \ldots, \mathbf{Q^{(K_1)}} \right)$, where $\mathbf{Q^{(0)}}=(q_{f,k_1}^{(0)})_{f \in [F], k_1 \in [K_1]}$, is an $F \times K_1$ array consisting of $\star$ and \textit{null},  and $\mathbf{Q^{(k_1)}}=(q_{f,k_2}^{(k_1)})_{f \in [F], k_2 \in [K_2]}$ is an $F \times K_2$  array over  $(\{\star\} \cup \{\textit{ null }\} \cup \mathcal{S}_{k_1} ), k_1 \in [K_1]$, satisfies the following conditions: \\
	\textit{A1}. Each column of $\mathbf{Q^{(0)}}$ has $Z_1$ stars. \\
	\textit{A2}. Each column of $\mathbf{Q^{(k_1)}}$ has $Z_2$ stars, for each $k_1 \in [K_1]$. \\
	\textit{A3}. Each integer $s \in \mathcal{S}_{k_1}$ occurs in exactly the subarray $\mathbf{Q^{(k_1)}}$ where $ k_1 \in [K_1]$, and if $q_{f,k_1}^{(0)}=\star$, then $q_{f,k_2}^{(k_1)} \in \{\star\} \cup \mathcal{S}_{k_1} $, $\forall$ $f \in [F],k_1 \in [K_1], k_2 \in [K_2]$. \\
	\textit{A4}.  For any two distinct entries $q_{f,k_i}^{(k_1)}$ and $q_{f',k_j}^{(k_1)}$, we have $q_{f,k_i}^{(k_1)}=q_{f',k_j}^{(k_1)}=s \in \mathcal{S}_{k_1}$ is an integer only if (\textit{a}) $f \neq f'$, $k_i \neq k_j$, %i.e., they lie in distinct rows and distinct columns of $\mathbf{Q^{(k_1)}}$, 
and (\textit{b}) $q_{f,k_j}^{(k_1)}=q_{f',k_i}^{(k_1)}=\star$. \\
	\noindent $\bullet$ An $ F' \times K'$ array $\mathbf{B}=(b_{f',k})_{f' \in [F'], k \in [K']}$ which is a $(K', F', Z', |\mathcal{S}|)$ PDA.	\\
%	For a given $\mathbf{Q}$, consider an $ F \times (K_1K_2)$ array $\mathbf{Q'}=\left(\mathbf{Q'^{(1)}}, \ldots,\mathbf{Q'^{(K_1)}} \right)$. For each $k_1 \in [K_1]$, $\mathbf{{Q'}^{(k_1)}}=({q'}_{f,k_2}^{(k_1)})_{f \in [F], k_2 \in [K_2]}$ is an $F \times K_2$  array consisting of $\star$ and \textit{null} such that 
%	\begin{equation}\label{eq:hhpda1}
%		{q'}_{f,k_2}^{(k_1)}=\begin{cases}
%			\star & \text{if} \text{ either } q_{f,k_1}^{(0)}=\star \text{ or } q_{f,k_2}^{(k_1)}=\star \\
%			\text{null} & \text{ otherwise. }
%		\end{cases}
%	\end{equation}
%	For each $\tau \subseteq [K_1K_2], |\tau| = K'$, there exists a subset $\zeta \subseteq [F], |\zeta|=F'$ such that 
%\begin{equation}\label{eq:hhpda2}
%	[\mathbf{Q'}]_{\zeta \times \tau} \myeq \mathbf{B},
%\end{equation}
%where array $[\mathbf{Q'}]_{\zeta \times \tau}$ denotes the subarray of $\mathbf{Q'}$ whose rows corresponds to the set $\zeta$ and columns corresponds to the set $\tau$, and $\myeq$ denotes that the positions of all stars are same in both the arrays. This is referred to as a $(K_1,K_2,K';F, F';Z_1,Z_2,Z';\mathcal{S},\mathcal{S}_1, \ldots,\mathcal{S}_{K_1})$ HHPDA $(\mathbf{Q}, \mathbf{B})$.
For each $\tau \subseteq \{(k_1, k_2) | k_1 \in [K_1], k_2\in [K_2]\}, |\tau| = K'$, there exists a subset $\zeta \subseteq [F], |\zeta|=F'$ such that 
\begin{equation}\label{eq:hhpda}
	\mathbf{Q'}_{\zeta,\tau} \myeq \mathbf{B},
\end{equation}
where array $\mathbf{Q'}_{\zeta,\tau} = (q'_{f', (k_1, k_2)})_{f' \in \zeta, (k_2,k_2) \in \tau}$ is an $F' \times K' $ array defined as 
