%%%%%HHPDA Algorithm
\begin{algorithm}[]
	%\setstretch{0.8}
	\renewcommand{\thealgorithm}{1}
	\caption{Hotplug hierarchical coded caching scheme based on a HHPDA $(\mathbf{Q}=\left( \mathbf{Q^{(0)}},\mathbf{Q^{(1)}}, \ldots,\mathbf{Q^{(K_1)}} \right), \mathbf{B})$}
	\label{alg:hhpda}
	\begin{algorithmic}[1]
		\Procedure{Placement}{$\mathbf{Q},\mathcal{W}$}       
		\State Split each file $W_n \in \mathcal{W}$ into $F'$ packets, i.e., $W_n =\{W_{n,f'} | f' \in [F']\}$.  Encode $F'$ packets of each file $W_n, n \in [N]$, into $F$ coded packets using $[F, F']$ MDS code with generator matrix $G$ of order $F' \times F$, i.e.,
		$$\begin{bmatrix}
			C_{n,1} \\ C_{n,2} \\ \vdots \\ C_{n, F} 
		\end{bmatrix} =  G^{T}\begin{bmatrix}
			W_{n,1} \\ W_{n,2} \\ \vdots \\ W_{n, F'} 
		\end{bmatrix} .$$ 
		\For{\texttt{$k_1 \in [K_1]$}}
		\State  $\mathcal{Z}_{k_1}$ $\leftarrow$ $\{C_{n,f}: q_{f,k_1}^{(0)}=\star, n \in [N],f \in [F]\}.$
		\EndFor
		\For{\texttt{$(k_1,k_2), k_1 \in [K_1], k_2 \in [K_2] $}}
		\State $\mathcal{Z}_{(k_1,k_2)}$ $\leftarrow$ $\{C_{n,f}: q_{f,k_2}^{(k_1)}=\star, n \in [N],f \in [F]\}.$
		\EndFor
		\EndProcedure	
\Procedure{Delivery Server}{$\mathbf{Q},\mathbf{B},\mathcal{W},\mathcal{U}',\vec{d} \hspace{0.1cm}$}
		\State 	For a set of active user $\mathcal{U}'$, find a subset $\zeta \subseteq [F], |\zeta|=F'$ such that $\mathbf{Q'}_{\zeta, \mathcal{U}'} \myeq \mathbf{B} $, where $\mathbf{Q'}_{\zeta, \mathcal{U}'}$ is defined in \eqref{arrayQ}.
		\State Make a new array $\overline{\mathbf{Q}}=(\overline{q}_{f,k})_{f \in \zeta, k \in [K']}$ by filling $s \in \mathcal{S}$ integers in null spaces of the array $\mathbf{Q'}_{\zeta, \mathcal{U}'}$ in such a way that $\overline{\mathbf{Q}}=\mathbf{B}$.
		\For{\texttt{$s \in \mathcal{S} $}}
		\State Server sends the following coded message to the mirror sites:
		\State $X_s=\underset{\overline{q}_{f,k}=s, f\in \zeta,k\in[K']}{\bigoplus}C_{d_{k},f}$
		\EndFor    
		\EndProcedure	
		\Procedure{Delivery Mirror $k_1$}{$\mathbf{Q},\mathbf{B},\mathcal{W},\mathcal{U}',\vec{d}, X_s $} 
		\State Let $\mathcal{S}^{(j)} \subseteq \mathcal{S}$ is the set of integers appearing in the $j^{th}$ column of $\textbf{B}$.
		\For{$ s \in \mathcal{S}^{(j)}$ for which $\phi^{-1}(j) \in \mathcal{U}'_{k_1} $}
		\State After receiving $X_s$, mirror site $k_1$ sends the following coded message to users in $\mathcal{U}_{k_1}$:
		\State \hspace{-0.4cm} $X_{k_1,s}=X_s{\bigoplus}\left(\tiny \underset{\begin{array}{c}  q^{(0)}_{f,k_1}=\star, \overline{q}_{f,k'}=s, f\in \zeta, \\ k' \in [K'] \backslash \phi(\mathcal{U}'_{k_1}) \end{array}}{\bigoplus}C_{d_{k'},f}\right)$
		\EndFor
		\State  Let $\mathcal{S}_{k_1}^{(k_2,\zeta)} \subseteq \mathcal{S}_{k_1}$ be the set of integers appearing in $k_2^{th}$ column and the rows indexed by $f \in \zeta$ of $\mathbf{Q^{(k_1)}}$.
		\For{$s' \in \mathcal{S}_{k_1}^{(k_2,\zeta)},$ for which $(k_1,k_2) \in \mathcal{U}'_{k_1}, $}
		\State Mirror site $k_1$ sends the following coded signal:
		\State $X_{k_1,s'}=\underset{q_{f,k_2}^{(k_1)}=s', f\in \zeta, \phi((k_1,k_2))=j  }{\bigoplus}C_{d_{j},f}$
		\EndFor   
		\EndProcedure	
	\end{algorithmic}
\end{algorithm}
\begin{comment}
	\begin{rem}
		If for some set $\tau \subseteq \{(k_1, k_2) | k_1 \in [K_1], k_2\in [K_2]\}, |\tau| = K'$, there exist more that one subset $\zeta \subseteq [F], |\zeta|=F'$ satisfying condition \eqref{eq:hhpda}, then select the one for which $q_{f',k_1}^{(0)}=\star$ for maximum possible $f' \in \zeta$. That will minimize $R_2$ for corresponding mirror $k_1 \in[K_1]$.
	\end{rem}
\end{comment}
\begin{rem}
	In Definition \ref{def:hhpda} of HHPDA, if $Z_1=0$, then discarding $\mathbf{Q^{(0)}}$ from $\mathbf{Q}$, results in an array $(\mathbf{Q}, \mathbf{B})$ that satisfies the definition of HpPDA. The resulting scheme corresponds to the hotplug hierarchical scheme described in \cite{ACS}.
\end{rem}

The following example illustrates Theorem \ref{thm:hhpda} and Algorithm \ref{alg:hhpda}.
	\begin{example}\label{hhpda_ex2}
	Consider the $(4,2,3;14, 9;3,4,5;\mathcal{S}=[5],\mathcal{S}_1=\{6:11\},\mathcal{S}_2=\{12:17\},\mathcal{S}_3=\{18:23\},\mathcal{S}_4=\{24:29\})$ HHPDA $(\mathbf{Q}, \mathbf{B})$ in Example \ref{hhpda_ex1}. Based on this HHPDA, one can obtain a $(4,2,3;\frac{N}{3},\frac{4N}{9};N)$ hotplug hierarchical coded caching scheme using Algorithm \ref{alg:hhpda} as follows. \\
	\noindent $\bullet$ \textit{Placement phase:} From line $2$ of Algorithm \ref{alg:hhpda}, each file $W_n, \forall n \in [N]$ is split into $9$ packets, i.e., $W_n =\{W_{n,1},W_{n,2}, \ldots, W_{n,9}\}$. These packets are then encoded using a $[9,14]$ MDS code. The $14$ coded packets of each file is denoted by $\{C_{n,1},C_{n,2}, \ldots,C_{n,14}\}$. By line $3-5$ of Algorithm \ref{alg:hhpda}, the packets cached in each mirror site is given by, $\mathcal{Z}_1 = \{C_{n,1},C_{n,2},C_{n,3}\}, \mathcal{Z}_2 = \{C_{n,1},C_{n,8},C_{n,13}\}, \mathcal{Z}_3 = \{C_{n,2},C_{n,13},C_{n,14}\}, \mathcal{Z}_4 = \{C_{n,3},C_{n,8},C_{n,14}\}, \forall n \in [N]$. Therefore, $\frac{M_1}{N}=\frac{Z_1}{F'}=\frac{3}{9}=\frac{1}{3}$. By lines $6-8$ of Algorithm \ref{alg:hhpda}, four coded packets are cached by each user. For example, the packets cached by user $\mathcal{U}_{(2,1)}$ is given by, $\mathcal{Z}_{(2,1)} = \{C_{n,4},C_{n,5},C_{n,10},C_{n,11}\}, \forall n \in [N]$. Therefore, $\frac{M_2}{N}=\frac{Z_2}{F'}=\frac{4}{9}$.\\
	\noindent $\bullet$ \textbf{Delivery phase}: Since $K'=3$, any three users are active during delivery phase. Let  $\mathcal{U}'=\{{(1,1)},{(2,2)},{(3,1)}\}$ be the set of $3$ active users arranged in the lexicographic order of $(k_1,k_2)$. Consider a bijection $\phi(.)$ from $\mathcal{U}'$ to $[3]$. Then the subset $\zeta \subseteq [14], |\zeta|=9$ such that $\mathbf{Q'}_{\zeta, \mathcal{U}'} \myeq \mathbf{B} $, specified in line $11$ of Algorithm \ref{alg:hhpda}, is given by $\zeta =\{1,2,12,7,4,13,3,8,14\}$. Therefore, by line $12$ of Algorithm \ref{alg:hhpda}, one can construct the array $\mathbf{Q'}_{\zeta, \mathcal{U}'}$ such that $\overline{\mathbf{Q}}=\mathbf{B}$. That is,
	\begin{equation*}
		\overline{\mathbf{Q}}=\begin{blockarray}{cccc}
			& 1 & 2 & 3  \\
			\begin{block}{c[ccc ]}
				1 &\star & \star &  1 \\
				2 & \star & 1 & \star\\
				12 &1 & \star & \star\\
				7 &\star & \star & 2  \\
				4 & \star & 2 & \star\\
				13 & 2 & \star & \star\\
				3 &\star & 3 &  4 \\
				8 & 3 & \star & 5 \\
				14 &4 & 5 & \star\\
			\end{block}
		\end{blockarray}.
	\end{equation*}

	Let demand vector $\vec{d}=(d_{1},d_{2},d_3)=(W_1,W_2,W_3)$. Then by lines $13-16$, the server sends the following coded messages. 
	$ X_1 = C_{1,12} \oplus C_{2,2} \oplus C_{3,1} , X_2 = C_{1,13} \oplus C_{2,4} \oplus C_{3,7}, X_3 = C_{1,8} \oplus C_{2,3}, X_4 = C_{1,14} \oplus C_{3,3} \text{ and } X_5 = C_{2,14} \oplus C_{3,8}$.
	Therefore the load of the first layer is $R_1=\frac{5}{9}$. 

	After receiving $X_1$, $X_2$, $X_3$, $X_4$ and $X_5$,  by lines $19-23$ of Algorithm \ref{alg:hhpda}, the mirror site $k_1=1$ sends the coded messages $X_{1,s}$ as follows.
	$X_{1,1}=X_1{\bigoplus} C_{2,2} \oplus C_{3,1} = C_{1,12}$, $X_{1,2}=X_2$, $X_{1,3}=X_3$, $X_{1,4}=X_4$. 
	Similarly, mirror site $2$ sends $X_{2,1}=X_1{\bigoplus} C_{3,1} =C_{1,12} \oplus C_{2,2}$, $X_{2,2}=X_2 $, $X_{2,3}=X_3{\bigoplus}C_{1,8} = C_{2,3}$, $X_{2,5}=X_5{\bigoplus}C_{3,8} =C_{2,14}$. 
	Similarly, mirror site $3$ sends $X_{3,1}=X_1{\bigoplus} C_{2,2} =C_{1,12} \oplus C_{3,1}$, $X_{3,2}=X_2 {\bigoplus}C_{1,13}= C_{2,4} \oplus C_{3,7}$, $X_{3,4}=X_4{\bigoplus}C_{1,14} = C_{3,3}$, $X_{3,5}=X_5{\bigoplus}C_{2,14} =C_{3,8}$. Therefore, $R'_2=\frac{4}{9}$. 

	By lines $24-28$ of Algorithm \ref{alg:hhpda}, the mirror sites $1$ sends the messages $X_{1,6}=C_{1,1}, X_{1,8}=C_{1,2}$ and $X_{1,9}=C_{1,3}$.  Similarly, mirror sites $2$ sends the messages $X_{2,13}=C_{2,1}, X_{2,15}=C_{2,8}$ and $X_{2,17}=C_{2,13}$. Similarly, mirror sites $3$ sends the messages $X_{3,18}=C_{3,2}, X_{3,20}=C_{3,13}$ and $X_{3,22}=C_{3,14}$. Therefore, $R''_2=\frac{3}{9}$. Therefore the load of the second layer is $R_2=R'_2+R''_2=\frac{7}{9}$.
	Each user can thus recover the demanded file. For example, consider user $(1,1)$. User  $(1,1)$ has in its cache the packets $C_{1,4}, C_{1,5}, C_{1,6}$ and $C_{1,7}$. From the transmissions $X_{1,1}, X_{1,2}, X_{1,3}$ and $X_{1,4}$,  user $(1,1)$ gets the packets  $C_{1,12}, C_{1,13}, C_{1,8}$ and $C_{1,14}$, respectively. From the transmissions $X_{1,6}, X_{1,8}$ and $X_{1,9}$,  user $(1,1)$ gets the packets  $C_{1,1}, C_{1,2}$ and $C_{1,3}$, respectively. Thus it has $9$ packets out of $14$ coded packets of the demanded file $W_{1}$. Since we have used a $[7,14]$ MDS code, the user can decode the demanded file $W_{1}$ correctly. 


\end{example}
