\section{A class of HHPDAs using $t$-Designs}\label{hhpda_tdes}
In this section, we first construct a class of HHPDAs using $t$-designs, and then the parameters of that class are given in Theorem \ref{thmt}. 

\noindent\textbf{Construction:}
Let $(X,\mathcal{A})$ be a $t$-$(v,k,\lambda)$ design with non-repeated blocks, where $X=\{1,2,\ldots, v\}$, $\mathcal{A}=\{A_1, A_2,$ $\ldots, A_b\}$ and $|A_i|=k$ for all $i \in \{1,2, \ldots, b\}$. Let $K_2$ be an integer such that $K_2<t$, and $v=K_1K_2$. Consider an array $\mathbf{Q}= \left( \mathbf{Q^{(0)}},\mathbf{Q^{(1)}}, \ldots, \mathbf{Q^{(K_1)}} \right)$ whose rows are indexed by the blocks in $\mathcal{A}$. Define a set $\mathcal{D}=\{D_1, D_2, \ldots, D_{K_1}\}$, where $D_{k_1}=\{(k_1-1)K_2+1, \ldots, k_1K_2\}$ for all $k_1 \in [K_1]$. The array $\mathbf{Q^{(0)}}=(q_{A,D}^{(0)})_{A \in \mathcal{A}, D \in \mathcal{D}}$, is a $b \times K_1$ array defined as
\begin{equation} \label{arrayQ0}
q_{A,D}^{(0)}=\begin{cases}
\star & \text{if} \ \ D \subseteq A, \\
null &  \text{otherwise}
\end{cases}.
\end{equation}
The array $(\mathbf{Q^{(1)}}, \ldots, \mathbf{Q^{(K_1)}})=(q_{A, i})_{A \in \mathcal{A}, i \in X}$ is an $b \times v$  array defined as 
\begin{equation} \label{arrayQk1}
q_{A,i}=\begin{cases}
\star & \text{if} \ \ i \in A \ \& \ q_{A,D_j}^{(0)} \ne \star, \ \text{for} \ i \in D_j \\
A\backslash\{i\} & \text{if} \ \ i \in A \ \& \ q_{A,D_j}^{(0)} = \star, \ \text{for} \ i \in D_j \\
null &  \text{otherwise}
\end{cases}.
\end{equation}


 The array $\mathbf{B}$ is defined in same manner as in the $t$-scheme given in \cite{CS_arx}. For $1 \leq s \leq t-1$, let $0 \leq a_s \leq \lambda_s^{t}$, and consider a set 
$\mathcal{\mathcal{R}}=\bigcup_{s=1}^{t-1} \left\{ (Y, i) \mid Y \in {[t] \choose s}, i \in [a_s] \right\}.$
Clearly, $|\mathcal{R}|=\sum_{s=1}^{t-1} a_s {t \choose s}$. The integers $a_s\in \{0,1, \ldots, \lambda_s^t\}, s \in [t-1]$ are chosen in such a way that $|\mathcal{R}| > \lambda_1$. 
Consider an array $B$ whose rows are indexed by the elements in $\mathcal{R}$ and columns are indexed by the points in $[t]$. The array $\mathbf{B}=(B((Y, i), j))$ is a $|\mathcal{R}| \times t$ array, defined as
\begin{equation} \label{arrayB}
B((Y, i), j)=\begin{cases}
* & \text{if} \ \ j \in Y, \\
\left(Y\cup\{j\},i\right) & \text{if} \ \ j \notin Y
\end{cases}.
\end{equation}
\begin{example}\label{hhpda_tdes_ex} 
 For a $3$-$(8, 4, 1)$ design, with $b=14$, and choosing $a_2 = 2$ and $a_1 = 1$, we get the arrays $(\mathbf{Q}, \mathbf{B})$ shown in Fig.\ref{fig:hhpda}. If we replace all the entries represented as different sets by different integers, we get the HHPDA $(\mathbf{Q}, \mathbf{B})$ given in Example \ref{hhpda_ex1}.
\end{example}

The following theorem gives the parameters of a class of HHPDAs constructed above using a $t$-design.
\begin{thm}\label{thmt}
    Given a $t$-$(v, k, \lambda)$ design with $b$ number of blocks, 
there exists a $(K_1,K_2,K';F, F';Z_1,Z_2,Z';\mathcal{S},\mathcal{S}_1, \ldots,\mathcal{S}_{K_1})$ HHPDA  $(\mathbf{Q}, \mathbf{B})$ with $K_2 \leq t$,  and  for some $s \in [t-1],$ $a_s \in \{0, 1, \ldots , \lambda_s^t \}$,
\begin{align*}
& K_1K_2=v, K'=t, F=b, F'=\sum_{s=1}^{t-1} a_s {t\choose s}, \\
& Z_1=\lambda_{K_2}, Z_2=\lambda_1-\lambda_{K_2}, Z'=\sum_{s=1}^{t-1} a_s {t-1\choose s-1}, \\
&|\mathcal{S}|=\sum_{s=1}^{t-1} a_s {t\choose s+1}, |\mathcal{S}_{k_1}|=\lambda_{k_2} K_2 \ \text{for all} \ k_1 \in [K_1].
\end{align*}
\end{thm}
The proof of Theorem \ref{thmt} is given in Appendix \ref{appendix_hhpda_tdes}.
The following corollary directly holds from Theorems \ref{thm:hhpda} and \ref{thmt}.
\begin{cor}
    Given a $t$-$(v, k, \lambda)$ design with $b$ number of blocks, there exists a scheme for a $(K_1, K_2, K'; M_1, M_2; N)$ hotplug hierarchical coded caching scheme with $K_1K_2=v$, $K'=t$ and $K_2 \leq t$, %each mirror is equipped with a cache of size $M_1$ files and each user is equipped with a cache of size $M_2$ files 
%and out of total $K_1K_2$ users, $K'=t$ number of users are active at the time of delivery. 
If $\mathcal{U}'=\cup_{k_1 \in [K_1]} \mathcal{U}'_{k_1}$ is the set of active users, where $\mathcal{U}'_{k_1}$ denotes the set of active users attached to mirror $k_1$, $k_1 \in [K_1]$, then the parameters of the scheme are given as follows: $\frac{M_1}{N}  = \frac{\lambda_{K_2}}{F'}$, $\frac{M_2}{N}  = \frac{\lambda-\lambda_{K_2}}{F'}$, $R_1  = \frac{|\mathcal{S}|}{F'}$, $R_2 =  \frac{1}{F'}  \underset{k_1 \in [K_1]} \max \left\{ | \cup_{j \in \mathcal{U}'_{k_1}} \mathcal{S}^{(j)} | +| \mathcal{U}'_{k_1}|\alpha \right\}$, where $\alpha \leq \lambda_{K_2}$, 
$F'$ and $|S|$ is same as defined in Theorem \ref{thmt}, and $\mathcal{S}^{(j)}$ is the set of integers appearing in the $j$-th column of $\mathbf{B}$.

%If $\tau \subseteq [K_1]\times [K_2], |\tau| = K'$ is the set of active users, then the parameters of the scheme are given as follows:
