%		$\bullet$ $\frac{M_1}{N}  = \frac{\lambda_{K_2}}{F'}$, & $\bullet$ $\frac{M_2}{N}  = \frac{\lambda-\lambda_{K_2}}{F'}$, & $\bullet$ $R_1  = \frac{|\mathcal{S}|}{F'}$,
%	\end{tabular} \\
%	$\bullet$ $R_2 =  \frac{1}{F'}  \underset{k_1 \in [K_1]} \max \left\{ \left| \cup_{j \in \mathcal{U}'_{k_1}} \mathcal{S}^{(j)} \right| +|\mathcal{U}'_{k_1}|\alpha \right\}$, where $\alpha \leq \lambda_{K_2}$, 
%$F'$ and $|S|$ is same as defined in Theorem \ref{thmt}, and $\mathcal{S}^{(j)}$ is the set of integers appearing in the $j$-th column of $B$.
\end{cor}
