\section{The Convexification Functional}

\label{sec:4}

First, we define the set of pairs $\left( u,m\right) $ of functions, on
which we want to find numerically an approximate solution of problem (\ref%
{2.1})-(\ref{2.4}). We need functions 
\begin{equation}
u,m\in C^{3}\left( \overline{Q}_{T}\right) \cap H_{0}^{2}\left( Q_{T}\right)
.  \label{5.1}
\end{equation}%
Denote 
\begin{equation}
k_{n}=\left[ \frac{n+1}{2}\right] +4,  \label{5.2}
\end{equation}%
where $\left[ \left( n+1\right) /2\right] $ denotes the largest integer
which does not exceed $\left( n+1\right) /2.$ By Sobolev embedding theorem 
\begin{equation}
\left. 
\begin{array}{c}
H^{k_{n}}\left( Q_{T}\right) \subset C^{3}\left( \overline{Q}_{T}\right) ,
\\ 
\left\Vert v\right\Vert _{C^{3}\left( \overline{Q}_{T}\right) }\leq
C\left\Vert v\right\Vert _{H^{k_{n}}\left( Q_{T}\right) },\text{ }\forall
v\in H^{k_{n}}\left( Q_{T}\right) ,%
\end{array}%
\right.  \label{5.3}
\end{equation}%
where the number $C=C\left( Q_{T}\right) $ depends only on the domain $%
Q_{T}\subset \mathbb{R}^{n+1}.$ Introduce the following spaces:%
\begin{equation}
\left. 
\begin{array}{c}
H_{2}^{k_{n}}\left( Q_{T}\right) =\left\{ 
\begin{array}{c}
\left( u,m\right) \in H^{k_{n}}\left( Q_{T}\right) \times H^{k_{n}}\left(
Q_{T}\right) : \\ 
\left\Vert \left( u,m\right) \right\Vert _{H_{2}^{k_{n}}\left( Q_{T}\right)
}^{2}=\left\Vert u\right\Vert _{H^{k_{n}}\left( Q_{T}\right)
}^{2}+\left\Vert m\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }^{2}<\infty%
\end{array}%
\right\} , \\ 
H_{2,0}^{k_{n}}\left( Q_{T}\right) =\left\{ 
\begin{array}{c}
\left( u,m\right) \in H_{2}^{k_{n}}\left( Q_{T}\right) : \\ 
\partial _{\nu }u\mid _{S_{T}}=\partial _{\nu }m\mid _{S_{T}}=0,%
\end{array}%
\right\} , \\ 
H_{2,0,0}^{k_{n}}\left( Q_{T}\right) =\left\{ \left( u,m\right) \in
H_{2,0}^{k_{n}}\left( Q_{T}\right) :u\left( x,0\right) =m\left( x,0\right)
=0\right\} , \\ 
H_{2,0}^{k_{n}}\left( \Omega \right) =\left\{ 
\begin{array}{c}
\left( f\left( x\right) ,g\left( x\right) \right) :\left\Vert \left(
f,g\right) \right\Vert _{H_{2}^{k_{n}}\left( \Omega \right) }^{2}= \\ 
