g\right\Vert _{H^{k_{n}}\left( \Omega \right) }^{2}<\infty , \\ 
\partial _{\nu }f\mid _{\partial \Omega }=\partial _{\nu }g\mid _{\partial
\Omega }=0.%
\end{array}%
\right\} , \\ 
\text{below }\left[ ,\right] \text{ denotes the scalar product in }%
H_{2}^{k_{n}}\left( Q_{T}\right) .%
\end{array}%
\right.  \label{5.30}
\end{equation}%
Recall that the number $\gamma $ and the domain $Q_{\gamma T}$ are defined
in (\ref{2.00}) and (\ref{2.0}) respectively. In addition, we define the
space $H^{1,0}\left( Q_{\gamma T}\right) $ as:%
\begin{equation*}
H^{1,0}\left( Q_{\gamma T}\right) =\left\{ u:\left\Vert u\right\Vert
_{H^{1,0}\left( Q_{\gamma T}\right) }^{2}=\left\Vert \nabla u\right\Vert
_{L_{2}\left( Q_{\gamma T}\right) }^{2}+\left\Vert u\right\Vert
_{L_{2}\left( Q_{\gamma T}\right) }^{2}<\infty ,\text{ }\gamma \in \left(
