We define the set $B\left( R\right) \subset H_{2,0}^{k_{n}}\left(
Q_{T}\right) ,$ in which we search our solution of Problem (\ref{2.1})-(\ref%
{2.4}), as:%
\begin{equation}
B\left( R\right) =\left\{ 
\begin{array}{c}
\left( u,m\right) \in H_{2,0}^{k_{n}}\left( Q_{T}\right) :\left\Vert \left(
u,m\right) \right\Vert _{H_{2}^{k_{n}}\left( Q_{T}\right) }<R, \\ 
u\left( x,0\right) =u_{0}\left( x\right) ,\text{ }m\left( x,0\right)
=m_{0}\left( x\right)%
\end{array}%
\right\} .  \label{5.4}
\end{equation}%
By (\ref{5.30}) and (\ref{5.4})%
\begin{equation}
B\left( R\right) \subset H_{2,0}^{k_{n}}\left( Q_{T}\right) .  \label{6.2}
\end{equation}%
Also, by (\ref{5.1})-(\ref{5.4})%
\begin{equation}
\left. 
\begin{array}{c}
u,m\in C^{3}\left( \overline{Q}_{T}\right) \cap H_{0}^{2}\left( Q_{T}\right)
, \\ 
\left\Vert u\right\Vert _{C^{3}\left( \overline{Q}_{T}\right) }\leq CR,\text{
}\left\Vert m\right\Vert _{C^{3}\left( \overline{Q}_{T}\right) }\leq CR, \\ 
\forall \left( u,m\right) \in B\left( R\right) .%
\end{array}%
\right.  \label{5.5}
\end{equation}

Let $L_{1}\left( u,m\right) $ and $L_{2}\left( u,m\right) $ be two operators
in the left hand sides of of equations (\ref{2.1}), (\ref{2.2}). Denote%
\begin{equation}
q_{\lambda }\left( c,T\right) =q=\frac{1}{\lambda \left( T+c\right)
^{\lambda -1}}.  \label{5.51}
\end{equation}%
Introduce the convexification functional%
\begin{equation}
\left. 
\begin{array}{c}
J_{\lambda ,\alpha }\left( u,m\right) :\overline{B\left( R\right) }%
\rightarrow \mathbb{R}, \\ 
J_{\lambda ,\alpha }\left( u,m\right) =e^{-2ac^{\lambda
}}\dint\limits_{Q_{T}}\left[ \left( L_{1}\left( u,m\right) \right)
^{2}+qd\left( L_{2}\left( u,m\right) \right) ^{2}\right] \varphi _{\lambda
}^{2}dxdt+ \\ 
+\alpha \left( \left\Vert u\right\Vert _{H^{k_{n}}\left( Q_{T}\right)
}^{2}+\left\Vert m\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }^{2}\right) ,%
\end{array}%
\right.  \label{5.6}
\end{equation}%
where $\alpha \in \left( 0,1\right) $ is the regularization parameter and $%
a>1$ and $d>0$ are two numbers of one's choice. Both of these numbers are
independent on $\lambda$, and both should be chosen computationally. Here
the multiplier $e^{-2ac^{\lambda }}$ is taken to partially balance the
integral term with the regularization term. Indeed, by (\ref{4.1}) 
\begin{equation}
\max_{t\in \left[ 0,T\right] }\varphi _{\lambda }^{2}\left( t\right) =\exp
\left( 2\left( T+c\right) ^{\lambda }\right) .  \label{5.7}
\end{equation}%
Our goal below is to solve the following problem:

\textbf{Minimization Problem. }{Minimize the functional }$J_{\lambda
,\alpha }\left( u,m\right) ${\ on the set }$\overline{B\left( R\right) }%
.$

\section{Strong Convexity}

\label{sec:5}

In this section we prove the key analytical result of our paper: the strong
convexity property of the functional $J_{\lambda ,\alpha }\left( u,m\right) $
on the set $\overline{B\left( R\right) }.$ Recall that the number $M>0$ was
introduced in (\ref{2.5}) and that in (\ref{5.6}) we must have $a>1.$

\begin{theorem}[the central result]\label{Theorem 5.1} {Assume that conditions (\ref%
{2.00}), (\ref{2.5}), (\ref{4.01}), (\ref{4.1}), (\ref{5.2}), (\ref{5.51})
and (\ref{5.6}) hold. Then:}

{1. At each point }$\left( u,m\right) \in \overline{B\left( R\right) }$%
{\ there exists Fr\'{e}chet derivative }$J_{\lambda ,\alpha }^{\prime
}\left( u,m\right) \in H_{2,0,0}^{k_{n}}\left( Q_{T}\right) ${\ of the
functional }$J_{\lambda ,\alpha }\left( u,m\right) .${\ Furthermore,
this derivative is Lipschitz continuous on }$\overline{B\left( R\right) }$%
{, i.e. there exists a number }$D=D\left( R,\lambda ,c,a,d,M,\alpha
,Q_{T}\right) ${\ depending only on listed parameters such that} 
\begin{equation}
\left. 
\begin{array}{c}
\left\Vert J_{\lambda ,\alpha }^{\prime }\left( u_{1},m_{1}\right)
-J_{\lambda ,\alpha }^{\prime }\left( u_{2},m_{2}\right) \right\Vert
_{H_{2}^{k_{n}}\left( Q_{T}\right) }\leq D\left\Vert \left(
u_{1},m_{1}\right) -\left( u_{2},m_{2}\right) \right\Vert
_{H_{2}^{k_{n}}\left( Q_{T}\right) }, \\ 
\forall \left( u_{1},m_{1}\right) ,\left( u_{2},m_{2}\right) \in \overline{%
B\left( R\right) }.%
\end{array}%
\right.  \label{6.3}
\end{equation}

{2. There exists a sufficiently large number }$\lambda _{1}=\lambda
_{1}\left( M,R,c,a,d,Q_{T}\right) \geq 1${\ depending only on listed
parameters such that if }$\lambda \geq \lambda _{1}${\ and if the
regularization parameter}%
\begin{equation}
\alpha \in \left[ 2e^{-\left( a-1\right) c^{\lambda }},1\right) ,
\label{6.4}
\end{equation}%
{then the functional }$J_{\lambda ,\alpha }\left( u,m\right) ${\
is strongly convex on the set }$\overline{B\left( R\right) }.${\ More
precisely, the} {following strong convexity estimate is valid:}%
\begin{equation}
\left. 
\begin{array}{c}
J_{\lambda ,\alpha }\left( u_{2},m_{2}\right) -J_{\lambda ,\alpha }\left(
u_{1},m_{1}\right) -\left[ J_{\lambda ,\alpha }^{\prime }\left(
u_{1},m_{1}\right) ,\left( u_{2}-u_{1},m_{2}-m_{1}\right) \right] \geq \\ 
\geq C_{3}e^{-2ac^{\lambda }}\left( c/\left( T+c\right) \right) ^{\lambda
}\exp \left[ 2\left( T\left( 1-\gamma \right) +c\right) ^{\lambda }\right]
\times \\ 
\times \left( \left\Vert u_{2}-u_{1}\right\Vert _{H^{1,0}\left( Q_{\gamma
T}\right) }^{2}+\left\Vert m_{2}-m_{1}\right\Vert _{H^{1,0}\left( Q_{\gamma
T}\right) }^{2}\right) + \\ 
+\left( \alpha /2\right) \left\Vert \left( u_{2}-u_{1},m_{2}-m_{1}\right)
\right\Vert _{H_{2}^{k_{n}}\left( Q_{T}\right) }^{2}, \\ 
\forall \left( u_{1},m_{1}\right) ,\left( u_{2},m_{2}\right) \in \overline{%
B\left( R\right) },\text{ }\forall \lambda \geq \lambda _{1},%
\end{array}%
\right.  \label{6.5}
\end{equation}%
{where the number }$C_{3}=C_{3}\left( M,R,c,d,Q_{T}\right) >0${\
depends only on listed parameters.}

3. Let $\lambda \geq \lambda_{1}$ and let (\ref{6.4}) holds. Then there exists unique minimizer \\ $\left( u_{\min ,\lambda},m_{\min,\lambda}\right) \in \overline{B\left( R\right)}$ of the functional $J_{\lambda ,\alpha }\left( u,m\right) ${\ on the set }$\overline{B\left( R\right)}$  and the following estimate holds
\begin{equation}
\left[ J_{\lambda ,\alpha }^{\prime }\left( u_{\min ,\lambda },m_{\min
,\lambda }\right) ,\left( u_{\min ,\lambda }-u,m_{\min ,\lambda }-m\right) %
\right] \leq 0,\text{ }\forall \left( u,m\right) \in \overline{B\left(
R\right) }.  \label{6.6}
\end{equation}
\end{theorem}

\begin{proof} Below in this paper $C_{3}=C_{3}\left(
M,R,c,a,d,Q_{T}\right) >0$ denotes different numbers depending only on
listed parameters. Let $\left( u_{1},m_{1}\right) ,\left( u_{2},m_{2}\right)
\in \overline{B\left( R\right) }$ be two arbitrary points. Denote $\left(
h_{1},h_{2}\right) =\left( u_{2}-u_{1},m_{2}-m_{1}\right) .$ Then 
\begin{equation}
\left( u_{2},m_{2}\right) =\left( u_{1}+h_{1},m_{1}+h_{2}\right) .
\label{6.7}
\end{equation}%
In addition, by (\ref{5.4}), (\ref{6.2}) and triangle inequality 
\begin{equation}
\left( h_{1},h_{2}\right) \in \overline{B_{0}\left( 2R\right) }=\left\{
\left( u,m\right) \in H_{2,0,0}^{k_{n}}\left( Q_{T}\right) :\left\Vert
\left( u,m\right) \right\Vert _{H_{2}^{k_{n}}\left( Q_{T}\right) }\leq
2R\right\} .  \label{6.8}
\end{equation}%
It is convenient to represent the functional {\ }$J_{\lambda ,\alpha
}\left( u,m\right) $ as the sum of three functionals and evaluate each of
them separately, i.e. 
\begin{equation}
\left. 
\begin{array}{c}
J_{1,\lambda ,\alpha }\left( u,m\right) =e^{-2ac^{\lambda
}}\dint\limits_{Q_{T}}\left( L_{1}\left( u,m\right) \right) ^{2}\varphi
_{\lambda }^{2}dxdt, \\ 
J_{2,\lambda ,\alpha }\left( u,m\right) =e^{-2ac^{\lambda
}}qd\dint\limits_{Q_{T}}\left( L_{2}\left( u,m\right) \right) ^{2}\varphi
_{\lambda }^{2}dxdt, \\ 
J_{3,\lambda ,\alpha }\left( u,m\right) =\alpha \left( \left\Vert
u\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }^{2}+\left\Vert m\right\Vert
_{H^{k_{n}}\left( Q_{T}\right) }^{2}\right) , \\ 
J_{\lambda ,\alpha }\left( u,m\right) =J_{1,\lambda ,\alpha }\left(
u,m\right) +J_{2,\lambda ,\alpha }\left( u,m\right) +J_{3,\lambda ,\alpha
}\left( u,m\right) .%
\end{array}%
\right.  \label{6.9}
\end{equation}

\textbf{Step 1. }Evaluate the functional $J_{1,\lambda ,\alpha }\left(
u,m\right) $ in (\ref{6.9}).

By (\ref{2.1}) and (\ref{6.7}) 
\begin{equation*}
\left. 
\begin{array}{c}
L_{1}\left( u_{2},m_{2}\right) =L_{1}\left( u_{1}+h_{1},m_{1}+h_{2}\right) =
\\ 
=\left( u_{1t}+\Delta u_{1}-r\left( \nabla u_{1}\right)
^{2}/2+\dint\limits_{\Omega }K\left( x,y\right) m_{1}\left( y,t\right)
dy\right) + \\ 
+\left( h_{1t}+\Delta h_{1}-r\nabla u_{1}\nabla h_{1}+\dint\limits_{\Omega
}K\left( x,y\right) h_{2}\left( y,t\right) dy\right) -r\left( \nabla
h_{1}\right) ^{2}/2.%
\end{array}%
\right.
\end{equation*}%
Hence,%
\begin{equation}
\left. 
\begin{array}{c}
e^{-2ac^{\lambda }}\left( L_{1}\left( u_{1}+h_{1},m_{1}+h_{2}\right) \right)
^{2}-e^{-3c^{\lambda }}\left( L_{1}\left( u_{1},m_{1}\right) \right) ^{2}=
\\ 
=2e^{-2ac^{\lambda }}L_{1}\left( u_{1},m_{1}\right) \left( h_{1t}+\Delta
h_{1}-r\nabla u_{1}\nabla h_{1}+\dint\limits_{\Omega }K\left( x,y\right)
h_{2}\left( y,t\right) dy\right) - \\ 
-e^{-2ac^{\lambda }}L_{1}\left( u_{1},m_{1}\right) \cdot r\left( \nabla
h_{1}\right) ^{2}+ \\ 
+e^{-2ac^{\lambda }}\left[ \left( h_{1t}+\Delta h_{1}-r\nabla u_{1}\nabla
h_{1}+\dint\limits_{\Omega }K\left( x,y\right) h_{2}\left( y,t\right)
dy\right) -r\left( \nabla h_{1}\right) ^{2}/2\right] ^{2}= \\ 
=A_{1,\text{lin}}\left( h_{1},h_{2}\right) +A_{1,\text{nonlin}}\left(
h_{1},h_{2}\right) ,%
\end{array}%
\right.  \label{6.10}
\end{equation}%
where $A_{1,\text{lin}}\left( h_{1},h_{2}\right) $ and $A_{1,\text{nonlin}%
}\left( h_{1},h_{2}\right) $ are linear and nonlinear operators respectively
with respect to $\left( h_{1},h_{2}\right) ,$%
\begin{equation}
\left. 
\begin{array}{c}
A_{1,\text{lin}}\left( h_{1},h_{2}\right) = \\ 
=2e^{-2ac^{\lambda }}L_{1}\left( u_{1},m_{1}\right) \left( h_{1t}+\Delta
h_{1}-r\nabla u_{1}\nabla h_{1}+\dint\limits_{\Omega }K\left( x,y\right)
h_{2}\left( y,t\right) dy\right) ,%
\end{array}%
\right.  \label{6.11}
\end{equation}%
\begin{equation}
\left. 
\begin{array}{c}
A_{1,\text{nonlin}}\left( h_{1},h_{2}\right) =-e^{-2ac^{\lambda
}}L_{1}\left( u_{1},m_{1}\right) \cdot r\left( \nabla h_{1}\right) ^{2}+ \\ 
+e^{-2ac^{\lambda }}\left[ \left( h_{1t}+\Delta h_{1}-r\nabla u_{1}\nabla
h_{1}+\dint\limits_{\Omega }K\left( x,y\right) h_{2}\left( y,t\right)
dy\right) -r\left( \nabla h_{1}\right) ^{2}/2\right] ^{2}.%
\end{array}%
\right.  \label{6.12}
\end{equation}%
Using the first line of (\ref{6.9}) as well as (\ref{6.10})-(\ref{6.12}), we
obtain 
\begin{equation}
\left. 
\begin{array}{c}
J_{1,\lambda ,\alpha }\left( u_{2},m_{2}\right) -J_{1,\lambda ,\alpha
}\left( u_{1},m_{1}\right) =J_{1,\lambda ,\alpha }\left(
u_{1}+h_{1},m_{1}+h_{2}\right) -J_{1,\lambda ,\alpha }\left(
u_{1},m_{1}\right) = \\ 
=\dint\limits_{Q_{T}}A_{1,\text{lin}}\left( h_{1},h_{2}\right) \varphi
_{\lambda }^{2}dxdt+\dint\limits_{Q_{T}}A_{1,\text{nonlin}}\left(
h_{1},h_{2}\right) \varphi _{\lambda }^{2}dxdt.%
\end{array}%
\right.  \label{6.13}
\end{equation}

\textbf{Step 2. }Evaluate the functional $J_{2,\lambda ,\alpha }\left(
u,m\right) $ in (\ref{6.9}).

By (\ref{2.2}), (\ref{6.7}) and (\ref{6.9})%
\begin{equation*}
\left. 
\begin{array}{c}
L_{2}\left( u_{2},m_{2}\right) =L_{2}\left( u_{1}+h_{1},m_{1}+h_{2}\right)
=L_{2}\left( u_{1},m_{1}\right) + \\ 
+\left[ h_{2t}-\Delta h_{2}-\func{div}\left( rm_{1}\nabla h_{1}\right) -%
\func{div}\left( rm_{1}h_{2}\right) -\func{div}\left( r\nabla
u_{1}h_{2}\right) \right] - \\ 
-\func{div}\left( rh_{2}\nabla h_{1}\right) .%
\end{array}%
\right.
\end{equation*}%
Hence,%
\begin{equation}
\left. 
\begin{array}{c}
e^{-2ac^{\lambda }}qd\left( L_{2}\left( u_{1}+h_{1},m_{1}+h_{2}\right)
\right) ^{2}-e^{-3c^{\lambda }}qd\left( L_{2}\left( u_{1},m_{1}\right)
\right) ^{2}= \\ 
=2e^{-2ac^{\lambda }}qdL_{2}\left( u_{1},m_{1}\right) \times \\ 
\times \left[ h_{2t}-\Delta h_{2}-\func{div}\left( rm_{1}\nabla h_{1}\right)
-\func{div}\left( rm_{1}h_{2}\right) -\func{div}\left( r\nabla
u_{1}h_{2}\right) \right] - \\ 
-2e^{-2ac^{\lambda }}qdL_{2}\left( u_{1},m_{1}\right) \func{div}\left(
rh_{2}\nabla h_{1}\right) + \\ 
+e^{-2ac^{\lambda }}qd\left[ 
\begin{array}{c}
h_{2t}-\Delta h_{2}-\func{div}\left( rm_{1}\nabla h_{1}\right) -\func{div}%
\left( rm_{1}h_{2}\right) - \\ 
-\func{div}\left( r\nabla u_{1}h_{2}\right) -\func{div}\left( rh_{2}\nabla
h_{1}\right)%
\end{array}%
\right] ^{2}= \\ 
=A_{2,\text{lin}}\left( h_{1},h_{2}\right) +A_{2,\text{nonlin}}\left(
h_{1},h_{2}\right) ,%
\end{array}%
\right.  \label{6.14}
\end{equation}%
where similarly with the above $A_{2,\text{lin}}\left( h_{1},h_{2}\right) $
and $A_{2,\text{nonlin}}\left( h_{1},h_{2}\right) $ are linear and nonlinear
operators respectively with respect to $\left( h_{1},h_{2}\right) ,$%
\begin{equation}
\left. 
\begin{array}{c}
A_{2,\text{lin}}\left( h_{1},h_{2}\right) =2e^{-2ac^{\lambda }}qdL_{2}\left(
u_{1},m_{1}\right) \times \\ 
\times \left[ h_{2t}-\Delta h_{2}-\func{div}\left( rm_{1}\nabla h_{1}\right)
-\func{div}\left( rm_{1}h_{2}\right) -\func{div}\left( r\nabla
u_{1}h_{2}\right) \right] ,%
\end{array}%
\right.  \label{6.15}
\end{equation}%
\begin{equation}
\left. 
\begin{array}{c}
A_{2,\text{nonlin}}\left( h_{1},h_{2}\right) =-2e^{-2ac^{\lambda
}}qdL_{2}\left( u_{1},m_{1}\right) \func{div}\left( rh_{2}\nabla
h_{1}\right) + \\ 
+e^{-2ac^{\lambda }}qd\left[ 
\begin{array}{c}
h_{2t}-\Delta h_{2}-\func{div}\left( rm_{1}\nabla h_{1}\right) -\func{div}%
\left( rm_{1}h_{2}\right) - \\ 
-\func{div}\left( r\nabla u_{1}h_{2}\right) -\func{div}\left( rh_{2}\nabla
h_{1}\right)%
\end{array}%
\right] ^{2}.%
\end{array}%
\right.  \label{6.16}
\end{equation}%
Hence,%
\begin{equation}
\left. 
\begin{array}{c}
J_{2,\lambda ,\alpha }\left( u_{2},m_{2}\right) -J_{2,\lambda ,\alpha
}\left( u_{1},m_{1}\right) = \\ 
=J_{2,\lambda ,\alpha }\left( u_{1}+h_{1},m_{1}+h_{2}\right) -J_{2,\lambda
,\alpha }\left( u_{1},m_{1}\right) = \\ 
=e^{-2ac^{\lambda }}qd\dint\limits_{Q_{T}}A_{2,\text{lin}}\left(
h_{1},h_{2}\right) \varphi _{\lambda }^{2}dxdt+e^{-2ac^{\lambda
}}qd\dint\limits_{Q_{T}}A_{2,\text{nonlin}}\left( h_{1},h_{2}\right) \varphi
_{\lambda }^{2}dxdt.%
\end{array}%
\right.  \label{6.17}
\end{equation}

\textbf{Step 3. }Evaluate the functional $J_{3,\lambda ,\alpha }\left(
u,m\right) $ in (\ref{6.9}).

We have: 
\begin{equation}
\left. 
\begin{array}{c}
J_{3,\lambda ,\alpha }\left( u_{2},m_{2}\right) -J_{3,\lambda ,\alpha
}\left( u_{1},m_{1}\right) = \\ 
=2\alpha \left[ \left( u_{1},m_{1}\right) ,\left( h_{1},h_{2}\right) \right]
+\alpha \left[ \left\Vert h_{1}\right\Vert _{H^{k_{n}}\left( Q_{T}\right)
}^{2}+\left\Vert h_{2}\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }^{2}\right]
= \\ 
=A_{3,\text{lin}}\left( h_{1},h_{2}\right) +A_{3,\text{nonlin}}\left(
h_{1},h_{2}\right) , \\ 
A_{3,\text{lin}}\left( h_{1},h_{2}\right) =2\alpha \left[ \left(
u_{1},m_{1}\right) ,\left( h_{1},h_{2}\right) \right] , \\ 
A_{3,\text{nonlin}}\left( h_{1},h_{2}\right) =\alpha \left[ \left\Vert
h_{1}\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }^{2}+\left\Vert
h_{2}\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }^{2}\right] .%
\end{array}%
\right.  \label{6.18}
\end{equation}

Thus, it follows from (\ref{6.9})-(\ref{6.18}) that%
\begin{equation}
\left. 
\begin{array}{c}
J_{\lambda ,\alpha }\left( u_{1}+h_{1},m_{1}+h_{2}\right) -J_{\lambda
,\alpha }\left( u_{1},m_{1}\right) = \\ 
=\dsum\limits_{i=1}^{3}A_{i,\text{lin}}\left( h_{1},h_{2}\right)
+\dsum\limits_{i=1}^{3}A_{i,\text{nonlin}}\left( h_{1},h_{2}\right) .%
\end{array}%
\right.  \label{6.19}
\end{equation}%
Consider the functional $A_{\text{lin}}\left( h_{1},h_{2}\right) ,$%
\begin{equation}
A_{\text{lin}}\left( h_{1},h_{2}\right) =\dsum\limits_{i=1}^{3}A_{i,\text{lin%
}}\left( h_{1},h_{2}\right) .  \label{6.20}
\end{equation}%
Since by (\ref{6.8}) the pair $\left( h_{1},h_{2}\right) \in
H_{2,0,0}^{k_{n}}\left( Q_{T}\right) ,$ then by (\ref{6.11}), (\ref{6.15})
and (\ref{6.18}) $A_{\text{lin}}\left( h_{1},h_{2}\right) $ is a linear
bounded functional such that 
\begin{equation}
A_{\text{lin}}\left( h_{1},h_{2}\right) :H_{2,0,0}^{k_{n}}\left(
Q_{T}\right) \rightarrow \mathbb{R}.  \label{6.21}
\end{equation}%
Next, it follows from Riesz theorem, the last line of (\ref{5.30}) and (\ref%
{6.21}) that there exists unique point $\overline{A}_{\text{lin}}\in
H_{2,0,0}^{k_{n}}\left( Q_{T}\right) $ such that 
\begin{equation}
A_{\text{lin}}\left( h_{1},h_{2}\right) =\left[ \overline{A}_{\text{lin}%
},\left( h_{1},h_{2}\right) \right] ,\text{ }\forall \left(
h_{1},h_{2}\right) \in H_{2,0,0}^{k_{n}}\left( Q_{T}\right) .  \label{6.22}
\end{equation}%
Hence, using (\ref{5.5}), (\ref{6.12}), (\ref{6.16}), the third line of (\ref%
{6.18}), (\ref{6.19}) and (\ref{6.22}), we obtain%
\begin{equation*}
\lim_{\left\Vert \left( h_{1},h_{2}\right) \right\Vert _{H_{2}^{k_{n}}\left(
Q_{T}\right) }\rightarrow 0}\frac{J_{\lambda ,\alpha }\left(
u_{1}+h_{1},m_{1}+h_{2}\right) -J_{\lambda ,\alpha }\left(
u_{1},m_{1}\right) -\left[ \overline{A}_{\text{lin}},\left(
h_{1},h_{2}\right) \right] }{\left\Vert \left( h_{1},h_{2}\right)
\right\Vert _{H_{2}^{k_{n}}\left( Q_{T}\right) }}=0.
\end{equation*}%
Hence, $\overline{A}_{\text{lin}}$ is the Fr\'{e}chet derivative of the
functional $J_{\lambda ,\alpha }\left( u,m\right) $ at the point $\left(
u_{1},m_{1}\right) ,$ i.e.%
\begin{equation}
J_{\lambda ,\alpha }^{\prime }\left( u_{1},m_{1}\right) \left(
h_{1},h_{2}\right) =\left[ \overline{A}_{\text{lin}},\left(
h_{1},h_{2}\right) \right] ,\text{ }\forall \left( h_{1},h_{2}\right) \in
H_{2,0,0}^{k_{n}}\left( Q_{T}\right) .  \label{6.220}
\end{equation}%
We omit the proof of estimate (\ref{6.3}) since it is proven similarly with
the proof of Theorem 3.1 of \cite{Bak}.

\textbf{Step 4.} We now prove the strong convexity estimate (\ref{6.5}).

By (\ref{5.3}), (\ref{6.8}), (\ref{6.12}), (\ref{6.16}), (\ref{6.18}) and (%
\ref{6.19}) 
\begin{equation}
\left. 
\begin{array}{c}
\dsum\limits_{i=1}^{2}A_{i,\text{nonlin}}\left( h_{1},h_{2}\right) \geq \\ 
\geq C_{3}e^{-2ac^{\lambda }}\left( h_{1t}+\Delta h_{1}\right)
^{2}+C_{3}e^{-2ac^{\lambda }}q\left( h_{2t}-\Delta h_{2}-rm_{1}\Delta
h_{1}\right) ^{2}- \\ 
