\section{The Accuracy of the Minimizer}

\label{sec:6}

In applications, input data are always given with errors. Therefore, it is
important to figure out how the error in the initial conditions (\ref{2.4})
affects the minimizer $\left( u_{\min ,\lambda },m_{\min ,\lambda }\right) $
of the functional $J_{\lambda ,\alpha }\left( u,m\right) .$ Recall that the
existence and uniqueness of this minimizer on the set $\overline{B\left(
R\right) }$ were established in \cref{Theorem 5.1}. In this section we estimate the
accuracy of the minimizer of a functional, which is closely related to $%
J_{\lambda ,\alpha }\left( u,m\right) .$ The reason of the replacement of $%
J_{\lambda ,\alpha }\left( u,m\right) $ with that new functional is that it
follows from the second line of (\ref{5.4}) and (\ref{6.6}) that we can
compare only pairs of functions $\left( u,m\right) ,$ which have the same
initial conditions $\left( u\left( x,0\right) ,m\left( x,0\right) \right) .$

To get the desired estimate, we first follow one of the main concepts of the
theory of Ill-Posed Problems \cite{T} via assuming that there exists an
ideal solution $\left( u^{\ast },m^{\ast }\right) $ of Forecasting Problem
of section 2 with the errorless initial conditions $\left( u_{0}^{\ast
},m_{0}^{\ast }\right) \in H_{2,0}^{k_{n}}\left( \Omega \right) ,$ see (\ref%
{5.30}) and (\ref{5.31}). Hence,%
\begin{equation}
L_{1}\left( u^{\ast },m^{\ast }\right) =L_{2}\left( u^{\ast },m^{\ast
}\right) =0.  \label{7.0}
\end{equation}%
Let a sufficiently small number $\delta \in \left( 0,1\right) $
characterizes the level of the error in the initial conditions (\ref{2.4}),%
\begin{equation}
\left\Vert u_{0}-u_{0}^{\ast }\right\Vert _{H^{2}\left( \Omega \right)
}<\delta ,\text{ }\left\Vert m_{0}-m_{0}^{\ast }\right\Vert _{H^{2}\left(
\Omega \right) }<\delta .  \label{7.1}
\end{equation}%
Since we seek solution $\left( u,m\right) \in \overline{B\left( R\right) }$
of our problem (see (\ref{5.31}) and (\ref{5.4})), then we assume that 
\begin{equation}
\left( u^{\ast },m^{\ast }\right) \in B^{\ast }\left( R\right) =\left\{ 
\begin{array}{c}
\left( u,m\right) \in H_{2,0}^{k_{n}}\left( Q_{T}\right) :\left\Vert \left(
u,m\right) \right\Vert _{H_{2}^{k_{n}}\left( Q_{T}\right) }<R, \\ 
u\left( x,0\right) =u_{0}^{\ast }\left( x\right) ,\text{ }m\left( x,0\right)
=m_{0}^{\ast }\left( x\right)%
\end{array}%
\right\} .  \label{7.2}
\end{equation}

Introduce functions 
\begin{equation}
\left. 
\begin{array}{c}
\widehat{u}_{0}\left( x,t\right) =u_{0}\left( x\right) \left( 1-t/T\right) ,%
\widehat{m}_{0}\left( x,t\right) =m_{0}\left( x\right) \left( 1-t/T\right) ,
\\ 
\widehat{u}_{0}^{\ast }\left( x,t\right) =u_{0}^{\ast }\left( x\right)
\left( 1-t/T\right) ,\widehat{m}_{0}^{\ast }\left( x,t\right) =m_{0}^{\ast
}\left( x\right) \left( 1-t/T\right) .%
\end{array}%
\right.  \label{7.3}
\end{equation}%
By (\ref{7.3})%
\begin{equation}
\left. 
\begin{array}{c}
\widehat{u}_{0}\left( x,0\right) =u_{0}\left( x\right) ,\text{ }\widehat{m}%
_{0}\left( x,0\right) =m_{0}\left( x\right) , \\ 
\widehat{u}_{0}^{\ast }\left( x,0\right) =u_{0}^{\ast }\left( x\right) ,%
\text{ }\widehat{m}_{0}^{\ast }\left( x,0\right) =m_{0}^{\ast }\left(
x\right) , \\ 
\widehat{u}_{0}\left( x,T\right) =\widehat{m}_{0}\left( x,T\right) =\widehat{%
u}_{0}^{\ast }\left( x,T\right) =\widehat{m}_{0}^{\ast }\left( x,T\right) =0.%
\end{array}%
\right.  \label{7.4}
\end{equation}%
It follows from (\ref{5.4}) and (\ref{7.1})-(\ref{7.4}) that it is natural
to assume that 
\begin{equation}
\left. 
\begin{array}{c}
\left( \widehat{u}_{0},\widehat{m}_{0}\right) \left( x,t\right) \in B\left(
R\right) ,\text{ } \\ 
\left( \widehat{u}_{0}^{\ast },\widehat{m}_{0}^{\ast }\right) \left(
x,t\right) \in B^{\ast }\left( R\right) .%
\end{array}%
\right.  \label{7.5}
\end{equation}

For each vector function $\left( u,m\right) \in B\left( R\right) $ we define
another vector function $\left( \overline{u},\overline{m}\right)$, 
\begin{equation}
\left( \overline{u},\overline{m}\right) \left( x,t\right) =\left( u,m\right)
\left( x,t\right) -\left( \widehat{u}_{0},\widehat{m}_{0}\right) \left(
x,t\right) .  \label{7.6}
\end{equation}%
Using (\ref{5.31}), (\ref{5.4}), (\ref{7.5}), (\ref{7.6}) and triangle
inequality, we obtain 
\begin{equation}
\left( \overline{u},\overline{m}\right) \in B_{0}\left( 2R\right) ,\text{ }%
\forall \left( u,m\right) \in B\left( R\right) .  \label{7.7}
\end{equation}%
Also, by (\ref{7.4})%
\begin{equation}
\left( \overline{u},\overline{m}\right) \left( x,T\right) =0.  \label{7.8}
\end{equation}%
In addition, we denote%
\begin{equation}
\left( \overline{u}^{\ast },\overline{m}^{\ast }\right) \left( x,t\right)
=\left( u^{\ast }-\widehat{u}_{0}^{\ast },m^{\ast }-\widehat{m}_{0}^{\ast
}\right) \left( x,t\right) .  \label{7.9}
\end{equation}%
Then, using (\ref{7.2})-(\ref{7.9}) and triangle inequality, we obtain%
\begin{equation}
\left( \overline{u}^{\ast },\overline{m}^{\ast }\right) \in B_{0}\left(
2R\right) .  \label{7.10}
\end{equation}%
Next, by the first line of (\ref{7.5}) and triangle inequality%
\begin{equation}
\left( v+\widehat{u}_{0},s+\widehat{m}_{0}\right) \in B\left( 3R\right) ,%
\text{ }\forall \left( v,s\right) \in B_{0}\left( 2R\right) .  \label{7.11}
\end{equation}

Introduce a new functional $I_{\lambda ,\alpha }\left( v,s\right) ,$ 
\begin{equation}
\left. 
\begin{array}{c}
