^{\ast }+\widehat{m}_{0}\right) \right\Vert _{L_{2}\left( Q_{T}\right) }^{2}=
\\ 
=\left\Vert L_{i}\left( \left( u^{\ast },m^{\ast }\right) +\left( \widehat{u}%
_{0}-\widehat{u}_{0}^{\ast },\widehat{m}_{0}-\widehat{m}_{0}^{\ast }\right)
\right) \right\Vert _{L_{2}\left( Q_{T}\right) }^{2}\leq C_{3}\delta ^{2},%
\text{ }i=1,2.%
\end{array}%
\right.  \label{7.230}
\end{equation}%
Hence, using (\ref{5.7}) and (\ref{7.22}), we obtain%
\begin{equation*}
\left\Vert v_{\min ,\lambda }-\overline{u}^{\ast }\right\Vert
_{H^{1,0}\left( Q_{\gamma T}\right) }^{2}+\left\Vert s_{\min ,\lambda }-%
\overline{m}^{\ast }\right\Vert _{H^{1,0}\left( Q_{\gamma T}\right) }^{2}\leq
\end{equation*}%
\begin{equation}
\leq C_{3}\exp \left( 3\left( T+c\right) ^{\lambda }\right) \delta ^{2}+
\label{7.24}
\end{equation}%
\begin{equation*}
+C_{3}\left( \frac{T+c}{c}\right) ^{\lambda }e^{\left( a+1\right) c^{\lambda
}}\exp \left[ -2\left( T\left( 1-\gamma \right) +c\right) ^{\lambda }\right]
.
\end{equation*}

Until now we have not used conditions (\ref{7.14}) and (\ref{7.15}). Now we
start to use them. Hence, elementary calculations lead to: 
\begin{equation}
\exp \left( 3\left( T+c\right) ^{\lambda \left( \delta \right) }\right)
\delta ^{2}=\delta ,\text{ }\forall \delta \in \left( 0,\delta _{0}\right) ,
\label{7.25}
\end{equation}%
\begin{equation*}
C_{3}\left( \frac{T+c}{c}\right) ^{\lambda \left( \delta \right) }e^{\left(
a+1\right) c^{\lambda \left( \delta \right) }}\exp \left[ -2\left( T\left(
1-\gamma \right) +c\right) ^{\lambda \left( \delta \right) }\right] \leq
\end{equation*}%
\begin{equation}
\leq C_{3}\exp \left[ -\left( T\left( 1-\gamma \right) +c\right) ^{\lambda
\left( \delta \right) }\right] \leq C_{3}\delta ,\text{ }\forall \delta \in
\left( 0,\delta _{0}\right) .  \label{7.26}
\end{equation}

The first target estimate (\ref{7.17}) of this theorem follows immediately
from (\ref{7.24})-(\ref{7.26}).\ Next, using (\ref{7.17}), (\ref{7.18}) and
the same considerations as the ones in the derivations of (\ref{7.23}) and (%
\ref{7.230}), we obtain the second target estimate (\ref{7.19}).
\end{proof}

\section{Global Convergence of the Gradient Descent Method}

\label{sec:7}

We assume in this section that conditions of \cref{Theorem 6.1} are in place.
Suppose that%
\begin{equation}
\left( u^{\ast },m^{\ast }\right) \in B^{\ast }\left( \frac{R}{3}-\delta
\right) ,\mbox{ }\frac{R}{3}-\delta >0.  \label{8.1}
\end{equation}%
We also assume that for $\lambda =\lambda \left( \delta \right) \geq \lambda
_{2}$ the minimizer $\left( u_{\min ,\lambda },m_{\min ,\lambda }\right) $
of the functional $J_{\lambda ,\alpha }\left( u,m\right) $ on the set $%
\overline{B\left( R\right) },$ which was found in \cref{Theorem 5.1}, is such that 
\begin{equation}
\left( \widetilde{v}_{\min ,\lambda },\widetilde{s}_{\min ,\lambda }\right)
=\left( u_{\min ,\lambda },m_{\min ,\lambda }\right) \in B\left( \frac{R}{3}%
\right) .  \label{8.2}
\end{equation}%
Formulas (\ref{7.17})-(\ref{7.19}) and (\ref{8.1}) indicate that assumption (%
\ref{8.2}) is reasonable.

We construct now the gradient descent method of the minimization of the
functional $J_{\lambda ,\alpha }.$ Consider an arbitrary pair of functions%
\begin{equation}
\left( u^{0},m^{0}\right) \in B\left( \frac{R}{3}\right) .  \label{8.3}
\end{equation}%
The iterative sequence of the gradient descent method with the step size $%
\xi >0$ is: 
\begin{equation}
\left( u^{n},m^{n}\right) =\left( u^{n-1},m^{n-1}\right) -\xi J_{\lambda
,\alpha }^{\prime }\left( u^{n-1},m^{n-1}\right) ,\mbox{ }n=1,2,...
\label{8.4}
\end{equation}%
By \cref{Theorem 6.1} $J_{\lambda ,\alpha }^{\prime }\left( u,m\right) \in
H_{2,0,0}^{k_{n}}\left( Q_{T}\right) $, see (\ref{5.31}). Hence, all pairs $%
\left( u^{n},m^{n}\right) $ have the same initial values $\left(
u^{n},m^{n}\right) \left( x,0\right) =\left( u^{0},m^{0}\right) \left(
x,0\right) =\left( u_{0}\left( x\right) ,m_{0}\left( x\right) \right) .$

\begin{theorem} \label{Theorem 7.1}{Let conditions of \cref{Theorem 6.1} as well as
conditions (\ref{8.1})-(\ref{8.4}) hold. Then there exists a number }$\xi
_{0}\in \left( 0,1\right) ${\ such that for any }$\xi \in \left( 0,\xi
_{0}\right) ${\ there exists a number }$\rho =\rho \left( \xi \right)
\in \left( 0,1\right) ${\ such that for all }$n\geq 1$%
\begin{equation}
\left. 
\begin{array}{c}
\left( u^{n},m^{n}\right) \in B\left( R\right) , \\ 
\left\Vert u^{n}-u^{\ast }\right\Vert _{_{H^{1,0}\left( Q_{\gamma T}\right)
}}+\left\Vert m^{n}-m^{\ast }\right\Vert _{_{H^{1,0}\left( Q_{\gamma
T}\right) }}\leq \\ 
\leq C_{3}\sqrt{\delta }+C_{3}\rho ^{n}\left( \left\Vert u_{\min ,\lambda
}-u^{0}\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }+\left\Vert m_{\min
,\lambda }-m^{0}\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }\right) .%
\end{array}%
\right.  \label{8.6}
\end{equation}%
{\ }
\end{theorem}

\begin{proof} The first line of (\ref{8.6}), existence of numbers $\xi
_{0} $ and $\rho \left( \xi \right) $ as well as estimate 
\begin{equation}
\hspace{-1cm}\left. 
\begin{array}{c}
\left\Vert u_{\min ,\lambda }-u^{n}\right\Vert _{_{H^{k_{n}}\left( Q_{\gamma
T}\right) }}+\left\Vert m_{\min ,\lambda }-m^{n}\right\Vert
_{_{H^{k_{n}}\left( Q_{\gamma T}\right) }}\leq \\ 
\leq C_{3}\rho ^{n}\left( \left\Vert u_{\min ,\lambda }-u^{0}\right\Vert
_{H^{k_{n}}\left( Q_{T}\right) }+\left\Vert m_{\min ,\lambda
}-m^{0}\right\Vert _{H^{k_{n}}\left( Q_{T}\right) }\right) .%
\end{array}%
\right.  \label{8.7}
\end{equation}%
follow immediately from (\ref{8.1})-(\ref{8.4}) and \cite[Theorem 6]{SAR}.
Next, triangle inequality, (\ref{7.18}), (\ref{7.19}), (\ref{8.2}) and (\ref%
{8.7}) lead to the desired result.
\end{proof}

Since $R>0$\ is an arbitrary number and the pair $\left( u_{0},m_{0}\right) $%
\ in (\ref{8.3}) is an arbitrary point of the set $B\left( R/3\right) ,$\
then \cref{Theorem 7.1} implies the global convergence of the iterative procedure (%
\ref{8.4}), see \cref{def:1.1} in section 1.

\section{Numerical Studies}

\label{sec:8}

Numerical tests were performed to test the performance of the
convexification method for the forecasting problem. The tests are conducted
using $c=3$, $d=1$, $a=1.1$, and the regularization parameter $\alpha
=10^{-5}$. These values of parameters are chosen by a trial and error
process to ensure that the method works well. We choose $\lambda =2$
following the same procedure as in previous publications of the method, see 
\cite{MFG7,MFGIPI,MFGCAMWA}, for example. We test the method on the
following model: 
\begin{gather}
u_{t}+u_{xx}+\frac{1}{2}u_{x}^{2}+\int_{\Omega }K(x,y)m(y,t)dy+f(x,t)m=0,
\label{num:1} \\
m_{t}-m_{xx}+\partial _{x}(mu_{x})=0,  \label{num:2} \\
u_{x}=m_{x}=0,\quad \text{on $\{\pm 1\}\times \lbrack 0,T]$},  \label{num:3}
\end{gather}%
i.e. $r(x,t)=-1$ in equation (\ref{2.1}). Both the spatial dimension $[-1,1]$
and temporal dimension $[0,T]$ are evenly discretized with step size $0.1$.

The minimization of the functional $J_{\lambda ,\alpha }(u,m)$ is performed
using the \textbf{fmincon} function in MATLAB. This function requires a
starting point, which is simply chosen as 
\begin{equation*}
u_{\text{start}}(x,t)=u(x,0),\quad m_{\text{start}}(x,t)=m(x,0),\quad
\forall t\in \lbrack 0,T].
\end{equation*}%
The algorithm terminates when the \textit{first order optimality} is less
than $10^{-5}$. The first order optimality for \textbf{fmincon} at $(u,m)$
is defined as the ratio 
\begin{equation*}
\frac{\Vert \nabla _{\text{proj}}J_{\lambda ,\alpha }(u,m)\Vert}{\Vert
\nabla J_{\lambda ,\alpha }(u_{\text{start}},m_{\text{start}})\Vert},
\end{equation*}%
where $\nabla _{\text{proj}}J_{\lambda ,\alpha }(u,m)$ is the projected
gradient of the functional $J_{\lambda ,\alpha }(u,m)$ onto the space of the
constraints. The constraints include the Neumann boundary conditions (\ref%
{num:3}) and the data $u(x,0)$ and $m(x,0)$, see (\ref{5.4}). We refer to
the documentation of \textbf{fmincon} for more details on the algorithm.

In all tests, $3\%$ of noise is added to the initial data according to the
following noise model: 
\begin{equation*}
\text{data} = \text{true data} + \text{noise}, \quad \text{where } \text{%
noise} = 0.03 \cdot \|\text{true data}\|_2 \cdot \text{rand}.
\end{equation*}
In this noise model, data/true data are arrays representing the discretized
version of the corresponding $u(x,0)$ and $m(x,0)$, rand is a random array
whose entries are uniformly distributed in $[-1, 1]$, and $\| \cdot \|_2$ is
the vector 2-norm.

We test the convexification method in two cases.

\textbf{The ideal case:} The true solution can be found to compare with the predicted solution by the
convexification method. It is hard to construct a precise solution of
problem (\ref{num:1})-(\ref{num:3}). Nevertheless, we need to verify somehow
the accuracy of our numerical technique. Hence, we proceed similarly with 
\cite{MFG7,MFGIPI,MFGCAMWA}. To be specific, the true solution is found as
follows:

\begin{enumerate}
\item Choose a function $u(x,t)$ satisfying (\ref{num:3}) and an initial
condition $m_0(x)$ for $m(x,t)$.

\item Solve for $m(x,t)$ using (\ref{num:2}), (\ref{num:3}), and $m(x,0) =
m_0(x)$.

\item Assuming that $m(x,t)$ does not vanish at any point $(x,t)$, we set
the function $f(x,t)$ in equation (\ref{num:1}) as: 
\begin{equation*}
f(x,t)=-\frac{u_{t}+u_{xx}+\frac{1}{2}u_{x}^{2}+\int_{\Omega }K(x,y)m(y,t)dy%
}{m(x,t)}.
\end{equation*}
\end{enumerate}

Then, we will have a MFG system that admits the solution $(u(x,t), m(x,t))$.
We extract the initial values $u(x,0)$ and $m(x,0)$ from the found solution
as data.

\textbf{A more realistic case:} This is when we set in (\ref{num:1}) $f=0$, and thus, the true solution
cannot easily be found. An important point of our study of this case is that
we will evaluate the relative cost without the CWF and regularization terms
at the solution: to see how well the minimizer of the functional $J_{\lambda
,\alpha }$ satisfies the MFG system (\ref{num:1}), (\ref{num:2}). This
relative cost at the time $t$ is defined as: 
\begin{equation}
F(t)=\left[ \frac{\dint\limits_{-1}^{1}\left[
L_{1}(u(x,t),m(x,t))^{2}+L_{2}(u(x,t),m(x,t))^{2}\right] dx}{%
\dint\limits_{-1}^{1}\left[ u^{2}(x,0)+m^{2}(x,0)\right] dx}\right]^{\frac{1}{2}} .
\label{num:rel-cost}
\end{equation}%
We note that the CWF is not involved in integrals in (\ref{num:rel-cost}), \
neither is the regularization term. We also point out that $(u,m)$ in (\ref%
{num:rel-cost}) is the minimizer of our target functional $J_{\lambda
,\alpha }$.

\begin{remark}
We observe numerically that the convexification method can predict the
solution of the MFG system accurately up to time $T=1$. See Figures \ref%
{fig:1-u-extended} for an example of the predicted solution $u(x,t)$ over
time for $t\in \lbrack 0,2]$ in the ideal case. The relative cost is also
shown in Figure \ref{fig:1-cost-extended}. We can see that both the
predicted solution and the relative cost behave badly for $t>1$, even for
the ideal case. From the theoretical point of view, this is to be expected
since the solution $u(x,t)$ of the MFG system with the initial data at $%
\left\{ t=0\right\} $ eventually blows up as $t$ increases, as it is well
known even for the simplistic case of the heat equation with the reversed
time%
\begin{equation*}
u_{t}+u_{xx}=0.
\end{equation*}
On the other hand, the convexification method seeks a solution with a
bounded norm. This means that the minimizer of the functional (\ref{5.6}),
which we use in (\ref{num:rel-cost}), actually represents a compromise
between the stability for the function $m(x,t)$ and the instability for the
function $u(x,t)$. However, this compromise holds only for $t\in \lbrack
0,1],$ and it is broken after $t=1$. Therefore, from now on, we will only
consider the time interval $t\in \lbrack 0,1]$ for the numerical tests.
\end{remark}

