\section{Proof of the main results}\label{sec:proof}
In this section, we provide a proof of our main results presented in Sections \ref{sec:composite} and \ref{sec:finite-sum}, which are particularly Theorems  \ref{thm:composite_fixed}, \ref{thm:composite}, \ref{thm:finite-sum_fixed}, and  \ref{thm:finite-sum}. To proceed, we establish a lemma regarding a relationship between problems \eqref{prob1} and \eqref{def-Frho1}, which will be used in our subsequent analysis.

\begin{lemma}\label{l-penalty}
Consider the penalty problem associated with \eqref{prob1}:
\beq \label{penalty-prob}
F_\rho^* = \min_x\Big\{F_\rho(x) := F(x)+\frac{\rho}{2}\|[c(x)]_+\|^2\Big\},
\eeq
where $F$ is defined in  \eqref{prob1}, and $\rho>0$. Suppose that Assumption \ref{a1}(iii) holds, and let $\Lambda$ be given in Assumption \ref{a1}(iii).  Then for any $x\in\cX$ and $\rho>0$, one has
\begin{align}
 &-\Lambda\|[c(x)]_+\| \leq F(x)-F^*\leq F_{\rho}(x)-F_{\rho}^*, \label{opt-gap}\\
  & \|[c(x)]_+\| \leq \frac{2\Lambda}{\rho}+\sqrt{\frac{2(F_{\rho}(x)-F_{\rho}^*)}{\rho}}. \label{feasibility}
\end{align}

\end{lemma}
\begin{proof}
By \eqref{prob1} and \eqref{def-Frho1}, one has $F_{\rho}(x)\geq F(x)$ and $F_{\rho}^*\leq F^*$, which imply that  
\begin{equation}\label{l1-0}
    F(x)-F^*\leq F_{\rho}(x)-F_{\rho}^*.
\end{equation}
By the definition of $\Lambda$ in Assumption \ref{a1}(iii), there exists an optimal Lagrange multiplier $\lambda^*$ for problem  \eqref{prob1} satisfying $\Lambda=\|\lambda^*\|$. Hence, one has $\lambda^* \geq 0$ and
\begin{equation*}
    F^*=\min_z \{F(z)+\langle\lambda^*,c(z)\rangle\} \leq F(x)+\langle\lambda^*, c(x)\rangle.
\end{equation*}
Using these and $\Lambda=\|\lambda^*\|$, we obtain that
\[
F(x)-F^* \geq -\langle\lambda^*, c( x)\rangle \geq -\langle\lambda^*,[c( x)]_+\rangle 
\geq -\Lambda\|[c( x)]_+\|,
\]
which together with \eqref{l1-0} leads to \eqref{opt-gap}. Also, by this relation, $F_\rho(x)=F(x)+\rho\|[c(x)]_+\|^2/2$, and $F_{\rho}^*\leq F^*$, one has
\[
 -\Lambda\|[c(x)]_+\| \leq F(x)-F^* = F_{\rho}(x)-\frac{\rho}{2}\|[c(x)]_+\|^2-F^*\leq F_{\rho}(x) -\frac{\rho}{2}\|[c(x)]_+\|^2- F_{\rho}^*,
\]
and hence 
\[
    \frac{\rho}{2}\|[c(x)]_+\|^2-\Lambda\|[c(x)]_+\|+F_{\rho}^*-F_{\rho}(x) \leq 0.
\]
It then follows from this and $\sqrt{a^2+b^2}\leq |a|+|b|$ that
\[
\|[c(x)]_+\| \leq \frac{\Lambda}{\rho}+\frac{\sqrt{\Lambda^2+2\rho(F_{\rho}(x)-F_{\rho}^*)}}{\rho} 
\leq \frac{2\Lambda}{\rho}+\sqrt{\frac{2(F_{\rho}(x)-F_{\rho}^*)}{\rho}}.
\]
\end{proof}

\subsection{Proof for the main results in Section \ref{sec:composite}}\label{sec:proof-composite}

In this subsection, we first establish several technical lemmas and then use them to prove Theorems \ref{thm:composite_fixed} and  \ref{thm:composite}.

For notational convenience, let 
\beq \label{L-rho}
f_{\rho}(x) := \bbE[\tilde f(x,\xi)]+\frac{\rho}{2}\|[c(x)]_+\|^2, \qquad L_{\rho} := L_{\nabla f}+\rho L_{\nabla c^2}
\eeq
for all $\rho>0$. It follows from these, the $L_{\nabla f}$-smoothness of $\bbE[\tilde f(\cdot,\xi)]$, and the $L_{\nabla c^2}$-smoothness of $\|[c(\cdot)]_+\|^2/2$ that $f_{\rho}$ is $L_{\rho}$-smooth.  One can also observe that $F_{\rho}(\cdot)=f_{\rho}(\cdot)+\psi(\cdot)$, where $F_\rho$ is defined in \eqref{penalty-prob}. These facts will be used in our subsequent analysis.  

The following lemma establishes recursive properties of the quantity $(\beta_k-1)\gamma_k(F_{\rho_k}(x_k)-F_{\rho_k}(x))+\|x-z_k\|^2/2$ and its expectation $\bbE\big[(\beta_k-1)\gamma_k(F_{\rho_k}(x_k)-F_{\rho_k}(x))+\|x-z_k\|^2/2\big]$ for all $x\in\cX$ and $k\geq 1$.

\begin{lemma}\label{l-iter}
Suppose that Assumptions \ref{a1} and \ref{a2} hold. Let $\{x_k\}$, $\{y_k\}$ and $\{z_k\}$ be generated in Algorithm \ref{alg1} with $\beta_k$, $ \gamma_k$, and $\rho_k$ satisfying $\beta_k\geq1$ and $L_{\rho_k}\gamma_k-\beta_k<0$ for all $k\geq1$, where $L_{\rho_k}$ is  defined in \eqref{L-rho}. Then for all $x\in\cX$ and $k\geq 1$, we have
\begin{align}
 & \beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F_{\rho_k}(x)\big)+\frac{1}{2}\|x-z_{k+1}\|^2\leq(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}(x)\big)+\frac{1}{2}\|x-z_k\|^2+\Delta_k(x), \label{determ-ineq}\\
 &  \bbE\Big[\beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F_{\rho_k}(x)\big)+\frac{1}{2}\|x-z_{k+1}\|^2\Big]\leq \bbE\Big[(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}(x)\big)+\frac{1}{2}\|x-z_k\|^2\Big] \nn \\
    &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad \quad+\frac{\beta_k\gamma_k^2}{2(\beta_k-L_{\rho_k}\gamma_k)}\bbE[\|\delta_k\|^2], \label{stoch-ineq}
\end{align}
where $F_{\rho_k}$ and $f_{\rho_k}$  are  defined in \eqref{penalty-prob} and \eqref{L-rho}, respectively, and 
\begin{equation}\label{delta}
    \delta_k=g_k-\nabla f_{\rho_k}(y_k), \quad \Delta_k(x)=\gamma_k\langle \delta_k, x-z_{k+1}\rangle-\frac{\beta_k-L_{\rho_k}\gamma_k}{2\beta_k}\|z_{k+1}-z_k\|^2.
\end{equation}
\end{lemma}

\begin{proof}
Observe from the definitions of $x_{k+1}$ and $y_k$ in Algorithm \ref{alg1} that
\begin{equation}\label{l1-1}
    x_{k+1}-y_k=\beta_k^{-1}(z_{k+1}-z_k).
\end{equation}
By this, the definition of $x_{k+1}$, and the convexity and $L_{\rho_k}$-smoothness of $f_{\rho_k}$, one has
\begin{align}
    &f_{\rho_k}(x_{k+1})\leq f_{\rho_k}(y_k)+\langle\nabla f_{\rho_k}(y_k), x_{k+1}-y_k\rangle+\frac{L_{\rho_k}}{2}\|x_{k+1}-y_k\|^2 \nn\\
    &= f_{\rho_k}(y_k)+\beta_k^{-1}\langle\nabla f_{\rho_k}(y_k), z_{k+1}-y_k\rangle+(1-\beta_k^{-1})\langle\nabla f_{\rho_k}(y_k), x_k-y_k\rangle+\frac{L_{\rho_k}}{2}\|x_{k+1}-y_k\|^2 \nn\\
    &= \beta_k^{-1}\left(f_{\rho_k}(y_k)+\langle\nabla f_{\rho_k}(y_k), z_{k+1}-y_k\rangle\right)+(1-\beta_k^{-1})\left(f_{\rho_k}(y_k)+\langle\nabla f_{\rho_k}(y_k), x_k-y_k\rangle\right)+\frac{L_{\rho_k}}{2}\|x_{k+1}-y_k\|^2 \nn\\
    &\leq \beta_k^{-1} \left(f_{\rho_k}(y_k)+\langle\nabla f_{\rho_k}(y_k), z_{k+1}-y_k\rangle\right) + (1-\beta_k^{-1})f_{\rho_k}(x_k) +\frac{L_{\rho_k}}{2}\|x_{k+1}-y_k\|^2\nn\\
    &=\beta_k^{-1} \left(f_{\rho_k}(y_k)+\langle g_k, z_{k+1}-y_k\rangle\right) +\beta_k^{-1}\langle\delta_k, y_k-z_{k+1}\rangle+(1-\beta_k^{-1})f_{\rho_k}(x_k) +\frac{L_{\rho_k}\beta_k^{-2}}{2}\|z_{k+1}-z_k\|^2, \label{l1-2}
\end{align}
where the first inequality is due to the $L_{\rho_k}$-smoothness of $f_{\rho_k}$,  the first equality follows from the definition of $x_{k+1}$ in Algorithm \ref{alg1}, and the second inequality is due to $\beta_k\geq 1$ and the convexity of $f_{\rho_k}$, while the last equality follows from \eqref{delta} and \eqref{l1-1}.

In addition, by the definition of $z_{k+1}$ in Algorithm \ref{alg1}, one has
\begin{equation*}
    z_{k+1}=\argmin_x\left\{\frac{1}{2\gamma_k}\|x-(z_k-\gamma_k g_k)\|^2+\psi(x)\right\},
\end{equation*}
which, together with the strong convexity of its objective function, implies that for all $x\in \cX$,
\begin{equation*}
    \frac{1}{2\gamma_k}\|z_{k+1}-z_k+\gamma_k g_k\|^2+\psi(z_{k+1})\leq \frac{1}{2\gamma_k}\|x-z_k+\gamma_k g_k\|^2+\psi(x) -\frac{1}{2\gamma_k}\|x-z_{k+1}\|^2.
\end{equation*}
It then follows that
\begin{equation*}
\langle g_k, z_{k+1}-y_k\rangle \leq \langle g_k, x-y_k\rangle +\psi(x)- \frac{1}{2\gamma_k}\|z_{k+1}-z_k\|^2+\frac{1}{2\gamma_k}\|x-z_k\|^2 -\frac{1}{2\gamma_k}\|x-z_{k+1}\|^2-\psi(z_{k+1}).
\end{equation*}
Using this, \eqref{delta}, and the convexity of $f_{\rho_k}$, we have
\begin{align*}
    f_{\rho_k}(y_k)+\langle g_k, z_{k+1}-y_k\rangle&\leq f_{\rho_k}(y_k) +\langle \nabla f_{\rho_k}(y_k), x-y_k\rangle+\langle \delta_k, x-y_k\rangle+\psi(x)-\frac{1}{2\gamma_k}\|z_{k+1}-z_k\|^2 \\
    &\quad +\frac{1}{2\gamma_k}\|x-z_k\|^2-\frac{1}{2\gamma_k}\|x-z_{k+1}\|^2 -\psi(z_{k+1})\\
    \leq F_{\rho_k}(x) +\langle \delta_k, x-y_k\rangle -&\frac{1}{2\gamma_k}\|z_{k+1}-z_k\|^2+\frac{1}{2\gamma_k}\|x-z_k\|^2-\frac{1}{2\gamma_k}\|x-z_{k+1}\|^2 -\psi(z_{k+1}).
\end{align*}
This together with \eqref{l1-2} implies that
\begin{align*}
    f_{\rho_k}(x_{k+1})&\leq \beta_k^{-1} \Big(F_{\rho_k}(x) +\langle \delta_k, x-y_k\rangle -\frac{1}{2\gamma_k}\|z_{k+1}-z_k\|^2+\frac{1}{2\gamma_k}\|x-z_k\|^2-\frac{1}{2\gamma_k}\|x-z_{k+1}\|^2 -\psi(z_{k+1})\Big) \\
    &\quad +(1-\beta_k^{-1})f_{\rho_k}(x_k)+\beta_k^{-1}\langle\delta_k, y_k-z_{k+1}\rangle +\frac{L_{\rho_k}\beta_k^{-2}}{2}\|z_{k+1}-z_k\|^2 \\
    &= \beta_k^{-1}F_{\rho_k}(x)+(1-\beta_k^{-1})f_{\rho_k}(x_k) +\beta_k^{-1}\langle \delta_k, x-z_{k+1}\rangle +\frac{1}{2}\Big(L_{\rho_k}\beta_k^{-2}-\frac{\beta_k^{-1}}{\gamma_k}\Big)\|z_{k+1}-z_k\|^2\\
    &\quad +\frac{\beta_k^{-1}}{2\gamma_k}\|x-z_k\|^2-\frac{\beta_k^{-1}}{2\gamma_k}\|x-z_{k+1}\|^2 - \beta_k^{-1}\psi(z_{k+1}).
\end{align*}
Also, by $\beta_k \geq 1$, the definition of $x_{k+1}$, and the convexity of $\psi$, one has
\begin{equation*}
    \psi(x_{k+1})=\psi\big(\beta_k^{-1}z_{k+1}+(1-\beta_k^{-1}) x_k\big)\leq \beta_k^{-1}\psi(z_{k+1})+(1-\beta_k^{-1})\psi(x_k).
\end{equation*}
Summing up the above two inequalities gives 
\begin{align*}
   F_{\rho_k}(x_{k+1})&\leq \beta_k^{-1}F_{\rho_k}(x)+(1-\beta_k^{-1})F_{\rho_k}(x_k)+\beta_k^{-1}\langle \delta_k, x-z_{k+1}\rangle +\frac{1}{2}\Big(L_{\rho_k}\beta_k^{-2}-\frac{\beta_k^{-1}}{\gamma_k}\Big)\|z_{k+1}-z_k\|^2 \\
    &\quad + \frac{\beta_k^{-1}}{2\gamma_k}\|x-z_k\|^2-\frac{\beta_k^{-1}}{2\gamma_k}\|x-z_{k+1}\|^2.
\end{align*}
Multiplying this by $\beta_k\gamma_k$ and rearranging the terms lead to the conclusion \eqref{determ-ineq}. 

We next show that \eqref{stoch-ineq} holds. To this end, one can first observe that 
\begin{align}
   \Delta_k(x)  &\overset{\eqref{delta}}= \gamma_k\langle \delta_k, x-z_k\rangle +\gamma_k\langle \delta_k, z_{k+1}-z_k\rangle-\frac{\beta_k-L_{\rho_k}\gamma_k}{2\beta_k}\|z_{k+1}-z_k\|^2 \nn \\
    &\leq \gamma_k\langle \delta_k, x-z_k\rangle + \frac{\beta_k\gamma_k^2\|\delta_k\|^2}{2(\beta_k-L_{\rho_k}\gamma_k)}, \label{Delta-ineq}
\end{align}
where the inequality follows from $\beta_k-L_{\rho_k}\gamma_k>0$ and Young's inequality. 
Let $\Xi_k=\{\xi_1,\xi_2,\dots,\xi_{k-1}\}$ denote the collection of samples drawn up to iteration $k-1$ in Algorithm 
\ref{alg1}.  It then follows from \eqref{delta}, $g_k=\nabla \tilde f (y_k,\xi_k)+{\rho_k}  \nabla c(y_k)[c(y_k)]_+$, $y_k\in\cX$, and Assumption \ref{a2} that for all $x\in\cX$, 
\begin{equation*}
    \bbE[\langle\delta_k, x-z_k\rangle|\Xi_k]=\bbE[\langle\nabla \tilde f(y_k,\xi_k)-\nabla f(y_k), x-z_k\rangle|\Xi_k]=\big\langle \bbE[\nabla \tilde f(y_k,\xi_k)|\Xi_k]-\nabla f(y_k), x-z_k\big\rangle=0.
\end{equation*}
This and \eqref{Delta-ineq} immediately imply that
\[
\bbE[\Delta_k(x)|\Xi_k] \leq  \frac{\beta_k\gamma_k^2\bbE[\|\delta_k\|^2|\Xi_k]}{2(\beta_k-L_{\rho_k}\gamma_k)}.
\]
Using this and taking expectation on both sides of \eqref{determ-ineq} conditional on $\Xi_k$, we obtain
\begin{align*}
    \bbE\Big[\beta_k\gamma_k(F_{\rho_k}(x_{k+1})-F_{\rho_k}(x))+\frac{1}{2}\|x-z_{k+1}\|^2\Big|\Xi_k\Big]&\leq \bbE\Big[(\beta_k-1)\gamma_k(F_{\rho_k}(x_k)-F_{\rho_k}(x))+\frac{1}{2}\|x-z_k\|^2\Big|\Xi_k\Big]\\
        &\quad +\frac{\beta_k\gamma_k^2\bbE[\|\delta_k\|^2|\Xi_k]}{2(\beta_k-L_{\rho_k}\gamma_k)}.
\end{align*}
The conclusion \eqref{stoch-ineq} then follows from taking expectation on both sides of this inequality.
\end{proof}

We next derive upper bounds for $F_\rho(x_k)-F^*_\rho $ and $\bbE[ F_\rho(x_k)-F^*_\rho]$ under the setting where constant penalty parameter $\rho_k \equiv \rho$ is used in Algorithm \ref{alg1} for some $\rho>0$.

\begin{lemma}\label{l-sum-fixed}
Suppose that Assumptions \ref{a1} and \ref{a2} hold.  Let $\{x_k\}$ be generated in Algorithm \ref{alg1} with $\rho_k \equiv \rho$,  and $\beta_k\in [1,\infty)$ and $\gamma_k>0$ satisfying $\beta_1=1$, $0<(\beta_{k+1}-1)\gamma_{k+1}\leq \beta_k\gamma_k$, and $2L_\rho\gamma_k\leq\beta_k$ for some $\rho>0$ and all $k\geq 1$,  where $L_{\rho}$ is defined in \eqref{L-rho}.  Then for all $k\geq 2$, we have
\begin{align*}
 & F_\rho(x_k)-F^*_\rho \leq\frac{1}{(\beta_k-1)\gamma_k}\Big(\frac{1}{2}D_\cX^2+2GD_\cX\sum_{i=1}^{k-1}\gamma_i\Big),  \\
 &  \bbE[ F_\rho(x_k)-F^*_\rho] \leq \frac{1}{(\beta_k-1)\gamma_k}\Big(\frac{1}{2}D_\cX^2+\sigma^2\sum_{i=1}^{k-1}\gamma_i^2\Big),
\end{align*}
where $F_\rho$ and $F^*_\rho$ are defined in \eqref{penalty-prob}, and $D_\cX$, $\sigma$ and $G$ are given in Assumptions \ref{a1} and \ref{a2}, respectively.
\end{lemma}

\begin{proof}
Since $2L_\rho\gamma_k\leq\beta_k$ and $\beta_k\geq 1$ for all $k$, the assumption of Lemma \ref{l-iter} holds.  Let $x^*_\rho\in\argmin\limits_{x} F_\rho(x)$. It follows from this and \eqref{penalty-prob} that $F^*_\rho=F_\rho(x^*_\rho)$ and $F_\rho(x_k) \geq F^*_\rho$ for all $k$. By these, \eqref{determ-ineq} with $x=x^*_\rho$, \eqref{delta}, and the assumption that $\rho_k= \rho$ and $0<(\beta_{k+1}-1)\gamma_{k+1}\leq\beta_k\gamma_k$ for all $k$,  one has that 
\begin{align}
    &(\beta_{i+1}-1)\gamma_{i+1}(F_\rho(x_{i+1})-F^*_\rho)+\frac{1}{2}\|x^*_\rho-z_{i+1}\|^2 \leq \beta_i\gamma_i(F_\rho(x_{i+1})-F^*_\rho)+\frac{1}{2}\|x^*_\rho-z_{i+1}\|^2\nn\\
    &\leq (\beta_i-1)\gamma_i(F_\rho(x_i)-F^*_\rho)+\frac{1}{2}\|x^*_\rho-z_i\|^2+\gamma_i\langle \delta_i, x^*_\rho-z_{i+1}\rangle-\frac{\beta_i-L_\rho\gamma_i}{2\beta_i}\|z_{i+1}-z_i\|^2\nn\\
    &\leq (\beta_i-1)\gamma_i(F_\rho(x_i)-F^*_\rho)+\frac{1}{2}\|x^*_\rho-z_i\|^2 + \gamma_i\|\delta_i\|\|x^*_\rho-z_{i+1}\| \qquad \forall i \geq 1.\label{rec}
\end{align}
In addition, by \eqref{delta} and Assumption \ref{a2}, one can observe that 
\begin{equation}\label{deltabound1}
    \|\delta_i\|\overset{\eqref{delta}}{=}\|\nabla \tilde f(y_i, \xi_i)-\bbE[\nabla \tf(y_i,\xi)]\|\leq \|\nabla \tilde f(y_i, \xi_i)\|+\bbE[\|\nabla \tf(y_i,\xi)\|]\leq 2G.
\end{equation}
Using this, $\beta_1=1$, $\|x^*_\rho-z_1\|\leq D_\cX$, and summing up \eqref{rec} from $i=1$ to $k-1$, we obtain that
\begin{align*}
    (\beta_k-1)\gamma_k(F_\rho(x_k)-F^*_\rho)&\leq (\beta_1-1)\gamma_1(F_\rho(x_1)-F^*_\rho)+\frac{1}{2}\|x^*_\rho-z_1\|^2+\sum_{i=1}^{k-1}\gamma_i\|\delta_i\|\|x^*_\rho-z_i\| \\
    &\leq \frac{D_\cX^2}{2}+2GD_\cX\sum_{i=1}^{k-1}\gamma_i,
\end{align*}
which implies that the first conclusion of this lemma holds.

We next show that the second conclusion of this lemma holds.  Indeed, by $2L_\rho\gamma_k\leq\beta_k$ and $\beta_k\geq1$, one has $\beta_k/(\beta_k-L_\rho\gamma_k)\leq 2$. Using this,  \eqref{stoch-ineq}, $0<(\beta_{k+1}-1)\gamma_{k+1}\leq\beta_k\gamma_k$, and $F_\rho(x) \geq F^*_\rho$, we obtain that
\begin{align*}
&  \bbE\Big[(\beta_{i+1}-1)\gamma_{i+1}(F_\rho(x_{i+1})-F^*_\rho)+\frac{1}{2}\|x^*_\rho-z_{i+1}\|^2\Big] \leq  \bbE\Big[\beta_i\gamma_i (F_\rho(x_{i+1})-F^*_\rho) +\frac{1}{2}\|x^*_\rho-z_{i+1}\|^2\Big] \\
    &\leq  \bbE\Big[(\beta_i-1)\gamma_i(F_\rho(x_i)-F^*_\rho)
     +\frac{1}{2}\|x^*_\rho-z_{i}\|^2 \Big]+\gamma_i^2\bbE[\|\delta_i\|^2],
\end{align*}
where the second inequality follows from \eqref{stoch-ineq} and $\beta_i/(\beta_i-L_\rho\gamma_i)\leq 2$. 
Using $\beta_1=1$, $\bbE[\|\delta_i\|^2]\leq\sigma^2$, $\|x^*_\rho-z_1\|\leq D_\cX$, and summing up the above inequalities from $i=1$ to $k-1$, we have
\begin{equation*}
    (\beta_k-1)\gamma_k\bbE[F_\rho(x_k)-F^*_\rho]\leq \frac{1}{2}\|x^*_\rho-z_{1}\|^2+\sum_{i=1}^{k-1}\gamma_i^2\bbE[\|\delta_i\|^2] \leq \frac{1}{2}D_\cX^2+\sigma^2\sum_{i=1}^{k-1}\gamma_i^2,
\end{equation*}
which implies that the second conclusion of this lemma holds. 
\end{proof}

We are now ready to prove Theorem \ref{thm:composite_fixed}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:composite_fixed}}]
Notice from \eqref{def-para2} that $\rho_k = \rho$, $\beta_k=(k+1)/2$, and $\gamma_k=(k+1)/(4L_\rho)$, where $L_\rho=L_{\nabla f}+\rho L_{\nabla c^2}$ and $\rho=K^{3/2}$. Observe that $0<\big((k+2)/2-1\big)(k+2) \leq (k+1)^2/2$ for all $k\geq 1$, which implies $0<(\beta_{k+1}-1)\gamma_{k+1}\leq \beta_k\gamma_k$. In addition, $2L_\rho\gamma_k\leq\beta_k$ clearly holds. Hence, the assumption of Lemma \ref{l-sum-fixed} holds for such $\rho_k$, $\beta_k$, and $\gamma_k$.  It then follows from $K\geq 2$ and Lemma \ref{l-sum-fixed} with such $\rho_k$, $\beta_k$, and $\gamma_k$ that 
\begin{align}
    F_{\rho}(x_K)-F_{\rho}^*&\leq\frac{1}{(\beta_K-1)\gamma_K}\Big(\frac{1}{2}D_\cX^2+2GD_\cX\sum_{i=1}^{K-1}\gamma_i\Big) \nn \\
    &=\frac{4L_\rho}{((K+1)/2-1) (K+1)}\Big(\frac{1}{2}D_\cX^2+2GD_\cX\sum_{i=1}^{K-1}\frac{i+1}{4L_\rho}\Big)\nn\\
    &= \frac{4L_\rho D_\cX^2}{K^2-1}+\frac{2GD_\cX(K+2)}{K+1}\, \leq \, \frac{4L_\rho D_\cX^2}{K^2-1}+\frac{8GD_\cX}{3},\label{t2_1}
\end{align}
where  the last inequality is due to $K\geq 2$. By \eqref{feasibility} and \eqref{t2_1}, one has
\begin{align*}
   & \|[c(x_K)]_+\|
     \overset{\eqref{feasibility}}{\leq} \frac{2\Lambda}{\rho}+\sqrt{\frac{2(F_{\rho}(x_K)-F_{\rho}^*)}{\rho}} \overset{\eqref{t2_1}}{\leq} \frac{2\Lambda}{\rho}+\sqrt{\frac{2}{\rho}\left(\frac{4L_\rho D_\cX^2}{K^2-1}+\frac{8GD_\cX}{3}\right)} \\
&\leq \frac{2\Lambda}{\rho}+\sqrt{\frac{8L_\rho D_\cX^2}{\rho(K^2-1)}}+\sqrt{\frac{16GD_\cX}{3\rho}}
  =\frac{2\Lambda}{K^{3/2}}+\sqrt{\frac{8(L_{\nabla f}+L_{\nabla c^2}K^{3/2}) D_\cX^2}{K^{3/2}(K^2-1)}}+\sqrt{\frac{16GD_\cX}{3K^{3/2}}} \\
& \leq\frac{2\Lambda}{K^{3/2}}+\sqrt{\frac{8L_{\nabla f} D_\cX^2}{K^{3/2}(K^2-1)}}+\sqrt{\frac{8L_{\nabla c^2} D_\cX^2}{K^2-1}}+\sqrt{\frac{16GD_\cX}{3K^{3/2}}}, 
\end{align*}
which, along with $K^2-1 \geq 3K^2/4$ due to $K\geq 2$, implies that \eqref{thm2:ineq1} holds.

In addition, using $\rho=K^{3/2}$, $L_\rho=L_{\nabla f}+\rho L_{\nabla c^2}$, $K\geq 2$, and Lemma \ref{l-sum-fixed},  we have that
\begin{align}
   & \bbE[F_{\rho}(x_K)-F_{\rho}^*]\overset{{\rm Lemma}\, \ref{l-sum-fixed}}{\leq} \frac{1}{(\beta_K-1)\gamma_K}\Big(\frac{1}{2}D_\cX^2+\sigma^2\sum_{i=1}^{K-1}\gamma_i^2\Big) \nn \\
    &=\frac{4L_\rho}{((K+1)/2-1) (K+1)}\Big(\frac{1}{2}D_\cX^2+\sigma^2\sum_{i=1}^{K-1}\left(\frac{i+1}{4L_\rho}\right)^2\Big) \leq \frac{4L_\rho D_\cX^2}{K^2-1}+\frac{\sigma^2(K+1)^3}{6L_\rho (K^2-1)} \nn \\ 
& =\frac{4L_{\nabla f} D_\cX^2}{K^2-1}+\frac{4L_{\nabla c^2} D_\cX^2K^{3/2}}{K^2-1}+\frac{\sigma^2(K+1)^2}{2(L_{\nabla f}+L_{\nabla c^2}K^{3/2})(K-1)}\nn \\
& \leq \frac{16L_{\nabla f} D_\cX^2}{3K^2}+\frac{16L_{\nabla c^2} D_\cX^2}{3K^{1/2}}+\frac{9\sigma^2}{4L_{\nabla c^2}K^{1/2}} \leq \frac{6L_{\nabla f} D_\cX^2}{K^2}+\frac{6L_{\nabla c^2} D_\cX^2+3\sigma^2L_{\nabla c^2}^{-1}}{K^{1/2}}, \label{t2_2}
\end{align}
 where the second inequality follows from the fact that $\sum_{i=1}^{K-1}(i+1)^2\leq\int_{1}^K(\tau+1)^2d\tau\leq(K+1)^3/3$,  and the third inequality follows from the fact that $K^2-1 \geq 3K^2/4$, $K+1 \leq 3K/2$, and $K-1\geq K/2$ due to $K\geq 2$. The relation \eqref{thm2:ineq2} then follows from  \eqref{t2_2} and $\bbE[F(x_K)-F^*]\leq\bbE[F_{\rho}(x_K)-F_{\rho}^*]$ due to \eqref{opt-gap}.

Lastly, it follows from $\rho=K^{3/2}$, \eqref{feasibility}, and \eqref{t2_2} that
\begin{align*}
    \bbE[\|[c(x_K)]_+\|] & \overset{\eqref{feasibility}}
    {\leq} \frac{2\Lambda}{\rho}+\bbE\left[\sqrt{\frac{2F_{\rho}(x_K)-F_{\rho}^*}{\rho}}\,\right] \leq\frac{2\Lambda}{\rho}+\sqrt{\frac{2\bbE\left[F_{\rho}(x_K)-F_{\rho}^*\right]}{\rho}} \\
   &  \overset{\eqref{t2_2}}\leq \frac{2\Lambda}{K^{3/2}}+\sqrt{\frac{12L_{\nabla f} D_\cX^2}{K^{7/2}}}+\sqrt{12L_{\nabla c^2} D_\cX^2+6\sigma^2L_{\nabla c^2}^{-1}}\  \frac{1}{K},
\end{align*}
which together with \eqref{opt-gap} implies that \eqref{thm2:ineq3} holds.
\end{proof}

In the remainder of this subsection, we provide a proof of Theorem \ref{thm:composite}.  Before proceeding, we first derive  an upper bound on $F_{\rho_k}(x_k)-F^*_{\rho_k} $ and $\bbE\big[F_{\rho_k}(x_k)-F^*_{\rho_k}\big]$ for all $k\geq 2$.

\begin{lemma}\label{l-sum}
Suppose that Assumptions \ref{a1} and \ref{a2} hold. Let $\{x_k\}$ be generated in Algorithm \ref{alg1} with a non-decreasing positive $\{\rho_k\}$, $\beta_k\in [1,\infty)$ and $\gamma_k>0$ satisfying $\beta_1=1$, $0<(\beta_{k+1}-1)\gamma_{k+1}\leq \beta_k\gamma_k(1-2(\rho_{k+1}-\rho_k)/\rho_{k+1})$, and $2L_{\rho_k}\gamma_k\leq\beta_k$ for all $k\geq 1$,  where $L_{\rho_k}$ is defined in \eqref{L-rho}. Then for all $k\geq 2$, we have
\begin{align*}
 & F_{\rho_k}(x_k)-F^*_{\rho_k} \leq\frac{1}{(\beta_k-1)\gamma_k}\Big(\frac{1}{2}D_\cX^2+2GD_\cX\sum_{i=1}^{k-1}\gamma_i+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_i}{\rho_i}+4\Lambda^2\sum_{i=1}^{k-1}\frac{\beta_i\gamma_i(\rho_{i+1}-\rho_i)}{\rho_{i+1}^2}\Big),  \\
 &  \bbE\big[F_{\rho_k}(x_k)-F^*_{\rho_k}\big] \leq \frac{1}{(\beta_k-1)\gamma_k}\Big(\frac{1}{2}D_\cX^2+\sigma^2\sum_{i=1}^{k-1}\gamma_i^2+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_i}{\rho_i}+4\Lambda^2\sum_{i=1}^{k-1}\frac{\beta_i\gamma_i(\rho_{i+1}-\rho_i)}{\rho_{i+1}^2}\Big),
\end{align*}
where $F_{\rho_k}$ and $F^*_{\rho_k}$ are defined in \eqref{penalty-prob},  and $D_\cX$, $\Lambda$, $\sigma$ and $G$ are given in Assumptions \ref{a1} and \ref{a2}, respectively. 
\end{lemma}

\begin{proof}
Since $2L_{\rho_k}\gamma_k\leq\beta_k$ and $\beta_k\geq 1$ for all $k\geq 1$, the assumption of Lemma \ref{l-iter} holds.  Let $x^*$ and $x^*_k$ be an arbitrary optimal solution of problems \eqref{prob1} and \eqref{def-Frho1}, respectively. It then follows that $F^*_{\rho_k}=F_{\rho_k}(x_k^*)$, $F_{\rho_k}(x_k) \geq F^*_{\rho_k}$, $F_{\rho_{k+1}}^* \geq F^*_{\rho_k}$, and $F_{\rho_k}(x^*)=F^*$ for all $k\geq 1$, where $F^*$ is defined in \eqref{prob1}.  By these, \eqref{opt-gap}, \eqref{feasibility}, and \eqref{determ-ineq} with $x=x^*$, one has that for all $k\geq 1$, 
\begin{align}
&\frac{1}{2}\|x^*-z_k\|^2-\frac{1}{2}\|x^*-z_{k+1}\|^2+\Delta_k(x) \overset{\eqref{determ-ineq}}{\geq}\beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F^*\big) \nn\\
&=\beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)+\beta_k\gamma_k\big(F_{\rho_{k+1}}^*-F^*\big)- (\beta_k-1)\gamma_k\big(F_{\rho_k}^*-F^*\big)\nn\\
&\geq\beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)+\gamma_k\big(F_{\rho_k}^*-F^*\big)\nn\\
&=\beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)+\gamma_k\big(F(x_k^*)-F^*\big)+\frac{\gamma_k\rho_k}{2}||[c(x_k^*)]_+\|^2\nn\\
&\overset{\eqref{opt-gap}}{\geq}\beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)- \gamma_k\Lambda\|[c(x_k^*)]_+\|+\frac{\gamma_k\rho_k}{2}\|[c(x_k^*)]_+\|^2\nn\\
&\geq\beta_k\gamma_k\big(F_{\rho_k}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)- \frac{\gamma_k\Lambda^2}{2\rho_k}\nn\\
&=\beta_k\gamma_k\big(F_{\rho_{k+1}}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)- \frac{\gamma_k\Lambda^2}{2\rho_k}-\frac{1}{2}\beta_k\gamma_k(\rho_{k+1}-\rho_k)\|[c(x_{k+1})]_+\|^2\nn\\
&\overset{\eqref{feasibility}}{\geq}\beta_k\gamma_k\big(F_{\rho_{k+1}}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)- \frac{\gamma_k\Lambda^2}{2\rho_k}\nn\\
&\quad\,\,-\frac{1}{2}\beta_k\gamma_k(\rho_{k+1}-\rho_k)\left(\frac{2\Lambda}{\rho_{k+1}}+\sqrt{\frac{2(F_{\rho_{k+1}}(x_{k+1})-F_{\rho_{k+1}}^*)}{\rho_{k+1}}}\,\right)^2\nn\\
&\geq \beta_k\gamma_k\Big(1-\frac{2(\rho_{k+1}-\rho_k)}{\rho_{k+1}}\Big)\big(F_{\rho_{k+1}}(x_{k+1})-F_{\rho_{k+1}}^*\big)-(\beta_k-1)\gamma_k\big(F_{\rho_k}(x_k)-F_{\rho_k}^*\big)- \frac{\gamma_k\Lambda^2}{2\rho_k}\nn\\
&\quad-\frac{4\beta_k\gamma_k(\rho_{k+1}-\rho_k)\Lambda^2}{\rho_{k+1}^2}, \label{l3-0}
\end{align}
where the second inequality is due to $F_{\rho_{k+1}}^* \geq F^*_{\rho_k}$, the second equality follows from \eqref{def-Frho1} and the definition of $F$ in \eqref{prob1}, and the fourth inequality is due to Young's inequality, while the last inequality follows from the fact that $(a+b)^2 \leq 2(a^2+b^2)$ for all $a,b\in\rr$.

Recall that $0<(\beta_{k+1}-1)\gamma_{k+1}\leq\beta_k\gamma_k\big(1-2(\rho_{k+1}-\rho_k)/\rho_{k+1}\big)$ and $L_{\rho_k}\gamma_k-\beta_k<0$ for all $k\geq 1$. These, together with \eqref{delta}, \eqref{l3-0}, and $F_{\rho_{i}}(x_{i}) \geq F^*_{\rho_{i}}$ for all $i$, imply that for all $i\geq1$, 
\begin{align}
    &(\beta_{i+1}-1)\gamma_{i+1}(F_{\rho_{i+1}}(x_{i+1})-F^*_{\rho_{i+1}})+\frac{1}{2}\|x^*-z_{i+1}\|^2 \nn\\
    &\leq \beta_i\gamma_i\Big(1-\frac{2(\rho_{i+1}-\rho_i)}{\rho_{i+1}}\Big)(F_{\rho_{i+1}}(x_{i+1})-F^*_{\rho_{i+1}})+\frac{1}{2}\|x^*-z_{i+1}\|^2\nn\\
    &\overset{\eqref{delta}\eqref{l3-0}}{\leq} (\beta_i-1)\gamma_i(F_{\rho_i}(x_i)-F^*_{\rho_i})+\frac{1}{2}\|x^*-z_i\|^2+\gamma_i\langle \delta_i, x^*-z_{i+1}\rangle-\frac{\beta_i-L_{\rho_i}\gamma_i}{2\beta_i}\|z_{i+1}-z_i\|^2\nn\\
    &\qquad\quad+\frac{\gamma_i\Lambda^2}{2\rho_i}+\frac{4\beta_i\gamma_i(\rho_{i+1}-\rho_i)\Lambda^2}{\rho_{i+1}^2}\nn\\
    &\leq (\beta_i-1)\gamma_i(F_{\rho_i}(x_i)-F^*_{\rho_i})+\frac{1}{2}\|x^*-z_i\|^2 + \gamma_i\|\delta_i\|\|x^*-z_{i+1}\|+\frac{\gamma_i\Lambda^2}{2\rho_i}+\frac{4\beta_i\gamma_i(\rho_{i+1}-\rho_i)\Lambda^2}{\rho_{i+1}^2}.\label{l3-1}
\end{align}

Using \eqref{deltabound1}, $\beta_1=1$, $\|x^*-z_1\|\leq D_\cX$, and summing up \eqref{l3-1} from $i=1$ to $k-1$, we obtain that
\begin{align*}
    &(\beta_k-1)\gamma_k(F_{\rho_k}(x_k)-F^*_{\rho_k})\\
    &\leq (\beta_1-1)\gamma_1(F_{\rho_k}(x_1)-F^*_{\rho_k})+\frac{1}{2}\|x^*-z_1\|^2+\sum_{i=1}^{k-1}\gamma_i\|\delta_i\|\|x^*-z_i\|+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_i}{\rho_i}+4\Lambda^2\sum_{i=1}^{k-1}\frac{\beta_i\gamma_i(\rho_{i+1}-\rho_i)}{\rho_{i+1}^2} \\
    &\leq \frac{D_\cX^2}{2}+2GD_\cX\sum_{i=1}^{k-1}\gamma_i+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_i}{\rho_i}+4\Lambda^2\sum_{i=1}^{k-1}\frac{\beta_i\gamma_i(\rho_{i+1}-\rho_i)}{\rho_{i+1}^2},
\end{align*}
which, along with the assumption that $(\beta_k-1)\gamma_k>0$ for all $k>1$, implies that the first conclusion of this lemma holds.

We next prove that the second conclusion of this lemma holds. Using \eqref{stoch-ineq} and applying similar arguments as those used to derive \eqref{l3-0}, we can show that for all $k\geq 1$, 
\begin{align}
&\frac{1}{2}\bbE[\|x^*-z_k\|^2]-\frac{1}{2}\bbE[\|x^*-z_{k+1}\|^2]+\frac{\beta_k\gamma_k^2}{2(\beta_k-L_{\rho_k}\gamma_k)}\bbE[\|\delta_k\|^2]\nn \\ 
&\geq \beta_k\gamma_k\Big(1-\frac{2(\rho_{k+1}-\rho_k)}{\rho_{k+1}}\Big)\bbE[F_{\rho_{k+1}}(x_{k+1})-F_{\rho_{k+1}}^*]
-(\beta_k-1)\gamma_k\bbE[(F_{\rho_k}(x_k)-F_{\rho_k}^*]- \frac{\gamma_k\Lambda^2}{2\rho_k}\nn \\
&\quad-\frac{4\beta_k\gamma_k(\rho_{k+1}-\rho_k)\Lambda^2}{\rho_{k+1}^2}.\label{l3-2}
\end{align}
Also, by the assumption $2L_{\rho_k}\gamma_k\leq\beta_k$, one has $\beta_k/(\beta_k-L_{\rho_k}\gamma_k)\leq 2$. Using this, \eqref{l3-2}, and the assumption that $0<(\beta_{k+1}-1)\gamma_{k+1}\leq\beta_k\gamma_k(1-2(\rho_{k+1}-\rho_k)/\rho_{k+1})$ for all $k$,  we obtain that for all $i\geq 1$, 
\begin{align*}
&  (\beta_{i+1}-1)\gamma_{i+1}\bbE[F_{\rho_{i+1}}(x_{i+1})-F^*_{\rho_{i+1}}]+\frac{1}{2}\bbE[\|x^*-z_{i+1}\|^2] \\
&\leq \beta_i\gamma_i\Big(1-\frac{2(\rho_{i+1}-\rho_i)}{\rho_{i+1}}\Big) \bbE[F_{\rho_{i+1}}(x_{i+1})-F^*_{\rho_{i+1}}] +\frac{1}{2}\bbE[\|x^*-z_{i+1}\|^2] \\
    &\leq (\beta_i-1)\gamma_i\bbE[F_{\rho_i}(x_i)-F^*_{\rho_i}]
     +\frac{1}{2}\bbE[\|x^*-z_{i}\|^2]+\gamma_i^2\bbE[\|\delta_i\|^2]+\frac{\gamma_i\Lambda^2}{2\rho_i}+\frac{4\beta_i\gamma_i(\rho_{i+1}-\rho_i)\Lambda^2}{\rho_{i+1}^2}.
\end{align*}
Using $\beta_1=1$, $\bbE[\|\delta_i\|^2]\leq\sigma^2$, $\|x^*-z_1\|\leq D_\cX$, and summing up the above inequalities from $i=1$ to $k-1$, we have
\begin{equation*}
    (\beta_k-1)\gamma_k\bbE[F_{\rho_k}(x_k)-F^*_{\rho_k}]\leq\frac{1}{2}D_\cX^2+\sigma^2\sum_{i=1}^{k-1}\gamma_i^2+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_i}{\rho_i}+4\Lambda^2\sum_{i=1}^{k-1}\frac{\beta_i\gamma_i(\rho_{i+1}-\rho_i)}{\rho_{i+1}^2},
\end{equation*}
which, along with the assumption that $(\beta_k-1)\gamma_k>0$ for all $k>1$,  implies that the second conclusion of this lemma holds. 
\end{proof}

We are now ready to prove Theorem \ref{thm:composite}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:composite}}]
Notice that $\rho_k=(k+4)^{3/2}$, $\beta_k=(k+4)/5$, $\gamma_k=(k+4)/(10L_{\rho_k})$, and $L_{\rho_k}=L_{\nabla f}+(k+4)^{3/2}L_{\nabla c^2}$. Also, one can verify that  $3(k+4)^2 \leq (k+5)\big((k+4)^2-k(k+5)\big)$, and  
\beq \label{aux-ineq1}
(k+5)^{3/2}-(k+4)^{3/2} \leq \frac{3}{2} (k+5)^{1/2} \ \ (\text{due to the convexity of}\  \tau^{3/2}). 
\eeq
Using these and $L_{\rho_{k+1}} \geq L_{\rho_k}$, we have
\begin{align*}
\frac{2\beta_k\gamma_k(\rho_{k+1}-\rho_k)}{\rho_{k+1}}&=\frac{2(k+4)^2((k+5)^{3/2}-(k+4)^{3/2})}{50L_{\rho_k}(k+5)^{3/2}}
\leq\frac{3(k+4)^2}{50L_{\rho_k}(k+5)}
\leq\frac{(k+4)^2}{50L_{\rho_k}}-\frac{k(k+5)}{50L_{\rho_k}} \\
&\leq\frac{(k+4)^2}{50L_{\rho_k}}-\frac{k(k+5)}{50L_{\rho_{k+1}}}=\beta_k\gamma_k-(\beta_{k+1}-1)\gamma_{k+1}.
\end{align*}
Hence, the assumption of Lemma \ref{l-sum} holds for such $\rho_k$, $\beta_k$, and $\gamma_k$.  In addition, one can verify that
\beq\label{aux-ineq2}
\sum_{i=1}^{k-1}(i+4)^{-1/2}\leq2(k+4)^{1/2}, \quad \sum_{i=1}^{k-1}(i+4)^{-2} \leq 1, \quad \sum_{i=1}^{k-1}(i+4)^{-1} \leq \log(k+4).
\eeq 
By \eqref{aux-ineq1}, \eqref{aux-ineq2},  Lemma \ref{l-sum}, and the definitions of $\tC_1$, $\tC_2$ in  \eqref{c12}, one has that for all $k\geq2$, 
\begin{align}
    &F_{\rho_k}(x_k)-F_{\rho_k}^*\leq\frac{1}{(\beta_k-1)\gamma_k}\Big(\frac{1}{2}D_\cX^2+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_i}{\rho_i}+4\Lambda^2\sum_{i=1}^{k-1}\frac{\beta_i\gamma_i(\rho_{i+1}-\rho_i)}{\rho_{i+1}^2}+2GD_\cX\sum_{i=1}^{k-1}\gamma_i\Big) \nn\\
    &=\frac{50L_{\rho_k}}{(k-1) (k+4)}\Big(\frac{1}{2}D_\cX^2+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{i+4}{10(L_{\nabla f}+(i+4)^{3/2}L_{\nabla c^2})(i+4)^{3/2}} \nn \\
&\qquad\qquad\qquad\qquad+4\Lambda^2\sum_{i=1}^{k-1}\frac{(i+4)^2((i+5)^{3/2}-(i+4)^{3/2})}{50(L_{\nabla f}+(i+4)^{3/2}L_{\nabla c^2})(i+5)^{3}}+2GD_\cX\sum_{i=1}^{k-1}\frac{i+4}{10(L_{\nabla f}+(i+4)^{3/2}L_{\nabla c^2})}\Big)\nn\\
    &\overset{\eqref{aux-ineq1}}{\leq}\frac{50L_{\rho_k}}{(k-1) (k+4)}\Big(\frac{1}{2}D_\cX^2+\frac{\Lambda^2}{20L_{\nabla c^2}}\sum_{i=1}^{k-1}\frac{1}{(i+4)^{2}}+\frac{3\Lambda^2}{25L_{\nabla c^2}}\sum_{i=1}^{k-1}\frac{1}{(i+4)^{2}}+\frac{GD_\cX}{5L_{\nabla c^2}}\sum_{i=1}^{k-1}\frac{1}{(i+4)^{1/2}}\Big)\nn\\
   &\overset{\eqref{aux-ineq2}}{\leq}\frac{50L_{\rho_k}}{(k-1) (k+4)}\Big(\frac{1}{2}D_\cX^2+\frac{\Lambda^2}{20L_{\nabla c^2}}+\frac{3\Lambda^2}{25L_{\nabla c^2}}+\frac{2GD_\cX}{5L_{\nabla c^2}}(k+4)^{\frac{1}{2}}\Big)\nn\\
    & \overset{\eqref{c12}}{\leq}\frac{\tC_1L_{\rho_k}}{(k-1) (k+4)}+\frac{20GD_\cX\big(L_{\nabla f}+(k+4)^{3/2}L_{\nabla c^2}\big)(k+4)^{1/2}}{L_{\nabla c^2}(k-1)(k+4)}
   \  \leq \ \frac{\tC_1L_{\rho_k}}{(k-1) (k+4)}+\tC_2,\label{l4-1}
\end{align}
where the last inequality follows from $k\geq2$ and \eqref{c12}. Applying similar arguments as those used to derive \eqref{l4-1},  we can show that for all $k\geq2$, 
\begin{align}
    &\bbE[F_{{\rho_k}}(x_k)-F_{{\rho_k}}^*]\leq \frac{1}{(\beta_k-1)\gamma_k}\Big(\frac{1}{2}D_\cX^2+\sigma^2\sum_{i=1}^{k-1}\gamma_i^2+4\Lambda^2\sum_{i=1}^{k-1}\frac{\beta_i\gamma_i(\rho_{i+1}-\rho_i)}{\rho_{i+1}^2}+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_i}{\rho_i}\Big)\nn\\
    &\leq \frac{\tC_1L_{\rho_k}}{(k-1) (k+4)}+\frac{\sigma^2L_{\rho_k}}{2(k-1) (k+4)}\sum_{i=1}^{k-1}\frac{(i+4)^2}{(L_{\nabla f}+(i+4)^{3/2}L_{\nabla c^2})^2}\nn\\
    &\leq\frac{\tC_1L_{\rho_k}}{(k-1) (k+4)}+\frac{\sigma^2L_{\rho_k}}{2L_{\nabla c^2}^2(k-1) (k+4)}\sum_{i=1}^{k-1}\frac{1}{i+4}
    \overset{\eqref{aux-ineq2}}{\leq}\frac{\tC_1L_{\rho_k}}{(k-1) (k+4)}+\frac{\sigma^2L_{\rho_k}\log(k+4)}{2L_{\nabla c^2}^2(k-1) (k+4)}.\label{l4-2}
\end{align}
Using  \eqref{feasibility}, \eqref{l4-1}, and the expressions of $\rho_k$ and $L_{\rho_k}$ in \eqref{def-para1} and \eqref{L-rho}, we have
\begin{align*}
    &\|[c(x_k)]_+\|
     \overset{\eqref{feasibility}}{\leq} \frac{2\Lambda}{\rho_k}+\sqrt{\frac{2(F_{{\rho_k}}(x_k)-F_{{\rho_k}}^*)}{{\rho_k}}} 
    \overset{\eqref{l4-1}}{\leq} \frac{2\Lambda}{{\rho_k}}+\sqrt{\frac{2}{{\rho_k}}\left(\frac{\tC_1L_{\rho_k}}{(k-1) (k+4)}+\tC_2\right)} \nn \\
    &\overset{\eqref{def-para1}\eqref{L-rho}}{=}\frac{2\Lambda}{(k+4)^{3/2}}+\sqrt{\frac{2\tC_1(L_{\nabla f}+(k+4)^{3/2}L_{\nabla c^2})}{(k-1)(k+4)^{5/2}}+\frac{2\tC_2}{(k+4)^{3/2}}}, \\
    &\leq\frac{2\Lambda}{(k+4)^{3/2}}+\sqrt{\frac{2\tC_1L_{\nabla f}}{(k-1)(k+4)^{5/2}}}+\sqrt{\frac{2\tC_1L_{\nabla c^2}}{(k-1)(k+4)}}+\sqrt{\frac{2\tC_2}{(k+4)^{3/2}}},
\end{align*}
which,  along with $k-1 \geq k/2$ for all $k\geq 2$,  implies that \eqref{thm1-ineq1} holds. In addition, by \eqref{l4-2}, and the expressions of $\rho_k$ and $L_{\rho_k}$ in \eqref{def-para1} and \eqref{L-rho}, one has
\begin{align}
    &\bbE[F_{{\rho_k}}(x_k)-F_{{\rho_k}}^*]\overset{\eqref{l4-2}}{\leq} \frac{\tC_1L_{\rho_k}}{(k-1) (k+4)}+\frac{\sigma^2L_{\rho_k}\log(k+4)}{2L_{\nabla c^2}^2(k-1) (k+4)}\nn\\
    &\overset{\eqref{def-para1}\eqref{L-rho}}{=}\frac{\tC_1L_{\nabla f} }{(k-1) (k+4)}+\frac{\tC_1L_{\nabla c^2} (k+4)^{1/2}}{k-1}+\frac{\sigma^2L_{\nabla f}\log(k+4)}{2L_{\nabla c^2}^2(k-1) (k+4)}+\frac{\sigma^2L_{\nabla c^2}(k+4)^{1/2}\log(k+4)}{2L_{\nabla c^2}^2(k-1)}\label{l4-3} \\
& \leq 2\tC_1L_{\nabla f}k^{-2}+2\sqrt{3}\tC_1L_{\nabla c^2}k ^{-1/2}+3\sigma^2L_{\nabla f}L_{\nabla c^2}^{-2}k^{-2}\log k+3\sqrt{3}\sigma^2L_{\nabla c^2}^{-1}k^{-1/2}\log k, \label{l4-4}
\end{align}
where the last inequality is due to the fact that $k-1 \geq k/2$, $k+4\leq 3k$, and $\log(k+4)\leq 3\log k$ for all $k\geq2$. The relation \eqref{thm1-ineq2} then  follows from \eqref{l4-4} and $\bbE[F(x_k)-F^*]\leq\bbE[F_{\rho_k}(x_k)-F_{\rho_k}^*]$ due to \eqref{opt-gap}.

Lastly, it follows from \eqref{def-para1}, \eqref{feasibility}, and \eqref{l4-3} that
\begin{align*}
    &\bbE[\|[c(x_k)]_+\|]  \overset{\eqref{feasibility}}
    {\leq} \frac{2\Lambda}{\rho_k}+\bbE\left[\sqrt{\frac{2F_{\rho_k}(x_k)-F_{\rho_k}^*}{\rho_k}}\,\right] 
    \leq\frac{2\Lambda}{\rho_k}+\sqrt{\frac{2\bbE\left[F_{\rho_k}(x_k)-F_{\rho_k}^*\right]}{\rho_k}} \\
   &  \overset{\eqref{def-para1}\eqref{l4-4}}\leq \frac{2\Lambda}{(k+4)^{3/2}}+\sqrt{\frac{2\tC_1L_{\nabla f} }{(k-1) (k+4)^{5/2}}}+\sqrt{\frac{2\tC_1L_{\nabla c^2} }{(k-1)(k+4)}}+\sqrt{\frac{\sigma^2L_{\nabla f}\log(k+4)}{L_{\nabla c^2}^2(k-1) (k+4)^{5/2}}} \\
&\qquad\,\,\,+\sqrt{\frac{\sigma^2L_{\nabla c^2}\log(k+4)}{L_{\nabla c^2}^2(k-1)(k+4)}}. \\
& \leq 2\Lambda k^{-3/2}+2(\tC_1L_{\nabla f})^{1/2}k^{-7/4}+2(\tC_1L_{\nabla c^2})^{1/2}k^{-1}+\sigma L_{\nabla c^2}^{-1} (6L_{\nabla f})^{1/2} k^{-7/4}(\log k)^{1/2} \nn \\
    &\quad\, +\sqrt{6}\sigma (L_{\nabla c^2})^{-1/2} k^{-1}(\log k)^{1/2},
\end{align*}
where the last inequality is due to the fact that $k-1 \geq k/2$ and $\log(k+4)\leq 3\log k$ for all $k\geq2$.
This together with \eqref{opt-gap} implies that  \eqref{thm1-ineq3} holds.
\end{proof}

\subsection{Proof for the main results in Section \ref{sec:finite-sum}}\label{sec:proof-finitesum}

In this subsection, we first establish several technical lemmas and then use them together with Lemma \ref{l-penalty} to prove Theorems  \ref{thm:finite-sum_fixed} and \ref{thm:finite-sum}.

Recall that $L_{\nabla c^2}$ and $L_{\nabla \barf}$ are defined in \eqref{L_nablac} and \eqref{Lam}, respectively. For notational convenience, we  define
\begin{equation}\label{notation}
\begin{aligned}
    &f_{\rho}(x) := \barf(x) + \frac{\rho}{2}\|[c(x)]_+\|^2 ,
    \qquad L_{\rho}:=L_{\nabla \barf}+\rho L_{\nabla c^2}, \\
    &\ell_{f_{\rho}}(u, v):=f_{\rho}(v)+\langle \nabla f_{\rho}(v), u-v\rangle
\end{aligned}
\end{equation}
for any $\rho>0$. Clearly, it follows from these and Assumption \ref{a3} that $\barf$ is $L_{\nabla \barf}$-smooth, and $f_{\rho}$ is $L_{\rho}$-smooth.  

The following lemma shows that $g_t$ is an unbiased stochastic estimator of $\nabla f_{\rho_k}(y_t)$ and also provides an upper bound on its variance. 

\begin{lemma}
Suppose that Assumptions \ref{a1} and \ref{a3} hold. Let $\{g_t\}$ and $\{y_t\}$ be generated in the $k$th outer iteration of Algorithm \ref{alg2} with $\{q_i\}$ given in \eqref{def-para3}.
Then for all $1\leq t\leq T_k$, we have
\begin{align}
    \bbE[\delta_t|\Xi_{k,t-1}]&=0, \label{mean}\\ 
    \bbE[\|\delta_t\|^2|\Xi_{k,t-1}]&\leq 2L_{\nabla \barf}(\barf(\tilde x_{k}) - \barf(y_t)-\langle\nabla \barf(y_t),\tilde x_{k} - y_t \rangle),\label{var}
\end{align}
where $\barf$ is given in \eqref{fun-f}, $L_{\nabla \barf}$ is defined in \eqref{Lam}, $\delta_t = g_t-\nabla f_{\rho_k}(y_t)$ with $f_{\rho}$ given in \eqref{notation}, and $\Xi_{k,t-1}$ denotes the collection of all samples that have been generated by Algorithm \ref{alg2} before the $t$-th inner iteration of the $k$th outer iteration.
\end{lemma}

\begin{proof}
In view of \eqref{notation} and the expressions of $g_t$ and $\delta_t$, one can observe that 
\[
\delta_t=g_t-\nabla f_{\rho_k}(y_t)=(\nabla f_{i_t}(y_t)-\nabla f_{i_t}(\tilde x_{k}))/(q_{i_t}s)+\nabla \barf(\tilde x_{k})- \nabla \barf(y_t).
\]
The rest proof of this lemma follows from this relation and similar arguments used in the proof of \cite[Lemma 3]{lan2019unified}.
\end{proof}

The next lemma presents a well-known result for an inexact proximal gradient step applied to the problem $\min_x\{ f_{\rho_k}(x)+\psi(x)\}$, whose proof is similar to that of \cite[Lemma 5]{lan2019unified}.

\begin{lemma}
Suppose that Assumptions \ref{a1} and \ref{a3} hold.  Let $\{g_t\}$, $\{y_t\}$, $\{z_t\}$ be generated in the $k$th outer iteration of Algorithm \ref{alg2}, and $\delta_t = g_t-\nabla f_{{\rho_k}}(y_t)$, where $f_{{\rho_k}}$ is defined in \eqref{notation}. 
Then for any $x\in\cX$ and $1\leq t\leq T_k$, we have
\begin{equation}\label{l6-1}
    \gamma_k\left(\ell_{f_{\rho_k}}(z_t, y_t)-\ell_{f_{\rho_k}}(x,y_t )+\psi(z_t)-\psi(x)\right)\leq \frac{1}{2}\|z_{t-1}-x\|^2-\frac{1}{2}\|z_{t}-x\|^2-\frac{1}{2}\|z_{t-1}-z_t\|^2-\gamma_k\langle \delta_t, z_t-x\rangle,
\end{equation}
where $\ell_{f_{\rho_k}}$ is defined in \eqref{notation}.
\end{lemma}

The following lemma establishes some recursions for 
$F_{{\rho_k}}(x_t)-F_{{\rho_k}}(x)$ and $\bbE[F_{{\rho_k}}(x_t)-F_{{\rho_k}}(x)]$ for all $x\in\cX$.

\begin{lemma}\label{l-iter2}
Suppose that Assumptions \ref{a1} and \ref{a3} hold. Let $\{x_t\}$, $\{y_t\}$, $\{z_t\}$,  $\{g_t\}$, and $\tilde x_{k}$ be generated in the $k$th outer iteration of Algorithm \ref{alg2} with $\{q_i\}$ given in \eqref{def-para3}, and $\alpha_k$, $\gamma_k$, $p_k$ and $\rho_k$ satisfying
\begin{align}
    &1-L_{\rho_k}\alpha_k\gamma_k>0, \label{l7-1}\\
    &p_k-\frac{L_{\nabla \barf}\alpha_k \gamma_k}{1-L_{\rho_k} \alpha_k\gamma_k}\geq 0 \label{l7-2}
\end{align}
for all $k\geq1$, and let $\delta_t = g_t-\nabla f_{\rho_k}(y_t)$, where $L_{\rho_k}$ and $f_{\rho_k}$ are given in \eqref{notation}. Then for all $k\geq 1$, $1\leq t\leq T_k$, and $x\in\cX$, we have
\begin{align}
    \frac{\gamma_k}{\alpha_k}(F_{{\rho_k}}(x_t)-F_{{\rho_k}}(x))+\frac{1}{2}\|z_t-x\|^2 &\leq \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{{\rho_k}}(x_{t-1})-F_{{\rho_k}}(x))+\frac{\gamma_kp_k}{\alpha_k} (F_{{\rho_k}}(\tilde x_{k})-F_{{\rho_k}}(x))\nn\\
    &\quad+\frac{1}{2}\|z_{t-1}-x\|^2 -\gamma_k\langle \delta_t, z_t-x\rangle, \label{l7-exact}\\
    \frac{\gamma_k}{\alpha_k}\bbE[F_{{\rho_k}}(x_t)-F_{{\rho_k}}(x)]+\frac{1}{2}\bbE[\|z_t-x\|^2] &\leq \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)\bbE[F_{{\rho_k}}(x_{t-1})-F_{{\rho_k}}(x)]+\frac{\gamma_kp_k}{\alpha_k} \bbE[F_{{\rho_k}}(\tilde x_{k})-F_{{\rho_k}}(x)]\nn\\
    &\quad+\frac{1}{2}\bbE[\|z_{t-1}-x\|^2] , \label{l7-exp}
\end{align}
where  $F_{\rho_k}$ is defined in \eqref{penalty-prob}.
\end{lemma}

\begin{proof}
Let $\{x_t\}$, $\{y_t\}$ and $\{z_t\}$ be generated in the $k$th outer iteration of Algorithm \ref{alg2}. Then it follows from the expressions of $x_t$ and $y_t$ in Algorithm \ref{alg2} that $ x_t-y_t=\alpha_k(z_t-z_{t-1})$.
By this, \eqref{l6-1}, the $L_{\rho_k}$-smoothness of $f_{{\rho_k}}$, and the definitions of $x_t$ and $\ell_{f_{\rho_k}}$, one has
\begin{align}
    &f_{\rho_k}(x_t)\leq \ell_{f_{\rho_k}}(x_t,y_t)+\frac{L_{\rho_k}}{2}\|x_t-y_t\|^2\nn\\
    &=(1-\alpha_k-p_k)\ell_{f_{{\rho_k}}}(x_{t-1},y_t)+\alpha_k \ell_{f_{{\rho_k}}}(z_t,y_t)+p_k\ell_{f_{{\rho_k}}}(\tilde x_{k},y_t)+\frac{L_{\rho_k}\alpha_k^2}{2}\|z_t-z_{t-1}\|^2\nn\\
    &\overset{\eqref{l6-1}}{\leq}(1-\alpha_k-p_k)\ell_{f_{{\rho_k}}}(x_{t-1},y_t) + \alpha_k\Big(\ell_{f_{{\rho_k}}}(x,y_t)+\psi(x)-\psi(z_t)+\frac{1}{2\gamma_k}\big(\|z_{t-1}-x\|^2-\|z_t-x\|^2\nn \\ 
&\qquad-\|z_{t-1}-z_t\|^2\big)-\langle \delta_t, z_t-x\rangle\Big)
+p_k\ell_{f_{{\rho_k}}}(\tilde x_{k},y_t)+\frac{L_{\rho_k}\alpha_k^2}{2}\|z_t-z_{t-1}\|^2\nn\\
    &= (1-\alpha_k-p_k)\ell_{f_{{\rho_k}}}(x_{t-1},y_t)
    +  \alpha_k\Big(\ell_{f_{{\rho_k}}}(x,y_t)+\psi(x)-\psi(z_t)+\frac{1}{2\gamma_k}\|z_{t-1}-x\|^2-\frac{1}{2\gamma_k}\|z_t-x\|^2\Big)\nn\\
    &\quad +p_k\ell_{f_{{\rho_k}}}(\tilde x_{k},y_t)-\frac{\alpha_k}{2\gamma_k}(1-L_{\rho_k}\alpha_k\gamma_k)\|z_{t-1}-z_t\|^2-\alpha_k\langle \delta_t, z_t-x\rangle \label{frho-bnd}  .
\end{align}
Using the convexity of $f_{{\rho_k}}$, we have $\ell_{f_{\rho_k}}(x,y_t)\leq f_{\rho_k}(x)$ for any $x\in\cX$. By this, \eqref{frho-bnd} and the definition of $F_{\rho_k}$ in \eqref{def-Frho2}, one has 
\begin{align*}
    f_{\rho_k}(x_t)&\leq (1-\alpha_k-p_k)f_{{\rho_k}}(x_{t-1})
    +\alpha_k\Big(F_{\rho_k}(x)-\psi(z_t)+\frac{1}{2\gamma_k}\|z_{t-1}-x\|^2-\frac{1}{2\gamma_k}\|z_t-x\|^2\Big)\nn\\
    &\quad + p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)-\frac{\alpha_k}{2\gamma_k}(1-L_{\rho_k}\alpha_k\gamma_k)\|z_{t-1}-z_t\|^2-\alpha_k\langle \delta_t, z_t-x\rangle. 
\end{align*}
Also, by the expression of $x_t$ and the convexity of $\psi$, one has
\[
    \psi(x_t)\leq (1-\alpha_k-p_k)\psi(x_{t-1})+\alpha_k\psi(z_t)+p_k\psi(\tilde x_{k}).
\]
Summing up these two inequalities, and using the definition of $F_{\rho_k}$ in \eqref{def-Frho2}, we have
\begin{align}
    F_{\rho_k}(x_t)& \leq(1-\alpha_k-p_k)F_{\rho_k}(x_{t-1})+\alpha_k\Big(F_{\rho_k}(x)+\frac{1}{2\gamma_k}\|z_{t-1}-x\|^2-\frac{1}{2\gamma_k}\|z_t-x\|^2\Big)+p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)\nn \\
    &\quad\,-\frac{\alpha_k}{2\gamma_k}(1-L_{\rho_k}\alpha_k\gamma_k)\|z_{t-1}-z_t\|^2-\alpha_k\langle \delta_t, z_t-x\rangle
+ p_k\psi(\tilde x_{k}). \label{l7-3}
\end{align}
Further, by \eqref{l7-1},  \eqref{l7-3},  $\ell_{f_{\rho_k}}(\tilde x_{k},y_t) \leq f_{\rho_k}(\tilde x_{k})$, and the definition of $F_{\rho_k}$ in \eqref{def-Frho2}, one has
\begin{align*}
    F_{\rho_k}(x_t)& \leq(1-\alpha_k-p_k)F_{\rho_k}(x_{t-1})+\alpha_k\Big(F_{\rho_k}(x)+\frac{1}{2\gamma_k}\|z_{t-1}-x\|^2-\frac{1}{2\gamma_k}\|z_t-x\|^2\Big)+p_kF_{\rho_k}(\tilde x_{k})\\
    &\quad\,-\alpha_k\langle\delta_t, z_t-x\rangle.
\end{align*}
The relation \eqref{l7-exact} then follows from this inequality by rearranging terms.

We next prove that \eqref{l7-exp} holds. Indeed, observe that
\begin{align}
&p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)-\frac{\alpha_k}{2\gamma_k}(1-L_{\rho_k}\alpha_k\gamma_k)\|z_{t-1}-z_t\|^2-\alpha_k\langle \delta_t, z_t-x\rangle \nn \\
 &=p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)-\frac{\alpha_k}{2\gamma_k}(1-L_{\rho_k}\alpha_k\gamma_k)\|z_{t-1}-z_t\|^2-\alpha_k\langle \delta_t, z_t-z_{t-1}\rangle-\alpha_k\langle \delta_t, z_{t-1}-x\rangle \nn\\
    &\leq  p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)+\frac{\alpha_k\gamma_k\|\delta_t\|^2}{2(1-L_{\rho_k}\alpha_k\gamma_k)}
    -\alpha_k\langle \delta_t, z_{t-1}-x\rangle, \label{l7-4}
\end{align}
where the last relation follows from \eqref{l7-1} and the Young's inequality $a\|u\|^2+ b^2\|v\|^2/a \geq 2b\langle u,v \rangle$ for any $a>0$ and $b$. In addition, let $\ell_{\barf}(u,v)=\barf(v)+\langle \nabla \barf(v), u-v\rangle$. Notice from this and \eqref{notation} that
\[
\ell_{f_{\rho_k}}(u,v) = \ell_{\barf}(u,v) + \frac{{\rho_k}}{2}\big(
\|[c(v)]_+\|^2+\langle \nabla(\|[c(v)]_+\|^2), u-v \rangle\big) \qquad \forall u, v .
\]
Using this, \eqref{mean}, \eqref{var}, \eqref{l7-2}, and the convexity of $\barf$ and $\|[c(\cdot)]_+\|^2$, we obtain that
\begin{align}
&p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)+\frac{\alpha_k\gamma_k\bbE[\|\delta_t\|^2|\Xi_{k,t-1}]}{2(1-L_{\rho_k}\alpha_k\gamma_k)}-\alpha_k\bbE[\langle \delta_t, z_{t-1}-x\rangle|\Xi_{k,t-1}]\nn\\
&\overset{\eqref{mean}\eqref{var}}{\leq} p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)+\frac{L_{\nabla \barf}\alpha_k\gamma_k}{1-L_{\rho_k}\alpha_k\gamma_k}\left(\barf(\tilde x_{k}) - \ell_{\barf}(\tilde x_{k},y_t)\right)\nn\\
&=p_k\ell_{\barf}(\tilde x_{k},y_t)+\frac{L_{\nabla \barf}\alpha_k\gamma_k}{1-L_{\rho_k}\alpha_k\gamma_k}\left(\barf(\tilde x_{k}) - \ell_{\barf}(\tilde x_{k},y_t)\right)+\frac{p_k{\rho_k}}{2}\left(\|[c(y_t)]_+\|^2+\langle \nabla (\|[c(y_t)]_+\|^2), \tilde x_{k} - y_t \rangle\right)\nn\\
&=\Big(p_k-\frac{L_{\nabla \barf}\alpha_k\gamma_k}{1-L_{\rho_k}\alpha_k\gamma_k}\Big)\ell_\barf(\tilde x_{k},y_t)+\frac{L_{\nabla \barf}\alpha_k\gamma_k}{1-L_{\rho_k}\alpha_k\gamma_k}\barf(\tilde x_{k})+\frac{p_k{\rho_k}}{2}\left(\|[c(y_t)]_+\|^2+\langle \nabla (\|[c(y_t)]_+\|^2), \tilde x_{k} - y_t \rangle\right)\nn\\
&\leq p_k\barf(\tilde x_{k}) + \frac{p_k{\rho_k}}{2}\|[c(\tilde x_{k})]_+\|^2
= p_kf_{\rho_k}(\tilde x_{k}),\label{l7-5}
\end{align}
where the last inequality follows from \eqref{l7-2} and the convexity of $\barf$ and $\|[c(\cdot)]_+\|^2$. It then follows from \eqref{l7-4} and \eqref{l7-5} that
\begin{align*}
&\bbE\Big[p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)-\frac{\alpha_k}{2\gamma_k}(1-L_{\rho_k}\alpha_k\gamma_k)\|z_{t-1}-z_t\|^2-\alpha_k\langle \delta_t, z_t-x\rangle\Big] \nn \\
    &\overset{\eqref{l7-4}}{\leq}  \bbE\Big[p_k\ell_{f_{\rho_k}}(\tilde x_{k},y_t)+\frac{\alpha_k\gamma_k\|\delta_t\|^2}{2(1-L_{\rho_k}\alpha_k\gamma_k)} -\alpha_k\langle \delta_t, z_{t-1}-x\rangle\Big] \overset{\eqref{l7-5}}{\leq} p_k\bbE[f_{\rho_k}(\tilde x_{k})].
\end{align*}
Using this inequality, the definition of $F_{\rho_k}$ in \eqref{def-Frho2}, and taking expectation on both sides of \eqref{l7-3} lead to
\[
 \bbE[F_{\rho_k}(x_t)] \leq(1-\alpha_k-p_k)\bbE[F_{\rho_k}(x_{t-1})]+\alpha_k\Big(F_{\rho_k}(x)+\frac{1}{2\gamma_k}\bbE[\|z_{t-1}-x\|^2]-\frac{1}{2\gamma_k}\bbE[\|z_t-x\|^2]\Big)+p_k\bbE[F_{\rho_k}(\tilde x_{k})].
\]
The relation \eqref{l7-exp} then follows from this inequality by rearranging the terms.
\end{proof}

We next derive upper bounds for $F_\rho(x_k)-F^*_\rho $ and $\bbE[ F_\rho(x_k)-F^*_\rho]$ under the setting where constant penalty parameter $\rho_k \equiv \rho$ is used in Algorithm \ref{alg2} for some $\rho>0$.

\begin{lemma}\label{l-exactbound3}
Suppose that Assumptions \ref{a1} and \ref{a3} hold, and that $\{\tilde x_{k}\}$ is generated by Algorithm \ref{alg2} with $\{q_i\}$, $\{\theta_t\}$, $\{\gamma_k\}$, $\{p_k\}$, $\{\alpha_k\}$ and $\{T_k\}$ given in \eqref{def-para4}, and $\rho_k \equiv \rho$  for some $\rho>0$.  Let $k_0=\lfloor \log_2 s\rfloor+1$. Then for all $K> k_0$, we have
\begin{align}
    &F_{\rho}(\tilde x_K)-F_{\rho}^*\leq
      \frac{16(\tC_3+\rho \tC_4)}{s(K-k_0+3)^2}+16L_{\nabla \barf}D_\cX^2,\label{l9-bound}  \\  
    &\bbE[F_{\rho}(\tilde x_K)-F_{\rho}^*]\leq
      \frac{16(\tC_3+\rho \tC_4)}{s(K-k_0+3)^2}, \label{l9-expbound}
\end{align}
 where $D_\cX$ is given in Assumption \ref{a1}, $L_{\nabla \barf}$ is defined in \eqref{Lam}, and $\tC_3$, $\tC_4$, $F_\rho$, and $F_{\rho}^*$ are defined in \eqref{c1011} and \eqref{penalty-prob}, respectively. 
\end{lemma}

\begin{proof}
Let $\{g_t\}$ and $\{y_t\}$ be generated in the $k$th outer iteration of Algorithm \ref{alg2}, and $\delta_t = g_t-\nabla f_{{\rho_k}}(y_t)$. Notice from \eqref{def-para3} that $q_i=L_i/(\sum_{j=1}^sL_j)$. By these, \eqref{Lam}, the expression of $g_t$,  $L_i$-smoothness of $f_i$, $L_{\nabla \barf}$-smoothness of $f$, and Assumption \ref{a1}, one has
\begin{align*}
    \|\delta_t\| &=\Big\|\frac{\nabla f_{i_t}(y_t)-\nabla f_{i_t}(\tilde x_{k})}{q_{i_t}s}+\nabla f(\tilde x_{k})- \nabla f(y_t)\Big\| \leq\frac{L_{i_t}\|y_t-\tilde x_{k}\|}{q_{i_t}s}+L_{\nabla \barf}\|\tilde x_{k}-y_t\| \\
& \leq \left(\frac{L_{i_t}}{q_{i_t}s}+L_{\nabla \barf}\right)D_\cX\overset{\eqref{Lam}}{=}2L_{\nabla \barf}D_\cX.
\end{align*}
This inequality and Assumption \ref{a1} imply that
\begin{equation}\label{deltabound}
    \langle\delta_t, z_t-x\rangle\leq \|\delta_t\|\|z_t-x\|\leq2L_{\nabla \barf}D_\cX^2 \qquad \forall x\in \cX.
\end{equation}

Let $L_{\rho}$ be defined in  \eqref{notation}.  Notice from  \eqref{def-para4} and \eqref{notation} that $1/(3L_{\rho_k}\alpha_k)=\gamma_k \leq 1/(3L_{\nabla \barf}\alpha_k)$, which implies that 
$L_{\rho_k}\alpha_k\gamma_k=1/3$ and $L_{\nabla \barf}\alpha_k\gamma_k \leq 1/3$. By these, one can verify that  the assumption of Lemma \ref{l-iter2} holds for $\{q_i\}$, $\{\alpha_k\}$, $\{\gamma_k\}$ and $\{p_k\}$ given in \eqref{def-para4}. Let $x^*_\rho\in\argmin\limits_{x\in\cX} F_\rho(x)$. It then follows from \eqref{l7-exact} with $x=x^*_\rho$ and \eqref{deltabound} that 
\begin{align}
    \frac{\gamma_k}{\alpha_k}(F_{\rho}(x_t)-F_\rho^*)&\leq 
 \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{\rho}(x_{t-1})-F_\rho^*)+\frac{\gamma_kp_k}{\alpha_k} (F_{\rho}(\tilde x_{k})-F_\rho^*)\nn\\
 &\quad +\frac{1}{2}\big(\|z_{t-1}-x^*_\rho\|^2-\|z_t-x^*_\rho\|^2\big) +2\gamma_kL_{\nabla \barf}D_\cX^2.\label{l9-1}
\end{align}
Summing up \eqref{l9-1} from $t=1$ to $T_k$, and using the fact that $x_0=\tilde x_{k}$, $z_0=\tilde z_{k}$, $z_{T_k}=\tilde z_{k+1}$, we have
\begin{align}
\sum_{t=1}^{T_k}\frac{\gamma_k}{\alpha_k}(F_\rho(x_t)-F_\rho^*)
&\leq \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_\rho(x_{0})-F_\rho^*)+ \sum_{t=2}^{T_k}\frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_\rho(x_{t-1})-F_\rho^*)\nn\\
&\quad+\frac{T_k\gamma_kp_k}{\alpha_k}(F_\rho(\tilde x_{k})-F_\rho^*)+\frac{1}{2}\big(\|z_{0}-x^*_\rho\|^2-\|z_{T_k}-x^*_\rho\|^2\big)+2\gamma_k T_k L_{\nabla \barf}D_\cX^2\nn\\
&= \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_\rho(\tilde x_{k})-F_\rho^*)+ \sum_{t=1}^{T_k-1}\frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_\rho(x_{t})-F_\rho^*)\nn\\
&\quad+\frac{T_k\gamma_kp_k}{\alpha_k}(F_\rho(\tilde x_{k})-F_\rho^*)
+\frac{1}{2}\big(\|\tilde z_{k}-x^*_\rho\|^2-\|\tilde z_{k+1}-x^*_\rho\|^2\big)+2\gamma_k T_k L_{\nabla \barf}D_\cX^2.\label{l9-sum}
\end{align}

Let $\cL_k$ and $\mathcal{R}_k$ be defined as
\beq \label{Lk}
    \cL_k :=\frac{\gamma_k}{\alpha_k}+(T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}, \qquad
    \mathcal{R}_k :=\frac{\gamma_k}{\alpha_k}(1-\alpha_k)+(T_k-1)\frac{\gamma_kp_k}{\alpha_k}
\eeq
 with the associated $\alpha_k$, $\gamma_k$, $p_k$ and $T_k$ given in \eqref{def-para4}. Notice from \eqref{def-para4}, the definition of $\cL_k$, and 
Algorithm \ref{alg2} that $\cL_k=\sum_{t=1}^{T_k}\theta_t$ and $\tilde x_{k+1}=\sum_{t=1}^{T_k}(\theta_tx_t)/\sum_{t=1}^{T_k}\theta_t$. Using  these, \eqref{l9-sum}, and the convexity of $F_\rho$, we have
    \begin{align}
        & \cL_k(F_\rho(\tilde x_{k+1})-F_\rho^*)=\Big(\sum_{t=1}^{T_k}\theta_t\Big)(F_\rho(\tilde x_{k+1})-F_\rho^*)\leq\sum_{t=1}^{T_k}\theta_t(F_\rho(x_t)-F_\rho^*)\nn\\
        &\overset{\eqref{def-para4}}=\sum_{t=1}^{T_k}\frac{\gamma_k}{\alpha_k}(F_\rho(x_t)-F_\rho^*)-\sum_{t=1}^{T_k-1}\frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_\rho(x_t)-F_\rho^*)\nn \\
        &\overset{\eqref{l9-sum}}{\leq} \Big(\frac{\gamma_k}{\alpha_k}(1-\alpha_k)+(T_k-1)\frac{\gamma_kp_k}{\alpha_k}\Big)(F_\rho(\tilde x_{k})-F_\rho^*)
    +\frac{1}{2}\big(\|\tilde z_{k}-x^*_\rho\|^2-\|\tilde z_{k+1}-x^*_\rho\|^2\big)+2\gamma_k T_k L_{\nabla \barf}D_\cX^2 \nn \\
& =\mathcal{R}_k(F_\rho(\tilde x_{k})-F_\rho^*)
    +\frac{1}{2}\big(\|\tilde z_{k}-x^*_\rho\|^2-\|\tilde z_{k+1}-x^*_\rho\|^2\big)+2\gamma_kT_k L_{\nabla \barf}D_\cX^2. \label{l9-2}
    \end{align}

Next claim that $\cL_k-\mathcal{R}_{k+1}\geq 0$ for all $k\geq1$. Indeed, notice from \eqref{def-para4} that if $1\leq k< k_0$,  $\alpha_{k+1}=\alpha_k=1/2$, $p_k=1/2$, $\gamma_{k+1}=\gamma_k$, and $T_{k+1}=2T_k$. Using these and \eqref{Lk}, we have that for all $1\leq k< k_0$,
\begin{align*}
    &\cL_k-\mathcal{R}_{k+1}
    \overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}-\frac{\gamma_{k+1}}{\alpha_{k+1}}(1-\alpha_{k+1})+(T_{k+1}-1)\frac{\gamma_{k+1}p_{k+1}}{\alpha_{k+1}}\\
    &= \frac{\gamma_k}{\alpha_k}\big(1+(T_k-1)(\alpha_k+p_k)-(1-\alpha_k)-(2T_k-1)p_k\big)=0,
\end{align*}
and hence the above claim holds for all $1\leq k< k_0$. On the other hand, if $k\geq k_0$, notice from \eqref{def-para4},  \eqref{notation},  $k_0 \geq 1$, and $\rho_k \equiv \rho$ that $T_k=T_{k+1}=T_{k_0}\geq1$, $\alpha_k=2/(k-k_0+4)$, $p_{k}=1/2$, and $\gamma_k=1/(3L_\rho\alpha_k)=(k-k_0+4)/(6L_\rho)$. Using these and \eqref{Lk}, we obtain that for all $k\geq k_0$,
\begin{align*}
    &\cL_k-\mathcal{R}_{k+1}\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_{k}-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}-\frac{\gamma_{k+1}}{\alpha_{k+1}}(1-\alpha_{k+1})-(T_{k+1}-1)\frac{\gamma_{k+1}p_{k+1}}{\alpha_{k+1}}\\
    &=\frac{\gamma_k}{\alpha_k}+(T_{k_0}-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}-\frac{\gamma_{k+1}}{\alpha_{k+1}}(1-\alpha_{k+1})-(T_{k_0}-1)\frac{\gamma_{k+1}p_{k+1}}{\alpha_{k+1}}\\
    &=\frac{\gamma_k}{\alpha_k}-\frac{\gamma_{k+1}}{\alpha_{k+1}}(1-\alpha_{k+1})+(T_{k_0}-1)\Big(\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}-\frac{\gamma_{k+1}p_{k+1}}{\alpha_{k+1}}\Big)\\
    &=\frac{(k-k_0+4)^2}{12L_\rho}-\frac{(k-k_0+5)^2}{12L_\rho}\Big(1-\frac{2}{k-k_0+5}\Big)\\
    &\quad+(T_{k_0}-1)\Big[\frac{(k-k_0+4)^2}{12L_\rho}\Big(\frac{2}{k-k_0+4}+\frac{1}{2}\Big)-\frac{(k-k_0+5)^2}{24L_\rho}\Big]\\
    &=\frac{(k-k_0+4)^2-(k-k_0+5)^2+2(k-k_0+5)}{12L_\rho} \\
    &\quad+\frac{(T_{k_0}-1)\big[4(k-k_0+4)+(k-k_0+4)^2-(k-k_0+5)^2\big]}{24L_\rho}\\
    &=\frac{1}{12L_\rho}+\frac{(T_{k_0}-1)(2(k-k_0)+7)}{24L_\rho}\geq 0,
\end{align*}
where the second equality is due to $T_k=T_{k+1}=T_{k_0}$, and the fourth equality follows from $\alpha_k=2/(k-k_0+4)$, $p_{k}=1/2$ and $\gamma_k=(k-k_0+4)/(6L_\rho)$. Hence, the above claim also holds for all $k \geq k_0$.

Summing up \eqref{l9-2} from $k=1$ to $K-1$, and using the fact that $F_\rho(x)-F_\rho^*\geq 0$ for any $x\in\cX$, $\cL_k-\mathcal{R}_{k+1}\geq 0$ for all $k\geq 1$, $\tilde x_1=\tilde z_1=x^0$, and $\mathcal{R}_1=2/(3L_\rho)$, we have
\begin{align}
\cL_{K-1}(F_\rho(\tilde x_K)-F_\rho^*)&
\leq \sum_{k=1}^{K-2}(\mathcal{R}_{k+1}-\cL_k)(F_\rho(\tilde x_{k})-F_\rho^*)+\mathcal{R}_1(F_\rho(\tilde x_1)-F_\rho^*)+\frac{1}{2}\|\tilde z_1-x^*_\rho\|^2+2L_{\nabla \barf}D_\cX^2\sum_{k=1}^{K-1}\gamma_kT_k \nn\\
&\leq\frac{2}{3L_\rho}(F_\rho(x^0)-F_\rho^*)+\frac{1}{2}\|x^0-x^*_\rho\|^2+2L_{\nabla \barf}D_\cX^2\sum_{k=1}^{K-1}\gamma_kT_k.    \label{l9-4}
\end{align}
In addition, recall that $k_0=\lfloor \log_2 s\rfloor+1$ and $T_{k_0}=2^{k_0-1}$, which imply that  $s/2\leq T_{k_0} \leq s$. By this, $\rho_k\equiv \rho$,  \eqref{def-para4}, \eqref{notation}, and \eqref{Lk}, one has that for all $K>k_0$,
\begin{align*}
    \cL_{K-1}&\overset{\eqref{Lk}}{=}\frac{\gamma_{K-1}}{\alpha_{K-1}}\big(1+(T_{K-1}-1)(\alpha_{K-1}+p_{K-1})\big)\\
    &\overset{\eqref{def-para4}\eqref{notation}}{=}\frac{1}{3L_\rho\alpha_{K-1}^2}\left(1+(T_{K-1}-1)\Big(\alpha_{K-1}+\frac{1}{2}\Big)\right)
    =\frac{T_{K-1}-1}{3L_\rho\alpha_{K-1}}+\frac{T_{K-1}+1}{6L_\rho\alpha_{K-1}^2}\\
    &\overset{\eqref{def-para4}}{=}\frac{(T_{k_0}-1)(K-k_0+3)}{6L_\rho}+\frac{(T_{k_0}+1)(K-k_0+3)^2}{24L_\rho}\\
    &\geq\frac{(s-2)(K-k_0+3)}{12L_\rho}+\frac{(s+2)(K-k_0+3)^2}{48L_\rho} \\
    & =\frac{(s-2)(K-k_0+3)}{12L_\rho}+\frac{2(K-k_0+3)^2}{48L_\rho} + \frac{s(K-k_0+3)^2}{48L_\rho} \\
    &\geq \frac{(s-2)(K-k_0+3)}{12L_\rho}+\frac{8(K-k_0+3)}{48L_\rho} + \frac{s(K-k_0+3)^2}{48L_\rho} \\
    & = \frac{s(K-k_0+3)}{12L_\rho}+ \frac{s(K-k_0+3)^2}{48L_\rho} 
     \geq \frac{s(K-k_0+3)^2}{48L_\rho},\\
    \sum_{k=1}^{K-1}\gamma_kT_k&=\sum_{k=1}^{k_0-1}\gamma_kT_k+\sum_{k=k_0}^{K-1}\gamma_kT_k 
    \overset{\eqref{def-para4}\eqref{notation}}{=} \frac{2}{3L_\rho}\sum_{k=1}^{k_0-1}2^{k-1}+\frac{T_{k_0}}{3L_\rho}\sum_{k=k_0}^{K-1}\frac{k-k_0+4}{2}\\
    &\leq \frac{2^{k_0}}{3L_\rho}+\frac{T_{k_0}}{3L_\rho}\frac{(K-k_0+7)(K-k_0)}{4}
    = \frac{T_{k_0}\big((K-k_0)^2+7(K-k_0)+8\big)}{12L_\rho}\\
    &\leq \frac{T_{k_0}\big(2(K-k_0)^2+12(K-k_0)+18\big)}{12L_\rho}\leq\frac{s(K-k_0+3)^2}{6L_\rho}.
\end{align*}
 It then follows from the above two relations,  \eqref{penalty-prob},  \eqref{notation}, \eqref{l9-4},  and  Assumption \ref{a1}(i) that
\begin{align*}
F_{\rho}(\tilde x_K)-F_\rho^*&\leq \frac{16}{s(K-k_0+3)^2}\Big(2(F_\rho(x^0)-F_\rho^*)+\frac{3L_\rho}{2}\|x^0-x^*_\rho\|^2\Big)+16L_{\nabla \barf}D_\cX^2\nn\\
&\overset{ \eqref{penalty-prob}}{\leq} \frac{16}{s(K-k_0+3)^2}\Big(2(F(x^0)-F(x^*_{\rho})) +\rho\|[c(x^0)]_+\|^2 +\frac{3L_\rho}{2}\|x^0-x^*_\rho\|^2\Big)+16L_{\nabla \barf}D_\cX^2, \nn \\
&\leq \frac{16}{s(K-k_0+3)^2}\Big(2D_F+\rho\|[c(x^0)]_+\|^2 + \frac{3(L_{\nabla \barf}+\rho L_{\nabla c^2})  D_\cX^2}{2}\Big)+16L_{\nabla \barf}D_\cX^2,
\end{align*}
which together with \eqref{c1011} implies that \eqref{l9-bound} holds. In addition, the proof of \eqref{l9-expbound} follows from  \eqref{l7-exp} and similar arguments as above, and is thus omitted.
\end{proof}

We are now ready to prove Theorem \ref{thm:finite-sum_fixed}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:finite-sum_fixed}}]
We first prove statement (i) of Theorem \ref{thm:finite-sum_fixed}, where $\rho=s^{2/3}K^{4/3}$. Using \eqref{feasibility} and \eqref{l9-bound},  we have
\begin{align}
&\|[c(\tilde x_K)]_+\|\overset{\eqref{feasibility}}{\leq}  \frac{2\Lambda}{\rho}+\sqrt{\frac{2(F_{\rho}(\tilde x_K)-F_{\rho}^*)}{\rho}}
\overset{\eqref{l9-bound}}{\leq}\frac{2\Lambda}{\rho}+\sqrt{\frac{32(\tC_3+\rho \tC_4)}{\rho s(K-k_0+3)^2}+\frac{32L_{\nabla \barf}D_\cX^2}{\rho}}\nn\\
&\leq \frac{2\Lambda}{\rho}+\sqrt{\frac{32\tC_3}{\rho s(K-k_0+3)^2}}+\sqrt{\frac{32\tC_4}{s(K-k_0+3)^2}}+\sqrt{\frac{32L_{\nabla \barf}D_\cX^2}{\rho}}.\label{Thm3-detercons}
\end{align}
Also, observe from \eqref{opt-gap} that $\bbE [F(\tilde x_K)-F^*] \leq \bbE[F_\rho(\tilde x_K)-F_\rho^*]$. Using these, \eqref{l9-expbound}, $\rho=s^{2/3}K^{4/3}$, and $K\geq2(k_0-3)$, we see that  \eqref{thm4-ineq1} and \eqref{thm4-ineq2} hold. In addition, by \eqref{feasibility} and \eqref{l9-expbound}, one has
\begin{align}
    \bbE[\|[c(\tilde x_K)]_+\|] & \overset{\eqref{feasibility}}
    {\leq} \frac{2\Lambda}{\rho}+\bbE\left[\sqrt{\frac{2(F_{\rho}(\tilde x_K)-F_{\rho}^*)}{\rho}}\,\right] \leq\frac{2\Lambda}{\rho}+\sqrt{\frac{2\bbE[F_{\rho}(\tilde x_K)-F_{\rho}^*]}{\rho}} \nn\\
&\overset{\eqref{l9-expbound}}{\leq} \frac{2\Lambda}{\rho} +\sqrt{\frac{32(\tC_3+\rho \tC_4)}{\rho s(K-k_0+3)^2}} \leq \frac{2\Lambda}{\rho} +\sqrt{\frac{32\tC_3}{\rho s(K-k_0+3)^2}}+\sqrt{\frac{32\tC_4}{s(K-k_0+3)^2}}.\label{Thm3-expcons}
\end{align}
Also, notice from  \eqref{opt-gap} that $\bbE [F(\tilde x_K)-F^*] \geq -\Lambda  \bbE[\|[c(\tilde x_K)]_+\|]$. By these, $\rho=s^{2/3}K^{4/3}$,  and $K\geq2(k_0-3)$, one can conclude that  \eqref{thm4-ineq1-exp} and \eqref{thm4-ineq3} hold.

The proof of statement (ii) of Theorem \ref{thm:finite-sum_fixed} follows from $\rho=\sqrt{s}K$ and similar arguments as above, and is thus omitted.
\end{proof}

In the remainder of this subsection, we provide a proof of Theorem \ref{thm:finite-sum}.  Before proceeding, we establish several technical lemmas below. The following lemma provides a relationship between $ \cL_{k}$ and $\mathcal{R}_{k+1}$.

\begin{lemma}\label{LkRk}
Let $\cL_k$ and $\mathcal{R}_k$ be defined in \eqref{Lk} with $\{\alpha_k\}$, $\{\gamma_k\}$, $\{p_k\}$  given in \eqref{def-para3}, and $k_0$, $\{\rho_k\}$, $\{T_k\}$ given in  \eqref{rho1} or  \eqref{rho2}. Then we have 
\begin{equation}\label{lkrk}
    \cL_{k}\Big(1-\frac{2(\rho_{k+1}-\rho_k)}{\rho_{k+1}}\Big)\geq \mathcal{R}_{k+1} \qquad \forall k \geq 1.
\end{equation}
\end{lemma}

\begin{proof}
We divide the proof into three separate cases: $1\leq k<k_0$, $k=k_0$, and $k>k_0$.

Case 1) $1\leq k<k_0$. Fix any $1\leq k<k_0$. Claim that $T_k \geq 1$ and $T_{k+1}\leq2T_k$ hold for $\{T_k\}$  given in  \eqref{rho1} or \eqref{rho2}. Indeed, if $\{T_k\}$ is given in  \eqref{rho1}, one has $T_{k}=\lceil2^{3(k-1)/4}\rceil$, which implies that $T_k \geq 1$ and 
\[
T_{k+1}=\lceil2^{3(k+1-1)/4}\rceil=\lceil2^{3/4}\times2^{3(k-1)/4}\rceil\leq\lceil2^{3/4}\rceil\times\lceil2^{3(k-1)/4}\rceil\leq2T_k.
\]
In addition, if $\{T_k\}$ is given in  \eqref{rho2}, one has $T_k=2^{k-1}$, yielding $T_k \geq 1$ and $T_{k+1}=2T_k$. Hence, the claim holds as desired. Observe from  \eqref{def-para3} that $\alpha_{k+1}=\alpha_k$ and $\rho_{k+1} \geq \rho_k$, which along with \eqref{notation} imply that $\gamma_{k+1} \leq \gamma_k$. Also, notice from  \eqref{def-para3} that $\alpha_{k+1}=\alpha_k=6/7$, $p_{k+1}=p_k=1/7$, $\rho_{k+1}=\sqrt{2}\rho_k$. Using these, \eqref{Lk}, $T_k \geq 1$, $T_{k+1}\leq2T_k$, and $\gamma_{k+1} \leq \gamma_k$, we obtain that
\begin{align*}
    \cL_k-\mathcal{R}_{k+1}&\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}-\frac{\gamma_{k+1}}{\alpha_{k+1}}(1-\alpha_{k+1})+(T_{k+1}-1)\frac{\gamma_{k+1}p_{k+1}}{\alpha_{k+1}}\\
    &\geq\frac{\gamma_k}{\alpha_k}(1+(T_k-1)(\alpha_k+p_k))-\frac{\gamma_{k+1}}{\alpha_k}((1-\alpha_k)+(2T_k-1)p_k) \\
    &\geq\frac{\gamma_k}{\alpha_k}(1+(T_k-1)(\alpha_k+p_k)-(1-\alpha_k)-(2T_k-1)p_k) \\
&=\frac{5\gamma_kT_k}{7\alpha_k}=\frac{5\cL_k}{7}  \geq\frac{2(\rho_{k+1}-\rho_k)}{\rho_{k+1}}\cL_k,
\end{align*}
where the first inequality is  due to $\alpha_{k+1}=\alpha_k$ and $T_{k+1}\leq2T_k$, the second inequality follows from $\gamma_{k+1} \leq \gamma_k$, $0<\alpha_k <1$ and $T_k \geq 1$, the second and third equalities are due  to $\alpha_k=6/7$, $p_k=1/7$, and \eqref{Lk}, and  the last inequality follows from $\rho_{k+1}=\sqrt{2}\rho_k$. Hence, \eqref{lkrk} holds for all $1\leq k< k_0$. 

Case 2) $k=k_0$. Claim that $0<(\rho_{k_0+1}-\rho_{k_0})/\rho_{k_0+1}\leq1/3$ holds for $k_0$, $\rho_{k_0}$, and $\rho_{k_0+1}$ given in \eqref{rho1} or  \eqref{rho2}. Indeed, if they are given in \eqref{rho1}, one can observe that $k_0=\lfloor(4/3)\log_2 s\rfloor+1$, $\rho_{k_0}=2^{k_0/2}$, and $\rho_{k_0+1}=3s^{2/3}/2$. Also, notice that $s^{2/3} \leq 2^{(\lfloor(4/3)\log_2 s\rfloor+1)/2}\leq \sqrt{2} s^{2/3}$ and hence $s^{2/3} \leq \rho_{k_0} \leq \sqrt{2} s^{2/3}$.  This together with $\rho_{k_0+1}=3s^{2/3}/2$ implies that
\[
0<(\rho_{k_0+1}-\rho_{k_0})/\rho_{k_0+1}\leq(3s^{2/3}/2-s^{2/3})/(3s^{2/3}/2)=1/3.
\]
 In addition, if $k_0$, $\rho_{k_0}$, and $\rho_{k_0+1}$ are given in \eqref{rho2}, we observe that  $k_0=\lfloor \log_2 s\rfloor+1$, $\rho_{k_0}=2^{k_0/2}$, and $\rho_{k_0+1}=3\sqrt{s}/2$. Notice that 
$\sqrt{s} \leq 2^{(\lfloor\log_2 s\rfloor+1)/2}\leq \sqrt{2s}$ and hence  $\sqrt{s} \leq \rho_{k_0} \leq  \sqrt{2s}$. By this and $\rho_{k_0+1}=3\sqrt{s}/2$, one has
\[
0<(\rho_{k_0+1}-\rho_{k_0})/\rho_{k_0+1}\leq(3\sqrt{s}/2-\sqrt{s})/(3\sqrt{s}/2)=1/3.
\]
Hence, the above claim holds as desired. Notice from this claim, \eqref{def-para3}, and \eqref{notation} that  $L_{\rho_{k_0+1}}\geq L_{\rho_{k_0}}$, $\alpha_{k_0}=6/7$, and $\alpha_{k_0+1}=6/8$. By these and  \eqref{def-para3}, one has
\begin{equation} \label{alpha-gamma}
\gamma_{k_0+1}/\alpha_{k_0+1}=1/(8L_{\rho_{k_0+1}}\alpha_{k_0+1}^2)\leq1/(8L_{\rho_{k_0}}\alpha_{k_0+1}^2)=64/(392L_{\rho_{k_0}}\alpha_{k_0}^2)=64\gamma_{k_0}/(49\alpha_{k_0}).
\end{equation}
Notice from \eqref{def-para3}, \eqref{rho1}, \eqref{rho2}, and \eqref{Lk} that $\alpha_{k_0+1} \leq 1$,  $\alpha_{k_0}=6/7$, $p_{k_0+1}=p_{k_0}=1/7$, $T_{k_0+1}=T_{k_0} \geq 1$, and $\cL_{k_0}= \gamma_{k_0}T_{k_0}/\alpha_{k_0}$. Using these, \eqref{alpha-gamma}, and $(\rho_{k_0+1}-\rho_{k_0})/\rho_{k_0+1}\leq1/3$, we obtain that
\begin{align*}
    \cL_{k_0}-\mathcal{R}_{k_0+1}
    &\overset{\eqref{Lk}}{=}\frac{\gamma_{k_0}}{\alpha_{k_0}}+(T_{k_0}-1)\frac{\gamma_{k_0}(\alpha_{k_0}+p_{k_0})}{\alpha_{k_0}}-\frac{\gamma_{k_0+1}}{\alpha_{k_0+1}}(1-\alpha_{k_0+1})-(T_{k_0+1}-1)\frac{\gamma_{k_0+1}p_{k_0+1}}{\alpha_{k_0+1}}\\
    &=\frac{\gamma_{k_0}}{\alpha_{k_0}}\big(1+(T_{k_0}-1)(\alpha_{k_0}+p_{k_0})\big)-\frac{\gamma_{k_0+1}}{\alpha_{k_0+1}}\big((1-\alpha_{k_0+1})+(T_{k_0+1}-1)p_{k_0+1}\big)\\
    &\overset{\eqref{alpha-gamma}}{\geq}\frac{\gamma_{k_0}}{\alpha_{k_0}}\Big(1+(T_{k_0}-1)(\alpha_{k_0}+p_{k_0})-\frac{64}{49}\big((1-\alpha_{k_0+1})+(T_{k_0+1}-1)p_{k_0+1}\big)\Big)\\
   &=\frac{\gamma_{k_0}}{\alpha_{k_0}}\Big(\Big(1-\frac{64}{343}\Big)T_{k_0}-\frac{16}{49}+\frac{64}{343}\Big)\\
    &\geq\frac{33\gamma_{k_0}T_{k_0}}{49\alpha_{k_0}}
    \geq \frac{2\gamma_{k_0}T_{k_0}}{3\alpha_{k_0}}
    \geq\frac{2(\rho_{k_0+1}-\rho_{k_0})}{\rho_{k_0+1}}\cL_{k_0},
\end{align*}
where the first inequality follows from \eqref{alpha-gamma}, $\alpha_{k_0+1} \leq 1$, and $T_{k_0+1} \geq 1$, the third equality is due to $\alpha_{k_0}=6/7$, $p_{k_0+1}=p_{k_0}=1/7$, and $T_{k_0+1}=T_{k_0}$, 
the second inequality follows from $T_{k_0}\geq1$ and $-16/49+64/343<0$, and the last inequality is due to 
$(\rho_{k_0+1}-\rho_{k_0})/\rho_{k_0+1}\leq1/3$ and $\cL_{k_0}= \gamma_{k_0}T_{k_0}/\alpha_{k_0}$. Hence, \eqref{lkrk} also holds for $k= k_0$. 

Case 3) $k>k_0$. Fix any $k>k_0$. Claim that 
\begin{align}
& \rho_{k+1} \geq \rho_k, \quad L_{\rho_{k+1}}   \leq 6L_{\rho_k}/5, \label{lrhoineq} \\
& \rho_{k+1}^{-1}(\rho_{k+1}-\rho_k) \leq 4(k-k_0+8)^{-1}/3 \label{rho-ineq}
\end{align}
hold for $\{\rho_k\}$ given in  \eqref{rho1} or \eqref{rho2}. Indeed, suppose that $\{\rho_k\}$ is given in  \eqref{rho1}. By this and $k>k_0$,  one has $\rho_k=3s^{2/3}(k-k_0+7)^{4/3}/32$. Using this, $k>k_0$, and \eqref{notation}, we obtain that $\rho_{k+1} \geq \rho_k$, and 
\begin{align*}
L_{\rho_{k+1}}  &=L_{\nabla \barf}+\rho_{k+1} L_{\nabla c^2} \leq \rho_{k+1}{\rho_k}^{-1} L_{\nabla \barf}+\rho_{k+1} L_{\nabla c^2}  =\rho_{k+1}{\rho_k}^{-1} L_{\rho_k}  \\ 
& \leq \Big(\frac{k-k_0+8}{k-k_0+7}\Big)^{4/3}L_{\rho_k}\leq\Big(\frac{8}{7}\Big)^{4/3}L_{\rho_k}\leq\frac{6L_{\rho_k}}{5}, \\
\rho_{k+1}-\rho_k & =3s^{2/3}((k-k_0+8)^{4/3}-(k-k_0+7)^{4/3} )/32\leq s^{2/3}(k-k_0+8)^{1/3}/8, \\ 
&= 4\rho_{k+1}(k-k_0+8)^{-1}/3,
\end{align*}
where the last inequality is due to the convexity of the function $\tau^{4/3}$. Hence, \eqref{lrhoineq} and \eqref{rho-ineq} hold for $\{\rho_k\}$ given in  \eqref{rho1}. In addition, if $\{\rho_k\}$ is given in  \eqref{rho2}, one has $\rho_k=3\sqrt{s}(k-k_0+7)/16$ due to $k>k_0$. By this and similar arguments as above, one can show that \eqref{lrhoineq} and \eqref{rho-ineq} also hold for $\{\rho_k\}$ given in  \eqref{rho2}. Hence, the above claim holds as desired.

Further, by  \eqref{notation} and $\rho_{k+1} \geq \rho_k$, one can see that  $L_{\rho_k}\leq L_{\rho_{k+1}}$. In addition, it follows from \eqref{def-para3},   \eqref{rho1}, \eqref{rho2}, \eqref{notation}, and $k>k_0$ that $\alpha_k=6/(k-k_0+7)$, $\alpha_{k+1}=6/(k-k_0+8)$, $p_{k}=p_{k+1}=1/7$, $\gamma_k=1/(8L_{\rho_k}\alpha_k)$, $\gamma_{k+1}=1/(8L_{\rho_{k+1}}\alpha_{k+1})$, $T_k=T_{k+1}=T_{k_0}$,  $\rho_k=3s^{2/3}(k-k_0+7)^{4/3}/32$ or $\rho_k=3\sqrt{s}(k-k_0+7)/16$. By these relations, \eqref{Lk},  \eqref{lrhoineq}, and \eqref{rho-ineq},  one has that 
\begin{align*}
    &\cL_k-\mathcal{R}_{k+1}\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_k-1)\gamma_k+(T_k-1)\frac{\gamma_kp_k}{\alpha_k}-\frac{\gamma_{k+1}}{\alpha_{k+1}}+\gamma_{k+1}-(T_{k+1}-1)\frac{\gamma_{k+1}p_{k+1}}{\alpha_{k+1}}\\
    &=\frac{1}{8L_{\rho_{k}}\alpha_k^2}+(T_k-1)\gamma_k+(T_k-1)\frac{p_k}{8L_{\rho_{k}}\alpha_k^2}-\frac{1}{8L_{\rho_{k+1}}\alpha_{k+1}^2}+\gamma_{k+1}-(T_k-1)\frac{p_k}{8L_{\rho_{k+1}}\alpha_{k+1}^2}\\
    &=(T_k-1)\Big(\gamma_k-\frac{p_k}{8L_{\rho_{k+1}}\alpha_{k+1}^2}+\frac{p_k}{8L_{\rho_{k}}\alpha_{k}^2}\Big)+\gamma_{k+1}-\frac{1}{8L_{\rho_{k+1}}\alpha_{k+1}^2}+\frac{1}{8L_{\rho_{k}}\alpha_{k}^2}\\
    &\geq (T_k-1)\Big(\gamma_k-\frac{p_k}{8L_{\rho_k}}\Big(\frac{1}{\alpha_{k+1}^2}-\frac{1}{\alpha_{k}^2}\Big)\Big)+\gamma_{k+1}-\frac{1}{8L_{\rho_{k+1}}}\Big(\frac{1}{\alpha_{k+1}^2}-\frac{1}{\alpha_{k}^2}\Big) \ (\text{due to} \ L_{\rho_k}\leq L_{\rho_{k+1}})\\
    &=(T_k-1)\Big(\gamma_k-\frac{p_k}{8L_{\rho_k}}\frac{(k-k_0+8)^2-(k-k_0+7)^2}{36}\Big)+\gamma_{k+1}-\frac{1}{8L_{\rho_{k+1}}}\frac{(k-k_0+8)^2-(k-k_0+7)^2}{36}  \\
    &=(T_k-1)\Big(\gamma_k-\frac{p_k}{8L_{\rho_k}}\frac{2(k-k_0)+15}{36}\Big)+\gamma_{k+1}-\frac{1}{8L_{\rho_{k+1}}}\frac{2(k-k_0)+15}{36}\\
    &\geq(T_k-1)\Big(\gamma_k-\frac{p_k}{8L_{\rho_k}}\frac{3(k-k_0+7)}{36}\Big)+\gamma_{k+1}-\frac{1}{8L_{\rho_{k+1}}}\frac{2(k-k_0+8)}{36} \\
&=(T_k-1)\Big(\gamma_k-\frac{p_k}{16L_{\rho_k}\alpha_k}\Big)+\gamma_{k+1}-\frac{1}{24L_{\rho_{k+1}}\alpha_{k+1}} \ (\text{due to} \ \alpha_k=6/(k-k_0+7)) \\
    &=(T_k-1)\Big(\gamma_k-\frac{p_k\gamma_k}{2}\Big)+\gamma_{k+1}-\frac{\gamma_{k+1}}{3}  \ (\text{due to} \ \gamma_k=1/(8L_{\rho_k}\alpha_k)) \\
    &=\frac{13}{14}(T_k-1)\gamma_k+\frac{2\gamma_{k+1}}{3}
    =\frac{13}{14}(T_k-1)\gamma_k+\frac{1}{12L_{\rho_{k+1}}\alpha_{k+1}} \ (\text{due to} \ p_k=1/7, \ \gamma_{k+1}=1/(8L_{\rho_{k+1}}\alpha_{k+1})) \\
    &\geq\frac{13}{14}(T_k-1)\gamma_k+\frac{1}{12L_{\rho_{k+1}}\alpha_{k}}
    \overset{\eqref{lrhoineq}}{\geq}\frac{13}{14}(T_k-1)\gamma_k+\frac{5}{72L_{\rho_{k}}\alpha_{k}}   \ (\text{due to} \ \alpha_{k+1} \leq \alpha_k)
    \\
    &=\frac{13}{14}(T_k-1)\gamma_k+\frac{5\gamma_{k}}{9}
    \geq \frac{8}{3(k-k_0+8)}\frac{k-k_0+7}{6}(T_k-1)\gamma_k+\frac{8}{3(k-k_0+8)}\frac{k-k_0+7}{6}\gamma_k\\
    &=\frac{8}{3(k-k_0+8)}\Big((T_k-1)\frac{\gamma_k}{\alpha_k}+\frac{\gamma_k}{\alpha_k}\Big) \ (\text{due to} \  \alpha_k=6/(k-k_0+7)) \\
   & \geq\frac{8}{3(k-k_0+8)}\Big((T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}+\frac{\gamma_k}{\alpha_k}\Big) \ (\text{due to} \  \alpha_k+p_k \leq 1) \\
    &\overset{\eqref{rho-ineq}}{\geq}\frac{2(\rho_{k+1}-\rho_k)}{\rho_{k+1}}\Big((T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}+\frac{\gamma_k}{\alpha_k}\Big)
    \overset{\eqref{Lk}}{=}\frac{2(\rho_{k+1}-\rho_k)}{\rho_{k+1}}\cL_k,
\end{align*}
where the second equality follows from $\gamma_k=1/(8L_{\rho_k}\alpha_k)$, $\gamma_{k+1}=1/(8L_{\rho_{k+1}}\alpha_{k+1})$, and $T_k=T_{k+1}$, and the fourth equality is due to $\alpha_k=6/(k-k_0+7)$ and $\alpha_{k+1}=6/(k-k_0+8)$.  Hence, \eqref{lkrk} also holds for $k>k_0$. 
\end{proof}

We next derive upper bounds on $F_{{\rho_k}}(\tilde x_k)-F_{{\rho_k}}^*$ and $\bbE[F_{{\rho_k}}(\tilde x_k)-F_{{\rho_k}}^*]$. 

\begin{lemma}\label{l-exactbound2}
Suppose that Assumptions \ref{a1} and \ref{a3} hold, and that $\{\tilde x_{k}\}$ is generated by Algorithm \ref{alg2} with $\{q_i\}$, $\{\theta_t\}$, $\{\gamma_k\}$, $\{p_k\}$, $\{\alpha_k\}$ given in \eqref{def-para3},  and $\{T_k\}$, $\{\rho_k\}$ given in \eqref{rho1} or   \eqref{rho2}. Let $F_{{\rho_k}}^*$, $F_{{\rho_k}}$, $\cL_k$ and $\mathcal{R}_k$ be defined in \eqref{def-Frho2} and \eqref{Lk} with such  $\{\rho_k\}$, $\{\gamma_k\}$, $\{p_k\}$, $\{\alpha_k\}$, and $\{T_k\}$. Then for all $k \geq 1$, we have
\begin{align}
F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*&\leq \mathcal{R}_{k}^{-1}\Big(\frac{1}{40L_{\rho_1}}\big(D_F+\frac{\rho_1}{2}\|[c(x^0)]_+\|^2\big)+\frac{D_\cX^2}{2}+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_iT_i}{\rho_i} \nn\\
&\qquad\quad\,\,\,+4\Lambda^2\sum_{i=1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2}+2L_{\nabla \barf}D_\cX^2\sum_{i=1}^{k-1}\gamma_i T_i\Big),\label{l8-bound}\\
\bbE[F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*]&\leq \mathcal{R}_{k}^{-1}\Big(\frac{1}{40L_{\rho_1}}\big(D_F+\frac{\rho_1}{2}\|[c(x^0)]_+\|^2\big)+\frac{D_\cX^2}{2} +\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_iT_i}{\rho_i}\nn\\
&\qquad\quad\,\,\,+4\Lambda^2\sum_{i=1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2}\Big), \label{expbound}
\end{align}
where $L_{\nabla \barf}$,  $D_{\mathcal{X}}$, $D_F$, and $\Lambda$ are given  in \eqref{Lam} and Assumptions \ref{a1}, respectively. 
\end{lemma}

\begin{proof}
Notice from  \eqref{def-para3} and \eqref{notation} that $1/(8L_{\rho_k}\alpha_k)=\gamma_k \leq 1/(8L_{\nabla \barf}\alpha_k)$, which implies that 
$L_{\rho_k}\alpha_k\gamma_k=1/8$ and $L_{\nabla \barf}\alpha_k\gamma_k \leq 1/8$. By these, one can easily verify that  the assumption of Lemma \ref{l-iter2} holds for $\{q_i\}$, $\{\alpha_k\}$, $\{\gamma_k\}$ and $\{p_k\}$ given in \eqref{def-para3}. Let $x^*$ be an arbitrary optimal solution of problem \eqref{prob2}. It then follows from \eqref{deltabound}, $F_{{\rho_k}}(x^*)=F^*$, and \eqref{l7-exact} with $x=x^*$ that 
\begin{align}
    \frac{\gamma_k}{\alpha_k}(F_{{\rho_k}}(x_t)-F^*)&\leq 
 \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{{\rho_k}}(x_{t-1})-F^*)+\frac{\gamma_kp_k}{\alpha_k} (F_{{\rho_k}}(\tilde x_{k})-F^*)\nn\\
 &\quad +\frac{1}{2}\big(\|z_{t-1}-x^*\|^2-\|z_t-x^*\|^2\big) +2\gamma_kL_{\nabla \barf}D_\cX^2.\label{l8-1}
\end{align}
Summing up \eqref{l8-1} from $t=1$ to $T_k$, and using the fact that $x_0=\tilde x_{k}$, $z_0=\tilde z_{k}$  and $z_{T_k}=\tilde z_{k+1}$, we have
\begin{align}
\sum_{t=1}^{T_k}\frac{\gamma_k}{\alpha_k}(F_{\rho_k}(x_t)-F^*)
&\leq \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{\rho_k}(x_{0})-F^*)+ \sum_{t=2}^{T_k}\frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{\rho_k}(x_{t-1})-F^*)\nn\\
&\quad+\frac{T_k\gamma_kp_k}{\alpha_k}(F_{\rho_k}(\tilde x_{k})-F^*)+\frac{1}{2}\big(\|z_{0}-x^*\|^2-\|z_{T_k}-x^*\|^2\big)+2\gamma_k T_k L_{\nabla \barf}D_\cX^2\nn\\
&= \frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{\rho_k}(\tilde x_{k})-F^*)+ \sum_{t=1}^{T_k-1}\frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{\rho_k}(x_{t})-F^*)\nn\\
&\quad+\frac{T_k\gamma_kp_k}{\alpha_k}(F_{\rho_k}(\tilde x_{k})-F^*)
+\frac{1}{2}\big(\|\tilde z_{k}-x^*\|^2-\|\tilde z_{k+1}-x^*\|^2\big)+2\gamma_k T_k L_{\nabla \barf}D_\cX^2.\label{l8-sum}
\end{align}
 By the  definitions of $\theta_t$ and $\cL_k$ in  \eqref{def-para3} and \eqref{Lk}, one can observe that $\cL_k=\sum_{t=1}^{T_k}\theta_t$. Using this, \eqref{l8-sum}, the definition of $\theta_t$ in \eqref{def-para3}, the convexity of $F_{\rho_k}(\cdot)$, and $\tilde x_{k+1}=\sum_{t=1}^{T_k}(\theta_tx_t)/(\sum_{t=1}^{T_k}\theta_t)$, we have
    \begin{align}
        & \cL_{k}(F_{\rho_k}(\tilde x_{k+1})-F^*)=\Big(\sum_{t=1}^{T_k}\theta_t\Big)(F_{\rho_k}(\tilde x_{k+1})-F^*) \leq\sum_{t=1}^{T_k}\theta_t(F_{\rho_k}(x_t)-F^*) \nn \\
        & \overset{\eqref{def-para3}}=\sum_{t=1}^{T_k}\frac{\gamma_k}{\alpha_k}(F_{\rho_k}(x_t)-F^*)-\sum_{t=1}^{T_k-1}\frac{\gamma_k}{\alpha_k}(1-\alpha_k-p_k)(F_{\rho_k}(x_t)-F^*)\nn \\
        &\overset{\eqref{l8-sum}}{\leq} \Big(\frac{\gamma_k}{\alpha_k}(1-\alpha_k)+(T_k-1)\frac{\gamma_kp_k}{\alpha_k}\Big)(F_{\rho_k}(\tilde x_{k})-F^*)
    +\frac{1}{2}\big(\|\tilde z_{k}-x^*\|^2-\|\tilde z_{k+1}-x^*\|^2\big)+2\gamma_k T_k L_{\nabla \barf}D_\cX^2, \nn \\
&\overset{\eqref{Lk}}{=}\mathcal{R}_{k}(F_{\rho_k}(\tilde x_{k})-F^*)
    +\frac{1}{2}\big(\|\tilde z_{k}-x^*\|^2-\|\tilde z_{k+1}-x^*\|^2\big)+2\gamma_k T_k L_{\nabla \barf}D_\cX^2. 
\label{l8-2}
    \end{align}

Let $x_k^*$ be an arbitrary optimal solution of \eqref{def-Frho2}. It then follows that $F_{\rho_k}^*=F_{\rho_k}(x_k^*)$. Notice from \eqref{def-Frho2} and  \eqref{Lk} that  $F_{\rho_{k+1}}^*\geq F_{\rho_k}^*$ and $\cL_k-\mathcal{R}_k=\gamma_kT_k\geq 0$. Using these, \eqref{prob2},  \eqref{def-Frho2}, \eqref{opt-gap}, \eqref{feasibility}, \eqref{Lk}, and \eqref{l8-2}, we obtain that for all $k\geq1$,
\begin{align}
&\frac{1}{2}\|\tilde z_{k}-x^*\|^2-\frac{1}{2}\|\tilde z_{k+1}-x^*\|^2+2\gamma_kT_k L_{\nabla \barf}D_\cX^2 \overset{\eqref{l8-2}}{\geq}\cL_k(F_{\rho_k}(\tilde x_{k+1})-F^*)- \mathcal{R}_k(F_{\rho_k}(\tilde x_{k})-F^*) \nn\\
&=\cL_k\big(F_{\rho_k}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_k}(\tilde x_{k})-F_{\rho_{k}}^*\big)+\cL_k\big(F_{\rho_{k+1}}^*-F^*\big)- \mathcal{R}_k\big(F_{\rho_{k}}^*-F^*\big)\nn\\
&\geq\cL_k\big(F_{\rho_k}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_k}(\tilde x_{k})-F_{\rho_{k}}^*\big)+(\cL_k-\mathcal{R}_k)\big(F_{\rho_k}^*-F^*\big)\nn\\
&\overset{\eqref{Lk}}{=}\cL_k\big(F_{\rho_k}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_k}(\tilde x_{k})-F_{\rho_{k}}^*\big)+\gamma_kT_k\big(F_{\rho_k}^*-F^*\big)\nn\\
&\overset{\eqref{prob2}\eqref{def-Frho2}}{=}\cL_k\big(F_{\rho_k}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_k}(\tilde x_{k})-F_{\rho_{k}}^*\big)+\gamma_kT_k\big(F(x_k^*)-F^*\big)+\frac{\gamma_kT_k\rho_k}{2}\|[c(x_k^*)]_+\|^2\nn\\
&\overset{\eqref{opt-gap}}{\geq}\cL_k\big(F_{\rho_k}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_k}(\tilde x_{k})-F_{\rho_{k}}^*\big)-\gamma_kT_k \Lambda \|[c(x_k^*)]_+\|+\frac{\gamma_kT_k\rho_k}{2}\|[c(x_k^*)]_+\|^2\nn\\
&\geq\cL_k\big(F_{\rho_k}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_k}(\tilde x_{k})-F_{\rho_{k}}^*\big)- \frac{\gamma_kT_k\Lambda^2}{2\rho_k} \ (\text{due to Young's inequality}) \nn\\
&\overset{\eqref{def-Frho2}}{=}\cL_k\big(F_{\rho_{k+1}}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*\big)- \frac{\gamma_kT_k\Lambda^2}{2\rho_k}-\frac{\cL_k(\rho_{k+1}-\rho_{k})}{2}\|[c(\tilde x_{k+1})]_+\|^2\nn\\
&\overset{\eqref{feasibility}}{\geq}\cL_k\big(F_{\rho_{k+1}}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*\big)- \frac{\gamma_kT_k\Lambda^2}{2\rho_k}\nn\\
&\quad\,\,-\frac{\cL_k(\rho_{k+1}-\rho_{k})}{2}\left(\frac{2\Lambda}{\rho_{k+1}}+\sqrt{\frac{2(F_{\rho_{k+1}}(\tilde x_{k+1})-F_{\rho_{k+1}}^*)}{\rho_{k+1}}}\,\right)^2\nn\\
&\geq \cL_k\Big(1-\frac{2(\rho_{k+1}-\rho_{k})}{\rho_{k+1}}\Big)\big(F_{\rho_{k+1}}(\tilde x_{k+1})-F_{\rho_{k+1}}^*\big)-\mathcal{R}_k\big(F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*\big)- \frac{\gamma_kT_k\Lambda^2}{2\rho_k}\nn\\
&\quad-\frac{4\cL_k(\rho_{k+1}-\rho_{k})\Lambda^2}{\rho_{k+1}^2}, \label{lem8-ineq1}
\end{align}
where the last inequality is due to $(a+b)^2 \leq 2(a^2+b^2)$ for all $a,b\in\rr$.
It then follows from \eqref{lkrk}, \eqref{lem8-ineq1}, and $F_{\rho_{i+1}}(\tilde x_{i+1})\geq F_{\rho_{i+1}}^*$ that for all $i\geq 1$, 
\begin{align}
&\mathcal{R}_{i+1}(F_{\rho_{i+1}}(\tilde x_{i+1})-F_{\rho_{i+1}}^*)
\overset{\eqref{lkrk}}{\leq}\cL_i\Big(1-\frac{2(\rho_{i+1}-\rho_{i})}{\rho_{i+1}}\Big)(F_{\rho_{i+1}}(\tilde x_{i+1})-F_{\rho_{i+1}}^*)\nn\\
&\overset{\eqref{lem8-ineq1}}{\leq} \mathcal{R}_i(F_{\rho_i}(\tilde x_{i})-F_{\rho_{i}}^*)
    +\frac{1}{2}\big(\|\tilde z_{i}-x^*\|^2-\|\tilde z_{i+1}-x^*\|^2\big)+2\gamma_iT_i L_{\nabla \barf}D_\cX^2+\frac{\gamma_iT_i\Lambda^2}{2\rho_i}+\frac{4\cL_i(\rho_{i+1}-\rho_{i})\Lambda^2}{\rho_{i+1}^2}.\label{l8-3}
\end{align}  
By \eqref{def-para3},  \eqref{rho1}, \eqref{rho2}, \eqref{notation}, and \eqref{Lk}, one can verify that $\mathcal{R}_1=7/(288L_{\rho_1})<1/(40L_{\rho_1})$. Summing up \eqref{l8-3} from $i=1$ to $k-1$, and using Assumption \ref{a1}(i), $\tilde x_1=\tilde z_1=x^0$, and $\mathcal{R}_1<1/(40L_{\rho_1})$, we have
\begin{align*}
\mathcal{R}_{k}(F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*)
&\leq \frac{1}{40L_{\rho_1}}(F_{\rho_1}(x^0)-F_{\rho_{1}}^*)+\frac{1}{2}\|x^0-x^*\|^2+2L_{\nabla \barf}D_\cX^2\sum_{i=1}^{k-1}\gamma_i T_i \nn\\
&\quad+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_iT_i}{\rho_i}+4\Lambda^2\sum_{i=1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2}.
\end{align*}
The conclusion \eqref{l8-bound} then follows from this and the fact that  
\[
F_{\rho_1}(x^0)-F_{\rho_{1}}^*\overset{\eqref{def-Frho2}}{\leq} F(x^0)-F(x^*_1)+\frac{\rho_1}{2}\|[c(x^0)]_+\|^2 \leq D_F+\frac{\rho_1}{2}\|[c(x^0)]_+\|^2,
\]
where the last inequality is due to Assumption \ref{a1}(i). In addition, the proof of \eqref{expbound} follows from \eqref{l7-exp} and similar arguments as above, and is thus omitted.
\end{proof}

We are now ready to prove Theorem \ref{thm:finite-sum}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:finite-sum}}]
Using  \eqref{opt-gap} and \eqref{feasibility} with $\rho=\rho_k$ and $x=\tilde x_k$, we have
\begin{align}
\|[c(\tilde x_k)]_+
\| &\overset{\eqref{feasibility}}{\leq} 
\frac{2\Lambda}{\rho_{k}}+\sqrt{\frac{2(F_{\rho_{k}}(\tilde x_k)-F_{\rho_{k}}^*)}{\rho_{k}}},\label{t2-cons}\\
\bbE[\|[c(\tilde x_k)]_+\|] &  \overset{\eqref{t2-cons}}{\leq} 
\frac{2\Lambda}{\rho_{k}}+\bbE\left[\sqrt{\frac{2(F_{\rho_{k}}(\tilde x_k)-F_{\rho_{k}}^*)}{\rho_{k}}}\,\right] \leq \frac{2\Lambda}{\rho_{k}}+\sqrt{\frac{2\bbE\left[F_{\rho_{k}}(\tilde x_k)-F_{\rho_{k}}^*\right]}{\rho_{k}}}.\label{t2-obj}
\end{align}
Also, notice from \eqref{def-para3} that $\alpha_k+p_k \leq 1$. Moreover, as shown in the proof of Lemma \ref{LkRk}, the sequence $\{\rho_k\}$ defined in \eqref{rho1} or \eqref{rho2} is nondecreasing.

We first prove statement (i) of Theorem \ref{thm:finite-sum}, where $k_0$, $\{T_k\}$,  and $\{\rho_k\}$ are chosen as in \eqref{rho1}. Notice from \eqref{def-para3} and \eqref{rho1} that $k_0=\lfloor (4/3)\log_2 s\rfloor+1$, 
$\alpha_k=6/7$, $p_k=1/7$,  $T_k=\lceil2^{3(k-1)/4}\rceil$, $\rho_k=2^{k/2}$, and $\gamma_k=1/(8(L_{\nabla \barf}+2^{k/2}L_{\nabla c^2})$  for all $1\leq k\leq k_0$.  Using these relations and \eqref{Lk}, we obtain that 
\begin{align}
  & \cL_k\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}=\frac{T_k\gamma_k}{\alpha_k}=\frac{49\times\lceil2^{3(k-1)/4}\rceil}{288(L_{\nabla \barf}+2^{k/2}L_{\nabla c^2})}\leq\frac{49\times2^{k/4}}{288L_{\nabla c^2}} \qquad \forall 1\leq k\leq k_0, \label{libound} \\
& s/2\leq T_{k_0}=\lceil2^{3(k_0-1)/4}\rceil=\lceil2^{3\lfloor (4/3)\log_2 s\rfloor/4}\rceil\leq s, \quad 
2^{k_0/4}=2^{(\lfloor (4/3)\log_2 s\rfloor+1)/4}\leq2^{1/4}s^{1/3}. \label{Tk0-bnd}
\end{align}
By \eqref{def-para3}, \eqref{rho1},  \eqref{Lk}, \eqref{Tk0-bnd}, and $\alpha_k+p_k \leq 1$, one has that for all $k> k_0$, 
\begin{align}
&\mathcal{R}_k\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}(1-\alpha_k)+(T_k-1)\frac{\gamma_kp_k}{\alpha_k}\geq\frac{\gamma_kp_kT_k}{\alpha_k}\overset{\eqref{def-para3}\eqref{rho1}}{=}\frac{T_{k_0}(k-k_0+7)^2}{2016(L_{\nabla \barf}+(3s^{2/3}(k-k_0+7)^{4/3}/32)L_{\nabla c^2})} \nn \\
&\quad \ \, \overset{\eqref{Tk0-bnd}}{\geq}\frac{s(k-k_0+7)^2}{4032(L_{\nabla \barf}+(3s^{2/3}(k-k_0+7)^{4/3}/32)L_{\nabla c^2})}, \label{Rk-lowbnd} \\
& \cL_k\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}\leq\frac{\gamma_kT_k}{\alpha_k} \overset{\eqref{def-para3}\eqref{rho1}}{=}\frac{T_{k_0}(k-k_0+7)^2}{288(L_{\nabla \barf}+(3s^{2/3}(k-k_0+7)^{4/3}/32)L_{\nabla c^2})} \nn \\
&\quad \ \, \overset{\eqref{Tk0-bnd}}{\leq}\frac{s(k-k_0+7)^2}{288(L_{\nabla \barf}+(3s^{2/3}(k-k_0+7)^{4/3}/32)L_{\nabla c^2})}  \leq\frac{s^{1/3}(k-k_0+7)^{2/3}}{27L_{\nabla c^2}}. \label{sub-ineq2}
\end{align}
In addition, observe that $\lceil2^{3(k-1)/4}\rceil\leq2^{3k/4}$ for all $k\geq 1$. Using this relation, $s\geq1$, \eqref{def-para3},  \eqref{rho1}, and \eqref{Tk0-bnd}, we obtain that for all $k\geq 1$, 
\begin{align}
&\sum_{i=1}^{k-1}\gamma_i T_i=\sum_{i=1}^{k_0}\gamma_i T_i+\sum_{i=k_0+1}^{k-1}\gamma_i T_i
\overset{\eqref{def-para3}\eqref{rho1}}{=}\sum_{i=1}^{k_0}\frac{7T_i}{48(L_{\nabla \barf}+\rho_i L_{\nabla c^2})}+\sum_{i=k_0+1}^{k-1}\frac{T_{k_0}}{8(L_{\nabla \barf}+\rho_i L_{\nabla c^2})\alpha_i} \nn\\
&\qquad\quad \overset{\eqref{Tk0-bnd}}{\leq}\frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{T_i}{\rho_i}+\frac{s}{8L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}\frac{1}{\rho_i\alpha_i} \nn \\
&\qquad\quad\overset{\eqref{def-para3}\eqref{rho1}}{=} \frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{\lceil2^{3(i-1)/4}\rceil}{2^{i/2}}+\frac{2s^{1/3}}{9L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}(i-k_0+7)^{-1/3}  \nn \\ 
&\qquad\quad\ \    \leq\frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{2^{3i/4}}{2^{i/2}}+\frac{2s^{1/3}}{9L_{\nabla c^2}}  \int_{k_0+1}^k (\tau-k_0+6)^{-1/3} d\tau \nn\\
&\qquad\quad\ \ \leq\frac{7\times 2^{k_0/4}}{48(1-2^{-1/4})L_{\nabla c^2}}+\frac{s^{1/3}(k-k_0+7)^{2/3}}{3L_{\nabla c^2}} 
  \overset{\eqref{Tk0-bnd}}{\leq} \frac{11s^{1/3}}{10L_{\nabla c^2}}+\frac{s^{1/3}(k-k_0+7)^{2/3}}{3L_{\nabla c^2}}, 
 \label{sum-gt}\\
&\sum_{i=1}^{k-1}\frac{\gamma_iT_i}{\rho_i}=\sum_{i=1}^{k_0}\frac{\gamma_iT_i}{\rho_i}+\sum_{i=k_0+1}^{k-1}\frac{\gamma_iT_i}{\rho_i}
\overset{\eqref{def-para3}\eqref{rho1}}{=}\sum_{i=1}^{k_0}\frac{7T_i}{48(L_{\nabla \barf}+\rho_i L_{\nabla c^2})\rho_i}+\sum_{i=k_0+1}^{k-1}\frac{T_{k_0}}{8(L_{\nabla \barf}+\rho_i L_{\nabla c^2})\rho_i\alpha_i} \nn\\
&\qquad\quad  \overset{\eqref{Tk0-bnd}}{\leq}\frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{T_i}{\rho_i^2}+\frac{s}{8L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}\frac{1}{\rho_i^2\alpha_i} \nn\\
&\qquad\quad \overset{\eqref{def-para3}\eqref{rho1}}{=}\frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{\lceil2^{3(i-1)/4}\rceil}{2^{i}}+ \frac{64s^{-1/3}}{27L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}(i-k_0+7)^{-5/3}\nn \\
&\qquad\quad  \leq \frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{2^{3i/4}}{2^{i}}+\frac{64s^{-1/3}}{27L_{\nabla c^2}} \int^k_{k_0+1} (\tau-k_0+6)^{-5/3}d\tau \nn \\
&\qquad\quad \leq \frac{7}{48(2^{1/4}-1)L_{\nabla c^2}}+\frac{32}{27L_{\nabla c^2}} 
 \leq\frac{2}{L_{\nabla c^2}}.  \label{sum-gtr}
 \end{align}
Observe from \eqref{rho1} that $2^{k_0/2}=2^{(\lfloor(4/3)\log_2s\rfloor+1)/2}\geq s^{2/3}$. 
By this, \eqref{rho1},  and the convexity of the functions $2^{\tau/2}$ and $\tau^{4/3}$, one has
\begin{align} \label{rho-diff}
    \rho_{i+1}-\rho_i=\left\{\begin{array}{ll}
       2^{(i+1)/2}-2^{i/2}\leq (2^{(i+1)/2}\log2)/2=(\rho_{i+1}\log2)/2  & \text{if} \  \ 1\leq i< k_0, \\
       3s^{2/3}/2-2^{k_0/2}\leq s^{2/3}/2=\rho_{i+1}/3\leq(\rho_{i+1}\log2)/2 & \text{if} \  \  i= k_0,\\
       3s^{2/3}((i-k_0+8)^{4/3}-(i-k_0+7)^{4/3})/32 \leq s^{2/3}(i-k_0+8)^{1/3}/8  & \text{if} \  \ i> k_0.
       \end{array}\right. 
\end{align}
Using \eqref{rho1}, \eqref{libound}, \eqref{sub-ineq2}, \eqref{rho-diff}, $s\geq1$, and $\rho_{i+1} \geq \rho_i$, we obtain that 
\begin{align}
& \sum_{i=1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2} =\sum_{i=1}^{k_0}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2}+\sum_{i=k_0+1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2} \nn \\
&\overset{\eqref{rho-diff}}{\leq}\sum_{i=1}^{k_0}\frac{\cL_i\log2}{2\rho_{i+1}}+\sum_{i=k_0+1}^{k-1}\frac{s^{2/3}\cL_i(i-k_0+8)^{1/3}}{8\rho_{i+1}^2}\nn\\
& \leq\sum_{i=1}^{k_0}\frac{\cL_i\log2}{2\rho_{i}}+\sum_{i=k_0+1}^{k-1}\frac{s^{2/3}\cL_i(i-k_0+8)^{1/3}}{8\rho_{i+1}^2} \  \  \ (\text{due to} \ \rho_{i+1} \geq \rho_i) \nn\\
&\leq \frac{49\log2}{576L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{2^{i/4}}{2^{i/2}}+ \frac{128s^{-1/3}}{243L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}\frac{(i-k_0+7)^{2/3}(i-k_0+8)^{1/3}}{(i-k_0+8)^{8/3}} \  \  \  (\text{due to} \  \eqref{rho1}, \eqref{libound}, \eqref{sub-ineq2}) \nn \\
& \leq \frac{49\log2}{576(2^{1/4}-1)L_{\nabla c^2}}+ \frac{128}{243L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}(i-k_0+8)^{-5/3}
\leq\frac{49\log2}{576(2^{1/4}-1)L_{\nabla c^2}}+\frac{16}{81L_{\nabla c^2}}\leq\frac{1}{L_{\nabla c^2}}. \nn
\end{align}
It follows from this, \eqref{c3-5}, \eqref{notation}, \eqref{l8-bound}, \eqref{Rk-lowbnd}, \eqref{sum-gt}, \eqref{sum-gtr}, $\rho_1=\sqrt{2}$, and $s\geq 1$ that for all $k>k_0$, 
\begin{align}
&F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*\overset{\eqref{l8-bound}}{\leq} \mathcal{R}_{k}^{-1}\Big(\frac{D_F+\rho_1\|[c(x^0)]_+\|^2/2}{40L_{\rho_1}}+\frac{D_\cX^2}{2}+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_iT_i}{\rho_i} +4\Lambda^2\sum_{i=1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2} \nn \\
&\qquad\qquad\qquad\qquad\qquad\, +2L_{\nabla \barf}D_\cX^2\sum_{i=1}^{k-1}\gamma_i T_i\Big)\nn\\
&\leq \frac{4032L_{\nabla \barf}+378L_{\nabla c^2}s^{2/3}(k-k_0+7)^{4/3}}{s(k-k_0+7)^2}\Big(\frac{D_F+\sqrt{2}\|[c(x^0)]_+\|^2/2}{40(L_{\nabla \barf}+\sqrt{2}L_{\nabla c^2})}+\frac{D_\cX^2}{2}+\frac{\Lambda^2}{L_{\nabla c^2}}\nn\\
&\quad +\frac{4\Lambda^2}{L_{\nabla c^2}}+\frac{11L_{\nabla \barf}D_\cX^2s^{1/3}}{5L_{\nabla c^2}}+\frac{2L_{\nabla \barf}D_\cX^2s^{1/3}(k-k_0+7)^{2/3}}{3L_{\nabla c^2}}\Big)\nn\\
&\overset{\eqref{c3-5}}{\leq}\frac{\tC_5s^{-1}+\tC_7s^{-2/3}}{(k-k_0+7)^{2}}+\frac{\tC_6s^{-1/3}+\tC_8}{(k-k_0+7)^{2/3}}+\frac{\tC_9s^{-2/3}}{(k-k_0+7)^{4/3}}+252L_{\nabla \barf}D_\cX^2\nn\\
&{\leq}\frac{(\tC_5+\tC_7)s^{-2/3}}{(k-k_0+7)^{2}}+\frac{\tC_6+\tC_8}{(k-k_0+7)^{2/3}}+\frac{\tC_9s^{-2/3}}{(k-k_0+7)^{4/3}}+252L_{\nabla \barf}D_\cX^2,\label{t2-bound3}
\end{align}
where $\tC_5$, $\tC_6$, $\tC_7$, $\tC_8$, and $\tC_9$ are given in \eqref{c3-5}. Similarly, by \eqref{c3-5} and \eqref{expbound}, one has
\beq\label{t2-bound4}
\bbE[F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*]\leq\frac{\tC_5s^{-1}}{(k-k_0+7)^{2}}+\frac{\tC_6s^{-1/3}}{(k-k_0+7)^{2/3}}.
\eeq
Further, using \eqref{expbound}, \eqref{t2-cons}, \eqref{t2-obj},  and \eqref{t2-bound3}, we obtain that
\begin{align*}
\|[c(\tilde x_k)]_+\| & \overset{\eqref{t2-cons}\eqref{t2-bound3}}{\leq} \frac{2\Lambda}{\rho_k}+\sqrt{\frac{2(\tC_5+\tC_7)s^{-2/3}}{(k-k_0+7)^{2}\rho_k}+\frac{2(\tC_6+\tC_8)}{(k-k_0+7)^{2/3}\rho_k}+\frac{2\tC_9s^{-2/3}}{(k-k_0+7)^{4/3}\rho_k}+\frac{504L_{\nabla \barf}D_{\cX}^2}{\rho_k}}\nn\\
&\ \  \leq\frac{2\Lambda}{\rho_k}+\sqrt{\frac{2(\tC_5+\tC_7)s^{-2/3}}{(k-k_0+7)^{2}\rho_k}}+\sqrt{\frac{2(\tC_6+\tC_8)}{(k-k_0+7)^{2/3}\rho_k}}+\sqrt{\frac{2\tC_9s^{-2/3}}{(k-k_0+7)^{4/3}\rho_k}}+\sqrt{\frac{504L_{\nabla \barf}D_{\cX}^2}{\rho_k}}, \\
    \bbE[\|[c(\tilde x_k)]_+\|] & \overset{\eqref{t2-obj}\eqref{t2-bound4}} \leq\frac{2\Lambda}{\rho_k}+\sqrt{\frac{2\tC_5s^{-1}}{(k-k_0+7)^{2}\rho_k}+\frac{2\tC_6s^{-1/3}}{(k-k_0+7)^{2/3}\rho_k}} \\
    &\quad  \leq \frac{2\Lambda}{\rho_k}+\sqrt{\frac{2\tC_5s^{-1}}{(k-k_0+7)^{2}\rho_k}}+\sqrt{\frac{2\tC_6s^{-1/3}}{(k-k_0+7)^{2/3}\rho_k}},
\end{align*}
which, togther with $k\geq2(k_0-7)$, $\rho_k=3s^{2/3}(k-k_0+7)^{4/3}/32$ and $\bbE [F(\tilde x_k)-F^*] \geq -\Lambda\,\bbE[\|[c(\tilde x_k)]_+\|]$ due to \eqref{opt-gap}, implies that \eqref{thm3-ineq1}, \eqref{thm3-ineq1-exp}, and \eqref{thm3-ineq3} hold. In addition,  \eqref{thm3-ineq2} follows from $k\geq2(k_0-7)$, \eqref{opt-gap}, and \eqref{t2-bound4}.

We next prove statement (ii) of Theorem \ref{thm:finite-sum}, where $k_0$, $\{T_k\}$,  and $\{\rho_k\}$ are chosen as in \eqref{rho2}.  Notice from \eqref{def-para3} and \eqref{rho2} that $k_0=\lfloor \log_2 s\rfloor+1$, 
$\alpha_k=6/7$, $p_k=1/7$,  $T_k=2^{k-1}$, $\rho_k=2^{k/2}$, and $\gamma_k=1/(8(L_{\nabla \barf}+2^{k/2}L_{\nabla c^2})$  for all $1\leq k\leq k_0$.  Using these relations and \eqref{Lk}, we obtain that 
\begin{align}
  & \cL_k\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}=\frac{T_k\gamma_k}{\alpha_k}=\frac{49\times2^{k-1}}{288(L_{\nabla \barf}+2^{k/2}L_{\nabla c^2})}\leq\frac{49\times2^{k/2}}{576L_{\nabla c^2}} \qquad \forall 1\leq k\leq k_0, \label{libound-1} \\
& s/2\leq T_{k_0}=2^{k_0-1}=2^{\lfloor \log_2 s\rfloor}\leq s, \quad 2^{k_0/2}=2^{(\lfloor \log_2 s\rfloor+1)/2}\leq\sqrt{2s}. \label{Tk0-bnd-1}
\end{align}
By \eqref{def-para3}, \eqref{rho2},  \eqref{Lk}, \eqref{Tk0-bnd-1}, and $\alpha_k+p_k \leq 1$, one has that for all $k> k_0$, 
\begin{align}
&\mathcal{R}_k\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}(1-\alpha_k)+(T_k-1)\frac{\gamma_kp_k}{\alpha_k}\geq\frac{\gamma_kp_kT_k}{\alpha_k}\overset{\eqref{def-para3}\eqref{rho2}}{=}\frac{T_{k_0}(k-k_0+7)^2}{2016(L_{\nabla \barf}+(3\sqrt{s}(k-k_0+7)/16)L_{\nabla c^2})} \nn \\
&\quad \ \, \overset{\eqref{Tk0-bnd-1}}{\geq}\frac{s(k-k_0+7)^2}{4032(L_{\nabla \barf}+(3\sqrt{s}(k-k_0+7)/16)L_{\nabla c^2})}, \label{Rk-lowbnd-1} \\
& \cL_k\overset{\eqref{Lk}}{=}\frac{\gamma_k}{\alpha_k}+(T_k-1)\frac{\gamma_k(\alpha_k+p_k)}{\alpha_k}\leq\frac{\gamma_kT_k}{\alpha_k}\overset{\eqref{def-para3}\eqref{rho2}}{\leq}\frac{s(k-k_0+7)^2}{288(L_{\nabla \barf}+(3\sqrt{s}(k-k_0+7)/16)L_{\nabla c^2})} \nn\\
&\quad \ \,   \overset{\eqref{Tk0-bnd-1}}{\leq}\frac{\sqrt{s}(k-k_0+7)}{54L_{\nabla c^2}}. \label{sub-ineq3}
\end{align}
Using \eqref{def-para3},  \eqref{rho2}, and \eqref{Tk0-bnd-1}, we obtain that for all $k\geq 1$, 
\begin{align}
&\sum_{i=1}^{k-1}\gamma_i T_i=\sum_{i=1}^{k_0}\gamma_i T_i+\sum_{i=k_0+1}^{k-1}\gamma_i T_i
\overset{\eqref{def-para3}\eqref{rho2}}{=}\sum_{i=1}^{k_0}\frac{7T_i}{48(L_{\nabla \barf}+\rho_i L_{\nabla c^2})}+\sum_{i=k_0+1}^{k-1}\frac{T_{k_0}}{8(L_{\nabla \barf}+\rho_i L_{\nabla c^2})\alpha_i} \nn\\
&\qquad\quad\ \ \overset{\eqref{Tk0-bnd-1}}{\leq}\frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{T_i}{\rho_i}+\frac{s}{8L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}\frac{1}{\rho_i\alpha_i}
\overset{\eqref{def-para3}\eqref{rho2}}{=} \frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{2^{i-1}}{2^{i/2}}+\frac{\sqrt{s}}{9L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}1  \nn \\ 
&\qquad\quad\ \    \leq\frac{7\times 2^{k_0/2}}{48(2-\sqrt{2})L_{\nabla c^2}}+\frac{\sqrt{s}(k-k_0-1)}{9L_{\nabla c^2}}   
  \overset{\eqref{Tk0-bnd-1}}{\leq}\frac{7\sqrt{s}}{48(\sqrt{2}-1)L_{\nabla c^2}}+\frac{\sqrt{s}(k-k_0+7)}{9L_{\nabla c^2}}, \label{sum-gt-1} \\
&\sum_{i=1}^{k-1}\frac{\gamma_iT_i}{\rho_i}=\sum_{i=1}^{k_0}\frac{\gamma_iT_i}{\rho_i}+\sum_{i=k_0+1}^{k-1}\frac{\gamma_iT_i}{\rho_i}
\overset{\eqref{def-para3}\eqref{rho2}}{=}\sum_{i=1}^{k_0}\frac{7T_i}{48(L_{\nabla \barf}+\rho_i L_{\nabla c^2})\rho_i}+\sum_{i=k_0+1}^{k-1}\frac{T_{k_0}}{8(L_{\nabla \barf}+\rho_i L_{\nabla c^2})\rho_i\alpha_i} \nn\\
&\qquad\qquad \overset{\eqref{Tk0-bnd-1}}{\leq}\frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{T_i}{\rho_i^2}+\frac{s}{8L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}\frac{1}{\rho_i^2\alpha_i} 
\overset{\eqref{def-para3}\eqref{rho2}}{=}\frac{7}{48L_{\nabla c^2}}\sum_{i=1}^{k_0}\frac{2^{i-1}}{2^{i}}+ \frac{16}{27L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}(i-k_0+7)^{-1}\nn \\
&\qquad\qquad  \leq \frac{7k_0}{96L_{\nabla c^2}}+\frac{16}{27L_{\nabla c^2}} \int^k_{1} \tau^{-1}d\tau
\leq\frac{k_0}{12L_{\nabla c^2}}+\frac{3\log k}{5L_{\nabla c^2}}. \label{sum-gtr-1} 
\end{align}
Observe from \eqref{rho2} that $2^{k_0/2}=2^{(\lfloor\log_2s\rfloor+1)/2}\geq \sqrt{s}$. 
By this, \eqref{rho2},  and the convexity of the function $2^{\tau/2}$, one has
\begin{align} \label{rho-diff-1}
    \rho_{i+1}-\rho_i=\left\{\begin{array}{ll}
       2^{(i+1)/2}-2^{i/2}\leq (2^{(i+1)/2}\log2)/2\leq(\rho_{i+1}\log2)/2  & \text{if} \  \ 1\leq i< k_0, \\
       3\sqrt{s}/2-2^{k_0/2}\leq\sqrt{s}/2=\rho_{i+1}/3\leq(\rho_{i+1}\log2)/2 & \text{if} \  \  i= k_0,\\
       3\sqrt{s}((i-k_0+8)-(i-k_0+7))/16 = 3\sqrt{s}/16  & \text{if} \  \ i> k_0.
       \end{array}\right. 
\end{align}
Using \eqref{rho2}, \eqref{libound-1}, \eqref{sub-ineq3},  \eqref{rho-diff-1}, and $\rho_{i+1} \geq \rho_i$, we obtain that 
\begin{align}
&\sum_{i=1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2}=\sum_{i=1}^{k_0}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2}+\sum_{i=k_0+1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2}
\overset{\eqref{rho-diff-1}}{\leq}\sum_{i=1}^{k_0}\frac{\cL_i\log2}{2\rho_{i+1}}+\sum_{i=k_0+1}^{k-1}\frac{3\sqrt{s}\cL_i}{16\rho_{i+1}^2}\nn\\
&\qquad\qquad\qquad\quad\ \leq\sum_{i=1}^{k_0}\frac{\cL_i\log2}{2\rho_{i}}+\sum_{i=k_0+1}^{k-1}\frac{3\sqrt{s}\cL_i}{16\rho_{i+1}^2} \  \  \ (\text{due to} \ \rho_{i+1} \geq \rho_i) \nn\\
&\qquad\qquad\qquad\quad\
\leq \frac{49\log2}{1152L_{\nabla c^2}}\sum_{i=1}^{k_0}1 +\frac{8}{81L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}\frac{i-k_0+7}{(i-k_0+8)^{2}}\  \  \  (\text{due to} \  \eqref{rho2}, \eqref{libound-1}, \eqref{sub-ineq3}) \nn \\
&\qquad\qquad\qquad\quad\ \leq \frac{49k_0\log2}{1152L_{\nabla c^2}}+ \frac{8}{81L_{\nabla c^2}}\sum_{i=k_0+1}^{k-1}{(i-k_0+7)^{-1}}
\leq\frac{k_0}{24L_{\nabla c^2}}+\frac{\log k}{10L_{\nabla c^2}}. \nn
\end{align}
It follows from this, \eqref{c6-9}, \eqref{notation}, \eqref{l8-bound}, \eqref{Rk-lowbnd-1}, \eqref{sum-gt-1}, \eqref{sum-gtr-1}, $\rho_1=\sqrt{2}$, and $s\geq1$ that for all $k>k_0$, 
\begin{align}
& F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*\overset{\eqref{l8-bound}}{\leq} \mathcal{R}_{k}^{-1}\Big(\frac{D_F+\rho_1\|[c(x^0)]_+\|^2/2}{40L_{\rho_1}}+\frac{D_\cX^2}{2}+\frac{\Lambda^2}{2}\sum_{i=1}^{k-1}\frac{\gamma_iT_i}{\rho_i} +4\Lambda^2\sum_{i=1}^{k-1}\frac{\cL_i(\rho_{i+1}-\rho_{i})}{\rho_{i+1}^2} \nn \\ 
&\qquad\qquad\qquad\qquad\qquad\,+2L_{\nabla \barf}D_\cX^2\sum_{i=1}^{k-1}\gamma_i T_i\Big)\nn\\
&\leq \frac{4032L_{\nabla \barf}+756\sqrt{s}(k-k_0+7)L_{\nabla c^2}}{s(k-k_0+7)^2}\Big(\frac{D_F+\sqrt{2}\|[c(x^0)]_+\|^2/2}{40(L_{\nabla \barf}+\sqrt{2}L_{\nabla c^2})}+\frac{D_\cX^2}{2}+\frac{\Lambda^2k_0}{24L_{\nabla c^2}}\nn\\
&\quad
+\frac{3\Lambda^2\log k}{10L_{\nabla c^2}}+\frac{\Lambda^2k_0}{6L_{\nabla c^2}}+\frac{2\Lambda^2\log k}{5L_{\nabla c^2}}+\frac{7L_{\nabla \barf}D_\cX^2\sqrt{s}}{24(\sqrt{2}-1)L_{\nabla c^2}}+\frac{2L_{\nabla \barf}D_\cX^2\sqrt{s}(k-k_0+7)}{9L_{\nabla c^2}}\Big)\nn\\
&\overset{ \eqref{c6-9}}{\leq} \frac{\tC_{10}s^{-1}+\tC_{13}s^{-1/2}}{(k-k_0+7)^2}+\frac{\tC_{11}s^{-1/2}+\tC_{14}+\tC_{15}s^{-1/2}}{k-k_0+7}+\frac{\tC_{12}s^{-1}\log k}{(k-k_0+7)^2}+\frac{523\Lambda^2s^{-1/2}\log k}{k-k_0+7}\nn\\
&\quad+168L_{\nabla \barf}D_\cX^2
\nn\\
&\leq \frac{(\tC_{10}+\tC_{13})s^{-1/2}}{(k-k_0+7)^2}+\frac{\tC_{11}+\tC_{14}+\tC_{15}}{k-k_0+7}+\frac{\tC_{12}s^{-1}\log k}{(k-k_0+7)^2}+\frac{523\Lambda^2s^{-1/2}\log k}{k-k_0+7}\nn\\
&\quad+168L_{\nabla \barf}D_\cX^2,\label{t2-bound4.5}
\end{align}
where $\tC_{10}$, $\tC_{11}$, $\tC_{12}$, $\tC_{13}$, $\tC_{14}$, and $\tC_{15}$ are given in \eqref{c6-9}. Similarly, by \eqref{c6-9} and \eqref{expbound}, one has
\beq\label{t2-bound5}
\bbE[F_{\rho_{k}}(\tilde x_{k})-F_{\rho_{k}}^*]\leq \frac{\tC_{10}s^{-1}}{(k-k_0+7)^2}+\frac{\tC_{11}s^{-1/2}}{k-k_0+7}+\frac{\tC_{12}s^{-1}\log k}{(k-k_0+7)^2}+\frac{523\Lambda^2s^{-1/2}\log k}{k-k_0+7}. 
\eeq
 Using \eqref{t2-cons}, \eqref{t2-obj}, \eqref{t2-bound4.5}, and \eqref{t2-bound5}, we have
\begin{align*}
&\|[c(\tilde x_k)]_+\| \overset{\eqref{t2-cons}\eqref{t2-bound4.5}}{\leq} \frac{2\Lambda}{\rho_k}+\sqrt{\frac{2(\tC_{10}+\tC_{13})s^{-1/2}}{(k-k_0+7)^{2}\rho_k}}+\sqrt{\frac{2(\tC_{11}+\tC_{14}+\tC_{15})}{(k-k_0+7)\rho_k}} \nn \\ 
& \qquad\qquad\qquad\quad\ +\sqrt{\frac{2\tC_{12}s^{-1}\log k}{(k-k_0+7)^2\rho_k}}+\sqrt{\frac{1046\Lambda^2s^{-1/2}\log k}{(k-k_0+7)\rho_k}} +\sqrt{\frac{336L_{\nabla \barf}D_{\cX}^2}{\rho_k}}, \\
&\bbE[\|[c(\tilde x_k)]_+\|]\overset{\eqref{t2-obj}\eqref{t2-bound5}}{\leq} \frac{2\Lambda}{\rho_k}+\sqrt{\frac{2\tC_{10}s^{-1}}{(k-k_0+7)^2\rho_k}}+\sqrt{\frac{2\tC_{11}s^{-1/2}}{(k-k_0+7)\rho_k}}+\sqrt{\frac{2\tC_{12}s^{-1}\log k}{(k-k_0+7)^2\rho_k}}\\
&\qquad\qquad\qquad\qquad\ +\sqrt{\frac{1046\Lambda^2s^{-1/2}\log k}{(k-k_0+7)\rho_k}}, 
\end{align*}
which, together with \eqref{opt-gap}, $\rho_k=3\sqrt{s}(k-k_0+7)/16$, and the relation $k-k_0+7\geq k/2$ for all $k\geq \max\{k_0+1,2(k_0-7)\}$,  imply that \eqref{thm3-ineq4-1}, \eqref{thm3-ineq4}, and \eqref{thm3-ineq6} hold. In addition, \eqref{thm3-ineq5} follows from $k \geq 2(k_0-7)$, \eqref{opt-gap}, and \eqref{t2-bound5}. 
\end{proof}

\section{Concluding remarks}\label{sec:conclude}

In this paper, we proposed first-order methods for computing an $\epsilon$-\emph{surely feasible} stochastic optimal ($\epsilon$-SFSO) solution for both stochastic and finite-sum convex optimization problems with deterministic constraints, and established first-order oracle (FO) complexity results for these methods. As a byproduct, we also derived FO complexity results for the sample average approximation (SAA) method in computing an $\epsilon$-SFSO solution of the stochastic optimization problem, using the proposed stochastic first-order method (Algorithm~\ref{alg2}) to solve the sample average problem.

Although we focused on problem \eqref{prob1} with convex inequality constraints, our algorithms and results can be directly extended to problems that include both affine equality constraints and convex inequality constraints. Furthermore, they can also be extended to problems with convex conic constraints of the form $c(x) \in -\mathcal{K}$, where $\mathcal{K}$ is a closed convex cone whose projection operator can be evaluated exactly, and $c$ is both Lipschitz smooth and $\mathcal{K}$-convex; that is, $\alpha c(x) + (1-\alpha) c(y) - c(\alpha x + (1 - \alpha) y) \in \mathcal{K}$ for all $x, y \in \mathbb{R}^n$ and $\alpha \in [0,1]$.

 An interesting direction for future research is to develop a stochastic first-order method for solving finite-sum convex optimization problems with deterministic constraints that achieves an FO complexity of $\mathcal{O}(s \log s + \sqrt{s} \epsilon^{-1})$ for computing an $\epsilon$-SFSO solution. This would significantly improve upon the current complexity of $\mathcal{O}(s \log s + \sqrt{s} \epsilon^{-3/2})$ achieved by our proposed method, and would match the optimal complexity known for computing an $\epsilon$-\emph{expectedly feasible} stochastic optimal solution.

