\title{Reasoning in Neurosymbolic AI}

\author[1]{Son Tran}
\author[2]{Edjard Mota}
\author[1]{Artur d'Avila Garcez}

\affil[1]{School of Information Technology, Deakin University, Victoria, 3125, Melbourne, Australia}
