In total, 
\begin{equation*}
 \delta(0)=t(2^m-1)-1.
\end{equation*}

(ii) When $3t\nmid2^m+1$, $\triangle(x)=1$ has no solution in $\mathbb{F}_{2^n}^{\sharp}$. We also obtain $\triangle(0)=1$ and $\triangle(1)=1$. So, $\delta(1)=2$.

When $3t\mid2^m+1$, $\alpha^{\frac{2^m+1}{3}}+\alpha^{\frac{2(2^m+1)}{3}}=1$. Equation $\triangle(x)=1$ has solutions only in 
\begin{equation*}
  \bigcup\limits_{0\leq j_1,j_2<t}\bigg(C_{2l+\frac{(2^m+1)j_1}{t},
  l+\frac{(2^m+1)j_2}{t}}
  \bigcup C_{l+\frac{(2^m+1)j_1}{t},
  2l+\frac{(2^m+1)j_2}{t}}\bigg)\bigcup\{0,1\},
\end{equation*}  
where $ls(2^m-1)\equiv \frac{2^n-1}{3}\,\,({\rm mod}\,\,2^n-1)$, $1\leq l<\frac{2^m+1}{t}$.
If $x\in C_{2l,l}$, then $\triangle(x)=1$ is equivalent to the system of equations
\begin{eqnarray}\label{001alpha12}
    \left \{
\begin{array}{lll}
\psi^{2l}x_1-\psi^{l} x_2=1,\\
ind_{\psi}(x_1)=ind_{\psi}(x_2)\equiv 0\,\,({\rm mod}\,\,2^m+1).\\
\end{array}\right.
\end{eqnarray}
By Lemma \ref{luo wang} (iv), we have 
\begin{equation*}
  \frac{2^n+2^{m+1}+1}{(2^m+1)^2}=1
\end{equation*}
solution to (\ref{001alpha12}). Using the same method, we can ultimately obtain $2t^2+2$ solutions for the equation $\triangle(x)=1$ in 
\begin{equation*}
  \bigcup\limits_{0\leq j_1,j_2<t}\bigg(C_{2l+\frac{(2^m+1)j_1}{t},
  l+\frac{(2^m+1)j_2}{t}}
  \bigcup C_{l+\frac{(2^m+1)j_1}{t},
  2l+\frac{(2^m+1)j_2}{t}}\bigg)\bigcup\{0,1\}.
\end{equation*}


(iii)-(iv) Note that $\triangle(x)=1+\alpha^s$ has solutions only in 
\begin{equation*}
  \bigcup\limits_{0\leq j_1,j_2<t}\bigg(C_{\frac{(2^m+1)j_1}{t},1+\frac{(2^m+1)j_2}{t}}
\bigcup C_{1+\frac{(2^m+1)j_1}{t},\frac{(2^m+1)j_2}{t}}\bigg),
\end{equation*}
and $\triangle(x)=\alpha^s+\alpha^{2s}$ has solutions only in 
\begin{equation*}
  \bigcup\limits_{0\leq j_1,j_2<t}\bigg(C_{2+\frac{(2^m+1)j_1}{t},1+\frac{(2^m+1)j_2}{t}}
\bigcup C_{1+\frac{(2^m+1)j_1}{t},2+\frac{(2^m+1)j_2}{t}}\bigg).
\end{equation*}
By Lemma \ref{luo wang}, we obtain
\begin{equation*}
 \delta(1+\alpha^s)=2t(t-1),
\end{equation*} 
and
\begin{equation*}
 \delta(\alpha^s+\alpha^{2s})
 =2t^2.
\end{equation*} 

(v) The obvious conclusion follows from (i)-(iv) and Lemma \ref{doubesame}.
\end{proof}

