\item[(iii)] if $2t\nmid3^m+1$, then $\delta(1-\alpha^{si})
    =\delta(\alpha^{si}-1)
    =t^2-t$, where $1\leq i< \frac{3^m+1}{t}$.
\item[(iv)] if $2t\mid3^m+1$, then $\delta(1-\alpha^{si})
    =\delta(\alpha^{si}-1)
    =2t^2-t$, where $1\leq i< \frac{3^m+1}{t}$ and $\alpha^{si}\neq2$.
\item[(v)] $\delta(2\alpha^{si})
    =0$ for $2t\nmid3^m+1$ and $1\leq i< \frac{3^m+1}{t}$. $\delta(2\alpha^{si})=t^2$ for $2t\mid3^m+1$, $1\leq i< \frac{3^m+1}{t}$ and $\alpha^{si}\neq2$.
\item[(vi)] if $2t\nmid3^m+1$, then $\delta(\alpha^{si}-\alpha^{sj})
    =t^2$, where $1\leq i,j<\frac{3^m+1}{t}$ and $i\neq j$.
\item[(vii)] if $2t\mid3^m+1$, then $\delta(\alpha^{si}-\alpha^{sj})
    =2t^2$, where $1\leq i,j< \frac{3^m+1}{t}$, $\alpha^{si},\alpha^{sj}\neq2$, $i\neq j$ and $\alpha^{si}-\alpha^{sj}\neq1,2$.
\item[(viii)] $\delta(b)=0$ for $b\neq\pm1, \alpha^{si}-\alpha^{sj}$, where $0\leq i,j< \frac{3^m+1}{t}$. \hfill$\square$
\end{itemize}
\end{lemma}
