\item[(ix)] $\delta(b)=0$ for $b\neq \pm1,\alpha^{si}-\alpha^{sj}$, where $0\leq i,j< \frac{p^m+1}{t}$.\hfill$\square$
\end{itemize}
\end{lemma}
