\section{Boomerang spectrum of $f(x)=x^{s(p^m-1)}$ over $\mathbb{F}_{p^n}$}\label{luo the bs}
In \cite{kpm-1}, Hu et al. determined the boomerang spectrum of $x^{s(p^m-1)}$ based on the differential spectrum of $x^{s(p^m-1)}$, where $n=2m$ and $\gcd(s,p^m+1)=1$. So what happens if $\gcd(s,p^m+1)\geq1$? Let $f(x)=x^d$, where $d=s(p^m-1)$, $n=2m$ and $\gcd(s,p^m+1)=t$. In this section,  by studying the number of rational points on some curves, and without relying on the differential spectrum of $f$, we determine the boomerang spectrum of $f$. For any fixed $b\in \mathbb{F}_{p^n}^*$, denote by $\beta(b)$ the number of solutions to 
\begin{eqnarray}\label{boom eq f2}
    \left \{
\begin{array}{lll}
x^d-y^d=b,\\
(x+1)^{d}-(y+1)^{d}=b,\\
\end{array}\right.
\end{eqnarray}
in $\mathbb{F}_{p^n}^2$.

\subsection{$p=2$}
In this subsection, we determine the boomerang spectrum of $f(x)=x^d$ over $\mathbb{F}_{2^n}$.
\begin{lemma}\label{bs 2 lemma}
Let $\alpha=\psi^{2^m-1}$ and $\frac{2^m+1}{t}>3$. With the notations above, we get 
\begin{itemize}
\item[(i)]  $\beta(1)=2$ for $3t\nmid2^m+1$. $\beta(1)=4t^4-4t^3+2t^2+2$ for $3t\mid2^m+1$. 
\item[(ii)] $\beta(1+\alpha^{si})=2t(t-1)(2^m+2t^2-4t)$ for $1\leq i<\frac{2^m+1}{t}$, $1+\alpha^{si}\neq\alpha^{\frac{2^m+1}{3}}, \alpha^{\frac{2(2^m+1)}{3}}$.
\item[(iii)] $\beta(\alpha^{si}+\alpha^{sj})=2t^4+2t^2(t-1)^2=4t^4-4t^3+2t^2$ for $1\leq i,j<\frac{2^m+1}{t}$, $i\neq j$, $\alpha^{si}+\alpha^{sj}\neq1$.
\item[(iv)] $\beta(\alpha^{\frac{2^m+1}{3}})=\beta(\alpha^{\frac{2(2^m+1)}{3}})=0$ for $3t\nmid2^m+1$. $\beta(\alpha^{\frac{2^m+1}{3}})
    =\beta(\alpha^{\frac{2(2^m+1)}{3}})=2t(t-1)(2^m+2t^2-4t)+4t^2$ for $3t\mid2^m+1$. 
\item[(v)] $\beta(b)=0$ for $b\neq0, 1, \alpha^{si}+\alpha^{sj}$, where $0\leq i,j<\frac{2^m+1}{t}$.
\end{itemize}
\end{lemma}
\begin{proof}
