\item[(ii)] if $2t\nmid3^m+1$, then $\beta(1-\alpha^{si})
    =\beta(\alpha^{si}-1)
    =t(t-1)(3^m+t^2-3t)$, where $1\leq i< \frac{3^m+1}{t}$.
\item[(iii)] if $2t\mid3^m+1$, then $\beta(1-\alpha^{si})
    =\beta(\alpha^{si}-1)
    =t(t-1)(3^m+4t^2-4t)$, where $1\leq i< \frac{3^m+1}{t}$, $\alpha^{si}\neq2$.
\item[(iv)] if $2t\nmid3^m+1$, then $\beta(2\alpha^{si})
    =0$, where $1\leq i< \frac{3^m+1}{t}$.
\item[(v)] if $2t\mid3^m+1$, then $\beta(2\alpha^{si})
    =t^4-2t^3+t^2$, where $1\leq i< \frac{3^m+1}{t}$, $\alpha^{si}\neq2$.
\item[(vi)] if $2t\nmid3^m+1$, then $\beta(\alpha^{si}-\alpha^{sj})
    =t^4-2t^3+t^2$, where $1\leq i,j< \frac{3^m+1}{t}$, $i\neq j$.
\item[(vii)] if $2t\mid3^m+1$, then $\beta(\alpha^{si}-\alpha^{sj})
    =4t^4-4t^3+2t^2$, where $1\leq i,j< \frac{3^m+1}{t}$, $\alpha^{si},\alpha^{sj}\neq2$, $i\neq j$.
\item[(viii)] $\beta(b)=0$ for $b\neq0, \pm1, \alpha^{si}-\alpha^{sj}$, where $0\leq i,j< \frac{3^m+1}{t}$. \hfill$\square$
\end{itemize}
\end{lemma}

