    $4$ & $(1,1,4)$ & $\Z_4$ & $\Z_4\oplus \Z_2$ \\
    $5$ & $(1, 1, 1, 16)$ & $\Z_{16}$ & $\Z_{16}\oplus \Z_2$\\
    $6$ & $(1, 1, 3, 3, 3)$ & $\Z_3^3$  & $\Z_3^3\oplus \Z_2$\\
    $7$ & $(1, 1, 1, 1, 1, 104)$  & $\Z_{104}$ & $\Z_{104}\oplus \Z_2$\\
    $8$ & $(1, 1, 1, 1, 2, 8, 8)$  & $\Z_{8}^2\oplus \Z_2$  & $\Z_{8}^2\oplus \Z_2^2$\\
    $9$ & $(1, 1, 1, 3, 3, 3, 3, 9)$ & $\Z_{9}\oplus \Z_3^4$ & $\Z_{9}\oplus \Z_3^4\oplus \Z_2$ \\
    $10$ & $(1, 1, 1, 1, 1, 1, 1, 16, 80)$ & $\Z_{80}\oplus \Z_{16}$ & $\Z_{80}\oplus \Z_{16}\oplus \Z_2$\\
    $11$ & $(1, 1, 1, 1, 1, 1, 1, 1, 22, 242)$ & $\Z_{242}\oplus \Z_{22}$ & $\Z_{242}\oplus \Z_{22}\oplus \Z_2$\\
    $12$ & $(1, 1, 1, 1, 3, 3, 3, 3, 3, 3, 12)$ & $\Z_{12}\oplus \Z_{3}^6$ & $\Z_{12}\oplus \Z_{3}^6\oplus \Z_2$
    \end{tabular}
  \end{center}
\end{table}

When $n$ is a power of $p$, the precise structure of the sandpile group (and hence of the Reutenauer group) can be easily given in terms of $p$ and $n$. Indeed, from the results in~\cite{ECCGTA13}, one can derive the following:

 \begin{lemma}
 For every prime $p$ and any $n\geq 1$ one has:
\begin{equation}\label{eq:SandpilePrime}
    K(\DB(p,p^n))\cong \big[ \bigoplus_{i=1}^{n-1}(\Z_{p^i})^{p^{n-1-i}(p^2-2p+1)}\big]\oplus \Z_{p^n}^{p-2},
\end{equation}
and hence, by Theorem~\ref{thm:KDB-RG},
\begin{equation}\label{eq:RG}
RG_p^n\cong \big[ \bigoplus_{i=1}^{n-1}(\Z_{p^i})^{p^{n-1-i}(p^2-2p+1)}\big]\oplus \Z_{p^n}^{p-2}\oplus \Z_{p-1}.
\end{equation}
 \end{lemma}

\begin{proof}
We use the formula from~\cite{ECCGTA13} (Theorem 3.1), that describes the group $K(\DB(d,k))$ for arbitrary $d,k$, in the case where $d=p$ is prime and $k=p^n$ for $n\ge 1$:

\begin{align*}
 K(\DB(p,p^n))%&\cong \bigoplus_{i=0}^{n-1}\big[\Z_{p^{i}}\oplus \Z_{p^{i+1}}^{n_i-2n_{i+1}+n_{i+2}-1} \big]\\
 &\cong \big[ \bigoplus_{i=1}^{n-1}\Z_{p^i}\big]\oplus \big[ \bigoplus_{i=0}^{n-2}\Z_{p^{i+1}}^{p^{n-i}-2p^{n-i-1}+p^{n-i-2}-1} \big]\oplus \Z_{p^n}^{p^{n-(n-1)}-2p^{n-(n-1)-1}+p^{n-(n-1)-1}-1} \\             &\cong \big[ \bigoplus_{i=1}^{n-1}\Z_{p^i}\big]\oplus \big[ \bigoplus_{i=0}^{n-2}\Z_{p^{i+1}}^{p^{n-i-2}(p^2-2p+1)-1} \big]\oplus \Z_{p^n}^{p-2} \\
 &\cong \big[ \bigoplus_{i=1}^{n-1}\Z_{p^i}\big]\oplus \big[ \bigoplus_{i=1}^{n-1}\Z_{p^{i}}^{p^{n-i-1}(p^2-2p+1)-1} \big]\oplus \Z_{p^n}^{p-2} \\
 &\cong \big[ \bigoplus_{i=1}^{n-1}\Z_{p^{i}}^{p^{n-i-1}(p^2-2p+1)} \big]\oplus \Z_{p^n}^{p-2} 
 \end{align*}
\end{proof}

Note that, as expected, for $p=2$ we obtain \eqref{Levine}.

We thus obtain the following formula for the number of generalized de Bruijn words over an alphabet of prime size:

\begin{theorem}
Let $p$ be a prime. For every $n\geq 2$, the number of generalized de Bruijn words of length $pn$ over $\Sigma_p=\{0,1,\ldots,p-1\}$ is 
\begin{equation}\label{eq:DBWprime}
    \DBW_p(pn)=\dfrac{((p-1)!)^n}{p-1}\dfrac{\Phi_p(n)}{n}=\dfrac{((p-1)!)^n}{p-1}\InvNeck_p(n)
\end{equation}
where $\InvNeck_p(n)$ is the number of invertible  necklaces of length $n$ over $\Sigma_p$.
\end{theorem}

\begin{proof}
We know that $\kappa(\DB(p,n))$ is equal to the order of $K(\DB(p,n))$. By Theorem~\ref{thm:KDB-RG}, $K(\DB(p,n))\cong  C(p, n)/(\Z_{p-1}\times \Z_n)$. Since the order of  $C(p,n)$ is $\Phi_p(n)$, we have $\kappa(\DB(p,n))=\Phi_p(n)/(n(p-1))$. The result then follows from \eqref{eqDBW}.
\end{proof}

\begin{remark}
Let $pn=p^d$, $d> 1$, i.e., $n=p^{d-1}$. Since $\Phi_p(p^{d-1})=p^{p^{d-1}}\dfrac{p-1}{p}$, from \eqref{eq:DBWprime} we get 
\[\DBW_p(p^d)=\dfrac{((p-1)!)^{p^{d-1}}p^{p^{d-1}}}{pp^{d-1}}=\dfrac{(p!)^{p^{d-1}}}{p^d}\]
 i.e., the number of (ordinary) de Bruijn words of order $d$ over $\Sigma_p$.
\end{remark}

In the special case $p=2$, we have, by Theorem~\ref{thm:KDB-RG}, that $K(\DB(2,n))\cong \RG_2^n$.
As a consequence, we have the following:

\begin{theorem}\label{thm:final1}
    For every $n\geq 1$, the following sets are in bijection: 
    \begin{itemize}
        \item The set of binary generalized de Bruijn words of length $2n$;
        \item The set of binary invertible necklaces of length $n$;
        \item The set of (unordered) normal bases of $\GF_{2^{n}}$.
    \end{itemize}
\end{theorem}

 In particular, when $n=2^d$ for some $d$, we have a bijection between the set of binary de Bruijn words of length $2^{d+1}$ and the set of necklaces of length $2^d$ having an odd number of $1$'s. This follows from Corollary~\ref{cor:artin}. Indeed, notice that we do not need to add the hypothesis that the necklaces are aperiodic, since their lengths are a power of $2$. 

\begin{theorem}\label{thm:final2}
    For every $d\geq 1$, the following sets are in bijection: 
    \begin{itemize}
        \item The set of binary de Bruijn words of order $d+1$;
        \item The set of necklaces of length $2^d$ having an odd number of $1$'s;
         \item The set of (unordered) normal bases of $\GF_{2^{2^d}}$.
    \end{itemize}
\end{theorem}

\begin{remark}
Any constructive bijection would allow one to derive algorithms for interchanging between these objects. One could, for example, use such a bijection to generate every binary de Bruijn word with uniform probability, a problem that is still open---in \cite{DBLP:conf/latin/LiptakP24} the authors presented an efficient algorithm to generate every binary de Bruijn word with positive probability.
Moreover, this could be made efficient in practice since the sum in $\GF_2$ is nothing else than the XOR.
\end{remark}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Conclusions and Open Problems}\label{sec:conclusion}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

As emphasized in the introduction, the central motivation of our work is to present a new formalism, based on combinatorics on words, that bridges various algebraic structures. This approach builds on known results relating sandpile groups of (generalized) de Bruijn graphs and groups of invertible matrices over finite fields (Reutenauer groups). The new classes of words we introduce in this paper---generalized de Bruijn words on the one hand, and conjugacy classes of words (necklaces) with invertible Burrows--Wheeler matrix on the other hand---offer a fresh reinterpretation of these connections in terms of words. The key advantage of the new framework is its foundation in the Burrows--Wheeler transform, which not only clarifies links to longstanding open problems in elementary number theory but also opens new avenues for further research.

 We 
 %believe our work will serve as a foundational contribution, and we 
 expect that different research communities, including those focused on combinatorics on words, commutative algebra, combinatorial algorithms, finite fields, and cryptography, will build upon the new constructions introduced in this paper.
For instance, it would be interesting to develop combinatorial characterizations of the newly introduced classes of words. Another compelling direction is to gain a deeper understanding of the group operation on invertible necklaces and investigate its relationship to the one recently introduced by Zamboni in the context of Christoffel words~\cite{DBLP:journals/corr/abs-2409-07974}, and further explored in~\cite{DBLP:journals/corr/abs-2409-09824}.


