\subsubsection{Population dynamics for infinite populations: The multi-population replicator dynamics}
\label{subsection:infinitepopulation}
In this section, we recall the framework of the replicator dynamics for multi-populations \cite{taylor1979evolutionarily,bauer2019stabilization}. To describe the dynamics, we consider a set of $m$ different populations ($m$ is some positive integer), which are infinitely large and well-mixed. Each population $i$, $i=1,\ldots m$, consists of $n_i$ ($n_i$ is some positive integer) different strategies (types). Let $x_{ij}, 1\leq i\leq m, 1\leq j\leq n_i$, be the frequency of the strategy $j$ in the population $i$. We denote by $x_i=(x_{ij})_{j=1}^{n_i}$, which is the collection of all strategies in the population $i$, and $x=(x_1,\ldots, x_m)$, which is the collection of all strategies in all populations. 

For each $i\in\{1,\ldots, m\}$ and $j\in\{1,\ldots, n_i\}$, let $f_{ij}(x)$ be the fitness (reproductive rate) of the strategy $j$ in the population $i$. This fitness is obtained when the strategy $j$ interacts with all other strategies in all populations; thus, it depends on all the strategies in the populations. The average fitness of the population $i$ is defined by
\[
\bar{f}_i(x)=\sum_{j=1}^{n_i} x_{ij} f_{ij}(x).
\]
The multi-population replicator dynamics is then given by
\begin{equation}
\label{eq: general replicator dynamics}
\dot{x}_{ij}=x_{ij} (f_{ij}(x)-\bar{f}_{i}(x)), \quad 1\leq i\leq m,\quad 1\leq j\leq n_i. 
\end{equation}
This is in general an ODE system of $\sum_{i=1}^m n_i$ equations. Noting, however that since $\sum_{j=1}^{n_i}x_{ij}=1$ for all $i=1,\ldots, m$, we can reduce the above system to a system of $\sum_{i=1}^m n_i-m$ equations. 

Now we focus on the case when there are two strategies in each population (which is the case for our models of AI governance and trust in the present paper), that is $n_i=2$ for all $i=1,\ldots, n_i$. Let $\eta_i$ be the frequency of the first strategy in the population $i$, $i=1,\ldots, m$ (thus $1-\eta_i$ will be the frequency of the second strategy in the population $i$), let $\eta=(\eta_1,\ldots, \eta_m)$. Let $f_{1i}(\eta)$ and $f_{2i}(\eta)$ be the fitness of the first and second strategy in the population $i$. Since:
\[
\bar{f}_i(\eta)=\eta_i f_{1i}(\eta)+(1-\eta_i) f_{2i}(\eta),
\]
we have:
\[
f_{1i}(\eta)-\bar{f}_i(\eta)=f_{1i}(\eta)-(\eta_i f_{1i}(\eta)+(1-\eta_i) f_{2i}(\eta))=(1-\eta_i)(f_{1i}(\eta)-f_{2i}(\eta)).
\]
Thus we obtain the following system of equations:
\begin{equation}
\label{eq: general replicator2}
\dot{\eta}_i=\eta_i(1-\eta_i)(f_{1i}(\eta)-f_{2i}(\eta)), \quad i=1,\ldots, m.
\end{equation}

This is a system of $m$ coupled nonlinear Ordinary Differential Equations (ODE) for $m$ variables.

In the subsequent sections, we employ \eqref{eq: general replicator2} to our models of AI governance trust, where the fitnesses are computed from the payoff matrix constructed in the models, see Tables~\ref{tab:payoff_matrix_1}-\ref{tab:payoff_matrix_2}. The resulting replicator dynamics for both models, (see equations \eqref{eq: replicator dynamics baseline model} and equations \eqref{eq: replicator dynamics model 2} below) can be written in a general form as:
\begin{subequations}
\label{eq: general system}
\begin{align}
 &\dot{x}=x(1-x) F_1(X)=:\tilde{F}_1(X),\\
&\dot{y}=y(1-y) F_2(X)=:\tilde{F}_2(X),\\
&\dot{z}=z(1-z) F_3(X)=:\tilde{F}_3(X),\\
&\dot{w}=w(1-w) F_4(X)=:\tilde{F}_4(X), 
\end{align}
\end{subequations}
where $X=(x,y,z,w)$ is the vector of frequencies, and $F_i(X)$ ($i=1,\ldots, 4$) are the corresponding difference of the fitnesses in the two models (precise formulas are given in the next section).

The 16 vertices $(x,y,z,w)\in\{0,1\}^4$ of the 4-dimensional cube are obviously equilibria of \eqref{eq: general system} (called vertical equilibria). An internal equilibria $X$ is a solution in $(0,1)^4$ of the following system of equations:
\begin{equation*}
 F_1(X)=F_2(X)=F_3(X)=F_4(X)=0.   
\end{equation*}
Analytically computing these internal equilibria and analysing their stable properties are very complicated due to the nonlinearity and number of the parameters, thus we will do so numerically. Here, we analyze the stability of the vertical equilibria. Let $X^*=(x^*,y^*,z^*, w^*)\in \{0,1\}^4$ be a vertical equilibrium. Since $x^*\in \{0,1\}$, we have:
\begin{align*}
&\frac{\partial}{\partial x} \tilde{F}_1(X)\Big\vert_{X=X^*}=(1-x^*)F_1(X^*)-x^* F_1(X^*)+x^*(1-x^*) \partial_x F_1(X^*)=(1-2x^*)F_1(X^*),\\
&\frac{\partial}{\partial t} \tilde{F}_1(X)\Big\vert_{X=X^*}=x^*(1-x^*) \partial_t F_1(X^*)=0.
\end{align*}
Similar computations yield:
\begin{align*}
 &\frac{\partial}{\partial y} \tilde{F}_2(X)\Big\vert_{X=X^*}=(1-2y^*)F_2(X^*),\\
&\frac{\partial}{\partial t} \tilde{F}_2(X)\Big\vert_{X=X^*}=0,\quad t\in\{x,z,w\},\\
 &\frac{\partial}{\partial z} \tilde{F}_3(X)\Big\vert_{X=X^*}=(1-2z^*)F_3(X^*),\\
&\frac{\partial}{\partial t} \tilde{F}_3(X)\Big\vert_{X=X^*}=0,\quad t\in\{x,y,w\},\\
 &\frac{\partial}{\partial w} \tilde{F}_4(X)\Big\vert_{X=X^*}=(1-2w^*)F_4(X^*),\\
&\frac{\partial}{\partial t} \tilde{F}_4(X)\Big\vert_{X=X^*}=0,\quad t\in\{x,y,z\}.
\end{align*}
From the above calculations, the Jacobian matrix $J(X)=\frac{D \tilde{F}(X)}{D X}$, evaluated at $X^*$, $J(X^*)=\frac{D \tilde{F}(X)}{D X}\vert_{X=X^*}$, will be the following diagonal matrix:
\[
J(X^*)=\mathrm{diag}((1-2x^*)F_1(X^*), (1-2y^*)F_2(X^*),(1-2z^*)F_3(X^*),(1-2w^*)F_4(X^*)).
\]
The diagonal entries are the real eigenvalues of $J(X^*)$. Thus, $X^*$ is stable if and only if the following conditions hold:
\[
(1-2x^*)F_1(X^*)<0,~ (1-2y^*)F_2(X^*)<0,~ (1-2z^*)F_3(X^*)<0,~(1-2w^*)F_4(X^*)<0.
\]
From these conditions, one can easily determine the stability of $X^*$ which depends on the parameters. We will employ this analysis for our models in the next section.
\section{Equilibrium analysis in infinite populations}


\subsubsection{Model I: developers are investigated by media } 
In order to write the replicator dynamics explicitly using the general framework \eqref{eq: general replicator2}, we need to derive the fitness differences for all participants in the game. We use the values from Table \ref{tab:payoff_matrix_1}; for brevity, we omit the explicit calculations. For commentariat and users, the following hold:
\begin{align}
    f^{Co}_C-f^{Co}_D &= \left(y b_i-c_i\right) -\left(y \left(b_i-p_W \left(b_i+c_W\right)\right)\right)\notag\\&= y p_W \left(b_i+c_W\right)-c_i,
\end{align}
\begin{align}
f^U_T-f^U_N&= b_U \left((x-1) p_W ((z-1) \epsilon +z)+z\right) - 0\notag\\&=b_U \left((x-1) p_W ((z-1) \epsilon +z)+z\right).\label{eq: differnce T and N}
\end{align}
Similarly, the difference of the fitness between two strategies in creators is:
\begin{align}
f^C_C-f^C_{D}&= \left(y b_P \left((x-1) p_W+1\right)-c_P\right) - \left((x-1) y p_W \left(u w-b_P\right)\right)\notag\\&=(x-1) y p_W \left(2 b_P-u w\right)+y b_P-c_P \label{eq: difference C and D for developers}
\end{align}
Finally, the difference of the fitness between two strategies in regulators is:
\begin{align}
f^R_{C}-f^R_{D}&= \left(-(x-1) y p_W \left((z-1) \left(v-b_{\text{f0}}\right)+(1-2 z) b_R\right)+y z b_R-c_R\right) \notag\\&- \left(y b_R \left((x-1) (2 z-1) p_W+z\right)\right)\notag\\&=-(x-1) y (z-1) p_W \left(v-b_{\text{f0}}\right)-c_R.
\end{align}

The replicator dynamics immediately becomes:
\begin{subequations}
\label{eq: replicator dynamics baseline model}
\begin{align}
&\dot{x}=x(1-x)\Big[  y p_w \left(b_I+c_W\right)-c_I
\Big],\label{eq:repdyn-a}\\ 
&\dot{y}=y(1-y)\Big[  b_U \left((x-1) p_w ((z-1) \epsilon +z)+z\right)\Big],\\ 
&\dot{z}=z(1-z)\Big[ (x-1) y p_W \left(2 b_P-u w\right)+y b_P-c_P\Big],\\
&\dot{w}=z(1-z)\Big[  -(x-1) y (z-1) p_W \left(v-b_{\text{f0}}\right)-c_R\Big],\\
&(x(0),y(0),z(0),w(0))=(x_0,y_0,z_0,w_0).\label{eq:repdyn-e}
\end{align}
\end{subequations}

First, we investigate the existence and the number of equilibria in the $[0,1]^4$ hypercube of the above system. Clearly, $(x,y,z,w)\in \{0,1\}^4$ will be (vertical) equilibrium points. The full list of  equilibria with one of the variables lying on the boundary consists of 29 isolated non-degenerate equilibrium points and two edges:
 \begin{equation}
 \begin{split}
 &\begin{cases}
     x = 1,\\
     z=0,\\
     w=0.
 \end{cases}, \ \  \begin{cases}
     x = 1,\\
     z=0,\\
     w=1.
 \end{cases}
 \end{split}
 \end{equation}
The two possible candidates for internal equilibria are: 
\begin{small}
    \begin{equation}
   \begin{cases}
       x=  \frac{-\sqrt{-2 (\epsilon -1) c_i c_R p_W \left(v-b_{\text{f0}}\right) \left(b_i+c_W\right)+c_i^2 \left(v-b_{\text{f0}}\right){}^2+(\epsilon +1)^2 c_R^2 p_W^2 \left(b_i+c_W\right){}^2}+c_i \left(2 p_W-1\right) \left(v-b_{\text{f0}}\right)+(\epsilon +1) c_R p_W \left(b_i+c_W\right)}{2 c_i p_W \left(v-b_{\text{f0}}\right)}\\
       y= \frac{c_i}{p_W \left(b_i+c_W\right)}\\
       z= \frac{\sqrt{-2 (\epsilon -1) c_i c_R p_W \left(v-b_{\text{f0}}\right) \left(b_i+c_W\right)+c_i^2 \left(v-b_{\text{f0}}\right){}^2+(\epsilon +1)^2 c_R^2 p_W^2 \left(b_i+c_W\right){}^2}+c_i \left(v-b_{\text{f0}}\right)+(\epsilon +1) c_R p_W \left(b_i+c_W\right)}{2 c_i \left(v-b_{\text{f0}}\right)}\\

