\end{small}
and
\begin{small}
    \begin{equation}
        \begin{cases}
          x =   \frac{\sqrt{-2 (\epsilon -1) c_i c_R p_W \left(v-b_{\text{f0}}\right) \left(b_i+c_W\right)+c_i^2 \left(v-b_{\text{f0}}\right){}^2+(\epsilon +1)^2 c_R^2 p_W^2 \left(b_i+c_W\right){}^2}+c_i \left(2 p_W-1\right) \left(v-b_{\text{f0}}\right)+(\epsilon +1) c_R p_W \left(b_i+c_W\right)}{2 c_i p_W \left(v-b_{\text{f0}}\right)},\\

          y= \frac{c_i}{p_W \left(b_i+c_W\right)},\\
          z= \frac{-\sqrt{-2 (\epsilon -1) c_i c_R p_W \left(v-b_{\text{f0}}\right) \left(b_i+c_W\right)+c_i^2 \left(v-b_{\text{f0}}\right){}^2+(\epsilon +1)^2 c_R^2 p_W^2 \left(b_i+c_W\right){}^2}+c_i \left(v-b_{\text{f0}}\right)+(\epsilon +1) c_R p_W \left(b_i+c_W\right)}{2 c_i \left(v-b_{\text{f0}}\right)},\\

          w =  \frac{b_P \left(\sqrt{-2 (\epsilon -1) c_i c_R p_W \left(v-b_{\text{f0}}\right) \left(b_i+c_W\right)+c_i^2 \left(v-b_{\text{f0}}\right){}^2+(\epsilon +1)^2 c_R^2 p_W^2 \left(b_i+c_W\right){}^2}+c_i \left(v-b_{\text{f0}}\right)\right)}{2 u c_Rp_W \left(b_i+c_W\right)}\\ \ \ \ +\frac{c_P \left(-\sqrt{-2 (\epsilon -1) c_i c_R p_W \left(v-b_{\text{f0}}\right) \left(b_i+c_W\right)+c_i^2 \left(v-b_{\text{f0}}\right){}^2+(\epsilon +1)^2 c_R^2 p_W^2 \left(b_i+c_W\right){}^2}+c_i \left(b_{\text{f0}}-v\right)+(\epsilon +1) c_R p_W \left(b_i+c_W\right)\right)}{2 u c_Rc_i}\\ \ \ \ +\frac{(3-\epsilon ) b_P c_R}{2 u c_R}.
        \end{cases}
    \end{equation}
\end{small}
Analytically determining whether they are indeed internal equilibria, that is, whether they lie inside the hypercube $(0,1)^4$ is intractable. We thus invoke numerical analysis. Figures \ref{fig:barcharta} and \ref{fig:barchartb} show the distribution of the number of solutions for randomly chosen values of the parameters, for both models I and II. Nevertheless, we obtain the following interesting result that provides simple conditions on the non-existence of internal equilibria.
\begin{lemma}
 There are no internal equilibria in $[0,1]^4$ when either of the following hold:
 \begin{enumerate}
     \item $v-b_{f_0}>0$,
     \item $0<\epsilon<1$. 
 \end{enumerate}
\end{lemma}
\begin{proof}

Internal equilibria are given by the solutions of the last parts of the equations \ref{eq:repdyn-a}-\ref{eq:repdyn-e}. 

From the first equation it is clear that $y= \frac{c_i}{p_W \left(b_i+c_W\right)}$. Substituting this value into the fourth equation yields:
\begin{equation*}
    -\frac{(x-1) (z-1) c_i \left(v-b_{\text{f0}}\right)}{b_i+c_W}-c_R=0.
\end{equation*}

Since $c_i,c_R>0$ and $0<x<1$, $0<z<1$, if $v-b_{f_0}>0$, the whole expression turns strictly negative and can't result in an equilibrium.   

Analogously, substituting the internal equilibrium value of $y$ into the second equation and solving it for $z$ gives:
\begin{equation*}
    z =-\frac{(1-x) \epsilon  p_W}{1-(1-x) (\epsilon +1) p_W},
\end{equation*}
which is negative when $0<\epsilon<1$. 
\end{proof}

